import { Verse } from './thirumanthiram';

// Tantra 2 — verses 337-548 — scraped from tamilnation.org/mp004b
export const VERSES_T2: Verse[] = [
  {
    id: 338, tantraId: 2, verseNumber: 337,
    tamil: `நடுவுநில் லாதிவ் வுலகஞ் சரிந்து
கெடுகின்ற தெம்பெரு மானென்ன ஈசன்
நடுவுள அங்கி அகத்திய நீபோய்
முடுகிய வையத்து முன்னிரென் றானே.`,
    transliteration: `naṭuvunil lātiv vulakañ carintu
keṭukiṉṟa temperu māṉeṉṉa īcaṉ
naṭuvuḷa aṅki akattiya nīpōy
muṭukiya vaiyattu muṉṉireṉ ṟāṉē.`,
    english: `337: The Lord Corrects the Earth's Balance Through Agastya
"Hail! Our Lord Supreme!
This earthly orb from its epicentre sways,
And dangerous on its side swerves"
Thus they bewailed, the Beings Celestial
And the Lord spoke:
"Agastya!
You that sit in tapas hard
Amidst the blazing sacrifice--fire
Hasten to the globe's swerving side
And there be seated, its balance to redress."`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-337-Second-Tantra-1.-Sage-Agasthya.mp3',
    elaborationTamil: `இறைவனும் இறைவியும் திருமணம் செய்த போது அதைக் காண வேண்டும் என்ற ஆசையில் உலகத்திலுள்ள அனைத்து முனிவர்களும் யோகிகளும் சித்தர்களும் தேவர்களும் திருக்கயிலாயத்தில் வந்து சேர்ந்தனர். அதனால் அதுவரை சரிசமமாக நின்ற வடக்கு நிலங்களும் தெற்கு நிலங்களும் அதிக பளுவால் மாறி வடக்கு நிலங்கள் தாழ்ந்தும் தெற்கு நிலங்கள் உயர்ந்தும் நின்றது. உலகத்திற்கு ஆபத்து வந்துவிடுமோ என்று பயந்து தேவர்கள் இறைவனிடம் சென்று எம்பெருமானே இப்படி உலகம் சமம் இல்லாமல் கெட்டு நிற்கின்றதே இதைக் காப்பாற்றுங்கள் என்று முறையிட்டனர். சிவபெருமான் அகத்தியரைப் பார்த்து நீ சென்று உயர்ந்து நிற்கும் தெற்கு நிலங்களின் மேல் நின்று இரு என்று கூறினார். அதைக்கேட்டு அகத்தியரும் தென்னாடு சென்று பொதிகை மலையில் நிற்க தெற்கு நிலங்கள் சமம் பெற்றது. உள்விளக்கம்: உடலும் உயிரும் சேர்ந்து பிறந்த போது அது வளர வளர அதற்கு சிறிது சிறிதாக ஆசைகள் கோபம் காமம் என்று பல குணங்கள் சேரும் போது உடலோடு இருக்கும் உயிர் சரிசம நிலை இல்லாமல் கெட்டு அழிய ஆரம்பிக்கின்றது. அப்போது உயிர் தமக்கு ஆபத்து இறைவா என்னை காப்பாற்று என்று வணங்க உடம்பில் உயிர் தங்குவதற்கும் சாப்பிடும் உணவு செரிப்பதற்கும் அக்னியை வைத்து இருக்கும் பேரருளாளன் எம்பெருமான் ஈசன் உடம்பில் உள்ள அக்னியை கொண்டு எப்பொழுதும் அந்த அக்னி அழியாமல் இருக்க ஒலியை வைத்து அந்த அக்னியை வளர்த்துக்கொண்டே இருக்கின்றான். இந்த உடம்பு எப்பொழுதும் அழியாமல் இருக்க ஒலியால் குண்டலியில் உள்ள அக்னியை விரைவாக வளர்த்து தலையின் உச்சிக்கு கொண்டு சென்றால் அழியாமல் வைத்திருக்கலாம் என்று அருளுகிறார். ஒலி என்பதற்க்கான விளக்கம்: மனிதனின் முன் மூளைப்பகுதியில் உள்ள நாளமில்லாச் சுரப்பி என் பெயர் பிட்யூடரி கிளாண்ட். பின் மூளையில் உள்ள நாளமில்லாச் சுரப்பு என் பெயர் பினியல் கிளாண்ட் இவை இரண்டும் வெவ்வேறு வகையில் வேலை செய்கின்றன. தெளிவான விளக்கங்கள் முன் மூளையிலும் அதனுடைய கருத்துக்கள் பின் மூளையிலும் பதிவு பெறுகின்றன. அவ்வகையான கருத்துக்களில் முதிர்ச்சியால் மூளையில் ஒரு வகை அதிர்வு (ஸ்பந்த உணர்வு) ஏற்பட்டு முன்மூளை அதிர்வு பின் நோக்கிச் செல்லும் பின் மூலையிலிருந்து அதிர்வு முன்மூளை நோக்கி செல்லும் இவை இரண்டும் சிரசின் உச்சியில் உரசுவதில் ஒலி உண்டாகும் இவ்விதமான அதிர்வு தலை முழுவதும் பரவி கவிழ்ந்து இருக்கும் சகஸ்ரதளத்தை நிமிர்ந்த சகஸ்ரதளமாக மாற்றும் இதுவே அகத்தியம்.`,
  },
  {
    id: 339, tantraId: 2, verseNumber: 338,
    tamil: `அங்கி உதயம் வளர்க்கும் அகத்தியன்
அங்கி உதயஞ்செய் மேல்பா லவனொடு
மங்கி உதயஞ்செய் வடபால் தவமுனி
எங்கும் வளங்கொள் இலங்கொளி தானே`,
    transliteration: `aṅki utayam vaḷarkkum akattiyaṉ
aṅki utayañcey mēlpā lavaṉoṭu
maṅki utayañcey vaṭapāl tavamuṉi
eṅkum vaḷaṅkoḷ ilaṅkoḷi tāṉē`,
    english: `338: Agastya--A Pervasive Light
Unfailing at dawn
With the sun that doth in high heavens
Agastya lights the Fire divine;
He is the holy Muni of North
Whence the Primal Fire was born;
And the radiant light, pervasive-all.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-338-Second-Tantra-1.-Sage-Agasthya.mp3',
    elaborationEnglish: `Of yore Siva and Parvati were getting married at Mount Kailas located in the Himalayan mountains. All the world’s inhabitants gathered there to witness the holy wedding. The south of India was depleted in weight by the exodus. The earth-orb swerved from its epicentre. Siva sent Rishi Agastya to the south to redress the imbalance. Such is the might of the tapas of rishis, that the spiritual weight of one soul devoted to Siva.equalled the physical weight of a whole population of ordinary millions. The earth regained its balance. Siva will not let imbalance or injustice occur anywhere.

Implied in this legend is the view that’ Saivism, tapas, and other cults were brought from the north (the Himalayas) by members of the Agastya cult who provided for themselves a base in the hills of the Pandya Nadu in the south. This was, apparently, for.a long time the centre of gathering for Siddhas, Yogis, tantrics, etc. The sanskrit term ‘‘Bodhi’’ meaning knowledge would in Tamil become ‘‘poti’’, due to absence of aspiration and of softening of consonants in the latter alphabetical system.`,
    elaborationTamil: `உடலில் இருக்கும் ஒலியானது உடம்பில் தோன்றும் அக்னியை வளர்த்து அந்த அக்னியை குண்டலினி மூலம் மேல்நோக்கி தலைக்கு கொண்டு சென்று வலது புறமாக நகன்று இடப்பக்கம் தலை முழுவதும் பரவச்செய்தால் உடலோடு இருக்கும் உயிரிடம் அருள் தன்மை வளம் நிறைந்து ஒளியுடன் இருக்கும்.`,
  },
  {
    id: 340, tantraId: 2, verseNumber: 339,
    tamil: `கருத்துறை அந்தகன் தன்போல் அசுரன்
வரத்தின் உலகத் துயிர்களை எல்லாம்
வருத்தஞ்செய் தானென்று வானவர் வேண்டக்
குருத்துயர் சூலங்கைக் கொண்டுகொன் றானே`,
    transliteration: `karuttuṟai antakaṉ taṉpōl acuraṉ
varattiṉ ulakat tuyirkkaḷai ellām
varuttañcey tāṉeṉṟu vāṉavar vēṇṭak
kuruttuyar cūlaṅkaik koṇṭukoṉ ṟāṉē`,
    english: `339: The Eight Mighty Deeds of Siva--Destruction of Antaka
"Antaka, the Asura
Frightening unto God of Death
Whose name he bore
Armed with boons divine
Harassed worlds all"
--Thus the Celestial Beings moaned to the Lord;
And the Lord,
Lifting high His trident sharp
Pierced him straight to certain death.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-339-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `There was an asura who bore the name of Antaka, same as that of the Death-god. He had acquired invincible powers by prolonged penance. But he misused them and harassed the population of all the worlds. Siva destroyed him with his sharp trident at a fatal encounter which took place at Tirukkovilur.`,
    elaborationTamil: `கருத்த நிற மேனியோடு இரு கண்களும் தெரியாத அந்தகன் என்கிற அசுரன் மிகக் கடுமையான தவம் செய்து சாகா வரம் பெற்று ஈரேழு பதினான்கு உலகத்தையும் வெற்றி பெற்று அதில் வாழும் அனைத்து உயிர்களையும் கொடுமை படுத்தினான். இவனது கொடுமை தாங்காத தேவர்கள் இறைவனிடம் சென்று தங்களைக் காப்பாற்றுமாறு வேண்டிக்கொள்ள மனமிறங்கிய இறைவன் பைரவர் அவதாரம் எடுத்து குருத்து போன்ற மூன்று இலைகளில் நடு இலை மட்டும் மிகவும் நீண்டு இருக்கும் கூர்மையான சூலாயுதத்தால் அந்தகாசுரனின் கொன்று தேவர்களைக் காப்பாற்றினார். உட்கருத்து: அறியாமையால் மாயையில் மயங்கி கண் தெரியாமல் இருட்டில் இருக்கும் மனம் உயிரை இறைவனை அடையவிடாமல் தீய எண்ணத்துடன் வதைத்துக்கொண்டிருக்கிறது. ஒரு நாள் உயிர் இறைவா என்னை காப்பாற்று என்று வேண்ணிக்கொள்ள இறைவன் மாயையில் சிக்கி இருட்டில் கண் தெரியாமல் இருக்கும் மனதில் ஒளியைக் கொடுத்து அறியாமை என்னும் தீய எண்ணங்களை கொன்று உயிரை காப்பாற்றி அருளினார். மனித முதுகெலும்பு முடியும் பகுதி கழுத்து எலும்பு களுக்கு மேல் உள்ளது இது பின் மூளைப் பகுதிக்கும் முன்மூளை பகுதிக்கும் இடையில் முடிவுறுகிறது இதற்கு குருந்தம் என்று பெயர். இதன்மேல் சோம ஒளி, சூரிய ஒளி, ஆன்ம ஒளி என்னும் மூன்று ஒளிகள் உள்ளன. இவைதான் குருத்துயர் சூலமாகும். இந்த குருத்துயர் சூலத்தின் மூலம் இறைவன் அருளால் அறியாமை என்னும் இருட்டை அகற்றி இறைவனை உணர்ந்துகொள்ளலாம்.`,
  },
  {
    id: 341, tantraId: 2, verseNumber: 340,
    tamil: `கொலையிற் பிழைத்த பிரசா பதியைத்
தலையைத் தடிந்திட்டுத் தானங்கி யிட்டு
நிலையுல குக்கிவன் வேண்டுமென் றெண்ணித்
தலையை யாரிந்திட்டுச் சந்திசெய் தானே`,
    transliteration: `kolaiyiṟ piḻaitta piracā patiyait
talaiyait taṭintiṭṭut tāṉaṅki yiṭṭu
nilaiyula kukkivaṉ vēṇṭumeṉ ṟeṇṇit
talaiyai yārintiṭṭuc canticey tāṉē`,
    english: `340: The Lord Punished Daksha
Daksha, the son of Brahma fatally erred;
Deadly was his sin
To defy the Lord's primacy;
And the Lord smote his head
And consigned it to flames
And then bethought;
"Such like are needed for this world
An object lesson to serve"
And so, fixing a sheep's head to the trunk
Thus let him be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-340-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `Daksha was the giant-king of the Himalayas. He was the son of Brahma. Sati, Siva’s consort, was his daughter. Daksha thought no end of himself and challenged the supremacy of Siva. To establish this he performed a sacriligious sacrifice. Siva appeared on the scene, smote Daksha’s head and threw it into, the sacrificial flame. Then, thinking that the incident should serve as an object lesson to others who dare perform such heinous crimes, Siva fixed a sheep's head to Daksha’s severed trunk and let him live in this chimerical form. This heroic deed was performed at Tiruppariyalur.`,
    elaborationTamil: `பிரம்மாவின் மூத்தகுமாரனாகிய தட்சன் தவமிருந்து வானவர்கள் தனக்கு அடிபணிய வேண்டும் என்று வரம் பெற்றான். வரம் பெற்ற ஆணவத்தால் அண்டசராசரங்களுக்கும் தலைவன் ஆனான். பார்வதி தேவியைத் தனது மகளாக அடைந்தான். பார்வதி தேவி ஈசனைக் கண்டு தனது மாயை மறைந்து அவருடன் இணைந்துவிட்டாள். தந்தையாகிய தனது சம்மதம் இல்லாமல் இறைவனுடன் இணைந்துவிட்டாள் என்ற கோபத்தில் இறைவனை அழிக்க ஒரு மாபெரும் யாகம் செய்த தட்சன் அதில் இறைவனை அழைக்காமலும் தேவர்களுக்குத் தரவேண்டிய அவிர்பாகத்தை அவருக்குத் தராமலும் கொலைக்குற்றத்திற்கு மேலான குற்றம் புரிந்தான். அவன் குற்றத்தில் கோபம் கொண்ட இறைவன் பைரவர் அவதாரம் எடுத்து அவனது தலையைத் துண்டித்து வேள்வித் தீயில் போட்டு எரித்துவிட்டார். அதன்பிறகு பார்வதி தேவியும் பிரம்ம தேரும் உலக நன்மைக்கு தட்சன் தேவை என்று வேண்டிக்கொள்ள மனமிறங்கிய இறைவன் ஒரு ஆட்டின் தலையை எடுத்து தட்சனின் உடலில் பொருத்தி அவன் வாழும்படி செய்தார். தட்சனும் தனது ஆணவம் அழிந்து இறைவனை வணங்கினான். இந்த புராணம் நிகழ்ந்த இடம் திருப்பறியலூர் தலமாகும். உட்கருத்து: உயிர்கள் தனது கர்மாக்களை தீர்க்க பிறந்து கர்மாக்கள் தீர்ந்ததும் இறைவனை அடைய காத்துக்கொண்டிருக்கிறது. ஆனால் உயிர்களிடம் ஆணவம் தலைவன் போல் குடிகொண்டு தான் சொல்லுவது தான் சரி. அடுத்தவர் சொல்வதை கேட்கமாட்டேன் என்று தன் சொல்படி உயிரை ஆட்டிப்படைத்துக் கொண்டு இறைவனிடம் உயிர் செல்லவிடாமல் தடுத்துக்கொண்டிருக்கிறது. உயிர் இறைவா ஆணவத்திடம் இருந்து என்னைக்காப்பாற்று என்று வேண்டிட இறைவன் ஆணவம் என்னும் தலைவனின் தலையை வெட்டி உயிர்களுக்கு அருள் செய்தான். ஆணவம் முற்றிலும் அழிந்தால் இறைவனை அடைந்து விடலாம். ஆனால் உயிர்கள் தனது கர்மாக்கள் தீர்ந்தால் மட்டுமே இறைவனை அடையமுடியும் ஆகவே கர்மாக்கள் தீரும்வரை நன்மை, தீமை என எது நடந்தாலும் எல்லாம் இறைவன் செயல் என்று எண்ணும் ஆட்டுத்தலை போன்ற எண்ணத்தை படைத்து உயிர்களுக்கு அருளினான்.`,
  },
  {
    id: 342, tantraId: 2, verseNumber: 341,
    tamil: `எங்கும் பரந்தும் இருநிலந் தாங்கியுந்
தங்கும் படித்தவன் தாளுணர் தேவர்கள்
பொங்கும் சினத்துள் அயன்தலை முன்னற
அங்குஅச் சுதனை உதிரங்கொண் டானே`,
    transliteration: `eṅkum parantum irunilan tāṅkiyun
taṅkum paṭittavaṉ tāḷuṇar tēvarkaḷ
poṅkum ciṉattuḷ ayaṉtalai muṉṉaṟa
aṅkuac cutaṉai utiraṅkoṇ ṭāṉē`,
    english: `341: How the Lord Punished Aya and Atchutha
All pervasive are the Lord's feet
All worlds they support
All life they sustain;
That this the Heavenly Beings may know
In mounting anger He nipped Aya's head
And in the skull drained Atchutha's blood
(When they His supremacy defied.)`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-341-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `Brahma at one time was as five-headed as Siva. Brahma and Mal, encouraged by the flattery of devas and rishis challenged Siva’s supremacy. Siva, assuming the aspect of Bhairava, pinched away one of Brahma’s heads with his finger nail. Bearing Brahma’s skull, Bhairava demanded of Mal to drain his blood into the skull and fill it up. Mal obeyed. Thus were the two gods shown their place. This is said to have happened at the place known as Tirukandiyur.`,
    elaborationTamil: `அண்டசராசரமெங்கும் பரவி இருப்பவனும் வாணுலகம் மண்ணுலகம் என்று இரண்டு நிலங்களையும் தாங்கி இருப்பவனும் தம்மை நாடி வருபவர்களுக்கு தஞ்சம் கொடுப்பவனுமாகிய இறைவனின் திருவடிகளின் பெருங்கருணையை உணர்ந்து இருக்கும் தேவர்கள் பிரம்மனைப் பார்த்துக் கோபம் கொண்டனர். பிரம்மன் படைப்புத் தொழிலைச் செய்வதாலும் ஐந்து தலைகளைக் கொண்டதாலும் மும்மூர்த்திகளிலேயே தாம்தான் உயர்ந்தவர் என்று தற்பெருமை கொண்டிருந்ததால் இறைவனது திருவடிக் கருணையை உணராமல் இருந்தார். பிரம்மனின் தற்பெருமையால் படைப்பு பாதிக்கப்படுவதைக் கண்ட இறைவன் பைரவ அவதாரம் எடுத்து பிரம்மனின் ஐந்து தலைகளின் ஒன்றைத் தனது விரல் நகத்தால் கிள்ளி எடுத்துவிட்டார். பிரம்மாவின் கிள்ளி எடுக்கப்பட்ட தலையிலிருந்து வந்த குருதியை அந்த கபாலத்திலேயே எடுத்து திருமாலை ஏற்றுக்கொள்ளச் செய்து அருளினார். இது நிகழ்ந்த இடம் திருக்கண்டியூர் தலமாகும். உட்கருத்து: உயிர்களிடம் இருக்கும் நான் என்னும் அகங்காரம் அகந்தை தான் யார் என்பதை உணரவிடாமல் செய்து நல்ல எண்ணம் குணங்களை அழிப்பதுடன் இறைவனையும் அடையவிடாமல் செய்து விடுகிறது. மேலும் அகந்தை அகங்காரத்தினால் மீண்டும் மீண்டும் பிறவி எடுத்து அதன் அடுத்த பிறவியையும் பாதிக்கிறது. (உதாரணமாக உயிருக்கு கர்மவினையின்படி 10 பிறவிகள் என்று எடுத்துக்கொண்டால் அகந்தை அகங்காரத்தினால் மேலும் பிறவிகள் எண்ணிக்கை கூடி அடுத்து வரும் பிறவிகளையும் பாதிக்கிறது) பிறவிகள் உயிர்கள் இறைவா என்னை காப்பாற்று என்று இறைவனை வேண்டிட தன்னை நாடி வருபவர்களுக்கு பெருங்கருணை செய்யும் இறைவன் அந்த அகந்தை அகங்காரத்தை அடியோடு வெட்டி எடுத்து உயிர்களை காக்கும் திருமாலிடம் அளித்து மீண்டும் இந்த உயிருக்கு மீண்டும் அகந்தை அகங்காரம் வராமல் இருக்க அருளினார்.`,
  },
  {
    id: 343, tantraId: 2, verseNumber: 342,
    tamil: `எங்குங் கலந்துமென் உள்ளத் தெழுகின்ற
அங்க முதல்வன் அருமறை யோதிபாற்
பொங்கும் சலந்தரன் போர்செய்ய நீர்மையின்
அங்கு விரற்குறித் தாழிசெய் தானே`,
    transliteration: `eṅkuṅ kalantumeṉ uḷḷat teḻukiṉṟa
aṅka mutalvaṉ arumaṟai yōtipāṟ
poṅkum calantaraṉ pōrceyya nīrmaiyiṉ
aṅku viraṟkuṟit tāḻicey tāṉē`,
    english: `342: How the Lord Destroyed Jalandhara
The Lord pervades all,
My heart too He fills with joy;
He spoke the Vedas and scriptures all;
Him--the haughty Jalandhara challenged in duel
And the Lord with his toe marked a circle
And into it He saw his final end.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-342-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `Jalandhara was a giant, and the foster son of Varuna, the Sea-god. By virtue of his penances, he received a boon that no one else could kill him. He became all-powerful and began to harass the celestials. They complained to Siva. Siva confronted Jalandhara and drew a circle around him. He challenged the giant to lift the circle. Jalandhara lifted it to his head, when lo, the circle turned into a powerful discus and destroyed him. Jalandhara had.to be destroyed by himself. This heroic deed is said to have happened at the place called Tiruvirkudi.`,
    elaborationTamil: `அனைத்து உயிருக்குள்ளும் எங்கும் எதிலும் இரண்டறக் கலந்திருப்பவனும் அனைத்து உயிர்களும் உய்ய வேதங்களை உலகிற்கு ஓதி அந்த வேதத்திற்கு முதல்வனாயும் இருக்கும் இறைவனை உணராமல் உயிர்கள் வீணாக ஒருவர்மேல் ஒருவர் குரோதம் கொண்டு ஆத்திரத்தில் அறிவிழந்து அடுத்த உயிருக்குள்ளும் இறைவன் இருக்கின்றான் என்பதை உணராமல் அந்த உயிரை அழிக்க பல கெட்ட செயல்களைச் செய்கின்றனர். உயிர்கள் இறைவா காப்பாற்று என்று வேண்டிட குரோதம் என்னும் அசுர குணத்தை உயிர்களிடம் உள்ள சக்திமய சக்கரங்களை கருவியாக பயன்படுத்தி இறைவன் தனது திருவடி மூலம் அழித்தான். இந்த பாடலுக்கான புராணம் நிகழ்ந்த இடம் திருவிற்குடி தலமாகும். ஒரு முறை இந்திரன் தான் என்ற அகந்தையுடன் சிவனை தரிசிக்க கைலாயத்திற்கு வந்தான். இதை அறிந்த சிவன் சேவகன் வடிவெடுத்து கைலாய வாசலில் நின்று உள்ளே செல்ல முடியாதபடி தடுத்தார். கோபமடைந்த இந்திரன் தன் வஜ்ராயுதத்தால் சிவனை அடித்தான். கோபத்தால் சிவன் தன் நெற்றிக்கண்ணை திறந்தார். காவல் காப்பவர் சிவன் என்பதை அறிந்த இந்திரன் ஆணவத்தால் தான் செய்த செயலை மன்னிக்க வேண்டினான். கோபத்தில் தன் உடலில் ஏற்பட்ட வியர்வைத்துளி பாற்கடலில் விழுந்தது. அதில் ஒரு குழந்தை தோன்றியது. இந்த குழந்தை பிரம்மனின் தாடியை பிடித்து இழுக்க வலி தாங்காத பிரம்மனின் கண்களிலிருந்து கண்ணீர் தோன்றி அந்த துளியும் குழந்தையின் மீது விழுந்தது. இப்படி சிவனின் வியர்வை துளி, பாற்கடல் நீர், பிரம்மனின் கண்ணீர் துளி ஆகிய ஜலத்தினால் உருவான குழந்தைக்கு ஜலந்தராசூரன் என பெயர் வைக்கப்பட்டது. அவன் பெரியவனானதும் மூவுலகும் தனக்கு அடிமையாக வேண்டும் என்றும் சாகாவரமும் கேட்டான். பிரம்மன் மறுத்தார். அதற்கு ஜலந்தராசூரன் தர்ம பத்தினியான என் மனைவி பிருந்தை எப்போது மனதளவில் கெடுகிறாளோ அப்போது எனக்கு அழிவு வரட்டும் என வரம் வாங்கி விட்டான். இவனது அட்டகாசம் அதிகமானது. கடைசியில் சிவனையே அழிக்க சென்றான். சிவன் அந்தணர் வேடமிட்டு அசுரன் முன் வந்து நின்று தன் காலால் தரையில் சக்கர வடிவில் ஒரு வட்டம் போட்டார் இந்த சக்கரத்தை எடுத்து உன் தலையில் வை. அது உன்னை அழிக்கும் என்றார். ஆணவம் கொண்ட ஜலந்தரன் என் மனைவியின் கற்பின் திறனால் எனக்கு அழிவு வராது என சவால் விட்டான். இந்த நேரத்தில் திருமாலை அழைத்த சிவன் நீர் ஜலந்தராசூரனைப் போல் வடிவெடுத்து அவன் மனைவி பிருந்தை முன் செல்லும்படி கூறினார். கணவன் தான் வந்திருக்கிறார் என வீட்டிற்குள் அழைத்தாள் பிருந்தை. ஒரு நொடியில் மாற்றானை தன் கணவன் என நினைத்ததால் அவளது மனம் களங்கமடைந்தது. இந்நேரத்தில் சக்கரத்தை அசுரன் எடுத்து தலையில் வைக்க அவன் கழுத்தை சக்கரம் துண்டித்து விடுகிறது.`,
  },
  {
    id: 344, tantraId: 2, verseNumber: 343,
    tamil: `அப்பணி செஞ்சடை ஆதி புராதனன்
முப்புரம் செற்றனன் என்பர்கள் மூடர்கள்
முப்புர மாவது மும்மல காரியம்
அப்புரம் எய்தமை யாரறி வாரே`,
    transliteration: `appaṇi ceñcaṭai āti purātaṉaṉ
muppuram ceṟṟaṉaṉ eṉparkaḷ mūṭarkaḷ
muppura māvatu mummala kāriyam
appuram eytamai yāraṟi vārē`,
    english: `343: The Lord Burnt the Cities Three
The Primal Lord,
Who on His matted crimson locks
Wears Ganga's water sacred,
He destroyed the Cities Three
--Thus say the ignorant;
The Three Cities are the Triple Impurities
It is them He burnt
Who knows this truth thereof?`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-343-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `Three giants by the power of penance ruled over three cities with three flying fortresses—one of gold, one of silver, and one of copper. Flying their fortresses, they landed on the cities of the celestials and destroyed them. Siva fought the three giants and reduced their three cities to ashes, all the while with'a smile of His lips. People who recount this legend do not realise that what Siva destroyed was the triple impurities—egoity, karma and maya. This heroic deed is associated with the place called Tiruathigai.`,
    elaborationTamil: `கங்கையைத் தன் சிவந்த சடையில் சூடியவனும் எல்லாவற்றிற்கும் முதலாயும் மூலமாயும் இருப்பவனுமாகிய இறைவனை முப்புரம் என்னும் இடத்தை எரித்தவன் என்று கூறுபவர்கள் மூடர்கள். அவர்களுக்கும் முப்புரமாக இருப்பது மும்மலங்களான ஆணவம், கன்மம், மாயை என்பது புரியவில்லை. அவற்றை இறைவன் அழிக்கிறான் என்பதை உணராமல் மூன்று புரங்களை எரித்ததாக கூறுபவர்களில் எவரும் அந்தப் புரங்கள் எரிந்த விதத்தை அறிந்தவர்கள் இல்லை. இந்த புராணநிகழ்வு நடந்த இடம் திருவதிகை தலமாகும். தாருகாசுரன் என்கிற அசுரனின் மகன்களான வித்துன்மாலி, தாரகாட்சன், கமலாட்சன் ஆகிய மூவரும் மிகச்சிறந்த இறை பக்தர்கள். அவர்கள் மூவரும் பிரம்மனை நோக்கிக் கடுந்தவம் செய்து நினைத்த இடத்திற்கு உடனே பறந்து செல்லும் மூன்று கோட்டைகளையும் அவை மூன்றும் ஒன்றாக இருக்கும்போது ஒரேயொரு அம்பினால் மட்டுமே தாங்கள் அழியவேண்டும் என்றும் வரம் பெற்றனர். வரம் கிடைத்ததும் அவர்கள் தேவலோகம் அனைத்தையும் ஆட்டிப்படைத்து வந்தனர். அவர்களின் அதிகாரம் தாங்காமல் தேவர்களும் பிரம்மரும் திருமாலும் இறைவனை வேண்ட மனமிறங்கிய இறைவன் அழகிய பைரவ அவதாரம் எடுத்து தேவதச்சன் விஸ்வகர்மாவிடம் ஒரு தேர் செய்யச் சொல்லி சந்திர சூரியரே தேர்ச் சக்கரங்களாகவும், நான்கு வேதங்களே தேரில் பூட்டிய குதிரைகளாகவும் பிரம்ம தேவரே தேரை ஓட்டும் சாரதியாகவும், மேரு மலையே வில்லாகவும், வாசுகி நாகமே வில்லைப் பூட்டும் நாணாகவும், அக்கினி அம்பின் முனையாகவும், வாயு அம்பின் வாலாகவும், திருமாலே அம்பாகவும் ஆக்கி எடுத்துக்கொண்டு முப்புரத்தை வந்து சேர்ந்தார். இறை பக்தியில் மிகவும் சிறந்து விளங்கும் அசுரர்களை அழிக்க வேண்டாமென்ற பெருங்கருணையில் தமது நெற்றிக் கண்ணைத் திறந்து ஒரு பார்வை பார்க்க மூன்று கோட்டைகளும் உடனே எரிந்து சாம்பலாகி மூவரும் இறைவனின் காலடியில் விழுந்து வணங்க இறைவனும் அவர்களை ஆட்கொண்டு தமது கோயிலின் வாயிற் காவலர்களாகவும் இருவரையும் கோயிலில் செய்யும் குடமுழுக்கை ஏற்பவராக ஒருவரையும் ஏற்றுக்கொண்டார்.`,
  },
  {
    id: 345, tantraId: 2, verseNumber: 344,
    tamil: `முத்தீ கொளுவி முழங்கொரி வேள்வியுள்
அத்தி யுரியர னாவ தறிகிலர்
சத்தி கருதிய தாம்பல தேவரும்
அத்தீயின் உள்ளெழுந் தன்று கொலையே`,
    transliteration: `muttī koḷuvi muḻaṅkori vēḷviyuḷ
atti yuriyara ṉāva taṟikilar
catti karutiya tāmpala tēvarum
attīyiṉ uḷḷeḻun taṉṟu kolaiyē`,
    english: `344: The Lord Unsloughed the Elephant
They lit the Fires Three
The sacrificial blaze roared high;
And from inside it arose
And Elephant of Evil Power,
Whose hide the Lord peeled;
Why the Lord did it, they know not;
Seeking to rival the Lord's might
The Heaven's beings performed a sacrifice unholy
And all those who from that fire arose
The Lord smote for the very fire to consume.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-344-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `a Gajasura was an elephant~monster that arose out of the sacrificial fire which the celestials had performed to challenge Siva's supremacy. Siva peeled the elephant’s skin and donned it as a vestment; and the’ celestials of evil intent were immolated in the very sacrificial fire they lit. This happened at Tiruvazhulur.`,
    elaborationTamil: `தாருகா வனத்திலிருந்த முனிவர்கள் இறைவனை வணங்காமல் இறைவனின் அருளை விட தங்களின் மந்திர சக்தியே பெரிது தாம் கற்ற மந்திரங்களின் மூலமாக எதையும் அடையலாம் என்ற அகங்காரத்தில் இருந்தனர். இவர்களின் அறியாமையைப் போக்க இறைவன் அழகிய உருவம் கொண்ட பிக்‌ஷாடனராகத் தோன்றி அந்த முனிவர்களின் வீட்டுக்குச் சென்று அங்கு இருந்த முனி பத்தினிகளின் முன்னால் பிச்சை கேட்டு நின்றார். அவரின் அழகில் மயங்கிய முனி பத்தினிகள் அவர் பின்னாலேயே மயக்கத்தில் கூடி வர ஆரம்பித்தனர். தங்களது பத்தினிகள் இப்படி ஒரு ஆடவனின் பின்னால் மயங்கி வருவதைக் கண்டு கோபமுற்ற முனிவர்கள் தமது தவ வலிமையால் மூன்றுவிதமான தீயை வளர்த்து மந்திரங்கள் மூலமாக (ஆகவனீயம் – காட்டுத்தீ, காருகபத்தியம் – வீட்டுத்தீ, தட்சிணாக்கினியம் – ஏட்டுத்தீ) கரிய நிறமுடைய ஒரு பெரிய யானையைத் தோன்றுவித்தனர். யாகத் தீயில் தோன்றிய யானை அவரை அழித்துவிடும் என்று நினைத்தார்கள். ஆனால் அந்தத் தீயிலிருந்து வெளிவந்த யானையைக் காடே அதிரும்படி பிளந்து கொன்று அதன் தோலை தனக்குப் போர்வையாக போர்த்திக்கொண்டு மூன்று வகையாக நெருப்பும் அதில் சொல்லும் மந்திரங்களும் மந்திரத்தின் பலனாக அதிலிருந்து வரும் பலனும் அனைத்தும் யாமே என்று தாருகா வனத்திலிருந்த முனிவர்களுக்கு உணர்த்தினார். இந்த புராணநிகழ்வு நடந்த இடம் திருவழுவூர் தலமாகும். உள்விளக்கம்: உயிர்களுக்கு வரும் கோபத்தினால் நான் என்ற அகங்காரம் அதிகரித்து என்ன செய்கின்றோம் என்ன பேசுகின்றோம் என்று தெரியாமல் மதம் பிடித்த யானை போல் இருக்கும் போது உயிர்கள் இறைவனை சரணடைய இறைவன் கோபத்தையும் அகங்காரத்தையும் அழித்து அனைத்தும் யாமே என்று உணர்த்துகிறார்.`,
  },
  {
    id: 346, tantraId: 2, verseNumber: 345,
    tamil: `மூலத் துவாரத்து மூளும் ஒருவனை
மேலைத் துவாரத்து மேலுற நோக்கிமுற்
காலுற்றுக் காலனைக் காய்ந்தங்கி யோகமாய்
ஞாலக் கடவூர் நலமாய் இருந்ததே`,
    transliteration: `mūlat tuvārattu mūḷum oruvaṉai
mēlait tuvārattu mēluṟa nōkkimuṟ
kāluṟṟuk kālaṉaik kāyntaṅki yōkamāy
ñālak kaṭavūr nalamāy iruntatē`,
    english: `345: The Lord Scorched the God of Death
The Kundalini Fire coiled in Muladhara
Upward He coursed it to Hollow on top;
That Fiery Yoga Way He scorched the God of Death
That was at Kadavoor, the holy shrine here below.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-345-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `Young Markandeya was an ardent devotee of Siva; but fate had decreed that.he should die at the age of sixteen. On the day destined, Yama, the god of death, promptly threw his noose around Markandeya’s life, not caring that the victim was immersed in Siva worship. At the sight of the god of death, the devotee clung fast to the Linga murthi. The death-noose thus encircled Siva as well. His wrath erupted, and rousing the kundalini fire from the muladhara, Siva spurned Yama forcing him to a regretful retreat by the heat of His divine fire. This heroic feat happened at the place called Kadavur.`,
    elaborationTamil: `மூலாதாரத்தில் எரிந்து கொண்டு இருக்கும் குண்டலினி சக்தியை சுழுமுனை நாடி வழியே மேலேற்றி அங்கே சகஸ்ரரதளத்தில் சேர்த்து அதைத்தாண்டிய பரவெளியில் இருக்கும் இறைவனை உணரும் உயிர்களுக்கு காலனை உதைத்து சாகா வரம் அளிப்பான் இறைவன். இதை உலகத்தவர்க்கு உணர்த்தும் விதமாகவே திருக்கடவூரின் திருத்தலம் இறைவனின் அருளால் நன்றாக அமைந்தது. இந்த பாடலுக்கான புராணம் நிகழ்ந்த இடம் திருக்கடவூர் தலமாகும். மிருகண்டு முனிவரும் அவருடைய மனைவியான மருத்துவவதி தேவியாரும் தங்களுக்கு குழந்தை பாக்கியம் தரும்படி இறைவனை வேண்ட குறைந்த ஆயுட்கொண்ட அறிவாளியான குழந்தை வேண்டுமா அல்லது அதிக ஆயுட்கொண்ட முட்டாளான குழந்தை வேண்டுமா என்று இறைவன் கேட்க அறிவாளியான குழந்தையே வேண்டும் என்று கேட்டு மார்க்கண்டேயன் எனும் குழந்தையைப் பெற்றுக் கொண்டனர். மார்க்கண்டேயர் பிறந்ததிலிருந்து ஆயுள் அதிகரிக்க இறைவனே சரணடைய வேண்டும் என்று போதித்து வந்தனர். அதனால் மிகச்சிறந்த இறை பக்தனான மார்க்கண்டேயர் எப்போதும் இறை பூஜையிலேயே வாழ்க்கையைக் கழித்து வந்தார். அவரது ஆயுட்காலம் முடியும்போது அவரை மேலுலகம் அழைத்துச்செல்ல எமதருமரும் எந்தப் பூஜையில் இருந்தாலும் அவரது ஆயுள் முடிந்தால் அழைத்துச் செல்லவேண்டியது தமது கடமை என்று எண்ணி அவரை அழைத்துச் செல்ல பாசக் கயிற்றை வீசுகிறார். சிவபூஜையில் இருந்த மார்க்கண்டேயர் சிவலிங்கத்தைக் கட்டி அணைத்திருக்கும்போது பாசக்கயிறு அவரோடு சிவலிங்கத்தின் மீதும் விழ அதிலிருந்து இறைவன் வெளிவந்து எமது பூஜையில் இருக்கும் அடியவர் எவரையும் கொண்டு செல்லும் உரிமை உமக்கு இல்லை என்று கூறி எமதருமரை காலால் எட்டி உதைத்துத் தள்ளிவிட்டு, மார்க்கண்டேயருக்கும் என்றும் 16 வயதுடன் சிரஞ்சீவியாக இருக்கும் வரமளித்தார். உட்கருத்து: தியானத்தில் இருந்து மூச்சுக்காற்றை உள்ளிழுத்து அடக்கி அதன் மூலம் மூலாதாரத்தில் எரிந்து கொண்டிருக்கும் குண்டலினி சக்தியை எழுப்பி சுழுமுனை நாடி வழியே மேல் நோக்கி எடுத்துச் சென்று ஏழாவதான சக்கரமான சகஸ்ரரதளத்தில் சேர்த்து அங்கு இருக்கும் இறைவனை உணர்ந்து விட்டால் மரண பயம் இன்றி சிரஞ்சீவியாக இறைவனிடம் பேரானந்தத்திலேயே இருக்கலாம்.`,
  },
  {
    id: 347, tantraId: 2, verseNumber: 346,
    tamil: `இருந்த மனத்தை இசைய இருத்திப்
பொருந்தி இலிங்க வழியது போக்கித்
திருந்திய காமன் செயலழித் தங்கண்
அருந்தவ யோகங் கொறுக்கை அமர்ந்ததே`,
    transliteration: `irunta maṉattai icaiya iruttip
porunti iliṅka vaḻiyatu pōkkit
tiruntiya kāmaṉ ceyalaḻit taṅkaṇ
aruntava yōkaṅ koṟukkai amarntatē`,
    english: `346: The Lord Vanquished Kama, the God of Love
The Lord was seated in Yoga
His thoughts stilled in meditation deep;
Lo! there came Kama
To tempt the Lord with shafts of love.
But the Love-God's wiles, the Lord foiled in Yoga Way;
This He did at Korukkai, the shrine divine.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-346-Second-Tantra-2.-Eight-Prowesses-of-Lord-Shiva.mp3',
    elaborationEnglish: `Siva was in intense tapas, of actionless trance. The work of destruction ceased over the entire universe. The world became over-populated. and too burdensome for Mother Earth to support. The celestials sent Kama, the god of love, to shoot his shafts of love at Siva and disturb His tapas. Siva in wrath burnt Kama to ashes and continued His tapas. This feat was performed at the place called Korukkai.`,
    elaborationTamil: `உலக நன்மைக்காக இன்னொரு உயிரை உருவாக்க தனது துணையுடன் சேரும் உயிர்கள் இறைவனை அடைய தடையாய் இருக்கும் காமம் என்னும் நோயில் சிக்காமல் இருக்க இறைவனை அடைய வேண்டும் என்ற குறிக்கோளுடன் ஒரு நிலைப்பட்ட மனமுடன் இறைவனை வேண்ட இறைவன் காமம் என்னும் நோயிலிருந்து உயிரை காப்பாற்றி உலக நன்மைக்காக இன்னொரு உடலுடன் கூடிய உயிரை உருவாக்க மட்டுமே இறை எண்ணத்துடன் தன்னுடைய துணையுடன் சேரும் உயிருக்கு அருந்தவ யோகத்தை அருளுவார். இந்த புராண நிகழ்வு நடந்த இடம் திருக்கொறுக்கை தலமாகும். சிவபெருமான் தியானத்தில் இருக்கும்போது உலக நன்மைக்காக அவர் தியானத்தை கலைக்க வேண்டும் என்று இந்திரன் கேட்டுக் கொண்டதற்கு இணங்கி மன்மதன் இறைவனின் மீது மலர்க்கணைகளைத் தொடுத்தான். அப்போதும் இறைவன் தமது நெற்றிக் கண்ணைத் திறந்து மன்மதனைப் பார்க்க அந்த நெற்றிக்கண்ணிலிருந்து வெளிப்பட்ட நெருப்பில் மன்மதன் எரிந்து சாம்பலானான். பிறகு மன்மதனின் மனைவியான ரதி தேவி இறைவனை வேண்டிக்கொள்ள உருவமில்லாத அருவமாக மன்மதனை மறுபடியும் உயிர்ப்பித்துக் கொடுத்தார்.`,
  },
  {
    id: 348, tantraId: 2, verseNumber: 347,
    tamil: `அடிசேர்வன் என்னஎம் ஆதியை நோக்கி
முடிசேர் மலைமக னார்மக ளாகித்
திடமார் தவஞ்செய்து தேவர் அறியப்
படியார அர்ச்சித்துப் பத்திசெய் தாளே`,
    transliteration: `aṭicērvaṉ eṉṉaem ātiyai nōkki
muṭicēr malaimaka ṉārmaka ḷākit
tiṭamār tavañceytu tēvar aṟiyap
paṭiyāra arccittup patticey tāḷē`,
    english: `347: The Benevolent Deeds Of The Lord-
How Sakti Won the Lord
"Of a certain will I espouse
My Lord of Divine Feet" thus saying
As Mountain King's daughter incarnate
Sakti performed penances severe;
For all celestial beings to witness,
For all earthly beings to delight,
In adoration intense to Primal Lord Divine.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-347-Second-Tantra-3.-Story-of-Linga.mp3',
    elaborationEnglish: `Sakti intent on reaching the Primal Being, incarnated Herself as Parvati, the daughter of the mountain-king, and performed hard penance. All the world stood in wonder. Siva warming up to Her intense devotion blessed Her.`,
    elaborationTamil: `ஆதிமூலமாகிய சிவ பரம்பொருளை அடைய வேண்டும் என்று சக்தி உறுதி எடுத்துக் கொண்டு இமய மலையின் அரசனாகிய பர்வதராஜனின் மகளாகப் பிறந்து பல காலம் உறுதியுடன் மாபெரும் தவம் செய்து தேவர்களும் அறியாத வழிபாட்டு முறைகளை தேவர்களும் அறிய முறையாக பூஜை செய்து இறைவனை அடைந்தாள். உட்கருத்து: ஆதிமூலமாகிய சிவ பரம்பொருளை அடைய வேண்டும் என்று ஆசைப்படும் உயிர்கள் தமது உறுதியிலிருந்து சற்றும் விலகாமல் தியானமும் தவமும் செய்து அசையும் சக்தியாகிய குண்டலினி சக்தியை மேலேற்றி தனது சிரசின் இடப்பக்கம் இருக்கும் அசையா சக்தியாகிய சிற்சக்தியுடன் சேர்த்தால் தேவர்களும் அறியாத இறைவனின் லிங்க உருவத்தையும் லிங்க தத்துவத்தையும் தனக்குள்ளேயே உணர்ந்து இறைவனின் திருவடிகளைச் சென்று அடையலாம்.`,
  },
  {
    id: 349, tantraId: 2, verseNumber: 348,
    tamil: `திரிகின்ற முப்புரஞ் செற்ற பிரானை
அரியனென் றெண்ணி அயர்வுற வேண்டா
புரிவுடை யாளர்க்குப் பொய்யலன் ஈசன்
பரிவொடு நின்று பரிசறி வானே`,
    transliteration: `tirikiṉṟa muppurañ ceṟṟa pirāṉai
ariyaṉeṉ ṟeṇṇi ayarvuṟa vēṇṭā
purivuṭai yāḷarkkup poyyalaṉ īcaṉ
parivoṭu niṉṟu paricaṟi vāṉē`,
    english: `348: The Lord is not Beyond Reach
Mighty is the Lord
The Flying Fortess He destroyed.
Thus despair not
That He is your reach beyond;
Sure is the Lord to seekers true
In them He abideth, Grace abounding.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-348-Second-Tantra-3.-Story-of-Linga.mp3',
    elaborationTamil: `எல்லா உயிர்களிடமும் இருக்கும் ஆணவம், கன்மம், மாயையாகிய மும்மலங்களை அழித்து அருளும் எம்பெருமான் ஈசன் கிடைப்பதற்கு மிகவும் அரிதானவன் என்று எண்ணிக்கொண்டு சோர்ந்து போக வேண்டாம். உண்மையான அன்புடன் தம்மை பூஜிக்கும் அடியவர்களுக்கு ஈசன் பொய்யானவன் அல்ல. பாடல் #347 ல் உள்ளபடி தனக்குள்ளேயே லிங்க உருவத்தையும் லிங்க தத்துவத்தையும் உணர்ந்து அன்போடு பூஜிக்கும் அடியவர்களின் அருகில் பேரன்புடன் பெருங்கருணையோடு நின்று அவர்களின் பக்திக்கு ஏற்ற பரிசை அருளுவான்.`,
  },
  {
    id: 350, tantraId: 2, verseNumber: 349,
    tamil: `ஆழி வலங்கொண் டயன்மால் இருவரும்
ஊழி வலஞ்செய்ய ஒண்சுட ராதியும்
ஆழி கொடுத்தனன் அச்சுதற்க் கவ்வழி
வாழி பிரமற்கும் வாள்கொடுத் தானே`,
    transliteration: `āḻi valaṅkoṇ ṭayaṉmāl iruvarum
ūḻi valañceyya oṇcuṭa rātiyum
āḻi koṭuttaṉaṉ accutaṟk kavvaḻi
vāḻi piramaṟkum vāḷkoṭut tāṉē`,
    english: `349: The Lord Blessed Aya and Mal
The Lord is the Primal One,
He is the Light Effulgent;
Seeking Him they went--Aya and Mal
Girdling the boundless oceans
And across the endless aeons;
And to Atchutha He granted the Disc Divine
And to Brahma, Jnana's Sword Eternal.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-349-Second-Tantra-3.-Story-of-Linga.mp3',
    elaborationEnglish: `Brahma, the creator, and Vishnu, the preserver, at one time contending for cosmic supremacy, battled indecisively around the sea-girt globe at numerous points for a countless number of years. Finally, Siva stood as a limitless Pillar of Flame in between them. Tired, they made a truce and agreed that he who would first behold either the peak or the base of the fire pillar was to be regarded as supreme. Vishnu took the form of a boar and burrowed deep into earth’s bottom. Brahma assumed the form of a hamsa bird (swan) and flew up high in the heavens. But neither saw either end of the fiery pillar. They realised their folly and worshipped Siva as supreme. Thereupon Siva blessed Vishnu with the chakra (discus), and Brahma with the sword (jnana).`,
    elaborationTamil: `கடல் போல் வலிமை கொண்ட பிரமன் திருமால் இருவரும் நெடுங்காலம் ஒளி வடிவாக இருக்கின்ற ஆதி இறைவனை வழிபட திருமாலுக்கு சக்ராயுதமும் பிரம்மனுக்கு வாளும் கொடுத்து அருளினான். உட்கருத்து: பாடல் #347 ல் உள்ளபடி அசையா சக்தியாகிய நற்சக்தியுடன் சேர முதல் சக்கரம் மூலாதாரத்தில் இருந்து கிளம்பும் அசையும் சக்தியான குண்டலினி கடல் போல் வலிமை கொண்ட 2வது சக்கரமாகிய பிரம்மன் வீற்றீருக்கும் சுவாதிட்டானம், 3வது சக்கரமாகிய திருமால் வீற்றிருக்கும் மணிப்பூரகத்தை உணர்ந்தும் அசையா சக்தியாகிய நற்சக்தியுடன் சேர்ந்து தனக்குள் லிங்க உருவத்தை உணர்ந்தும் தத்துவத்தை உணர்ந்தும் நெடுங்காலம் ஒளி வடிவாய் இருக்கும் ஆதி இறைவனை வழிபட்டால் திருமால் செய்யும் காக்கும் வேலையும் பிரம்மன் செய்யும் படைக்கும் வேலையையும் இறைவன் கொடுத்து அருளுவான். இதனை திருமந்திர பாடல் #302, பாடல் #321 ன் மூலம் அறிந்து கொள்ளலாம். உதாரணமாக பல புராண வரலாறுகளில் பல மகான்கள் சித்தர்கள் தங்கள் வாழ்க்கை வரலாற்றில் இறந்தவர்களை மீண்டும் மீட்டு படைக்கும் பிரம்மனின் தொழிலை செய்துள்ளார்கள். கர்மவினைகளின் படி இறக்கவேண்டியவர்களை காத்து காக்கும் திருமாலின் தொழிலை செய்துள்ளார்கள்.`,
  },
  {
    id: 351, tantraId: 2, verseNumber: 350,
    tamil: `தாங்கி இருபது தோளுந் தடவரை
ஓங்க எடுத்தவன் ஒப்பில் பெருவலி
ஆங்கு நெரித்தம ராவென் றழைத்தபின்
நீங்கா அருள்செய்தான் நின்மலன் தானே`,
    transliteration: `tāṅki irupatu tōḷun taṭavarai
ōṅka eṭuttavaṉ oppil peruvali
āṅku nerittama rāveṉ ṟaḻaittapiṉ
nīṅkā aruḷceytāṉ niṉmalaṉ tāṉē`,
    english: `350: Lord Blessed Ravana
Of peerless in might and shoulder twenty
Ravana the Giant lifted lofty mount Kailas;
With toe down, the Lord but gently pressed
And lo! the Giant screamed: "Lord Eternal."`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-350-Second-Tantra-3.-Story-of-Linga.mp3',
    elaborationEnglish: `The ten-headed giant Ravana, filled with great conceit over his might and prowess, put his 20 shoulders to Mount Kailas, the seat of Siva, in an attempt to lift it. Siva gently pressed His toe, and lo, the giant writhing in pain cried 'Oh, My Lord, You are eternal.' Thereupon Ravana played on his veena and evoked repentant melodies from the Sama Veda in adoration of the Lord. The Lord released him from under the weight of the mountain and blessed him.`,
    elaborationTamil: `இறைவனிடம் மிகுந்த பக்தி கொண்டிருந்த இலங்கையின் அரசன் ராவணன் ஒரு முறை அவரைப் பார்க்க எண்ணி கையிலாய மலைக்கு வந்தான். அவன் மானிடனாக இருப்பதால் உள்ளே விட முடியாது என்று வாயிற் காவலர்கள் தடுத்துவிட இறைவனைக் காண முடியவில்லையே என்ற கோபத்தில் தனது இருபது தோள்களால் கையிலாய மலையை தூக்கி இலங்கைக்கு எடுத்துச் செல்ல முயன்றான். ராவணனை நிகரில்லாத பேராற்றலை உடைய இறைவன் தமது திருவடியின் பெருவிரலால் சிறிது அழுத்தம் கொடுக்க அதன் அழுத்தத்தால் தாங்க முடியாத பெரும் வேதனையை அடைந்த இராவணன் கோபம் நீங்கி இறைவா எம்மைக் காப்பாற்று என்று உரக்க அழைத்தான். ஒரு மாசும் இல்லாத இறைவனும் அவனின் உண்மையான பக்தியை மெச்சி அவன் முன்னே தோன்றி அவனுக்கு என்றும் நீங்காத திருவருளை வழங்கி அருளினார். உட்கருத்து: உயிர்கள் பாடல் #347 ல் உள்ளபடி லிங்க தத்துவத்தையும் லிங்கத்தையும் தனக்குள் உணரும் போது மனிதனின் குணங்கள் பத்தும், ஞானேந்திரியங்கள் ஐந்தும் கன்மேந்திரியம் ஐந்தும் அவற்றால் ஏற்படங்கூடிய உலகப்பற்றுகள் இறைவனை அடையவிடாமல் தடுக்கும் போது இறைவா காப்பாற்று என்று உயிர்கள் வேண்டிட அவர்களுக்கு திருவடி தீட்சை வழங்கி அவர்களின் குணங்கள் ஞானேந்திரிய கன்மேந்திரியங்களை நீங்கி மீண்டும் வராமல் அருள் செய்வான். குணங்கள் உயிரை மனதால் பாதிப்பது குணங்களுக்கான விளக்கம்: காமம்-சிற்றின்பம் குரோதம்-கோபம் உலோபம்-பேராசை,கருமித்தனம் மோகம்-மாயை யால் நிகழும் மயக்க உணர்ச்சி, மதம்-கொள்கை,செருக்கு,வெறி,மதுபானக் களிப்பு,பெருமை மாச்சரியம்-பொறாமை,பகைமை டம்பம்-ஆடம்பரம் தர்ப்பம்-ஆசைகள், கர்வம் அசூயை-பொறாமை ஈரிசை-பிறர் துன்பம் கண்டு மகிழ்வது. ஞானேந்திரிய கர்மங்கள் என்பது ஐம்புலன்களான மெய், வாய், கண், மூக்கு, செவி இவற்றால் உயிரை பாதிப்பது, கன்மேந்திரியம் என்றால் செயல் மனித உடல் செய்யும் ஐந்து வகையான செயல்கள் இந்த ஐந்து வகையான செயல்கள் தொடர்ந்து செயல்படுவதால் ஆத்மா உடலோடு கலந்து இருக்கிறது.`,
  },
  {
    id: 352, tantraId: 2, verseNumber: 351,
    tamil: `உறுவது அறிதண்டி ஒண்மணற் கூட்டி
அறுவகை ஆன்ஐந்தும் ஆட்டத்தன் தாதை
செறுவகை செய்து சிதைப்ப முனிந்து
மறுமழு வால்வெட்டி மாலைபெற் றானே`,
    transliteration: `uṟuvatu aṟitaṇṭi oṇmaṇaṟ kūṭṭi
aṟuvakai āṉaintum āṭṭattaṉ tātai
ceṟuvakai ceytu citaippa muṉintu
maṟumaḻu vālveṭṭi mālaipeṟ ṟāṉē`,
    english: `351: The Lord Blessed Chandeswara
Dandi, that knew the way of Hereafter
Heaped sands into linga shape
And poured on it in adoration
The five products of his herd of cows;
His father seeing beat the boy
And kicked his fond image off;
Dandi flew into a blind rage
And smote the parent's leg with sword;
And lo! the Lord
Bedecked Dandi with His own garland of flowers forever to sport.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-351-Second-Tantra-3.-Story-of-Linga.mp3',
    elaborationTamil: `இந்த உலகத்தில் நடக்கும் செயல்கள் அனைத்துக்கும் காரணமாணவன் ஈசன் என்பதை அறிந்த தண்டி மணல்களைச் சேர்த்து ஒரு லிங்கம் செய்து அந்த மணல் லிங்கத்தை பசும்பாலால் வழிபட்டான். பசும்பால் வீணாவதைப் பார்த்துக் கோபப்பட்ட தண்டியின் தந்தை அந்த மணல் லிங்கத்தைக் காலால் எட்டி உதைத்தார். தந்தையின் இந்த செயலால் கோபம் கொண்ட தண்டி பசுவை மேய்க்க வைத்திருந்த கம்பை கையில் எடுக்க அந்தக் கம்பு மழு என்னும் ஆயுதமாக மாறியது. அந்த மழுவால் தன் தந்தையின் இரண்டு கால்களையும் வெட்டினான். தண்டீசனின் பக்தியைப் பார்த்த சிவபெருமான் தான் சூடியிருக்கும் கொன்றை மாலையை எடுத்து மகிழ்வுடன் சண்டேசுரருக்கு அணிவித்தான். உட்கருத்து: லிங்க உருவத்தையும் லிங்க தத்துவத்தையும் உணர்ந்து இந்த உலகத்தில் நடக்கும் செயல்கள் அனைத்துக்கும் காரணமாணவன் ஈசன் என்பதை அறிந்த உயிர் உடலில் இருந்து உயிரை பிரிக்கவும் மீண்டும் பிறவாமல் பிறவியை அறுக்கவும் தான் உணர்ந்த இறைவனை பூஜை செய்யும் பொழுது உடல் தனது ஐம்புலன்களால் அதை தடுக்கிறது. குண்டலினி சக்தி என்னும் கம்பால் ஐம்புலன்களை அடிக்க குண்டலினி என்னும் கம்பு மழுவாக மாறி உடலில் இருக்கும் இடகலை பிங்கலை முச்சுக்காற்றை வெட்டி உடலில் இருந்து உயிரை பிரிக்கிறது. உயிரின் பக்தியைப் பார்த்த சிவபெருமான் தான் சூடியிருக்கும் கொன்றை மாலையை எடுத்து மகிழ்வுடன் அந்த உயிருக்கு அணிவித்து தனது அடியவர்களின் தலைவன் என்னும் பதவி அளிப்பார்.`,
  },
  {
    id: 353, tantraId: 2, verseNumber: 352,
    tamil: `ஓடிவந் தெல்லாம் ஒருங்கிய தேவர்கள்
வாடி முகமும் வருத்தத்துத் தாஞ்சென்று
நாடி இறைவா நமேன்று கும்பிட
ஈடில் புகழோன் எழுகவென் றானே.`,
    transliteration: `ōṭivan tellām oruṅkiya tēvarkaḷ
vāṭi mukamum varuttattut tāñceṉṟu
nāṭi iṟaivā namēṉṟu kumpiṭa
īṭil pukaḻōṉ eḻukaveṉ ṟāṉē.`,
    english: `352: The Lord is the Refuge of the Heavenly Beings too
Faces drawn in care
Hearts stricken with grief
The Devas together rushed and cried;
"Lord! we bow to You"
And thus they prayed, prostrating low;
And He of Renown unsurpassed said;
"Arise, fear not."`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-352-Second-Tantra-3.-Story-of-Linga.mp3',
    elaborationEnglish: `Dandi was a brahmin boy who herded the cows of his village. Filled with intense devotion for Siva, Dandi would make. Lingam images out of sand from the river bed, milk the cows. ‘and offer the five products of cows to the Lingam in worship. The matter reached the ears of his father who, incensed at the way the precious. milk and other products of the cows were being wasted by his son, knocked the sand-made lingam with a blow from his leg. Such was Dandi’s devotion to Siva, that he was unable to contain the insult and smote the parent’s offending leg with a stroke of the sword. Siva appeared on the scene, and blessed Dandi, bestowing His own garland on him. Seeing Dandi’s father dead, the celestials appealed to Siva, who revived the parent. se`,
    elaborationTamil: `தேவர்கள் எல்லாம் தமக்குத் துன்பம் நேரும் போதெல்லாம் வாடிய முகத்துடன் மனம் வருந்தி இறைவனை விரும்பிச்சென்று இறைவா நமசிவாய என்று திருவடி பணிந்து கும்பிட ஈடு இணையில்லாத புகழை உடைய இறைவன் அவர்கள் மேல் கருணை கொண்டு எழுக என்று கூறி அவர்களின் துயரங்களைத் தீர்த்தான். உட்கருத்து: தனக்குள் லிங்க உருவத்தையும் லிங்க தத்துவத்தை உணர்ந்த உயிர்களுக்கு படைக்கும் பிரம்மாவின் தொழிலையும் காக்கும் திருமாலின் தொழிலையும் அளித்து அந்த உயிருக்கு தேவர்கள் என்னும் தகுதியை அளிக்கும் இறைவன் (இதனை திருமந்திர பாடல் எண் #349 மூலம் அறியலாம்) அவர்கள் உணர்ந்த லிங்க தத்துவத்தை இறைவா நமசிவாய என்று வழிபட ஈடு இணையில்லாத புகழை உடைய இறைவன் அவர்கள் மேல் கருணை கொண்டு எழுக என்று கூறி அவர்களின் உடலில் இருந்து உயிரை பிரித்து பிறவா நிலையை அந்த உயிருக்கு அளிப்பார். லிங்க வடிவின் தத்துவமும் இறைவனும் ஒன்றே என்பதை இப்பாடலின் மூலம் உணரலாம்.`,
  },
  {
    id: 354, tantraId: 2, verseNumber: 353,
    tamil: `தந்தைபி ரான்வெகுண் டாந்தக்கன் வேள்வியை
வெந்தழல் ஊடே புறப்பட விண்ணவர்
முந்திய பூசை முடியார் முறைகெட்டுச்
சிந்தினர் அண்ணல் சினஞ்செய்த போதே`,
    transliteration: `tantaipi rāṉvekuṇ ṭāntakkaṉ vēḷviyai
ventaḻal ūṭē puṟappaṭa viṇṇavar
muntiya pūcai muṭiyār muṟaikeṭṭuc
cintiṉar aṇṇal ciṉañceyta pōtē`,
    english: `353: What Befell Celestials at Daksha's Sacrifice
The Heavenly Father walked in boundless fury
Into the raging blaze of Daksha's sacrifice,
And lo! as the Lord in wrath rose
Helter-skelter ran the Devas
Deranged in directions all
--Their depraved worship unconsummated.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-353-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationEnglish: `Gods who participated in Daksha’s unholy sacrifice in an attempt to denigrate Siva, met with diverse dire fates—some losing their head, others the face, the nose, the shoulders, the hands or other limbs. Having described the fate of the gods—Brahma, Vishnu, the mountain-god, the sun-god, the moon-god, the fire-god, the goddess of learning, and the god of celestials (Indra), Tirumular exhorts, ‘Be thou constant in devotion to Siva.’’`,
    elaborationTamil: `அனைத்து உயிர்களுக்கும் தந்தையாகவும் தலைவனாகவும் இருக்கும் இறைவனுக்குத் தரும் அவிர்பாகத்தையும் அவருக்குத் தராமலும் அவரை மதிக்காமலும் இறைவனை அழிக்க மாபெரும் யாகம் ஒன்றை செய்தான் தக்கன். அவனது அறியாமையைக் கண்டு கோபமுற்ற ஈசன் அந்த யாகத்தையும் அவனது செறுக்கையும் அழித்து அவனக்கு நல் அறிவைக் கொடுக்க மறக்கருணை கொண்டு வீரபத்திரர் எனும் பைரவ அவதாரத்தை அந்த மாபெரும் யாகத்தின் தீயிலிருந்து வெளிப்பட்டார். அந்த மாபெரும் யாகத்தை செய்தவர்கள் மற்றும் அதை ஏற்க வந்த தேவர்களும் இறைவனின் கோப முக தரிசனத்தைப் பார்த்த மறுகணமே அவனது அருளன்றி இந்த யாகத்தைப் பூர்த்தி செய்ய முடியாதென்பதை அறிந்து இறைவனின் கோபத்தைக் கண்டு மிகவும் அஞ்சி தமது நிலை தடுமாறி எல்லாத் திசையிலும் சிதைந்து போனார்கள். உட்கருத்து: தாம் செய்யும் எந்த செயலானாலும் மனம் வாக்கு உடம்பு மூன்றையும் ஒருநிலைப்படுத்தி இறையருளுடன் செய்வது வேள்வியாகும். மனம், வாக்கு, உடம்பு மூன்றை மட்டுமே வைத்து இறையருள் இல்லாமல் செய்வது தக்கன் வேள்வியாகும்.`,
  },
  {
    id: 355, tantraId: 2, verseNumber: 354,
    tamil: `சந்தி செயக்கண் டெழுகின் றரிதானும்
எந்தை யிவனல்ல யாமே உலகினிற்
பந்தஞ்செய் பாசத்து வீழ்ந்து தவஞ்செய்ய
அந்தமி லானும் அருள்புரிந் தானே`,
    transliteration: `canti ceyakkaṇ ṭeḻukiṉ ṟaritāṉum
entai yivaṉalla yāmē ulakiṉiṟ
pantañcey pācattu vīḻntu tavañceyya
antami lāṉum aruḷpurin tāṉē`,
    english: `354: What Befell Hari
In a vain attempt to quell
The confusion that ensued
Hari rising bragged:
"Not He, but I am the beginning of things"
And so fell into this world below
A prey to Passion's consuming fetters;
Then repentant he performed tapas
And the Lord that has no beginning nor end
Bestowed His Grace on him.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-354-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationTamil: `தக்கன் யாகத்தையும் அதைச் செய்ய முற்பட்டவர்களையும் அதை ஏற்றுக்கொண்ட தேவர்களையும் இறைவனின் பைரவ அவதாரமான வீரபத்திரர் அளித்த தண்டனையை கண்டு யாகத்தீயில் இருந்து எழுந்து வந்த திருமால் இறைவனே தவறு செய்தவன் இவனல்ல உலகினில் பிறந்த சதியின் மேல் வைத்த பாசத்தாலும் கொண்ட பந்தத்தாலும் அறிவிழந்து இவன் செய்த யாகத்தின் அவிர்பாகத்தை ஏற்றுக்கொண்ட நாங்களே பெரும் தவறு செய்தவர்கள் எம்மை மன்னித்து அருளுங்கள் என்று கூறி இறைவனின் திருவடிகளில் விழுந்து தொழ என்றுமே இறப்பில்லாத இறைவனும் அவர்களுக்கு அருள் புரிந்தான். உட்கருத்து: மனம், வாக்கு, உடம்பு மூன்றையும் ஒருநிலைப்படுத்தி பந்த பாசத்தினால் செயல்களை செய்தால் அந்த செயல் இறையருள் இல்லாமல் பூர்த்தியாகாமல் இருக்கும் அதை உணர்ந்து உயிர்கள் பந்த பாசத்தில் இருந்து விடுபட்டு இறையருளுடன் செய்யும் போது இறைவன் அந்த உயிருக்கு அருள் செய்வான்.`,
  },
  {
    id: 356, tantraId: 2, verseNumber: 355,
    tamil: `அப்பரி சேயய னார்பதி வேள்வியுள்
அப்பரி சேயங்கி அதிசய மாகிலும்
அப்பரி சேயது நீர்மையை யுள்கலந்
தப்பரி சேசிவன் ஆலிக்கின் றானே`,
    transliteration: `appari cēyaya nārpati vēḷviyuḷ
appari cēyaṅki aticaya mākilum
appari cēyatu nīrmaiyai yuḷkalan
tappari cēcivaṉ ālikkiṉ ṟāṉē`,
    english: `355: To Each According to His Desert--the Way of Siva's
Justice
And so it befell at Daksha's sacrifice,
And so indeed it befell;
A wonder though it be,
Verily that is what there befell;
Thus does the Lord lend His Grace
In the knowledge of each according to his desert.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-355-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationTamil: `இறைவனை அழிக்க தக்கன் செய்த மாபெரும் யாகத்தில் மந்திரங்களுக்குக் கட்டுப்பட்டு அவிர்பாகங்களை ஏற்க வந்த பிரம்மன் மற்றும் தேவர்கள் அனைவருக்கும் அவரவர் தொழில்களைப் பரிசாக அளித்து அந்தத் தொழில்களைச் செய்யும் சக்தியாகவும் இருக்கும் இறைவனை அழிக்க யாகத்தில் மாபெரும் அக்னி வந்தது அதிசயமாக தெரிந்தாலும். தீயாகவும் தீயை வளர்க்க யாகத்தில் இடும் பொருட்களாகவும் அந்த பொருளின் தன்மையாகவும் அதனை ஏற்று ஆவியாக்குபவனும் இறைவனே. உட்கருத்து: உயிர்கள் நல்செயல்கள் செய்தால் நல்வினைகள் கிடைத்து சிவனின் அருளும், தீய செயல்கள் செய்தால் தீவினைகள் சேர்ந்து அதற்கான தண்டனைகளும் உயிருக்கு கிடைக்கும் இவை அனைத்திலும் சிவன் அணுவாய் கலந்திருப்பான். அனைத்தும் இறைவனே ஆவதால் நல்லவையானாலும் தீயவையானாலும் அவனின்றி எந்தச் செயலும் நிகழாது.`,
  },
  {
    id: 357, tantraId: 2, verseNumber: 356,
    tamil: `அப்பரி சேஅயன் மால்முதல் தேவர்கள்
அப்பரி சேயவ ராகிய காரணம்
அப்பரி சங்கி யுளநாளும் உள்ளிட்
டப்பரி சாகி அலர்ந்திருந் தானே`,
    transliteration: `appari cēayaṉ mālmutal tēvarkaḷ
appari cēyava rākiya kāraṇam
appari caṅki yuḷanāḷum uḷḷiṭ
ṭappari cāki alarntirun tāṉē`,
    english: `356: Gods Got What They Deserved
And thus it is with Aya, Mal and the rest of Gods;
And thus it is they came to what they are;
And thus it is that they are there;
And thus does the Lord sit serene within
To reward the heart that daily seeks Him true.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-356-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationTamil: `தக்கன் செய்த யாகத்தில் அவிர்பாகத்தைப் பரிசாகப் பெற்ற பிரம்மன் திருமால் மற்றும் அனைத்து தேவர்களும் இறைவனே தாமாக இருக்கும் காரணத்தை அறிந்து தமது அறியாமையால் பிழை செய்துவிட்டோமே என்று வருந்தி அவனது திருவருளை வேண்டி நின்றனர். அக்கினிதேவனும் தமக்குள் தீயாகவும் ஒளியாகவும் வெப்பமாகவும் என்னாளும் இருப்பவன் இறைவனே என்பதை உணர்ந்து அவனது திருவருளை வேண்டி நின்றான். அவர்களின் வேண்டுதலை ஏற்ற இறைவனும் அனைவரின் பிழைகளை மன்னித்து ஒளிமயமாகி எங்கும் வியாபித்து இருந்தான். உட்கருத்து: உயிர்கள் அறியாமையால் செய்யும் தவறுகளிலும் அணுவாய் கலந்திருக்கும் இறைவன் உயிர்கள் தன் தவறை உணரும் போது அவர்களை மன்னித்து அருள்செய்வான்.`,
  },
  {
    id: 358, tantraId: 2, verseNumber: 357,
    tamil: `அலர்ந்திருந் தானென் றமரர் துதிப்பக்
குலந்தரும் கீழங்கி கோளுற நோக்கிச்
சிவந்த பரமிது சென்று கதுவ
உவந்த பெருவழி யோடி வந்தானே`,
    transliteration: `alarntirun tāṉeṉ ṟamarar tutippak
kulantarum kīḻaṅki kōḷuṟa nōkkic
civanta paramitu ceṉṟu katuva
uvanta peruvaḻi yōṭi vantāṉē`,
    english: `357: The Lord Comes to Those Who Seek Him in Yoga Way
While the heavenly Beings sang of Him
As seated in rapture serene,
He came rushing
To me along the highway of bliss that opened up
As from Muladhara the Kundalini fire shot up
To the crimson spheres of Sahasrara
In the way that is yoga.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-357-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationTamil: `பாடல் #356 ல் உள்ளபடி அனைவரின் பிழைகளை மன்னித்து எங்கும் ஒளிமயமாகி வியாபித்து இருக்கும் சிவபெருமானை வானவர்கள் வணங்க அழுக்குகளையெல்லாம் எரித்து எதையும் தூய்மையாக்கும் அக்கினி தக்கன் யாகத்தில் கலந்து கொண்டு தூய்மை கெட்டதால் தன் குற்றம் நீங்க சிவனின் திருவடிகளை பற்றிக்கொள்ள சிவனும் அன்போடு அக்னிக்கு அருள் செய்ய ஓடிவந்தான். உட்கருத்து: உயிர்கள் அறியாமையால் செய்யும் தவறுகளை உணர்ந்து தன்னை திருத்திக்கொண்டு அந்த தவறில் அணுவாய் கலந்திருக்கும் இறைவனின் திருவடிகளை நினைத்து உள்ளத்தில் பற்றிக்கொள்ள இறைவன் அன்போடு அவர்களுக்கு அருள் செய்ய ஒடிவருவான்.`,
  },
  {
    id: 359, tantraId: 2, verseNumber: 358,
    tamil: `அரிபிர மந்தக்கன் அருக்க னுடனே
வருமதி வாலை வன்னிநல் இந்திரன்
சிரமுக நாசி சிறந்தகை தோள்தான்
அரனருள் இன்றி அழிந்தநல் லோரே`,
    transliteration: `aripira mantakkaṉ arukka ṉuṭaṉē
varumati vālai vaṉṉinal intiraṉ
ciramuka nāci ciṟantakai tōḷtāṉ
araṉaruḷ iṉṟi aḻintanal lōrē`,
    english: `358: For Want of Hara's Grace They Lost All
Lacking Lord's Grace
Many the high and handsome
That destruction and disfigurement met;
Thus Hari, Brahma, and Daksha
The Sun, Moon and Fire and Indra as well
All these Gods lost
Head, face, nose, hand and shoulder; some limb or other.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-358-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationTamil: `திருமால், பிரம்மன், தக்கன், சூரியன் அவனுடன் வரும் சந்திரன், சரஸ்வதி, அக்கினி, தேவர் தலைவனாகிய இந்திரன் ஆகிய தேவர்களின் தலை, முகம், மூக்கு, சிறப்பான கைகள் அவற்றைத் தாங்கும் தோள்கள் இறைவனின் அருள் இன்றி அறியாமையில் தக்கன் செய்த யாகத்தில் கலந்து கொண்டதனால் இறைவனின் சினத்தினால் அழிந்தது. பிறகு தமது பிழை உணர்ந்து இறைவனை வேண்டி அவற்றினைத் திரும்ப நலமுடன் பெற்றார்கள். உட்கருத்து: பாடல் #357ல் உள்ள உட்கருத்தின் படி அறியாமையால் செய்யும் தவறுகளை உணர்ந்து தன்னை திருத்திக்கொண்டு இறைவன் அருள் பெற்ற உயிர்கள் இறைவனை அடையும் வழிகளான பக்தி, யோக, கர்ம, யோகம் போன்ற மார்கங்களை மீண்டும் இறையருளால் செய்து இறைவனை அடையலாம்.`,
  },
  {
    id: 360, tantraId: 2, verseNumber: 359,
    tamil: `செவிமந் திரஞ்சொல்லுஞ் செய்தவத் தேவர்
அவிமந் திரத்தின் அடுக்களை கோலிச்
செவிமந் திரஞ்செய்து தாமுற நோக்குங்
குவிமந் திரங்கொல் கொடியது வாமே`,
    transliteration: `ceviman tirañcolluñ ceytavat tēvar
aviman tirattiṉ aṭukkaḷai kōlic
ceviman tirañceytu tāmuṟa nōkkuṅ
kuviman tiraṅkol koṭiyatu vāmē`,
    english: `359: Self-Seeking Mantra Has Fatal Consequences
If the holy Devas
Who should Upadesa mantra chant,
Instead in self-seeking power evoke
Sacrificial mantras in Japas numberless
That verily will spell
Their own deadly end.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-359-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `இறைவனுக்காக மந்திரங்களை செபித்து இறையருள் பெற்ற தேவர்கள் தக்கனின் யாகத்தில் இறையருள் இல்லாத மந்திரங்களை சொல்லி தங்களுக்குப் பெரும் பொருள் கிடைக்கும் நோக்கத்திலேயே குறியாக இருந்து செய்து குவித்த மந்திரங்கள் இறைவனது அருள் பெறாமல் செய்யப்பட்டமையால் அவர்களையே கொல்லும் கொடிய மந்திரங்களாக மாறிவிட்டன. உட்கருத்து: உயிர்கள் வேள்வி போல் செய்யும் செயல்கள் யாவும் இறையருளுடன் செய்தால் அவர்களை நல்வழிக்கு அழைத்துச் செல்லும் உலக ஆசைக்காக இறையருள் இல்லாமல் செய்யும் செயல்கள் யாவும் அவர்களுக்கு தீமைகளையே செய்யும்.`,
  },
  {
    id: 361, tantraId: 2, verseNumber: 360,
    tamil: `நல்லார் நவகுண்டம் ஒன்பதும் இன்புறப்
பல்லார் அமரர் பரிந்தருள் செய்கென
வில்லாற் புரத்தை விளங்கொரி கோத்தவன்
பொல்லா அசுரர்கள் பொன்றும் படிக்கே`,
    transliteration: `nallār navakuṇṭam oṉpatum iṉpuṟap
pallār amarar parintaruḷ ceykeṉa
villāṟ purattai viḷaṅkori kōttavaṉ
pollā acurarkaḷ poṉṟum paṭikkē`,
    english: `360: The Lord Destroyed Asuras to Protect the Sacrificial Rites
of Devas
The Immortal Many prayed to the Lord;
"O Lord ! protect the nine sacrificial pits
For the holy ones to delight"
And the Lord, who bending His Mountain -bow
Sent forth shafts of fire at Asura's city
Destroying the evil ones, never to rise again.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-360-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationTamil: `இறைவனின் அருள் வேண்டி வேள்விகள் அமைத்து தம்மை வணங்கும் நல்லவர்கள் அனைவரும் அனைத்துவித நலன்களும் பெற்று வாழ தயைகூர்ந்து அருள் புரியுமாறு பலகோடி தேவர்கள் அனைவரும் இறைவனை வேண்டிக்கொள்ள யாராலும் அழிக்க முடியாத அசுரர்களையும் அவர்களின் முப்புரங்களையும் வில்லேந்தி அம்புகொண்டு எரித்த எம்பெருமானும் கருணைகொண்டு உயிர்களை வாட்டும் பல கொடிய அசுரர்களையும் அழிக்கும் வலிமையை அவர்களுக்கு வழங்கி அருளினான். உட்கருத்து: உயிர்கள் எந்த செயலைச் செய்தாலும், மனம், வாக்கு, உடம்பு ஆகிய மூன்றும் ஒன்றாக வைத்து இறைவனை மட்டுமே நினைத்து அவனது திருவருளை கொடுக்குமாறு வேண்டிக்கொண்டு இறை அருள் பெற்று செய்தால் எத்தகைய வேலையையும் செய்யத்தடையாக இருப்பவற்றை அழிக்கும் சக்தியை இறைவன் உயிர்களுக்கு அருளுவான்.`,
  },
  {
    id: 362, tantraId: 2, verseNumber: 361,
    tamil: `தெளிந்தார் கலங்கினும் நீகலங் காதே
அளிந்தாங் கடைவதெம் ஆதிப் பிரானை
விளிந்தா னது தக்கன் வேள்வியை வீயச்
சுளிந்தாங் கருள்செய்த தூய்மொழி யானே`,
    transliteration: `teḷintār kalaṅkiṉum nīkalaṅ kātē
aḷintāṅ kaṭaivatem ātip pirāṉai
viḷintā ṉatu takkaṉ vēḷviyai vīyac
cuḷintāṅ karuḷceyta tūymoḻi yāṉē`,
    english: `361: Repent and Pray; Lord Blesses
Well may the learned in lores waver
But waver not;
Melt in love for our Primal Lord
And you shall have him sure;
He destroyed the unholy sacrifice of Daksha
And yet turning back
As they repented and prayed
He blessed them all,
He our Lord of holy speech.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-361-Second-Tantra-4.-Yagna-of-Thakkan.mp3',
    elaborationTamil: `இறையருள் இல்லாத தக்கன் செய்த வேள்வியில் கலந்து கொண்டு பின்பு இறைவனின் கோபத்திற்குள்ளாகி இறைவனால் தடுத்தாட்கொள்ளப்பட்டு அனைத்தும் இறைவனே என்று புரிந்துகொண்ட தேவர்கள் இப்படி ஒரு பிழை செய்துவிட்டோமே என்று கலங்கி இருக்கும் போது தேவர்களே நீங்கள் கலங்க வேண்டாம். இறைவன் மேல் உண்மையான அன்பு வைத்தவர்கள் அனைவருமே சென்று சேருமிடம் அவரது திருவடிகளே. தக்கனது வேள்வியை அழித்தது அவனது அறியாமையை நீக்கி அவனை ஆட்கொள்ள வேண்டும் என்ற கருணையினால்தான். தூய்மையான வாக்கை உடைய இறைவன் எது செய்தாலும் அது உயிர்களின் நன்மைக்கே ஆகும். உட்கருத்து: உயிர்கள் மனம், வாக்கு, உடல் ஆகிய மூன்றையும் ஒன்றாக வைத்து இறைவனை வேண்டி இறையருளோடு பல செயல்களைச் செய்தாலும் சில சமயங்களில் அவை தோல்வியடைவதைக் கண்டு மனம் கலங்க வேண்டாம். அவை தோல்வியடைவதும் உயிர்கள் மீது இருக்கும் இறைவனது மாபெரும் கருணையினால்தான். அதற்கும் பின்னால் இறைவன் அடியவருக்கு வழங்கும் அருள் இருக்கும்.`,
  },
  {
    id: 363, tantraId: 2, verseNumber: 362,
    tamil: `கருவரை மூடிக் கலந்தெழும் வெள்ளத்
திருவருங் கோவென் றிகல இறைவன்
ஒருவனும் நீருற ஓங்கொளி யாகி
அருவரை யாய்நின் றருள் புரிந் தானே`,
    transliteration: `karuvarai mūṭik kalanteḻum veḷḷat
tiruvaruṅ kōveṉ ṟikala iṟaivaṉ
oruvaṉum nīruṟa ōṅkoḷi yāki
aruvarai yāyniṉ ṟaruḷ purin tāṉē`,
    english: `362: The Lord Blesses the Two Who for Primacy Contended
When the swelling deluge at the end of Time
Swallowed the black mountain tops
Hari and Brahma fought
For primacy contending;
And then from amidst the floods arose
As an immeasurable mountain of Light
The One Lord, manifesting the Truth,
And thus blessing both.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-362-Second-Tantra-5.-Cataclysm.mp3',
    elaborationEnglish: `At the yugas end when cataclysmal floods swallowed the earth, Brahma, Vishnu and other denizens of the celestial world sought refuge in Siva, and Siva saved them from disaster.`,
    elaborationTamil: `பிரளய வெள்ளத்தில் பெரிய மலைகளும் நீரில் மூழ்கின. உலகெங்கும் படைத்தல் தொழில் நின்றது. அந்நேரத்தில் பிரமனும் திருமாலும் தங்கள் கடமையை செய்யாமல் யாமே தலைவர் என்று ஒருவருக்கொருவர் மாறுபட்டு கூறிக்கொண்டனர். சதாசிவமூர்த்தியான இறைவன் பேரொளி மிகுந்த நெருப்பு மலையாக நின்று வெள்ள நீரெல்லாம் வற்றச் செய்தான். சதாசிவமூர்த்தியின் ஆற்றலைக் கண்ட பிரமனும் திருமாலும் தலைவன் யார் என்பதை உணர்ந்தார்கள். தம் தவற்றை உணர்ந்த அவர்களுக்கு சதாசிவமூர்த்தி நெருப்பு மலையாக நின்று அருள் செய்தார்.`,
  },
  {
    id: 364, tantraId: 2, verseNumber: 363,
    tamil: `அலைகடல் ஊடறுத் தண்டத்து வானோர்
தலைவன் எனும்பெயர் தான்றலை மேற்கொண்டு
உலகார் அழற்கண் டுள்விழா தோடி
அலைவாயில் வீழாமல் அஞ்சலென் றானே`,
    transliteration: `alaikaṭal ūṭaṟut taṇṭattu vāṉōr
talaivaṉ eṉumpeyar tāṉṟalai mēṟkoṇṭu
ulakār aḻaṟkaṇ ṭuḷviḻā tōṭi
alaivāyil vīḻāmal añcaleṉ ṟāṉē`,
    english: `363: The Lord Saved Mortals
And as high amidst the surging flood
The Lord as Flaming Mountain stood
His primacy for the Gods to know
The mortal ones
Powerless to stand the Fire-Mountain's radiant glow
Rushed to the surging waters in trembling fear;
The Lord then said to them: "Fear not! you shall be saved."`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-363-Second-Tantra-5.-Cataclysm.mp3',
    elaborationTamil: `பாடல் #362ல் உள்ளபடி பேரோளி மிகுந்த நெருப்பு மலையாக இருந்த சதாசிவமூர்த்தி கடலை உடுறுவி கீழையும் வானத்தை ஊடுறுவி மேலேயும் இருந்து வானவர்கள் அனைவருக்கும் தலைவன் என்னும் பெயர் பெற்று உலகம் முழுவதும் நிறைந்த ஊழித்தீயில் உலக மக்கள் நெருப்புப் பிழம்பைப் பார்த்துப் பயந்து வெள்ள நீரில் விழுந்து விடாதபடிக்கு யாரும் அஞ்சாதீர்கள் என்று கூறி அருள் செய்தான்.`,
  },
  {
    id: 365, tantraId: 2, verseNumber: 364,
    tamil: `தண்கடல் விட்ட தமரருந் தேவரும்
எண்கடல் சூழெம் பிரானென் றிறைஞ்சுவர்
விண்கடல் செய்தவர் மேலெழுந் தப்புறங்
கண்கடல் செய்யுங் கருத்தறி யாரே.`,
    transliteration: `taṇkaṭal viṭṭa tamararun tēvarum
eṇkaṭal cūḻem pirāṉeṉ ṟiṟaiñcuvar
viṇkaṭal ceytavar mēleḻun tappuṟaṅ
kaṇkaṭal ceyyuṅ karuttaṟi yārē.`,
    english: `364: Lord is Ocean of Grace
As the Ocean's swell subsided;
The ocean of immortals and Devas sang;
"Praised be Our Lord;"
Little do they know
That He who created the ocean and the firmament
Rises beyond to the Ocean of his benignant grace.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-364-Second-Tantra-5.-Cataclysm.mp3',
    elaborationTamil: `உலகம் முழுவதும் நிறைந்து இருந்த குளிர்ந்த பிரளய கடல் நீர் வடிந்தது. வானகத்தவர்களும் தேவர்களும் கடல் போன்ற எங்கள் எண்ணங்களில் சிவத்தைப் பற்றிய நினைவே வெள்ளம் போல சூழ்ந்து இருக்க வேண்டும் என்று வேண்டினார்கள். கடல்நீரை விண்ணகம் வரை பரவச் செய்த இறைவனும் கடைக்கண் பார்வையால் அருள் புரிந்து பேரொளியாய் எழுந்தருளினன். இத்தகைய பிரளயத்தை ஏற்படுத்தி பின்பு அனைவருக்கும் அருள் செய்த இறைவன் திருவுள்ளத்தை யாரும் அறியவில்லை.`,
  },
  {
    id: 366, tantraId: 2, verseNumber: 365,
    tamil: `சமைக்கவல் லானைச் சயம்புவென் றேத்தி
அமைக்கவல் லாரிவ் வுலகத்து ளாரே
திகைத்தெண் ணீரிற் கடலொலி ஓசை
மிகைக்கொள அங்கி மிகாமைவைத் தானே`,
    transliteration: `camaikkaval lāṉaic cayampuveṉ ṟētti
amaikkaval lāriv vulakattu ḷārē
tikaitteṇ ṇīriṟ kaṭaloli ōcai
mikaikkoḷa aṅki mikāmaivait tāṉē`,
    english: `365: To Quell Rising Tides Lord Placed Primal Fire
The Lord, He creates all
Himself the Being Uncreated--
Who is there in the world below
That thinking thus holds Him to heart?
When the oceans ebbed and roared
He placed the Primal Fire to quell the tides;
How compassionate He was!`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-365-Second-Tantra-5.-Cataclysm.mp3',
    elaborationTamil: `பிரளயத்தின் போது எழுந்த கடலோசையைக் கேட்ட உலகத்தவர் திகைத்துப் போனார்கள். அங்கு பேரோளி மிகுந்த நெருப்பு மலையாக இருந்த சதாசிவமூர்த்தியை அனைத்தையும் படைத்து சுயம்புவாய் தோன்றியவனே என்று இறைவனை மனதில் வைத்து வழிபட்ட உலகத்தில் உள்ள உயிர்களுக்காக கடல்நீர் வெள்ளம் கடலோசை மேலும் அதிகரிக்காமல் இருக்க அந்த நீரில் அக்னியை உண்டாக்கினார் இறைவன். உட்கருத்து: பிரளயத்தை ஏற்படுத்தி அனைத்தையும் அழித்த இறைவன் தன்னை வழிபட்டு சரணடைந்த உயிர்களை காப்பாற்றினார்.`,
  },
  {
    id: 367, tantraId: 2, verseNumber: 366,
    tamil: `பண்பழி செய்வழி பாடுசென் றப்புறங்
கண்பழி யாத கமலத் திருக்கின்ற
நண்பழி யாளனை நாடிச்சென் றச்சிரம்
விண்பழி யாத விருத்திகொண் டானே.`,
    transliteration: `paṇpaḻi ceyvaḻi pāṭuceṉ ṟappuṟaṅ
kaṇpaḻi yāta kamalat tirukkiṉṟa
naṇpaḻi yāḷaṉai nāṭicceṉ ṟacciram
viṇpaḻi yāta viruttikoṇ ṭāṉē.`,
    english: `366: The Lord Severed Head of Brahma Who Sinned
Brahma that is seated on the lotus comely
Sauntered in the Lord's path in manner unseasonable
--The sinful wretch!
The Lord sought Him
And in his severed head gathered alms
In ways the Gods approved.`,
    elaborationTamil: `இறைவனை ஏற்காமல் அவரை குற்றப்படுத்தும் வழிகளைப் பின்பற்றி நடக்கும் உயிர்களை பிரளய காலத்தில் மாபெரும் அழிவிலிருந்து காப்பாற்ற தன் மேல் உண்மையான அன்பை வைக்க முடியாதபடி அந்த உயிர்களின் தலையின் உச்சியில் இருந்து ஆட்சி செய்யும் ஆணவத்தை அழித்து அவர்களையும் ஆட்கொண்டு விண்ணுலகத் தேவர்களும் குற்றம் கூற முடியாதபடி புதிய உலகங்களையும் உயிர்களையும் உருவாக்கினான். உட்கருத்து: பிரளய காலத்தில் தம் மீது அன்புகொண்ட அடியவர்களை மட்டுமே காப்பாற்றுவான் என்று இல்லாமல் தம்மை பழிக்கும் உயிர்களையும் காப்பாற்றும் பெரும் கருணை கொண்டவன் இறைவன். பிரளய காலத்தில் தம் மீது அன்பு கொள்ளாத பிற உயிர்களின் தலையில் இருக்கும் அகங்காரம் ஆணவத்தை அழித்து அந்த உயிர்களையும் ஆட்கொண்டு அருளும் இறைவன் பிறகு புதியதாக உலகங்களையும் உயிர்களையும் உருவாக்கி அருளுகின்றான்.`,
  },
  {
    id: 368, tantraId: 2, verseNumber: 367,
    tamil: `மால்போ தகனென்னும் வண்மைக்கிங் காங்காரங்
கால்போதகங் கையினோ டந்தரச் சக்கர
மேல்போக வெள்ளி மலைஅம ராபதி
பார்ப்போக மேழும் படைத்துடை யானே`,
    transliteration: `mālpō takaṉeṉṉum vaṇmaikkiṅ kāṅkāraṅ
kālpōtakaṅ kaiyiṉō ṭantarac cakkara
mēlpōka veḷḷi malaiama rāpati
pārppōka mēḻum paṭaittuṭai yāṉē`,
    english: `367: Through Arrogance Mal Lost His Chakra
Filled with arrogance as Guru Supreme
Mal vaunted his egoism about;
Then away flew his heavenly discus,
Atop the Silver Mountains
Of the Lord of Celestial Beings
That created the seven worlds of delight.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-367-Second-Tantra-6.-Benefits-of-Chakra.mp3',
    elaborationEnglish: `Then the Lord of the Silver Mountain made the discus fly away And it orbited around the seven worlds.

Vishnu worshipped Siva who granted him the powerful discus. But such was the potency of the weapon that it had to be. split by Siva — one half going Vishnu and the other half to Sakti, nonseparate on Siva's side.`,
    elaborationTamil: `திருக்கயிலாய வெள்ளி மலையின் மீது அமர்ந்திருக்கும் பிறப்பு இறப்பு இல்லாத இறைவன். ஏழு உலகங்களை படைத்து அந்த உலக தொழில்கள் சீராக நடைபெற திருமாலுக்கு கை பெருவிரலினை ஒட்டி அந்தரத்தில் பறப்பது போல் சக்கரம் தந்து அருளினான். இவ்வுலக தொழில்கள் சீராக நடைபெற்றுக்கொண்டிருக்கும் போது அகங்காரத்தினால் ஏதேனும் தடை ஏற்பட்டால் திருமால் தனது சக்கராயுதத்தால் அகங்காரத்தை அழித்து இவ்வுலகைக் காப்பான்.`,
  },
  {
    id: 369, tantraId: 2, verseNumber: 368,
    tamil: `சக்கரம் பெற்றுநல் தாமோ தரந்தானும்
சக்கரந் தன்னைத் தரிக்கவொண் ணாமையால்
மிக்கரன் தன்னை விருப்புடன் அர்ச்சிக்கத்
தக்கநற் சக்தியைத் தான்கூறு செய்ததே`,
    transliteration: `cakkaram peṟṟunal tāmō tarantāṉum
cakkaran taṉṉait tarikkavoṇ ṇāmaiyāl
mikkaraṉ taṉṉai viruppuṭaṉ arccikkat
takkanaṟ caktiyait tāṉkūṟu ceytatē`,
    english: `368: The Lord Split Power of Chakra
He bestowed on Damodara the divine discus,
But potent far was it for him to hold
And so he prayed to the Lord in fervour
And the Lord split its power in twain.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-368-Second-Tantra-6.-Benefits-of-Chakra.mp3',
    elaborationTamil: `பாடல் #367ல் உள்ளபடி இறைவனிடம் பெற்ற உலகைக்காக்கும் வலிமை மிக்க சக்கரத்தை தனது கரத்தில் தாங்கும் சக்தி இல்லாததால் திருமால் அனைத்திலும் மேலான வலிமையுடைய இறைவனை அன்புடன் அர்ச்சனை செய்து வேண்டிக்கொள்ள அவனது வேண்டுதலுக்கு மனமிறங்கிய இறைவனும் தனது சக்தியிலிருந்து ஒரு பகுதியை திருமாலுக்குக் கொடுத்து சக்கரத்தைத் தாங்கும் வல்லமை பெறச்செய்து அருளினான்.`,
  },
  {
    id: 370, tantraId: 2, verseNumber: 369,
    tamil: `கூறது வாகக் குறித்துநற் சக்கரங்
கூறது செய்து கொடுத்தனன் மாலுக்குக்
கூறது செய்து கொடுத்தனன் சத்திக்குக்
கூறது செய்து தரித்தனன் கோலமே`,
    transliteration: `kūṟatu vākak kuṟittunaṟ cakkaraṅ
kūṟatu ceytu koṭuttaṉaṉ mālukkuk
kūṟatu ceytu koṭuttaṉaṉ cattikkuk
kūṟatu ceytu tarittaṉaṉ kōlamē`,
    english: `369: The Lord Split Power of Chakra
Splitting thus the power of goodly Chakra
One part He gave to Vishnu,
One part He gave to Sakti,
And that part He on His forehead assumed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-369-Second-Tantra-6.-Benefits-of-Chakra.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உலகைக்காத்து உலகத்தொழில்கள் சீராக நடைபெற இறைவன் தனது ஆற்றலின் ஒரு பகுதியில் சக்கரத்தை படைத்தார். தனது ஆற்றலின் ஒரு பகுதியான சக்கரத்தை திருமாலுக்கு கொடுத்தாருளினார். திருமால் அந்த சக்கரத்தை தாங்கும் வலிமை பெறுவதற்காக தமது சக்தியிலிருந்து ஒரு பகுதியையே கொடுத்து அருளினார். தனது ஆற்றலின் ஒரு பகுதியாக இருந்த சக்கரமும் அதன் சக்தியையும் திருமாலுக்கு கொடுத்தாலும் சக்கரமும் அதன் சக்தியாகவும் இருப்பவர் இறைவனே.`,
  },
  {
    id: 371, tantraId: 2, verseNumber: 370,
    tamil: `தக்கன்றன் வேள்வி தகர்த்தநல் வீரர்பால்
தக்கன்றன் வேள்வியில் தாமோ தரந்தானுஞ்
சக்கரந் தன்னைச் சசிமுடி மேல்விட
அக்கி உமிழ்ந்தது வாயுக் கரத்திலே`,
    transliteration: `takkaṉṟaṉ vēḷvi takarttanal vīrarpāl
takkaṉṟaṉ vēḷviyil tāmō tarantāṉuñ
cakkaran taṉṉaic cacimuṭi mēlviṭa
akki umiḻntatu vāyuk karattilē`,
    english: `370: At Daksha's Sacrifice Chakra Lost Power
At the crescent-bedecked head of Valiant Lord,
That destroyed the depraved sacrifice of Daksha,
Damodara aimed his discus;
And then the doughty Lord sent forth a sneeze;
And lo! a gusty tempest blew
And down fell discus, powerless against Supreme God.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-370-Second-Tantra-6.-Benefits-of-Chakra.mp3',
    elaborationTamil: `அறியாமையால் இறைவனை அழிக்க தக்கன் செய்த பெரிய வேள்வியை இறைவனின் அவதாரமான வீரபத்திரர் அழித்துத் தகர்த்தார். அப்போது வந்திருந்த திருமால் பிறை சந்திரனைச் சூடியிருக்கும் வீரபத்திரர் இறைவனின் அவதாரம் என்பதை உணராமல் வேள்வியை முறையின்றி அழித்துவிட்டதாக எண்ணி சக்கராயுதத்தை வீரபத்திரரின் பிறை சூடிய தலையை நோக்கி ஏவினான். அதைப் பார்த்த வீரபத்திரர் தமது கண்களில் நெருப்பு உமிழ அந்தச் சக்கரத்தைப் பார்த்து வாயிலிந்து ஒரு உக்கிர மிரட்டல் விட சக்கரம் வலுவிழந்து கீழே விழுந்தது. குறிப்பு: பாடல் #369ல் உள்ளபடி தனது ஆற்றலின் ஒரு பகுதியாக இருந்த சக்கரமும் அதன் சக்தியையும் திருமாலுக்கு கொடுத்தாலும் சக்கரமும் அதன் சக்தியாகவும் இருப்பவர் இறைவனே ஆகையால் இறைவனின் அவதாரமாய் இருந்த வீரபத்திரரின் கட்டளைக்கிணங்க சக்கரம் வலுவிழந்து கீழே விழுந்தது.`,
  },
  {
    id: 372, tantraId: 2, verseNumber: 371,
    tamil: `எலும்புங் கபாலமும் ஏந்தி எழுந்த
வலம்பன் மணிமுடி வானவ ராதி
எலும்புங் கபாலமும் ஏந்தில நாகில்
எலும்புங் கபாலமும் இற்றுமண் ணாமே`,
    transliteration: `elumpuṅ kapālamum ēnti eḻunta
valampaṉ maṇimuṭi vāṉava rāti
elumpuṅ kapālamum ēntila nākil
elumpuṅ kapālamum iṟṟumaṇ ṇāmē`,
    english: `371: Why The Lord Wears Skull and Bone
He is the Lord of all Celestial Beings,
Who wear bejewelled crowns of dazzling beauty;
But the Lord did bedeck Himself in Skull and Bone
How is it?
If He bears not skull and bone.
Dust unto dust will theirs be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2021/08/Song-371-Second-Tantra-7.-Bones-and-Skulls.mp3',
    elaborationEnglish: `Siva wears the garland of skeletons and skulls strung from crowned heads of the celestials. Why does He do so? That they may not turn into dust forever; that they may yet be redeemed.`,
    elaborationTamil: `ஊழிக்காலத்தில் மனித உடலின் எலும்புகளையும் மண்டையோடுகளையும் மாலையாகத் தரித்து எழுந்தருளும் இறைவன் வீரர்களுக்கெல்லாம் மிகச் சிறந்த வீரனும் மணிமுடி சூடிய விண்ணுலகத் தேவர்களுக்கெல்லாம் முதன்மையானவனும் ஆவான். ஊழிக்காலத்தில் இறைவன் மானிட உடலின் எலும்புகளையும் மண்டையோடுகளையும் ஏந்தி நிற்கவில்லை என்றால் அனைத்து உயிர்களின் எலும்புகளும் மண்டையோடுகளும் மண்ணோடு மண்ணாக மக்கிப் போய் அழிந்துவிடும். உட்கருத்து: ஊழிக்காலத்தில் (பிரளயம்) உயிர்கள் மொத்தமாக சுவடின்றி மண்ணோடு மண்ணாக அழிந்து போய்விடாமல் காக்கும் மாபெரும் கருணையினால் இறைவனே மனித உடலின் எலும்புகளையும் மண்டையோடுகளையும் தாங்கி நிற்கின்றான். அப்படி அவன் நிற்கவில்லையெனில் உயிர்களின் சுவடுகூட மிஞ்சாது மொத்த உலகமும் அழிந்துபோய்விடும்.`,
  },
  {
    id: 373, tantraId: 2, verseNumber: 372,
    tamil: `பிரமனும் மாலும் பிரானேநான் என்னப்
பிரமன்மால் தங்கள்தம் பேதைமை யாலே
பரமன் அனலாய்ப் பரந்துமுன் நிற்க
அரனடி தேடி அரற்றுகின் றாரே.`,
    transliteration: `piramaṉum mālum pirāṉēnāṉ eṉṉap
piramaṉmāl taṅkaḷtam pētaimai yālē
paramaṉ aṉalāyp parantumuṉ niṟka
araṉaṭi tēṭi araṟṟukiṉ ṟārē.`,
    english: `372: Brahma and Mal Seek His Feet
In ignorance gross, Brahma and Mal
Each bragged Himself as Lord Supreme;
Then as a pillar of Fire the Lord stood before them
And they search and scream
In vain His Feet to behold.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-372-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationEnglish: `The story of Brahma and Vishnu vainly seeking to see the peak and bottom of Siva, who stood before them as a monument of fire, is again recounted here.`,
    elaborationTamil: `பிரளயம் முடிந்து புதிய உலகங்கள் உருவாகிய காலத்தில் உலகங்களில் எல்லாம் புதிய உயிர்களைப் படைப்பதால் தாமே இறைவன் என்று பிரம்மனும், அந்த உயிர்களை எல்லாம் காப்பதால் தாமே இறைவன் என்று திருமாலும் அறியாமையால் ஒருவருக்கொருவர் எண்ணிக்கொண்டு இருந்தார்கள். அப்போது இறைவன் அவர்களின் முன்பு ஒரு மாபெரும் தீப்பிழம்பாக வந்து நின்று இப்பிழம்பின் அடி அல்லது உச்சியைக் காணுபவரே இறைவன் என்று கூற இருவரும் தீப்பிழம்பின் அடியையோ உச்சியையோ காண இயலாமல் புலம்ப ஆரம்பித்தனர்.`,
  },
  {
    id: 374, tantraId: 2, verseNumber: 373,
    tamil: `ஆமே ழுலகுற நின்றேம் அண்ணலுந்
தாமே ழுலகில் தழற்பிழம் பாய்நிற்கும்
வானே ழுலகுறும் மாமணி கண்டனை
நானே அறிந்தேன் அவனாண்மை யாலே`,
    transliteration: `āmē ḻulakuṟa niṉṟēm aṇṇalun
tāmē ḻulakil taḻaṟpiḻam pāyniṟkum
vāṉē ḻulakuṟum māmaṇi kaṇṭaṉai
nāṉē aṟintēṉ avaṉāṇmai yālē`,
    english: `373: But I Knew Lord, By His Grace Abounding
Yet I knew the Lord
Through His Grace abounding;
He who fills the seven heavens
He who stood as Pillar of Fire
The seven worlds pervading,
He of the bejewelled throat.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-373-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `பிரம்மனும் திருமாலும் அடியையோ உச்சியையோ காண முடியாத அளவிற்கு ஈரேழு பதினான்கு உலகங்களையும் கடந்து நிற்கின்றான் எம்பெருமான் சதாசிவமூர்த்தி. அவன் தாமாகவே ஏழுலகிற்கும் தீப்பிழம்பாக நிற்கின்றான். ஏழுலகமும் வியாபித்திருக்கும் வானத்திலும் மாபெரும் ஒளிப்பிழம்பாக ஊடுருவி நிற்பவன் நீலநிறமடைந்த கழுத்தை உடைய சிவபெருமான். இறைவன் என்னை ஆட்கொண்ட இறைதன்மையாலே நானும் இதை அறிந்தேன்.`,
  },
  {
    id: 375, tantraId: 2, verseNumber: 374,
    tamil: `ஊனாய் உயிராய் உணர்வங்கி யாய்முன்னஞ்
சேணாய்வா னோங்கி திருவுரு வாய் அண்டத்
தாணுவும் ஞாயிறுந் தண்மதி யுங்கடந்
தாண்முழு தண்டமு மாகிநின் றானே`,
    transliteration: `ūṉāy uyirāy uṇarvaṅki yāymuṉṉañ
cēṇāyvā ṉōṅki tiruvuru vāy aṇṭat
tāṇuvum ñāyiṟun taṇmati yuṅkaṭan
tāṇmuḻu taṇṭamu mākiniṉ ṟāṉē`,
    english: `374: Lord is Omnipresent
The Lord is life, body and consciousness
Fire that enveloped the firmament far
Transcending sun and moon
He pervades the Cosmic space--
Holy thus His Form of yore
Support of Universe vast.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-374-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `சதாசிவமூர்த்தியாகிய இறைவன் ஒருவனே அனைத்து உயிர்களின் உடம்பாகவும் உயிராகவும் உணர்வாகவும் உள்ளிருக்கும் நெருப்பாகவும் மண்ணுக்கும் விண்ணுக்கும் ஓங்கி நின்ற தீப்பிழம்பு உருவமாகவும் அண்டங்கள் அனைத்தையும் தாங்கி நிற்கும் தூணாகவும் சூரியனாகவும் குளிர்ந்த சந்திரனாகவும் பரவி இருக்கின்ற அண்டங்கள் மொத்தமும் தாமாகவும் நிற்கின்றான்.`,
  },
  {
    id: 376, tantraId: 2, verseNumber: 375,
    tamil: `நின்றான் நிலமுழு தண்டத்துள் நீளியன்
அன்றே யவன்வடி வஞ்சின ராய்ந்தது
சென்றார் இருவர் திருமுடி மேற்செல
நன்றாங் கழலடி நாடவொண் ணாதே.`,
    transliteration: `niṉṟāṉ nilamuḻu taṇṭattuḷ nīḷiyaṉ
aṉṟē yavaṉvaṭi vañciṉa rāyntatu
ceṉṟār iruvar tirumuṭi mēṟcela
naṉṟāṅ kaḻalaṭi nāṭavoṇ ṇātē.`,
    english: `375: The Two Saw not His Form Entire
He stood filling Cosmic space
And the two in fear trembled
They went searching His Form entire
The one seeking the crown
The other His Feet
Neither found them.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-375-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `மண்ணுலகிலிருந்து அண்டங்கள் அனைத்தையும் தன்னுள் அடக்கிக்கொண்டு விண்ணுலகமும் தாண்டி நீண்டு வளர்ந்த தீப்பிழம்பாக நின்றான் சதாசிவமூர்த்தி. அவனது அக்னி உருவத்தை ஆராய முற்பட்டு பிரம்மன் இறைவனின் திருமுடியைக் காணவும் திருமால் இறைவனின் திருவடியைக் காணவும் சென்றனர். பிரம்மன் மேல் செல்ல செல்ல இறைவனின் திருமுடி மேலே வளர்ந்து கொண்டே இருக்க திருமால் கீழே செல்ல செல்ல நன்மையை அருளும் இறைவனின் கழல்கள் அணிந்த திருவடி கீழே வளர்ந்து கொண்டே இருந்து இருவருக்கும் எதையும் காண இயலவில்லை. உள்விளக்கம்: இறைவனை உணர்ந்தால் இறைவன் எந்த ரூபத்தில் இருந்தாலும் இறைவனை அறியலாம். இறைவனை ஆராய்ச்சி செய்து தெரிந்து கொள்ள முயன்றால் அவரை அறிய இயலாது.`,
  },
  {
    id: 377, tantraId: 2, verseNumber: 376,
    tamil: `சேவடி ஏத்துஞ் செறிவுடை வானவர்
மூவடி தாவென் றானும் முனிவரும்
பாவடி யாலே பதஞ்செய் பிரமனுந்
தாவடி யிட்டுத் தலைப்பெய்து மாறே`,
    transliteration: `cēvaṭi ēttuñ ceṟivuṭai vāṉavar
mūvaṭi tāveṉ ṟāṉum muṉivarum
pāvaṭi yālē patañcey piramaṉun
tāvaṭi yiṭṭut talaippeytu māṟē`,
    english: `376: The Two Contended For Primacy
Vishnu, adored of the Devas,
That asked of Mahabali for three feet land
And Brahma
Whom the rishis in hymnal praise please,
The two in ego contended
For primacy to gain.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-376-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `இறைவனின் சிவந்த திருவடிகளை போற்றி வணங்கும் பலகோடி தேவர்களும், மாபலியிடம் மூன்று அடி நிலம் தா என்று கேட்டு வென்ற திருமாலும் இறைவனிடம் அருள் வேண்டி தவமிருக்கும் முனிவர்களும் இறைவன் வகுத்துக்கொடுத்த வேதங்களை ஓதி உயிர்களைப் படைக்கும் பிரம்மனும் எவ்வளவு தூரம் தான் அலைந்து தேடினாலும் இறைவனின் திருவடிகளையோ திருமுடியையோ காண இயலாது. உள்விளக்கம்: தேவர்கள், முனிவர்கள், திருமால், பிரம்மா என்று எவ்வளவு உயர்ந்த இறைநிலையில் இருந்தாலும் நானே செய்கிறேன் என்ற எண்ணத்துடன் இறைவனை தனக்குள் உணராமல் வெளியில் தேடினால் இறைவனை காண இயலாது.`,
  },
  {
    id: 378, tantraId: 2, verseNumber: 377,
    tamil: `தானக் கமலத் திருந்த சதுமுகன்
தானக் கருங் கடல் வாழித் தலைவனும்
ஊனத்தின் உள்ளே உயிர்போல் உணர்கின்ற
தானப் பெரும்பொருள் தன்மைய தாமே`,
    transliteration: `tāṉak kamalat tirunta catumukaṉ
tāṉak karuṅ kaṭal vāḻit talaivaṉum
ūṉattiṉ uḷḷē uyirpōl uṇarkiṉṟa
tāṉap perumporuḷ taṉmaiya tāmē`,
    english: `377: The Lord Animates Within Brahma and Vishnu Also
The four headed God on lotus seated
The comely lord on dark sea sleepeth
They both are of the essence same
Of the One Great who cognises all,
As unto life within the fleshly body.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-377-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `நான்கு முகங்களோடு தாமரை மலரை இருப்பிடமாகக் கொண்டு அமர்ந்திருக்கும் பிரம்மனும் கருமையான நிறத்தோடு பாற்கடலை இருப்பிடமாகக் கொண்டு படுத்திருக்கும் திருமாலும் ஊழிக்காலத்தில் அழிவின் தலைவனாக இருக்கும் உருத்திரனும், உயிர்களின் உடலாகவும் உயிராகவும் உயிரின் உணர்வாகவும் உயிர்களுடனே கலந்து இருக்கும் மாபெரும் பரம்பொருளாகிய சதாசிவமூர்த்தியின் தன்மையை ஒத்தவர்கள் ஆக முடியாது.`,
  },
  {
    id: 379, tantraId: 2, verseNumber: 378,
    tamil: `ஆலிங் கனஞ்செய் தெழுந்த பரஞ்சுடர்
மேலிங்ஙன் வைத்ததோர் மெய்ந்நெறி முன்கண்
டாலிங் கனஞ்செய் துலகம் வலம்வருங்
கோலிங் கமைஞ்சருள் கூடலு மாமே`,
    transliteration: `āliṅ kaṉañcey teḻunta parañcuṭar
mēliṅṅaṉ vaittatōr meynneṟi muṉkaṇ
ṭāliṅ kaṉañcey tulakam valamvaruṅ
kōliṅ kamaiñcaruḷ kūṭalu māmē`,
    english: `378: Know God's Truth and Be Blessed Now and Hereafter
Know afore
The Truth of Divine flame that enveloped all
And hold fast unto that;
Then may you receive
The sceptre to hold domain over earth
And the Grace to follow in heaven above.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-378-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `அண்டங்கள் அனைத்தலும் இரண்டறக்கலந்து எழுந்து நின்ற மாபெரும் தீப்பிழம்பான பரம்பொருள் உயிர்கள் தம்மை நாடி வந்து சேர பெருங்கருணை கொண்டு உண்மையான வழிமுறைகளை கொடுத்து உலகத்துப்பொருட்கள் எல்லாவற்றிலும் கலந்து உலா வருகிறது. இறைவனை அடையவேண்டும் என்ற உயர்ந்த குறிக்கோளுடன் அந்த உண்மையான வழிமுறைகளை பின்பற்றினால் எல்லாவற்றிலும் கலந்திருக்கும் அடிமுடி காண முடியாத பரம்பொருள் இறைவனை உணரலாம். உட்கருத்து: அடிமுடி காண முடியாத அளவு மிகப்பெரும் மகோன்னதம் மிக்கவனாக இறைவன் காட்டிய நெறி வழிகளைப் பின்பற்றி சென்றால் எல்லாவற்றிலும் கலந்திருக்கும் அடிமுடி காண முடியாத பரம்பொருள் இறைவனை உணரலாம்.`,
  },
  {
    id: 380, tantraId: 2, verseNumber: 379,
    tamil: `வாள்கொடுத் தானை வழிபட்ட தேவர்கள்
ஆள்கொடுத் தெம்போல் அரனை அறிகிலர்
ஆள்கொடுத் தின்பங் கொடுத்துக் கோளாகத்
தாள்கொடுத் தானடி சாரகி லாரே`,
    transliteration: `vāḷkoṭut tāṉai vaḻipaṭṭa tēvarkaḷ
āḷkoṭut tempōl araṉai aṟikilar
āḷkoṭut tiṉpaṅ koṭuttuk kōḷākat
tāḷkoṭut tāṉaṭi cāraki lārē`,
    english: `379: Only in Self-Surrender Will the Lord Be Truly Known
The Lord granted the Sword of Protection
To Beings Celestial that prayed to Him
But they know Him not entire
As I who His vassal became;
He granted me Himself
He granted me Bliss
And His Feet's grace as final prize;
They approach not His Feet thus.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-379-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `ஒளிபொருந்திய உடலைக் கொடுத்த இறைவனை வழிபடுகின்ற தேவர்கள் எம்மைப் போல இறைவனிடம் தம்மையே ஒப்படைத்தாலும் இறைவனின் தன்மையை அறிய மாட்டார்கள். இறைவனிடம் தன்னைக் கொடுத்தால் இறைவனை அறியலாம். தன்னைக் கொடுத்தவர்க்கு இறைவனும் தன்னையும் தந்து பேரின்பத்தையும் தருவான். அந்த இன்பத்திலேயே மூழ்கித் தம்மை மறந்துவிடாதபடி வலிமை பெறும் பொருட்டு தம் திருவடியையும் தருகிறான் இறைவன். ஆனால் தேவர்கள் யாம் இறைவனின் திருவடியை சார்ந்திருப்பதைப்போல தேவர்கள் இறைவனின் திருவடியைச் சார்ந்திருக்கவில்லை.`,
  },
  {
    id: 381, tantraId: 2, verseNumber: 380,
    tamil: `ஊழி வலஞ்செய்தங் கோரும் ஒருவற்கு
வாழி சதுமுகன் வந்து வெளிப்படும்
வீழித் தலைநீர் விதித்தது தாவென
ஊழிக் கதிரோன் ஒளியைவென் றானே`,
    transliteration: `ūḻi valañceytaṅ kōrum oruvaṟku
vāḻi catumukaṉ vantu veḷippaṭum
vīḻit talainīr vitittatu tāveṉa
ūḻik katirōṉ oḷiyaiveṉ ṟāṉē`,
    english: `380: Lord Decreed Brahma's Fate
Inscrutable is the Lord
He defies Time's infinite vistas;
The four-headed Brahma prayed;
"Do reveal Yourself
And on this bowed head decree my Fate,"
And the Lord,
Surpassing far the dazzle of the sun at end of Time
Revealed Himself as Light Pure.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-380-Second-Tantra-8.-Searching-the-Feet-and-Head.mp3',
    elaborationTamil: `ஊழிக்காலம் முடிந்ததும் இறைவனை சரணடைந்து ஒளி உடலோடு வாழும் அடியவர்களில் ஒருவரை நான்கு முகங்கள் கொண்டு படைத்தல் தொழில் புரியும் பிரம்மனின் தொழிலை செய்ய இறைவன் தேர்ந்தெடுக்கின்றான். புதியதாக பிரம்மனின் தொழில் பெற்ற அடியவரும் இறைவனை நாடி வந்து என்ன வேலை செய்ய வேண்டும் என்று அதைத் தந்தருளுங்கள் என்று வேண்டிக்கொள்ள ஊழிக்காலத்தில் அனைத்தையும் சுட்டெரிக்கும் சூரியனையும் மிஞ்சி நிற்கும் மாபெரும் ஒளியாகிய இறைவனும் அவருக்கு படைக்கும் தொழிலைக் கொடுத்து அருளினான். குறிப்பு: பிரம்மன் திருமால் மற்றும் உலக தொழில்கள் செய்யும் தேவர்கள் அனைவருமே பல காலமாக இறைவனின் அடியவர்களாக இருந்து தவம் புரிந்தவர்கள்தான். தற்போது இருக்கும் பிரம்மன் திருமால் மற்றும் உலக தொழில்கள் செய்யும் தேவர்களின் பதவிக்காலம் முடிந்ததும் அடுத்த அடியவர்களுக்கு அந்த தொழிலை செய்யும் தகுதி இறைவனது திருவருளால் கிடைத்ததும் அவர்களுக்கு ஏற்ற தொழிலை இறைவன் கொடுத்து அருளுகின்றார்.`,
  },
  {
    id: 382, tantraId: 2, verseNumber: 381,
    tamil: `ஆதியோ டந்தம் இலாத பராபரம்
போதம தாகப் புணரும் பராபரை
சோதி யதனிற் பரந்தோன்றத் தோன்றுமாந்
தீதில் பரையதன் பால்திகழ் நாதமே`,
    transliteration: `ātiyō ṭantam ilāta parāparam
pōtama tākap puṇarum parāparai
cōti yataṉiṟ parantōṉṟat tōṉṟumān
tītil paraiyataṉ pāltikaḻ nātamē`,
    english: `381: Act of Creation by the Primal One
Paraparam that has neither Beginning nor End,
In pure Consciousness consorted with Paraparai
And in that Light Pure arose Param;
And from union of Param with Parai immaculate
Was Nada born.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-381-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `முதலும் முடிவும் இல்லாத பரம்பொருள் அசையா சக்தியாகிய பராபரமாக இருக்கிறார். அறிவு வடிவாக இருக்கும் அந்த பராபரத்தில் உலகை படைக்க வேண்டும் என்ற எண்ணம் தோன்றியதும் அசையும் சக்தியாகிய பராபரை உருவாகிறது. அசையும் சக்தி உருவானதும் அதிலிருந்து சோதி உருவாகிறது. அந்த சோதியில் இருந்து ஒலி உருவாகிறது.`,
  },
  {
    id: 383, tantraId: 2, verseNumber: 382,
    tamil: `நாதத்தில் விந்துவும் நாதவிந் துக்களில்
தீதற் றகம்வந்த சிவன்சத்தி என்னவே
பேதித்து ஞானங் கிரியை பிறத்தலால்
வாதித்த விச்சையில் வந்தெழும் விந்துவே`,
    transliteration: `nātattil vintuvum nātavin tukkaḷil
tītaṟ ṟakamvanta civaṉcatti eṉṉavē
pētittu ñāṉaṅ kiriyai piṟattalāl
vātitta viccaiyil vanteḻum vintuvē`,
    english: `382: Creation Continues
Nada united with Bindu
From the union of Nada-Bindu
Was Siva and Sakti born;
From them evoluted the three--
Jnana, Kriya and Iccha;
Iccha then sought union with Bindu.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-382-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `பாடல் #381 இல் உள்ளபடி பராபரையாகிய எண்ணத்தில் சுத்தமான ஒலியும் ஒளியும் இருக்கிறது. அந்த சுத்தமான ஒலி ஒளிக்கு சிவன் சக்தி என்று பெயர். அந்த பராபரையாகிய எண்ணம் ஒலி ஒளி என்று பிரிந்து இருப்பதற்கு காரணம் அசையாத அறிவு சக்தியில் இருந்து உலகை உருவாக்கும் செயல் சக்தி பிறப்பதற்காக. அசையாத அறிவு சக்தியில் அசைகின்ற எண்ண சக்தி கலக்க ஒலியும் ஒளியும் தோன்றுகிறது.`,
  },
  {
    id: 384, tantraId: 2, verseNumber: 383,
    tamil: `இல்லது சத்தி இடந்தனில் உண்டாகிக்
கல்லொளி போலக் கலந்துள் ளிருந்திடும்
வல்லது ஆக வழிசெய்த அப்பொருள்
சொல்லது சொல்லிடில் தூராதி தூரமே`,
    transliteration: `illatu catti iṭantaṉil uṇṭākik
kalloḷi pōlak kalantuḷ ḷiruntiṭum
vallatu āka vaḻiceyta apporuḷ
collatu colliṭil tūrāti tūramē`,
    english: `383: Latent Maya Evolutes
From thence evoluted Maya
Latent in Sakti like lustre in crystal
Mighty its power
Beyond power of speech to recount.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-383-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `ஒலியாய் இருக்கும் சிவத்தோடு எப்போதும் பிரியாமல் ஒளியாய் இருக்கும் சக்தி சேர்ந்தே இருக்கிறது. நவரத்தினத்தில் உள்ள வைரமும் அந்த வைரத்தில் இருந்து வரும் ஒளியும் வேறு வேறாய் அறியப்பட்டாலும் இரண்டும் ஒன்றே ஆகும். அது போல் சிவமும் சக்தியும் ஒன்றேவாகும். இப்படி இருக்கின்ற சிவசக்தியை உருவாக்கிய பரம்பொருளின் வலிமைகளை விளக்கிச் சொல்லினால் அது பலகாத தூரத்திற்கும் நீண்டு போய்க்கொண்டே இருக்குமே தவிர முடியாது.`,
  },
  {
    id: 385, tantraId: 2, verseNumber: 384,
    tamil: `தூரத்திற் சோதி தொடர்ந்தொரு சத்தியாய்
ஆர்வத்து நாதம் அணைந்தொரு விந்துவாய்ப்
பாரச் சதாசிவம் பார்முதல் ஐந்துக்கும்
சார்வத்து சத்திஓர் சாத்துமா னாமே`,
    transliteration: `tūrattiṟ cōti toṭarntoru cattiyāy
ārvattu nātam aṇaintoru vintuvāyp
pārac catācivam pārmutal aintukkum
cārvattu cattiōr cāttumā ṉāmē`,
    english: `384: Evolution of Maan Sakti--the Substratum of Matter
Away in the far distance of Time
Paraparam and Paraparai conjoined
Then did Nada with Bindu;
And further on Sadasiva with Sakti;
Thus was Maan born
The finite support of elements five.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-384-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: `Anava Sakti then acts on the prakriti maya (material) sphere. This sphere is known as ‘maan’ or ‘mahat’. From maan evolves the five elements—earth, water, fire, ether and space.`,
    elaborationTamil: `வார்த்தைகளில் விவரிக்க இயலாத மாபெரும் வல்லமை பொருந்திய ஜோதி வடிவான இறைவன் அண்டம் முதல் அனைத்தையும் உருவாக்க எண்ணி தனது ஒரு கூறு சக்தியை சேர்ந்தே இருக்கும் ஒலிக்கும் ஒளிக்கும் கொடுத்து பஞ்ச பூதங்கள் முதல் உலகம் வரை அனைத்தையும் உருவாக்குகின்றான்.`,
  },
  {
    id: 386, tantraId: 2, verseNumber: 385,
    tamil: `மானின்கண் வானாகி வாயு வளர்ந்திடும்
கானின்கண் நீருங் கலந்து கடினமாய்த்
தேனின்கண் ஐந்துஞ் செறிந்தைந்து பூதமாய்ப்
பூவின்கண் நின்று பொருந்தும் புவனமே`,
    transliteration: `māṉiṉkaṇ vāṉāki vāyu vaḷarntiṭum
kāṉiṉkaṇ nīruṅ kalantu kaṭiṉamāyt
tēṉiṉkaṇ aintuñ ceṟintaintu pūtamāyp
pūviṉkaṇ niṉṟu poruntum puvaṉamē`,
    english: `385: Universe of Five Elements--Evolutes
Out of Maan evoluted space
From space, ether
From ether, water
From water, earth's hard crust;
Thus they formed in succession
The elements five;
They were for the universe
The nectar unto Flower.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-385-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `ஜோதி வடிவான இறைவனின் மாபெரும் சக்தியிலிருந்து ஒளியும் ஓலியும் தோன்றி இரண்டும் கலந்து அதிலிருந்து ஆகாயம் உருவாகியது. ஆகாயத்திலிருந்து காற்று உருவாகியது. காற்றிலிருந்து வெப்பம் (நெருப்பு) உருவாகியது. வெப்பம் குளிர்ந்து நீர் உருவாகியது. இவை நான்கும் கலந்து நிலம் உருவாகியது. இவை ஐந்தும் முழுமையடைந்து உலகம் உருவாகியது. பூவுக்குள் கலந்திருக்கும் தேன் போல உலகங்களில் பஞ்சபூதங்களான ஆகாயம், காற்று, நெருப்பு, நீர், நிலம் கலந்திருக்கிறது.`,
  },
  {
    id: 387, tantraId: 2, verseNumber: 386,
    tamil: `புவனம் படைப்பான் ஒருவன் ஒருத்தி
புவனம் படைப்பார்க்குப் புத்திரர் ஐவர்
புவனம் படைப்பானும் பூமிசை யானாய்
புவனம் படைப்பானப் புண்ணியன் தானே`,
    transliteration: `puvaṉam paṭaippāṉ oruvaṉ orutti
puvaṉam paṭaippārkkup puttirar aivar
puvaṉam paṭaippāṉum pūmicai yāṉāy
puvaṉam paṭaippāṉap puṇṇiyaṉ tāṉē`,
    english: `386: Sadasiva is the Source of Creation
Sada-Siva, the He-She, creates universe all,
He has sons five
The Holy One that creates universe all
Himself as lotus-seated Brahma
The Creator became.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-386-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: `“The Five manifestations are Sadasiva, Mahesvara, Rudra, Brahma and Yishnu.`,
    elaborationTamil: `உலகங்களைப் படைப்பது ஒலியாகிய சிவமும் ஒளியாகிய சக்தியுமாகும். அந்த உலகங்களில் பல தொழில்களைப் புரிவதற்காக இவர்களின் சக்தியிலிருந்து தோன்றிய பிள்ளைகள் ஐந்து பேர். அவர்கள் உயிர்களைப் படைக்கும் பிரம்மன் உயிர்களைக் காக்கும் திருமால் உயிர்களை அழிக்கும் உருத்திரன் உயிர்களை மாயையால் மறைக்கும் மகேசுவரன் உயிர்களுக்கு அருளும் சதாசிவன் ஆகிய ஐந்து பேராவார்கள். அனைத்தையும் படைப்பதற்குக் காரணமான சதாசிவமூர்த்தியே ஆயிரம் இதழ்கள் கொண்ட தாமரை மலரில் வீற்றிருந்து உலகங்கள் அனைத்துமாகவும் அதிலிருக்கும் உயிர்கள் அனைத்துமாகவும் இருக்கின்றான்.`,
  },
  {
    id: 388, tantraId: 2, verseNumber: 387,
    tamil: `புண்ணியன் நந்தி பொருந்தி உலகெங்கும்
தண்ணிய மானை வளர்த்திடுஞ் சத்தியுஞ்
கண்ணியல் பாகக் கலவி முழுதுமாய்
மண்ணியல் பாக மலர்ந்தெழு பூவிலே`,
    transliteration: `puṇṇiyaṉ nanti porunti ulakeṅkum
taṇṇiya māṉai vaḷarttiṭuñ cattiyuñ
kaṇṇiyal pākak kalavi muḻutumāy
maṇṇiyal pāka malarnteḻu pūvilē`,
    english: `387: In the Union of Sadasiva with Maan Sakti Blossomed the
Universe
The Holy Nandi that is Sadasiva
And the Sakti that devoluted Maan
Together in looks united in full;
And from that union arose the universe
As unto a blossom gently opening.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-387-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `குளிர்ந்த நீரையும் மண்ணையும் படைத்து அதற்கான தன்மைகளை குருவாக இருந்து சதாசிவமூர்த்தி கொடுக்கின்றார். அதன் மூலம் நல்வினைகளை அருளி சதாசிவமூர்த்தியுடன் ஒன்றாகச் சேர்ந்து உலகங்கள் அனைத்திலும் நீரையும் மண்ணையும் சக்தி வளர்க்கின்றாள். சதாசிவமூர்த்தியின் அசையும் சக்தியான எண்ணத்திலே உதித்த கருத்தானது சிவத்துடன் கலந்து மண்ணாகவும் சக்தியோடு கலந்து நீராகவும் இரண்டும் கலந்து உலகங்களாகவும் மாறுகின்றது. இதில் சிவமும் சக்தியும் மலரில் கலந்திருக்கும் வாசனை போல உலகமெங்கும் ஒன்றாகக் கலந்தே இருக்கின்றனர்.`,
  },
  {
    id: 389, tantraId: 2, verseNumber: 388,
    tamil: `நீரகத் தின்பம் பிறக்கும் நெருப்பிடை
காயத்திற் சோதி பிறக்கும்அக் காற்றிடை
ஓர்வுடை நல்லுயிர்ப் பாதம் ஒலிசத்தி
நீரிடை மண்ணின் நிலைபிறப் பாமே`,
    transliteration: `nīrakat tiṉpam piṟakkum neruppiṭai
kāyattiṟ cōti piṟakkumak kāṟṟiṭai
ōrvuṭai nalluyirp pātam olicatti
nīriṭai maṇṇiṉ nilaipiṟap pāmē`,
    english: `388: How the Elements Five Evoluted
From Fire emanated water
From Wind emanated light
From Space emanated sound
From Water emanated earth
This the way the elements five evoluted.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-388-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `இறைவனது தன்மையானது பஞ்ச பூதங்களில் நீரில் சுவையாகவும் நெருப்பில் ஒளியாகவும் காற்றில் உணர்வாகவும் ஆகாயத்தில் ஒலியாகவும் நிலத்தில் உடல் சார்ந்த உயிர்களாகவும் பிறந்து இருக்கின்றது. உட்கருத்து: பஞ்ச பூதங்கள் ஐந்தும் இறைவனது பண்புகளில் இருந்து உருவானவையே. உலகங்கள் அனைத்தும் இவற்றில் அடக்கம்.`,
  },
  {
    id: 390, tantraId: 2, verseNumber: 389,
    tamil: `உண்டுல கேழும் உமிழ்ந்தான் உடனாகி
அண்டத் தமரர் தலைவனும் ஆதியுங்
கண்டச் சதுர்முகக் காரணன் தன்னொடும்
பண்டிவ் வுலகம் படைக்கும் பொருளே`,
    transliteration: `uṇṭula kēḻum umiḻntāṉ uṭaṉāki
aṇṭat tamarar talaivaṉum ātiyuṅ
kaṇṭac caturmukak kāraṇaṉ taṉṉoṭum
paṇṭiv vulakam paṭaikkum poruḷē`,
    english: `389: The Primal One Created the Universe With Brahma and
Vishnu
With Hari who spat out the seven worlds
With Brahma, the four headed maker
The Primal One, the Lord of Celestial Beings
Created, of yore, this universe vast.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-389-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `ஏழு உலகங்களையும் காப்பாற்றி பிறகு வெளிப்படுத்திய திருமால் அண்டங்கள் அனைத்திலும் இருக்கின்ற தேவர்களின் தலைவனாகவும் ஆதிமூல நாயகனாகவும் விளங்குகின்ற சிவபெருமான் கர்வத்தினால் தனது ஐந்து தலைகளில் ஒன்றை இறைவனால் கொய்யப்பட்டு நான்கு முகங்களை மட்டுமே கொண்டவனாகிய பிரம்மன் ஆகிய இந்த மூவருடனும் கலந்து இருந்து பழமை வாய்ந்த இந்த உலகங்கள் அனைத்தையும் படைக்கும் பரம்பொருள் சதாசிவமூர்த்தி ஒருவனே ஆவான்.`,
  },
  {
    id: 391, tantraId: 2, verseNumber: 390,
    tamil: `ஓங்கு பெருங்கடல் உள்ளுறு வானொடும்
பாங்கார் கயிலைப் பராபரன் தானும்
வீங்குங் கமல மலர்மிசை மேலயன்
ஆங்குயிர் வைக்கும் அதுவுணர்ந் தானே`,
    transliteration: `ōṅku peruṅkaṭal uḷḷuṟu vāṉoṭum
pāṅkār kayilaip parāparaṉ tāṉum
vīṅkuṅ kamala malarmicai mēlayaṉ
āṅkuyir vaikkum atuvuṇarn tāṉē`,
    english: `390: Creation is an Act of Pure Consciousness by the Primal
One
The Supreme One aloft the Mount Kailas
With Hari in the ocean bed
And Brahma on the blooming lotus
Created life
By Consciousness Pure.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-390-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: `Thus, ultimately it is the Primal One who created this vast universe by pure consciousness. It was He who created Brahma, the creator, and Vishnu, who contains in himself the seven worlds.`,
    elaborationTamil: `ஓங்கிய பாற்கடலின் மேல் இருக்கும் திருமாலும் அழகிய கயிலை மலையின் மேல் இருக்கும் பரம்பொருளான சிவபெருமானும் மலர்ந்து விரிந்து இருக்கின்ற தாமரை மலரின் மேல் இருக்கும் பிரம்மனும் ஒவ்வொரு உயிருக்குள்ளும் ஆன்மாவை வைக்கின்ற மூலப் பொருளான சதாசிவமூர்த்தியை உணர்ந்து இருக்கின்றார்கள். உட்கருத்து: பிரம்மன் படைத்தலும், திருமால் காத்தலும், சிவன் அழித்தலும் செய்யும் உயிர்கள் அனைத்திலும் ஆன்மாவாக இருப்பது சதாசிவமூர்த்தியே என்பதை மூவரும் உணர்ந்திருக்கின்றார்கள்.`,
  },
  {
    id: 392, tantraId: 2, verseNumber: 391,
    tamil: `காரணன் அன்பிற் கலந்தெங்கும் நின்றவன்
நாரணன் நின்ற நடுவுட லாய்நிற்கும்
பாரணன் அன்பிற் பதஞ்செய்யும் நான்முகன்
ஆரண மாஉல காயமர்ந் தானே`,
    transliteration: `kāraṇaṉ aṉpiṟ kalanteṅkum niṉṟavaṉ
nāraṇaṉ niṉṟa naṭuvuṭa lāyniṟkum
pāraṇaṉ aṉpiṟ patañceyyum nāṉmukaṉ
āraṇa māula kāyamarn tāṉē`,
    english: `391: The Primal One is Narayana and Brahma as Well
He is the First Cause,
All-pervasive in love;
He is Vishnu; He is Brahma,
He is Veda, the Cosmos, the Abiding One.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-391-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: `He is the First Cause: He is Vishnu; He is Brahma; He is Veda; He is the cosmos. All, all, are diverse manifestations of the Ever-abiding Compassionate One.`,
    elaborationTamil: `அண்ட சராசரங்கள் அனைத்தும் உருவாகக் காரணமானவனாகிய சதாசிவமூர்த்தி அனைத்திலும் அன்பாகக் கலந்து இருக்கின்றான். அண்ட சராசரங்கள் அனைத்திலும் உடலாக இருக்கும் பொருட்கள் அனைத்தையும் தாங்கிக் காப்பாற்றி நிற்கும் திருமாலாகவும் அவனே இருக்கின்றான். அந்த அண்ட சராசரங்கள் அனைத்திலும் உயிர்களை அன்போடு வேதங்கள் ஓதி உருவாக்கும் நான்கு முகங்களைக் கொண்ட பிரம்மனாகவும் அவனே இருக்கின்றேன். அண்ட சராசரங்கள் அனைத்துமாகவும், அதிலிருக்கும் பொருட்களாகவும் அதில் வாழும் உயிர்களாகவும் இருந்து அன்பினால் கட்டி வைத்திருப்பவன் சதாசிவமூர்த்தியாகிய இறைவனே.`,
  },
  {
    id: 393, tantraId: 2, verseNumber: 392,
    tamil: `பயன்எளி தாம்பரு மாமணி செய்ய
நயன்எளி தாகிய நம்பன்ஒன் றுண்டு
அயஓளி யாயிருந் தங்கே படைக்கும்
பயனெளி தாம்வய ணந்தெளிந் தேனே`,
    transliteration: `payaṉeḷi tāmparu māmaṇi ceyya
nayaṉeḷi tākiya nampaṉoṉ ṟuṇṭu
ayaōḷi yāyirun taṅkē paṭaikkum
payaṉeḷi tāmvaya ṇanteḷin tēṉē`,
    english: `392: As Light Within Brahma, the Primal One Creates
A rare Ruby--He is easy of reach,
The One Lord--He is easy of love,
He is the light within Brahma;
And now I know why the Creator does it easy so.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-392-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `எல்லாப்பயன்களையும் எளிதில் அளிக்கக் கூடியதும் பேரின்பத்தை வழங்கக் கூடியதும் நம்பிக்கைக்கு உரியதுமான ஒரு மாணிக்ககல் இருக்கிறது. அந்தக் மாணிக்ககல்லே உயிர்களைப் படைக்கும் பிரம்மனுக்கு ஒளியாக இருந்து வழிகாட்டுகிறது. அந்த மாணிக்ககல்லாக இறைவன் இருக்கும் காரணத்தை யாம் அறிந்து தெளிந்து கொண்டோம்.`,
  },
  {
    id: 394, tantraId: 2, verseNumber: 393,
    tamil: `போக்கும் வரவும் புனிதன் அருள்புரிந்
தாக்கமுஞ் சிந்தைய தாகின்ற காலத்து
மேக்கு மிகநின்ற எட்டுத் திசையொடுந்
தாக்குங் கலக்குந் தயாபரன் தானே`,
    transliteration: `pōkkum varavum puṉitaṉ aruḷpurin
tākkamuñ cintaiya tākiṉṟa kālattu
mēkku mikaniṉṟa eṭṭut ticaiyoṭun
tākkuṅ kalakkun tayāparaṉ tāṉē`,
    english: `393: At the Creation the Compassionate One Pervades All
Space
Death and birth, the Holy One in Grace ordained;
And in that hour when by His Thought
He Commenced the act of Creation
He fills and pervades in eight directions
He, the Compassionate One.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-393-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `உலகத்தில் இருக்கும் அனைத்தையும் தனது அருளால் படைத்து காத்து பின்பு அழிக்கின்றான் இறைவன். இந்த மூன்று தொழிலையும் செய்யும் இறைவன் எதனாலும் பாதிக்காமல் புனிதனாக இருந்து எண்ணங்களுக்கு எட்டாத உயரத்தில் எட்டுத்திசைகளில் உள்ள எல்லாவற்றிலும் அவன் கலந்து பரவியிருக்கிறான்.`,
  },
  {
    id: 395, tantraId: 2, verseNumber: 394,
    tamil: `நின்றுயி ராக்கு நிமலன்என் னாருயிர்
ஒன்றுயி ராக்கும் அளவை உடலுற
முன்துய ராக்கும் உடற்குந் துணையதா
நன்றுயிர்ப் பானே நடுவுநின் றானே`,
    transliteration: `niṉṟuyi rākku nimalaṉeṉ ṉāruyir
oṉṟuyi rākkum aḷavai uṭaluṟa
muṉtuya rākkum uṭaṟkun tuṇaiyatā
naṉṟuyirp pāṉē naṭuvuniṉ ṟāṉē`,
    english: `394: The Lord Animates the Body in Justice
The Immaculate One creates all;
And as He created me too,
He animates within me
A support to the body, an heir to karmic ills;
Verily, the Lord is the Just one.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-394-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: `The immaculate One, who creates all, who creates the bodies and milieus for jivas too, according to their karmic desert. That is His act of divine justice. In the act of creation He stands adorning death’s bones and konrai’s blooms gleaming © as pure gold. He beckons to departed souls as the Final Refuge of Becoming. He enters within jiva and cognises all.`,
    elaborationTamil: `: உடலில் ஆன்மாவை வைத்து உயிராக மாற்றுபவன் என் ஆருயிர் இறைவனே உயிர்களிடத்தில் கொண்ட மாபெரும் கருணையினால் உடலில் இணைந்த ஆன்மாவுடன் உயிராகக் கலந்து இருக்கின்றான். முன்பிறவியின் வினைகளைத் தீர்க்க வேண்டிப் பிறவி எடுத்த அந்த உயிரின் காலம் முடியும் வரை அந்த உயிர் செய்யும் எந்த செயலிலும் தலையிடாமல் நடு நிலையாக நின்று கவனித்துக் கொண்டு அந்த உயிர் வாழ வேண்டிய காலம் வரை அந்த உயிரின் உடலோடு ஒன்றாகக் கலந்து நன்றாகக் காத்துக் கொண்டு நிற்கின்றான் இறைவன்.`,
  },
  {
    id: 396, tantraId: 2, verseNumber: 395,
    tamil: `ஆகின்ற தன்மையில் அக்கணி கொன்றையன்
வேகின்ற செம்பொனின் மேலணி மேனியன்
போகின்ற சீவன் புகுந்துட லாய்உளன்
ஆகின்ற தன்மைசெய் ஆண்டகை யானே`,
    transliteration: `ākiṉṟa taṉmaiyil akkaṇi koṉṟaiyaṉ
vēkiṉṟa cempoṉiṉ mēlaṇi mēṉiyaṉ
pōkiṉṟa cīvaṉ pukuntuṭa lāyuḷaṉ
ākiṉṟa taṉmaicey āṇṭakai yāṉē`,
    english: `395: Lord is the Refuge of All Departed Life
In the act of creations
He stands adorning death's bones and konrai's blooms,
His resplendent Form out-shines red-hot gold;
A refuge vast of all departed life;
The Lord that performs the act of Becoming.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-395-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `: எலும்புகளை அணிந்து கொன்றை மலரைச் சூடியிருக்கும் சிவபெருமான் உலகத்தில் நிகழும் அனைத்து தொழிலின் தன்மையாக இருக்கின்றான். உருகுகின்ற தங்கம் போன்ற மினுமினுப்பான உடல் கொண்டவன் அவன். பிறவிக்கு செல்லும் உயிர்கள் வாழும் உடலாயும் இருக்கின்றான். பிறவி எடுத்த உயிருக்கு நிகழும் தன்மையிலும் அவனே கலந்திருந்து துணையாக இருப்பான்.`,
  },
  {
    id: 397, tantraId: 2, verseNumber: 396,
    tamil: `ஒருவன் ஒருத்தி விளையாடல் உற்றார்
இருவர் விளையாட்டும் எல்லாம் விளைக்கும்
பருவங்கள் தோறும் பயன்பல வான
திருவொன்றிற் செய்கை செகமுற்று மாமே`,
    transliteration: `oruvaṉ orutti viḷaiyāṭal uṟṟār
iruvar viḷaiyāṭṭum ellām viḷaikkum
paruvaṅkaḷ tōṟum payaṉpala vāṉa
tiruvoṉṟiṟ ceykai cekamuṟṟu māmē`,
    english: `396: Creation the Play of He-She
He-and-She commenced play
The play of Two produced all;
With seasons changing, diverse the produce;
When He-and-She in holy union join
Complete be the act of creation.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-396-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `பரம்பொருள் அனைத்தையும் உருவாக்க வேண்டும் என்கிற எண்ணத்தால் சிவமாகவும் சக்தியாகவும் வெளிப்பட்டு இருவரின் திருவிளையாடலால் அனைத்தும் உருவாகும். அப்படி உருவாகிய அனைத்தும் காலத்திற்கு ஏற்ற மாதிரியும் அவைகள் அடைந்த பக்குவத்திற்கு ஏற்ற மாதிரியும் பலவகையான வினைப் பயன்களைப் பெறும். எப்போது இறைவனது திருவிளையாட்டால் உருவாகிய ஒன்று இறைவனிடமே சென்று சேர்கின்றதோ அப்போது அதன் உலக வாழ்க்கை முற்றுப் பெற்றுவிடும். உட்கருத்து: உலகத்தில் அனைத்தும் இறைவனது திருவிளையாட்டால்தான் உருவாகின்றது. அவை பிறந்து, வாழ்ந்து, இறந்து மீண்டும் பிறக்கும் உலகச் சுழற்சி அந்தந்த ஆன்மாக்களின் காலத்திற்கு ஏற்ற பக்குவத்தைப் பொறுத்து வினைப் பயனாக அமையும். எப்போது இறைவனிடமிருந்து வெளிவந்த ஆன்மா அதன் வினைப் பயன் முழுவதையும் கழித்து இறைவனிடமே சென்று கலந்து விடுகின்றதோ அப்போது அதன் உலகச் சுழற்சி முற்றுப் பெற்றுவிடுகிறது.`,
  },
  {
    id: 398, tantraId: 2, verseNumber: 397,
    tamil: `புகுந்தறி வான்புவ னாபதி அண்ணல்
புகுந்தறி வான்புரி சக்கரத் தண்ணல்
புகுந்தறி வான்மலர் மேலுறை புத்தேள்
புகுந்தறி யும்முடிக் காகிநின் றாரே`,
    transliteration: `pukuntaṟi vāṉpuva ṉāpati aṇṇal
pukuntaṟi vāṉpuri cakkarat taṇṇal
pukuntaṟi vāṉmalar mēluṟai puttēḷ
pukuntaṟi yummuṭik kākiniṉ ṟārē`,
    english: `397: The Three Gods Enter Within Us and Know All
The Lord of universe vast enters within and cognises
So does Hari that wields the Chakra;
And so too Brahma on the lotus flower seated;
They Three stood within
As treasure-heap of cognition all.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-397-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உலகத்தை அழிக்கும் உருத்திரனும் சங்கு சக்கரத்தைத் தரித்து காக்கின்ற திருமாலும் தாமரை மலரின் மேல் அமர்ந்து படைக்கின்ற பிரம்மனும் தாங்கள் செய்ய வேண்டியது என்ன என்பதை தமக்குள் புகுந்து தம்மோடு கலந்து நிற்கும் பரம்பொருளாகிய சதாசிவமூர்த்தியை உணர்ந்து அறிந்து கொள்வதனால் பரம்பொருளின் விருப்பத்தை செய்லாக்கும் கருவிகளாகவே இவர்கள் மூவரும் இருக்கின்றார்கள். உட்கருத்து: உயிர்கள் சென்று அடைய வேண்டியது அழிக்கின்ற உருத்திரனையோ காக்கின்ற திருமாலையோ படைக்கின்ற பிரம்மனையோ இல்லை. இவர்கள் மூவரையும் தம் விருப்பத்தை செயலாக்கும் படி வைத்து இயக்கும் பரம்பொருளாகிய சதாசிவமூர்த்தியை அடைந்தால் மட்டுமே பாடல் #396 இல் கூறியுள்ளபடி உயிர்களின் உலகச் சுழற்சி முற்றுப் பெறும்.`,
  },
  {
    id: 399, tantraId: 2, verseNumber: 398,
    tamil: `ஆணவச் சத்தியும் ஆம்அதில் ஐவருங்
காரிய காரண ஈசர் கடைமுறை
பேணிய ஐந்தொழி லால்விந்து விற்பிறந்து
ஆணவம் நீங்கா தவரென லாகுமே`,
    transliteration: `āṇavac cattiyum āmatil aivaruṅ
kāriya kāraṇa īcar kaṭaimuṟai
pēṇiya aintoḻi lālvintu viṟpiṟantu
āṇavam nīṅkā tavareṉa lākumē`,
    english: `398: The Five Gods Were Born of Anava Sakti
Out of the union of Anava Sakti with Bindu
The Five Gods were born.
Brahma, Vishnu, Rudra, Sadasiva and Maheswara.
For the five acts to perform-
Creation, preservation, destruction, obscuration and redemption-
As One from the other in causative succession;
Born as they were of the Anava Sakti,
Of Anava they were not rid.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-398-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: `Out of apara bindu uniting with anava {ichcha) sakti in the impure maya sphere, were born the five Gods—Sadasiva, Mahesvara, Rudra, Vishnu and Brahma—to perform their five respective functions; and being born of anava sakti they were not free from the taint of the individualising malam {anava malam).`,
    elaborationTamil: `சதாசிவமூர்த்தியாகிய பரம்பொருளின் திருவிளையாடலால் ஆணவ மாயையில் நின்று உயிர்களைப் படைக்கும் தொழிலை பிரம்மனும் காக்கும் தொழிலை திருமாலும் அழிக்கும் தொழிலை உருத்திரனும் மாயையால் மறைக்கும் தொழிலை மகேசுவரனும் கருணையால் அருளும் தொழிலை சதாசிவனும் செய்கின்றனர். இவர்களும் உடலெடுத்து உயிர்களாகப் பிறந்து இறைவனை வேண்டித் தவமிருந்து இறைவனது அருளால் இந்த ஐந்து தொழில்களையும் பெற்று அவரவர்களுக்கு உரிய தொழிலைச் செய்தாலும் ஆணவம் முற்றிலும் நீங்காமல் இருப்பவர்கள் தான். குறிப்பு: பிரம்மன், திருமால், உருத்திரன், மகேசுவரன், சதாசிவன் ஆகிய ஐந்து தேவர்களும் சிறிதளவு ஆணவம் இருப்பதினால் தான் அவர்கள் ஐந்து பெயர்களில் குறிக்கப்பட்டு தனியாக ஐந்து தொழில்களை செய்து கொண்டிருக்கின்றனர். அந்த சிறிதளவு ஆணவமும் இல்லையெனில் அவர்கள் அசையா சக்தியாக இருக்கும் சதாசிவமூர்த்தியுடன் கலந்திருப்பார்கள். இவர்களும் உடலெடுத்து உயிர்களாக பிறப்பெடுத்து சிவனடியார்களாக இருந்தவர்கள் தான் என்பதை திருமந்திரம் பாடல் எண் 302, 380 பாடல்களின் மூலம் அறியலாம்.`,
  },
  {
    id: 400, tantraId: 2, verseNumber: 399,
    tamil: `உற்றமுப் பாலொன்று மாயாள் உதயமா
மற்றைய மூன்று மாயோ தயம்விந்து
பெற்றவன் நாதம் பரையிற் பிறத்தலால்
துற்ற பரசிவன் தொல்விளை யாட்டிதே`,
    transliteration: `uṟṟamup pāloṉṟu māyāḷ utayamā
maṟṟaiya mūṉṟu māyō tayamvintu
peṟṟavaṉ nātam paraiyiṟ piṟattalāl
tuṟṟa paracivaṉ tolviḷai yāṭṭitē`,
    english: `399: Creation the Play of the Ultimate
Out of Ichcha of the Saktis three arose Maya;
And Maya in union with Bindu yielded
The rest of Mayas three (Suddha, Asuddha and Prakriti)
(The Bindu was of Nada born)
And Nada was of Parai born;
And all this in the Creative play of Parasiva, the Unltimate.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-399-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `மாயையாகிய சக்தியிலிருந்து சுத்த மாயை, அசுத்த மாயை, பிரகிருதி மாயை என மூன்றும் தோற்றுவிக்கப்படுகின்றன. படைத்தல், காத்தல், அழித்தல் ஆகிய மூன்றும் சுத்த மாயையின் தொழிலாகும். இந்த மாயைகளைத் தாண்டி ஒலியும் ஒளியும் இருக்கின்றது. இவை இரண்டும் அசையும் சக்தியாகிய பரையிடமிருந்து பிறப்பதால் இவை அனைத்தும் அசையாத சக்தியாகிய பரம்பொருள் சதாசிவமூர்த்தியின் திருவிளையாடலால் உருவானவையே ஆகும். உட்கருத்து: அசையாத சக்தியாகிய பராவிடம் திருவிளையாடல் புரிய எண்ணம் தோன்றும்போது அசையும் சக்தியாகிய பரையிடமிருந்து ஒளியும் ஒலியும் தோன்றுகின்றது. இதிலிருந்து மாயைகள் அனைத்தும் உருவாகின்றது. இவை அனைத்துமே அசையாத சக்தியாகிய பரம்பொருளின் திருவிளையாடலாகும்.`,
  },
  {
    id: 401, tantraId: 2, verseNumber: 400,
    tamil: `ஆகாய மாதி சதாசிவ ராதியென்
போகாத சத்தியுட் போந்துடன் போந்தனர்
மாகாய ஈசன் அரன்மால் பிரமனாம்
ஆகாயம் பூமி காண அளித்தலே`,
    transliteration: `ākāya māti catāciva rātiyeṉ
pōkāta cattiyuṭ pōntuṭaṉ pōntaṉar
mākāya īcaṉ araṉmāl piramaṉām
ākāyam pūmi kāṇa aḷittalē`,
    english: `400: The Five Gods Were the Primal Family for Five Duties to
Perform
From out of Anava Sakti
Arose the Primal Family;
Sadasiva was the First Born;
With Him came the brothers
Maheswara, Rudra, Vishnu and Brahma--
Each to perform on heaven and earth
His allotted function--Creation, Preservation and the rest.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-400-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `ஆகாயம், நீர், நெருப்பு, காற்று, மண் ஆகிய பஞ்ச பூதங்களும். சிவன், மகேசுவரன், உருத்திரன், திருமால், பிரம்மன் ஆகிய பஞ்ச தெய்வங்களும் என்றும் அழியாத மாபெரும் சக்தியினுள்ளிருந்தே தோன்றியவர்களாகும். பஞ்ச தெய்வங்களில் உருவமில்லாமல் அருவமாக முதலில் தோன்றிய சிவனிடமிருந்து தூல உருவமுள்ள மகேசுவரன் தோன்றி மகேசுவரனிடமிருந்து உருத்திரன் தோன்றி உருத்திரனிடமிருந்து திருமால் தோன்றி திருமாலிடமிருந்து பிரம்மன் தோன்றினான். அதுபோலவே பஞ்ச பூதங்களில் உருவமில்லாத அருவமாக முதலில் தோன்றிய ஆகாயத்திலிருந்து சூட்சும உருவமான வாயு தோன்றி வாயுவிலிருந்து தூல உருவமான நெருப்பு தோன்றி நெருப்பிலிருந்து நீர் தோன்றி நீரிலிருந்து நிலம் தோன்றியது. இவை அனைத்தும் சேர்ந்தே உலகம் என்ற பொருள் தோன்றி கண்ணால் காண முடியும்படி அளிக்கப்பட்டது.`,
  },
  {
    id: 402, tantraId: 2, verseNumber: 401,
    tamil: `அளியார் முக்கோணம் வயிந்தவந் தன்னில்
அளியார் திரிபுரை யாமவள் தானே
அளியார் சதாசிவ மாகி அமைவாள்
அளியார் கருமங்கள் ஐந்துசெய் வாளே`,
    transliteration: `aḷiyār mukkōṇam vayintavan taṉṉil
aḷiyār tiripurai yāmavaḷ tāṉē
aḷiyār catāciva māki amaivāḷ
aḷiyār karumaṅkaḷ aintucey vāḷē`,
    english: `401: Maya Sakti Born of Bindu Performs the Five Acts
From Bindu by Orderly triangle denoted
The honeyed Sakti Tripurai devoluted;
She it is the Compassionate Sadasiva became;
She it is the five merciful deeds performs.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-401-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `பரவிந்து, அபரநாதம், அபரவிந்து எனும் மூன்று முக்கோணம் போன்ற ஒளி ஒலியாகிய அசையும் சக்தியின் மையப்பகுதியில் இருந்து திரிபுரை என்ற பெயருடைய சக்தி தோன்றுவாள். அவளே சதாசிவமூர்த்தியின் தொழிலை செயல்படுத்துவாள். அவளது மாபெரும் கருணையினால் சிவன், மகேசுவரன், உருத்திரன், திருமால், பிரம்மன் ஆகிய ஐந்து மூர்த்திகளின் சக்தியாக உடன் இருந்து அருளல், மறைத்தல், அழித்தல், காத்தல், படைத்தல் ஆகிய ஐந்து தொழில்களையும் செய்வாள்.`,
  },
  {
    id: 403, tantraId: 2, verseNumber: 402,
    tamil: `வாரணி கொங்கை மனோன்மணி மங்கலி
காரணி காரிய மாகக் கலந்தவள்
வாரணி ஆரணி வானவர் மோகினி
பூரணி போதாதி போதமு மாமே`,
    transliteration: `vāraṇi koṅkai maṉōṉmaṇi maṅkali
kāraṇi kāriya mākak kalantavaḷ
vāraṇi āraṇi vāṉavar mōkiṉi
pūraṇi pōtāti pōtamu māmē`,
    english: `402: Names of Glories of Maya Sakti
She is Manonmani, the ample-bosomed;
Mangali, the ever auspicious;
Varani of elephant form
Arani of haunting forests
Mohini of tempting beauty
Poorani--the Perfect Being,
Cause-Effect conjoint in one
--She, Consciousness beyond Consciousness.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-402-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `சூரிய சந்திரனை மார்புக் கச்சையாக சூடியிருக்கும் சிவனின் சக்தியான மனோன்மணி மங்கள சொரூபமானவள். அவளே அனைத்திற்கும் காரணமாகிய அசையா சக்தியான இறைவனுடன் அசையும் சக்தியாகவும் உலக காரியங்களை செய்யும் சிவன், மகேசுவரன், உருத்திரன், திருமால், பிரம்மன் ஆகியோருடன் காரிய சக்திகளாகவும் கலந்து நிற்கின்றாள். அவளே ஓங்கார வடிவாகவும் அழிக்கும் தொழிலில் வாரணியாகவும் படைக்கும் தொழிலில் ஆரணியாகவும் காக்கும் தொழிலில் வானவர் கொண்டாடும் மோகினியாகவும், மறைக்கும் தொழிலில் பூரணியாகவும் பேரறிவாக இருக்கின்றாள். உட்கருத்து: அசையா சக்தியாகிய இறைவனின் அசையும் சக்தியாகிய இறைவி உலகம் உருவாக வேண்டும் என்கிற காரணத்தில் பேரறிவு ஞானமாக இருந்து அதை செயலாக்கும் பொருட்டு காரிய சக்திகளாக ஐந்து தேவர்களுடன் ஐந்து தேவிகளாக இருந்து அனைத்தையும் செயல்படுத்துகின்றாள். காரணம் – இறைவன் (அசையாசக்தி) – இறைவி (அசையும்சக்தி) – அனைத்தும் உருவாக்குதல் காரியம் – பிரம்மன் – ஆரணி (சரஸ்வதி) – படைத்தல் காரியம் – திருமால் – மோகினி (இலட்சுமி) – காத்தல் காரியம் – உருத்திரன் – வாரணி – அழித்தல் காரியம் – மகேஸ்வரன் – பூரணி (உமா மகேஸ்வரி) – மறைத்தல் காரியம் – சிவன் – மனோன்மணி (பார்வதி) – அருளல்`,
  },
  {
    id: 404, tantraId: 2, verseNumber: 403,
    tamil: `நின்றது தானாய் நிறைந்த மகேசுரன்
சென்றங் கியங்கும் அரந்திரு மாலவன்
மன்றது செய்யும் மலர்மிசை மேலயன்
என்றிவ ராக இசைந்திருந் தானே`,
    transliteration: `niṉṟatu tāṉāy niṟainta makēcuraṉ
ceṉṟaṅ kiyaṅkum arantiru mālavaṉ
maṉṟatu ceyyum malarmicai mēlayaṉ
eṉṟiva rāka icaintirun tāṉē`,
    english: `403: One Sadasiva Became Five
Sadsiva that stood as One
Animated Maheswara;
And then Hara, Hari and Brahma,
Thus did the One become the familial Five.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-403-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `அசையா சக்தியும் அசையும் சக்தியும் சேர்ந்த ரூபமான அருளல் தொழிலை செய்யும் சிவனின் அம்சம் முழுவதும் நிறைந்து தாமாகவே சதாசிவனிடமிருந்து தோன்றியவர் மறைத்தல் தொழில் செய்யும் மகேஸ்வரன். இவரே காத்தலையும் அழித்தலையும் செய்யும் உருத்திரன் திருமாலின் செயல்களில் இயக்கமாக இருக்கிறார். திருமாலின் தொப்புள் கொடியிலிருந்து வெளி வந்த தாமரை மலரின் மீது உருவானவர் அனைத்தையும் படைக்கும் தொழிலை செய்யும் பிரம்மன் ஆவார். ஆகவே இந்த ஐந்து தேவர்களாகவும் அசையா சக்தியான இறைவன் ஒருவனே ஒவ்வொருவருடனும் ஒவ்வொருவராகக் கலந்து இருக்கின்றான்.`,
  },
  {
    id: 405, tantraId: 2, verseNumber: 404,
    tamil: `ஒருவனு மேஉல கேழும் படைத்தான்
ஒருவனு மேஉல கேழும் அளித்தான்
ஒருவனு மேஉல கேழுந் துடைத்தான்
ஒருவனு மேஉல கோடுயிர் தானே`,
    transliteration: `oruvaṉu mēula kēḻum paṭaittāṉ
oruvaṉu mēula kēḻum aḷittāṉ
oruvaṉu mēula kēḻun tuṭaittāṉ
oruvaṉu mēula kōṭuyir tāṉē`,
    english: `404: Sadasiva Alone Performs the Five Functions
The One alone created the worlds seven;
The One alone spanned the worlds seven;
The One alone survived the worlds seven;
The One alone pervaded body and life.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-404-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `ஏழு உலகங்களையும் படைக்கின்ற பிரம்மனாகவும் ஏழு உலகங்களையும் காக்கின்ற திருமாலாகவும் ஏழு உலகங்களையும் அழிக்கின்ற சிவபெருமானாகவும் இருப்பவன் இறைவன் ஒருவனே. சதாசிவமூர்த்தியாக இருந்து ஒவ்வொரு உயிரின் உடலோடு உயிராக கலந்து இருப்பவனும் இறைவன் ஒருவனே.`,
  },
  {
    id: 406, tantraId: 2, verseNumber: 405,
    tamil: `செந்தா மரைவண்ணன் தீவண்ணன் எம் இறை
மைந்தார் முகில்வண்ணன் மாயஞ்செய் பாசத்தும்
கொந்தார் குழலியர் கூடிய கூட்டத்தும்
மைந்தார் பிறவி அறுத்துநின் றானே`,
    transliteration: `centā maraivaṇṇaṉ tīvaṇṇaṉ em iṟai
maintār mukilvaṇṇaṉ māyañcey pācattum
kontār kuḻaliyar kūṭiya kūṭṭattum
maintār piṟavi aṟuttuniṉ ṟāṉē`,
    english: `405: Of Red Lotus Hue is Our Lord!
Of red lotus hue is our Lord!
Of Crimson fire hue is our Lord!
He sundered the chain of births,
That the dark cloud hued Mal in pasa bound,
And to flower-bedecked Maya-Crowd, consigned.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-405-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `சிவந்த தாமரை மலரின் நிறத்தைப் போன்ற பிரம்மனும் கொழுந்து விட்டு எரியும் தீப் பிழம்பின் நிறத்தைக் கொண்ட எமது இறைவன் சிவபெருமானும் நீர் நிறைந்த மேகங்களைப் போன்ற கருமை நிறம் கொண்ட திருமாலும் சேர்ந்து மாயையால் பாசப்பிணைப்புகளை உண்டாக்கி உயிர்களை மயக்கி பூக்களை தங்களது கூந்தலில் சூடியிருக்கின்ற பெண்கள் கூட்டத்துடன் ஆண்களை கூடுமாறு செய்து அவர்களின் கூடுதலில் பிறவியை அமைத்து நிற்கின்றான் இறைவன்.`,
  },
  {
    id: 407, tantraId: 2, verseNumber: 406,
    tamil: `தேடுந் திசைஎட்டுஞ் சீவன் உடல்உயிர்
கூடும் பிறவிக் குணஞ்செய்த மாநந்தி
ஊடும் அவர்தம் துள்ளத்துள் ளேநின்று
நாடும் வழக்கமும் நான்அறிந் தேனே`,
    transliteration: `tēṭun ticaieṭṭuñ cīvaṉ uṭaluyir
kūṭum piṟavik kuṇañceyta mānanti
ūṭum avartam tuḷḷattuḷ ḷēniṉṟu
nāṭum vaḻakkamum nāṉaṟin tēṉē`,
    english: `406: Sadasiva is in the Heart of Even Those Who Doubt Him
He is Nandi the Great;
In directions eight,
He is life pervasive;
He brings body and soul together in birth;
Even in the heart of those who doubt Him, He is;
And from there He seeks them;
This I have known Him oft perform.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-406-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `உயிர்கள் தேடிப் பார்க்கக்கூடிய எட்டுத் திசைகளிலும் உடலோடு உயிராக ஆன்மா கூடித் தனது வினையின் பயனாக பிறவி எடுக்கும்படி செய்த மாபெரும் குருவான இறைவன் ஆணாகவும் பெண்ணாகவும் பிறவி பெற்ற அந்த உயிர்களின் உள்ளத்துக்குள் நின்று காதல் மயக்கத்தினால் ஒருவரை ஒருவர் நாடிச் சென்று மேலும் பிறவிகளை உருவாக்க காரணமாகவும் இருப்பதை இறைவனது திருவருளால் யான் அறிந்துகொண்டேன்.`,
  },
  {
    id: 408, tantraId: 2, verseNumber: 407,
    tamil: `ஓராய மேஉல கேழும் படைப்பதும்
ஓராய மேஉல கேழும் அளிப்பதும்
ஓராய மேஉல கேழுந் துடைப்பதும்
ஓராய மே உல கோடுயிர் தானே`,
    transliteration: `ōrāya mēula kēḻum paṭaippatum
ōrāya mēula kēḻum aḷippatum
ōrāya mēula kēḻun tuṭaippatum
ōrāya mē ula kōṭuyir tāṉē`,
    english: `407: The One Holy Family Performs All
The One Family creates the worlds seven;
The One Family preserves the worlds seven;
The One Family destroys the worlds seven;
The One Family pervades all life and body.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-407-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `தேவர்கள் உடல் கொண்ட மூர்த்தியாகவும் தேவியர்கள் உயிர்கொண்ட சக்தியாகவும் கூடி நின்று ஏழு உலகங்களையும் படைத்து காத்து அழிக்கின்றனர்.`,
  },
  {
    id: 409, tantraId: 2, verseNumber: 408,
    tamil: `நாதன் ஒருவனும் நல்ல இருவருங்
கோது குலத்தொடுங் கூட்டிக் குழைத்தனர்
ஏது பணியென் றிசையும் இருவருக்
காதி இவனே அருளுகின் றானே`,
    transliteration: `nātaṉ oruvaṉum nalla iruvaruṅ
kōtu kulattoṭuṅ kūṭṭik kuḻaittaṉar
ētu paṇiyeṉ ṟicaiyum iruvaruk
kāti ivaṉē aruḷukiṉ ṟāṉē`,
    english: `408: The Act of Genesis
The One Lord and the goodly two (Maya Saktis)
Together stirred and Commingled the Family Impure (of matter)
The Two then besought of the Lord:
"What shall we make? Command us, O Lord"
And the Lord Himself then spells them out.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-408-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `அனைத்திற்கும் தலைவனாகிய சிவம் ஒருவனும் அவனிடமிருந்து நன்மை புரியத் தோன்றிய சிவன் சக்தியாகிய இருவரும் சேர்ந்து அசுத்த மாயையில் பிறக்கும் மனித பிறப்பினரோடு சுத்தமாயையை கூட்டிச் சேர்த்து தேவர்களைப் படைத்தனர். இந்த தேவர்கள் இறைவனிடம் வந்து எங்களுக்கு இடும் பணி என்ன என்று கேட்டுப் பெற்று அப்படியே செய்வதாக ஏற்றுக்கொண்டு அதை செயல் படுத்துகின்றனர். இந்த தேவர்கள் அனைவருக்கும் தத்தமது பணிகளை கருணையால் அருளுபவன் ஆதியிலிருந்தே இருக்கின்ற இறைவன் ஆவான். உட்கருத்து: தேவர்கள் அனைவருமே முதலில் மனிதர்களாகப் பிறந்து பிறகு தவம் செய்து இறைவனிடம் தமக்கு கொடுக்கும் வேலைகளைக் கேட்டு அவனது அருளால் பெற்று அதை நடத்துபவர்களாகும். இதை 302, 380, 398 பாடல்களின் மூலம் தெரிந்து கொள்ளலாம்.`,
  },
  {
    id: 410, tantraId: 2, verseNumber: 409,
    tamil: `அப்பரி செண்பத்து நான்குநூ றாயிரம்
மெய்ப்பரி செய்தி விரிந்துயி ராய்நிற்கும்
பொய்ப்பரி செய்திப் புகலும் மனிதர்கட்
கிப்பரி சேஇருள் மூடிநின் றானே`,
    transliteration: `appari ceṇpattu nāṉkunū ṟāyiram
meyppari ceyti virintuyi rāyniṟkum
poyppari ceytip pukalum maṉitarkaṭ
kippari cēiruḷ mūṭiniṉ ṟāṉē`,
    english: `409: He Pervades All Creation as Life Within
And so,
Through creations four and eighty lakhs of species
He filled as life within;
Then men who in doubt ask: How is it?
Are verily to enveloping darkness condemned.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-409-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `இறைவன் உலகத்தில் பரிசாகக் கொடுத்தது என்பத்து நான்கு இலட்சம் வகை உயிரினங்களாகும். இந்த அனைத்து உயிர்களிலும் உண்மையான பரிசாக அவற்றுடன் கலந்து உயிராக நிற்பது இறைவனே ஆகும். ஆனால் இறைவனை தமக்குள் அறியாமல் ஆணவத்தால் அவன் எங்கே இருக்கின்றான் என்று கேட்கும் மனிதர்களை மாயை என்னும் ஆணவ இருளாய் உயிர்களுக்கு பரிசாய் இருக்கும் இறைவனே மூடியிருகின்றான்.`,
  },
  {
    id: 411, tantraId: 2, verseNumber: 410,
    tamil: `ஆதித்தன் சந்திரன் அங்கிஎண் பாலர்கள்
போதித்த வானொலி பொங்கிய நீர்ப்புவி
வாதித்த சத்தாதி வாக்கு மனாதிகள்
ஓதுற்ற மாயையின் விந்துவின் உற்றதே`,
    transliteration: `ātittaṉ cantiraṉ aṅkieṇ pālarkaḷ
pōtitta vāṉoli poṅkiya nīrppuvi
vātitta cattāti vākku maṉātikaḷ
ōtuṟṟa māyaiyiṉ vintuviṉ uṟṟatē`,
    english: `410: Varieties of Creation
The Sun, Moon, Agni and rest of celestials,
The space, air, fire, water and earth
The sound, word, mind andd the like
All these were of Maya born,
In union with Bindu.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-410-Second-Tantra-9.-Creation-of-Everything.mp3',
    elaborationTamil: `சூரியன், சந்திரன் மற்றும் அக்கினி, இந்திரன், இயமன், நிருதி, வருணன், வாயு, குபேரன், ஈசானன் ஆகிய எட்டுத்திசைகளுக்கான காவலர்களும் போதனை செய்யும் ஆகாயம், ஒலியை பரப்பும் காற்று, சுட்டெரிக்கும் நெருப்பு, நீர் இருக்கும் பூமி ஆகிய பஞ்ச பூதங்களும், கேட்டல், ருசித்தல், முகர்தல், பார்த்தல், உணர்தல் ஆகிய ஐந்து ஞானேந்திரியங்களும் வாக்கு, கைகள், கால்கள், உடல்கழிவுகளை வெளியே தள்ளும் உறுப்புகள் பிறப்புறுப்புக்கள் ஆகிய ஐந்து கர்மேந்திரியங்களும். செயல், புத்தி, சித்தம், அஹங்காரம் என நான்கு அந்தக்கரணங்கள் இவை அனைத்தும் அசையா சக்தி அசையும் சக்தியினால் தோன்றிய சுத்தமாயை அசுத்த மாயையில் இருந்து தோன்றியவையாகும்.`,
  },
  {
    id: 412, tantraId: 2, verseNumber: 411,
    tamil: `புகுந்துநின் றான்வெளி யாய்இரு ளாகிப்
புகுந்துநின் றான்புகழ் வாய்இகழ் வாகிப்
புகுந்துநின் றான்உட லாய்உயி ராகிப்
புகுந்துநின் றான்புந்தி மன்னிநின் றானே`,
    transliteration: `pukuntuniṉ ṟāṉveḷi yāyiru ḷākip
pukuntuniṉ ṟāṉpukaḻ vāyikaḻ vākip
pukuntuniṉ ṟāṉuṭa lāyuyi rākip
pukuntuniṉ ṟāṉpunti maṉṉiniṉ ṟāṉē`,
    english: `411: The Spirit Pervades All
As Light and Darkness He pervaded,
As Fame and Blemish He pervaded,
As Body and Life He pervaded,
As my constant thought He pervaded.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-411-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `உயிரின் உடலில் புகுந்து நிலையாய் நின்ற இறைவன் அவ்வுயிரின் அருள் அறிவு என்னும் வெளிச்சமாகவும் அறியாமை என்னும் இருளாகவும் அவ்வுயிருக்கு கிடைக்கும் புகழ்ச்சியாகவும் இகழ்ச்சியாகவும் அவ்வுயிரின் உடலாகவும் உயிராகவும் ஒன்றி அவ்வுயிரின் அறிவாகவும் நிரந்தரமாக கலந்து அவை வாழும் காலம் வரை அருளுகின்றான்.`,
  },
  {
    id: 413, tantraId: 2, verseNumber: 412,
    tamil: `தானே திசையொடு தேவரு மாய்நிற்குந்
தானே உடலுயிர் தத்துவ மாய்நிற்குந்
தானே கடல்மலை யாதியு மாய்நிற்குந்
தானே உலகில் தலைவனு மாமே`,
    transliteration: `tāṉē ticaiyoṭu tēvaru māyniṟkun
tāṉē uṭaluyir tattuva māyniṟkun
tāṉē kaṭalmalai yātiyu māyniṟkun
tāṉē ulakil talaivaṉu māmē`,
    english: `412: He is the Totality
Himself as space and celstials stands,
Himself as body, life and matter stands,
Himself as sea, hill and dale stands,
Himself--all worlds' Lord Supreme.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-412-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `உலகத்தை படைத்து அதனைக்காக்க இறைவன் ஒருவனே பத்து திசைகளாகவும் (எட்டுத் திசைகள், மேல், கீழ்) அவற்றைக் காத்து நிற்கும் தேவர்களாகவும் அனைத்து உயிர்களின் ஸ்தூல உடலாகவும் சூட்சும உயிராகவும் அவை இரண்டும் உணர்த்தும் இருபத்து நான்கு வகை தத்துவங்களாகவும் காணுகின்ற கடல் போன்ற நீர் நிலைகளாகவும் மலை போன்ற நிலப் பரப்புகளாகவும் அனைத்திற்கும் முதலாகவும் உலகத்திலுள்ள அனைத்திற்கும் தலைவனாகவும் இருக்கின்றான்.`,
  },
  {
    id: 414, tantraId: 2, verseNumber: 413,
    tamil: `உடலாய் உயிராய் உலகம தாகிக்
கடலாய் கார்முகில் நீர்ப்பொழி வானாய்
இடையாய் உலப்பிலி எங்குந்தா னாகி
அடையார் பெருவழி அண்ணல் நின்றானே`,
    transliteration: `uṭalāy uyirāy ulakama tākik
kaṭalāy kārmukil nīrppoḻi vāṉāy
iṭaiyāy ulappili eṅkuntā ṉāki
aṭaiyār peruvaḻi aṇṇal niṉṟāṉē`,
    english: `413: The True Way
As body, life, and world,
As sea, cloud and cloud-laden sky,
Permeating all, indestructible and continuous
The Lord stands in Majesty
The True way that never closes.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-413-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `உலகத்தை படைத்து அதனைக்காக்க அனைத்து உயிர்களின் உடலாகவும் சூட்சுமத்தில் உயிராகவும் அவை பிறந்து வாழும் அனைத்து உலகங்களாகவும் அந்த உலகங்களில் உயிர் தோன்ற வழி செய்யும் கடல்களாகவும் அவை வாழ வழி செய்யும் மழை நீரைப் பொழியும் கருத்த மேகங்களைக் கொண்ட வானமாகவும் வானத்துக்கும் பூமிக்கும் இடையில் இருக்கும் வெற்றிட ஆகாயமாகவும் அனைத்தும் தானே ஆகவும் உண்மையான அடியவர்கள் தேடி அடையும் முக்தியாகவும் இறைவன் ஒருவனே நிற்கின்றான். உட்கருத்து: உயிர்கள் அடைவதற்குரிய பெருவழியான முக்தியை அருளிய இறைவன் உலகப்பொருட்களில் அதுவாகவே இருக்கின்றான்.`,
  },
  {
    id: 415, tantraId: 2, verseNumber: 414,
    tamil: `தேடுந் திசைஎட்டுஞ் சீவன் உடல்உயிர்
கூடு மரபிற் குணஞ்செய்த மாநந்தி
ஊடும் அவர்தம துள்ளத்து ளேநின்று
நாடும் வழக்கமும் நான்அறிந் தேனே`,
    transliteration: `tēṭun ticaieṭṭuñ cīvaṉ uṭaluyir
kūṭu marapiṟ kuṇañceyta mānanti
ūṭum avartama tuḷḷattu ḷēniṉṟu
nāṭum vaḻakkamum nāṉaṟin tēṉē`,
    english: `414: Sadasiva is in the Heart of Even Those Who Doubt Him
He is Nandi the Great;
In directions eight,
He is life pervasive;
He brings body and soul together in birth;
Even in the heart of those who doubt Him, He is;
And from there He seeks them;
This I have known Him oft perform.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-414-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `உயிர்கள் தேடிப் பார்க்கக்கூடிய எட்டுத் திசைகளிலும் பிறவி எடுத்திருக்கும் பல ஆன்மாக்கள் கூடி நிற்கின்ற உடல்களின் உயிராகவும் அப்படிக் கூடுகின்ற காரணமான வினைப் பயனாகவும் இருக்கின்றவன் மாபெரும் குருவான இறைவன். அவனே உயிர்களின் உள்ளத்துக்குள் மன சாட்சியாய் நின்று அவற்றின் வினைப் பயனுக்கு ஏற்ப அவை அனுபவிக்கும் இன்பம் துன்பமாகவும் விருப்பு வெறுப்பாகவும் இருக்கும் முறையையும் அவனது கருணையினால் யான் அறிந்தேன். உட்கருத்து: பாடல் #406 இந்த பாடல் போலவே இருந்தாலும் அதில் பிறப்பைக் கூறிய திருமூலர் இதில் காப்பதைக் கூறியிருக்கின்றார். இதை ஒரு வார்த்தையையும் ஒரு எழுத்தையும் மாற்றி உணர்த்தி நிற்கின்றார் திருமூலர்.`,
  },
  {
    id: 416, tantraId: 2, verseNumber: 415,
    tamil: `தானொரு காலந் தனிச்சுட ராய்நிற்குந்
தானொரு கால்சண்ட மாருத மாய்நிற்குந்
தானொரு காலந் தண்மழை யாய்நிற்குந்
தானொரு காலந்தண் மாயனு மாமே`,
    transliteration: `tāṉoru kālan taṉiccuṭa rāyniṟkun
tāṉoru kālcaṇṭa māruta māyniṟkun
tāṉoru kālan taṇmaḻai yāyniṟkun
tāṉoru kālantaṇ māyaṉu māmē`,
    english: `415: Lord is Diverse
At the end of aeons,
Once He stands as Pure Light,
Once as the tempestuous typhoon,
Once as incessant rain,
Once as Vishu, floating on the deluge.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-415-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `இறைவன் ஒருவனே ஆதி காலத்தில் இருந்தே மாபெரும் தனிச்சுடர் கொண்ட பேரொளியாய் நிற்கின்றான். அழிக்கின்ற காலத்தில் சூராவளிப் புயலாக இருக்கின்றான். உயிர்களை வாழ்விக்கின்ற காலத்தில் குளிர்ச்சியுடைய மழையாய் வருகின்றான். காலத்திற்கு ஏற்ப உருவம் கொண்டு உயிர்களைக் காப்பாற்றும் திருமாலின் தன்மையாகவும் அவனே இருக்கின்றான்.`,
  },
  {
    id: 417, tantraId: 2, verseNumber: 416,
    tamil: `அன்பும் அறிவும் அடக்கமு மாய்நிற்கும்
இன்பமும் இன்பக் கலவியு மாய்நிற்கும்
முன்புறு காலமும் ஊழியு மாய்நிற்கும்
அன்புற ஐந்தில் அமர்ந்துநின் றானே`,
    transliteration: `aṉpum aṟivum aṭakkamu māyniṟkum
iṉpamum iṉpak kalaviyu māyniṟkum
muṉpuṟu kālamum ūḻiyu māyniṟkum
aṉpuṟa aintil amarntuniṉ ṟāṉē`,
    english: `416: He Stands in Divine Love
As love, wisdom and meekness He stands,
As pleasure and pleasureable union He stands,
As Time's Beginning and End He stands,
As Five elements filled He stands in love divine.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-416-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `அனைத்து உயிர்களுக்குள்ளும் தோன்றும் உண்மையான அன்பாகவும் அறிவாகவும் அவை பெறும் ஒழுக்கமான அடக்கமாகவும் இருப்பவன் இறைவனே. நல் வினையால் உயிர்கள் பெறும் இன்பமாகவும் இன்பத்தில் மற்ற உயிர்களோடு கலக்கும் புணர்ச்சியாகவும் இருப்பவன் இறைவனே. உலகம் உருவான ஆதிகாலமாகவும் அந்த உலகம் இறுதியில் அழியும் ஊழிக் காலமாகவும் இருப்பவன் இறைவனே. அவனே உயிர்களிடத்தில் கொண்ட மாபெரும் அன்பினால் ஐந்து பூதங்களிலும் அமர்ந்து இருந்து உயிர்களை எப்போதும் காத்து அருளுகின்றான்.`,
  },
  {
    id: 418, tantraId: 2, verseNumber: 417,
    tamil: `உற்று வனைவான் அவனே உலகினைப்
பெற்று வனைவான் அவனே பிறவியைச்
சுற்றிய சாலுங் குடமுஞ் சிறுதூதை
மற்றும் அவனே வனையவல் லானே`,
    transliteration: `uṟṟu vaṉaivāṉ avaṉē ulakiṉaip
peṟṟu vaṉaivāṉ avaṉē piṟaviyaic
cuṟṟiya cāluṅ kuṭamuñ ciṟutūtai
maṟṟum avaṉē vaṉaiyaval lāṉē`,
    english: `417: He Fashions Things Big and Small
Himself fashions worlds all in detail minute
Himself fashions life, conferring birth
Himself fashions things big and small
--The cauldron, the pitcher and the pot
Himself He fashions these and more
--He the Architect Almighty.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-417-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `உயிர்கள் உருவாக வேண்டும் என்ற எண்ணத்தில் உயிர்களைப் பல்வேறு உலகங்களிலும் உருவாக்குபவன் இறைவனே. அவனே உயிர்களின் வினைப் பயனைப் பெற்று அதன் காரணமாக பிறவியை உருவாக்குபவன். ஒரு குயவன் தனது அச்சுச் சக்கரத்தில் களிமண்ணை வைத்துச் சுற்றி அந்தக் களிமண்ணைப் பிடித்து தாழியும், குடமும், சிறு பாண்டங்களும் மற்றும் பலவிதமான மண் பாத்திரங்களும் செய்வதைப் போல இறைவன் உயிர்களின் வினைகளுக்கு ஏற்ப பல்வேறு விதமான உடல்களை வடித்து அருளும் வல்லமை உள்ளவன் ஆவான்.`,
  },
  {
    id: 419, tantraId: 2, verseNumber: 418,
    tamil: `உள்ளுயிர்ப் பாயுட லாகிநின் றான்நந்தி
வெள்ளுயி ராகும் வெளியான் நிலங்கொளி
உள்ளுயிர்க் கும்உணர் வேயுட லுட்பரந்
தள்ளுயி ராவண்ணந் தாங்கிநின் றானே`,
    transliteration: `uḷḷuyirp pāyuṭa lākiniṉ ṟāṉnanti
veḷḷuyi rākum veḷiyāṉ nilaṅkoḷi
uḷḷuyirk kumuṇar vēyuṭa luṭparan
taḷḷuyi rāvaṇṇan tāṅkiniṉ ṟāṉē`,
    english: `418: He is Nandi
He is Life within; He is the body corporeal;
He is Spirit Pure; He is space Infinite;
He is Light Radiant; He is Consciousness inside;
Animating life in the body
He supports me;
--He is Nandi.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-418-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `அனைத்து உயிர்களுக்கும் உள்ளிருக்கும் உயிராகவும் வெளியிலிருக்கும் உடலாகவும் மூச்சுக்காற்றாகவும் நின்று கர்மாக்கள் வினைகள் சூழ்ந்த அசுத்த மாயையில் இருக்கும் உலக உயிர்களையும் கர்மாக்கள் வினைகள் இல்லாத சுத்த மாயையில் இருக்கும் தேவர்களையும் தாண்டிய பரவெளியில் உண்மைப் பொருளை உணர வைக்கும் பேரொளியாக குருவாய் நின்று அருளுகின்றான் இறைவன். அனைத்து உயிர்களுக்குள் உயிராகவும் உணர்வாகவும் அவற்றின் உடலுக்குள் பரவி இருந்து அந்த உயிர்களின் மூச்சுக்காற்று உடலை விட்டு செல்லாதபடி உடலையும் உயிரையும் உள்ளுக்குள்ளிருந்து தாங்கிக் கொண்டு நிற்பவனும் இறைவனே.`,
  },
  {
    id: 420, tantraId: 2, verseNumber: 419,
    tamil: `தாங்கருந் தன்மையுந் தானவை பல்லுயிர்
வாங்கிய காலத்து மற்றோர் பிறிதில்லை
ஓங்கி எழுமைக்கும் யோகாந்த மவ்வழி
தாங்கிநின் றானும்அத் தாரணி தானே`,
    transliteration: `tāṅkarun taṉmaiyun tāṉavai palluyir
vāṅkiya kālattu maṟṟōr piṟitillai
ōṅki eḻumaikkum yōkānta mavvaḻi
tāṅkiniṉ ṟāṉumat tāraṇi tāṉē`,
    english: `419: He Supports All Worlds
A miracle indeed it is
To sustain the myriad lives in the Universe;
Not less so,
When after total destruction
He draws them unto Himself;
He supports too
That Seventh World
The Path of yoga leads to.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-419-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationTamil: `பல்வேறு விதமான உயிர்களுக்கும் அவற்றின் உடலுக்குள் இருந்து உயிரைத் தாங்கும் தன்மையாக இருக்கும் இறைவனே அவை அழியும் காலத்தில் உள்ளிருந்து வெளியே வரும் உயிரை வாங்குகின்றவனாகவும் இருக்கின்றான். அவனைத் தவிர உயிர்களைத் தாங்கவும் வாங்கவும் அருள் செய்யும் தெய்வம் வேறு ஒன்று இல்லை. இப்படி ஏழு உலகங்களையும் அதிலிருக்கும் அனைத்து உயிர்களையும் தாங்கி நிற்கின்ற இறைவனே அதைத் தாண்டிய விண்ணுலகத்தையும் தாங்கி நிற்கின்றான். அவனே உயிர்கள் தமது பிறவிச் சூழலிலிருந்து விடுபட்டு விண்ணுலகம் அடைய வழியாக யோக முறைகளையும் அருளி அந்த முறைகளைப் பின்பற்றி வரும் உயிர்களின் வழிமுழுவதும் அவற்றைக் காத்தும் அருளுகின்றான்.`,
  },
  {
    id: 421, tantraId: 2, verseNumber: 420,
    tamil: `அணுகினுஞ் சேயவன் அங்கியிற் கூடி
நணுகினும் ஞானக் கொழுந்தொன்று நல்கும்
பணுகினும் பார்மிசைப் பல்லுயி ராகித்
தணிகினும் மண்ணுடல் அண்ணல்செய் வானே`,
    transliteration: `aṇukiṉuñ cēyavaṉ aṅkiyiṟ kūṭi
naṇukiṉum ñāṉak koḻuntoṉṟu nalkum
paṇukiṉum pārmicaip palluyi rākit
taṇikiṉum maṇṇuṭal aṇṇalcey vāṉē`,
    english: `420: He Grants Immortal Body to Those Who Seek Him in Love
Well may you seek Him
Through rituals before fires,
Distant only shall He be;
Seek Him in yearning love
Bend low on ground
Hanker after Him life after life,
The great One Shall Grant you the body immortal.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-420-Second-Tantra-10.-Remembering-the-Dead.mp3',
    elaborationEnglish: `Mantras 411 - 420

The creation that ensued thus has to be continuously sustained. Although Vishnu is entrusted with this task, He is onJy an aspect of Siva/Sakti; and so ultimately it is Siva who performs the task of preservation. And so He pervades all: as body and life, as light and darkness, as fame and ignominy, as oceans and continents, as space and the celesuajs, as sea, hill and dale—through the entirety of creation in unbroken continuity. He pervades our thoughts too. There He stands as love, wisdom and meekness as pleasure and pleasurable union, as the beginning and end of time. He sustains the yogic path that leads to the state of existence.

To sustain the lives in countless universes is indeed a miracle that staggers the imaginatidn. But even after the destruction of the cosmos at the end of an aeon, He draws the jivas to Himself, and sustains them in quiescent slumber’ until the next of creation commences.

Thus Vishnu performs the function of sustenance only as ordained by Siva. .`,
    elaborationTamil: `அனைத்து உயிர்களின் உள்ளுக்குள்ளும் இறைவன் இருந்தாலும் அவனை அறிந்து கொள்ள முடியாதபடி மாயையால் மறைக்கப்பட்டு இருக்கின்றான். அவனை மூச்சுக்காற்றின் மூலம் குண்டலினியை மேலெழுப்பி சகஸ்ரர தளத்தில் கொண்டு சேர்த்துவிட்டால் பேரறிவு ஞானத்தைத் தந்து அருளுவான். அதன் மூலம் பிறவிச் சுழற்சியை அறுத்து முக்தி பெறலாம். இறைவனை எவ்வளவு தான் பணிந்து தொழுதாலும் ஞானத்தை அடைய வேண்டும் என்ற எண்ணம் இல்லாமல் உலக ஆசைகளோடு இருந்தால் உலகத்தில் பல்வேறு விதமான உயிர்களாக உடலெடுத்துப் பிறந்து அழிந்தாலும் மீண்டும் மீண்டும் மண்ணுலகத்தில் உடல் பெறவே செய்வான் உலகத்தின் தலைவனாகிய இறைவன்.`,
  },
  {
    id: 422, tantraId: 2, verseNumber: 421,
    tamil: `அங்கிசெய் தீசன் அகலிடஞ் சுட்டது
அங்கிசெய் தீசன் அலைகடற் சுட்டது
அங்கிசெய் தீசன் அசுரரைச் சுட்டது
அங்கியவ் வீசற்குக் கைஅம்பு தானே`,
    transliteration: `aṅkicey tīcaṉ akaliṭañ cuṭṭatu
aṅkicey tīcaṉ alaikaṭaṟ cuṭṭatu
aṅkicey tīcaṉ acuraraic cuṭṭatu
aṅkiyav vīcaṟkuk kaiampu tāṉē`,
    english: `421: Fire is Lord's Shaft
With fire the Lord burnt all Space
With fire the Lord burnt the Oceans,
With fire the Lord burnt the Asuras
Fire, verily, is the Lord's shaft on hand.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-421-Second-Tantra-11.-Destruction.mp3',
    elaborationTamil: `இறைவன் பஞ்சபூதங்களில் ஒன்றான நெருப்பின் மூலம் பிரளய காலத்தில் பரந்து விரிந்த உலகத்தையும் அலைகள் நிறைந்த கடல்களையும் அறியாமையாகிய அசுரர்களையும் அழித்து அருளினான். இறைவனால் உருவாக்கப்பட்ட அனைத்தும் அதனதன் வினையின்படி அழிந்து நன்மை பெறுவதற்காக இறைவன் அழித்தல் தொழிலை செய்யும் போது நெருப்பு அவனது திருக்கரத்தில் அம்பாக இருக்கின்றது.`,
  },
  {
    id: 423, tantraId: 2, verseNumber: 422,
    tamil: `இலயங்கள் மூன்றினும் ஒன்றுகற் பாந்த
நிலையன் றழிந்தமை நின்றுணர்ந் தேனால்
உலைதந்த மெல்லரி போலும் உலகம்
மலைதந்த மானிலந் தான்வெந் ததுவே`,
    transliteration: `ilayaṅkaḷ mūṉṟiṉum oṉṟukaṟ pānta
nilaiyaṉ ṟaḻintamai niṉṟuṇarn tēṉāl
ulaitanta mellari pōlum ulakam
malaitanta māṉilan tāṉven tatuvē`,
    english: `422: Three are His Layas
Three are His layas--the moments of Repose
Of them one, karpandha--the end of aeons,
I witnessed;
All things fell uprooted in destruction
This orb then was unto a boiling rice pot
Its mountains and valleys alike burnt to ashes.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-422-Second-Tantra-11.-Destruction.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `இறைவன் வினையின்படி அனைத்தையும் அழிக்கும் மூன்று விதமான பிரளய வகைகளில் கற்பாந்தப் பிரளயத்தில் நிலையில்லாத இந்த உலகம் இழிவு நிலை பெற்று அழிந்து போனதை யானும் இறைவனின் திருவருளால் அவனோடு நின்று கண்டு உணர்ந்தேன். உலையில் இடப்பட்ட அரிசி நெருப்பினால் சூடு பெற்று கொதித்து வெந்து சாதமாகிறதோ அதுபோல மலைகளால் சூழப்பட்ட மாபெரும் நிலப்பரப்பான இந்த உலகமும் இறைவன் தந்த நெருப்பினால் வெந்து அழிந்தது. மூன்று வகை பிரளயங்கள்: தினப் பிரளயம் – ஒவ்வொரு உயிரும் தினமும் தூங்கி எழும் இடைவெளியில் நிகழும் அழிவுகள் கற்பாந்தப் பிரளயம் – வினை முடிந்தபின் வரும் அழிவுகள் (உயிர்களோடு உலகமும் அழிவது) மகாப் பிரளயம் – ஊழிக்காலத்தில் வரும் பேரழிவு (அண்டங்களையே அழிக்கக் கூடியது)`,
  },
  {
    id: 424, tantraId: 2, verseNumber: 423,
    tamil: `பதஞ்செய்யும் பாரும் பனிவரை எட்டும்
உதஞ்செய்யும் ஏழ்கடல் ஓதம் முதலாங்
குதஞ்செய்யும் அங்கி கொளுவியா காசம்
விதஞ்செய்யும் நெஞ்சில் வியப்பில்லை தானே`,
    transliteration: `patañceyyum pārum paṉivarai eṭṭum
utañceyyum ēḻkaṭal ōtam mutalāṅ
kutañceyyum aṅki koḷuviyā kācam
vitañceyyum neñcil viyappillai tāṉē`,
    english: `423: The Fire Spreads
The earth on which we tread
The snow-clad mountains eight.
The seven seas whose ebbing tides roar,
Over all these and else
The Fire that resides in Muladhara spreads;
And the spreading conflagration turned
Earth and sky seem alike;
--This the truth, imagination none.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-423-Second-Tantra-11.-Destruction.mp3',
    elaborationTamil: `உயிர்களுக்கு இயற்கையை வழங்கி அவர்களை வாழ வைக்கும் உலகமும் பனிபடர்ந்து ஓங்கி நிற்கும் எட்டு விதமான மலைகளும் ஓசை எழுப்பும் அலைகளைக் கொண்ட ஏழு விதமான கடல்களின் வெள்ளப் பெருக்கும் ஆகிய இவை அனைத்தும் இறைவனின் சிறிதளவு நெருப்பினால் அழிந்து ஆகாயம் போல வெற்றிடமாகும் விதத்தைக் கண்ட உண்மை ஞானிகளுக்கு வியப்பாக இருக்காது.`,
  },
  {
    id: 425, tantraId: 2, verseNumber: 424,
    tamil: `கொண்டல் வரைநின் றிழிந்த குலக்கொடி
அண்டத்துள் ஊறி யிருந்தெண் டிசையாதி
ஒன்றின் பதந்செய்த ஓம்என்ற அப்புறக்
குண்டத்தின் மேலங்கி கோலிக் கொண்டானே`,
    transliteration: `koṇṭal varainiṉ ṟiḻinta kulakkoṭi
aṇṭattuḷ ūṟi yirunteṇ ṭicaiyāti
oṉṟiṉ patanceyta ōmeṉṟa appuṟak
kuṇṭattiṉ mēlaṅki kōlik koṇṭāṉē`,
    english: `424: The Fire Spreads to the Seas Also
From aloft the cloud laden mountains
She descended--
The benign river Ganga;
Into the earth the waters seeped
In directions eight,
Emptying itself eventually
Into the deep pit that is the Ocean,
That Constant sings the praise of Lord
With Chant of "Aum"
--That Ocean too the fire gulped in fury.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-424-Second-Tantra-11.-Destruction.mp3',
    elaborationTamil: `மழை நீரைக் கொண்டிருப்பதால் கருத்த மேகங்கள் காற்றினால் தள்ளப்பட்டு மலைகளின் மழையாகப் பொழிந்து மழை அருவியாகி அருவி ஆறாகி ஆறு எட்டுத்திசையிலும் உள்ள நிலங்களிலெல்லாம் பரவி ஆற்றின் தண்ணீர் நிலத்தில் ஊறி உயிர்களை காக்கும் அனைத்துவிதமான உணவு பொருட்களையும் விளைவித்து பின் ஆற்றின் தண்ணீர் கடலில் கலந்து அதுவே பெருங்கடலாக உருவெடுத்து நிலங்களையெல்லாம் சூழ்ந்து கடல் இருக்கும். வினையின் படி நன்மைக்காக இறைவன் தனது சக்தியை ஓம் எனும் மந்திரத்தை பதம் செய்து யாகக் குண்டத்தின் மேலெழும்பி வரும் சிறிய நெருப்பினால் அழித்து தன்னுள் அடக்கிக் கொள்கிறான் இறைவன். உள்விளக்கம்: நல்வினையின் காரணமாக கருத்த மேகங்கள் அழிந்து மழையாகப்பொழிகிறது. மழைநீர் நிலங்களுக்கு பரவி உணவு பொருட்களை உற்பத்தி செய்ய அழிந்து போகின்றது. மீதம் இருக்கும் நல்ல மழை நீர் கடலினில் கலந்து அழிந்து உப்பு நீராகிறது. அந்த நீர் மீண்டும் அழிந்து கருத்த நீர் இருக்கும் மேகமாகின்றது. இது போல் உலகத்தில் நடக்கும் பல அழிவுகளும் உலக நன்மைக்காக இறைவன் ஓம் என்னும் மந்திரத்தை பதம் செய்து உலகம் என்னும் குண்டத்தில் அக்னியை உருவாக்கி செய்கின்றான்.`,
  },
  {
    id: 426, tantraId: 2, verseNumber: 425,
    tamil: `நித்தசங் காரம் உறக்கத்து நீள்மூடம்
வைத்தசங் காரமுஞ் சாக்கிரா தீதமாஞ்
சுத்தசங் காரந் தொழிலற்ற கேவலம்
உய்த்தசங் காரம் பரன் அருள் உண்மையே`,
    transliteration: `nittacaṅ kāram uṟakkattu nīḷmūṭam
vaittacaṅ kāramuñ cākkirā tītamāñ
cuttacaṅ kāran toḻilaṟṟa kēvalam
uyttacaṅ kāram paraṉ aruḷ uṇmaiyē`,
    english: `425: Four Forms of Death
Four are the forms of death
Daily death is the state of sense loss in sleep;
Fated Death is no-return to waking;
Pure Death is when the Soul reacheth inertia;
Redeemed Death is being in Lord's Grace True.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-425-Second-Tantra-11.-Destruction.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `நித்த சங்காரம் என்பது உயிர்கள் உறங்கும் போது தம்மைச் சுற்றி என்ன நடக்கிறது என்பதை முற்றிலும் அறியாத நிலையாகும். வைத்த சங்காரம் என்பது உயிர்கள் இளைப்பாற வேண்டும் என்று உறங்கும்போது ஏற்படும் கனவு நிலையாகும். சுத்த சங்காரம் என்பது உயிர்கள் உடலை விட்டு உயிர் பிரிந்த ஆன்மா ஆணவ மலத்திலேயே இருந்து பிறக்கவும் முடியாமல் இறைவனிடமும் செல்ல முடியாமல் எந்தச் செயலும் செய்ய முடியாமல் கிடக்கும் கேவலமான நிலையாகும். உய்த்த சங்காரம் என்பது இறைவனது திருவருளால் ஆன்மா உண்மைப் பொருளான இறைவனுடனே சென்று இரண்டறக் கலந்துவிடுகின்ற நிலையாகும். உள்விளக்கம்: நித்த சங்காரம் – தூங்கும் போது நான் என்ற எண்ணம் அழிந்திருந்த நிலை. வைத்த சங்காரம் – தூங்கும் போது கனவில் எல்லாம் தன்னுடையது போல் இருக்கும் ஆனால் விழித்ததும் எதுவும் தனது இல்லை என்று அனைத்தும் அழிந்த நிலை. சுத்த சங்காரம் – உடல் அழிந்த பின் ஆத்மா தான் என்ற அகங்காரத்தினால் உடலெடுக்கவும் முடியாமல் இறைவனுடன் கலக்கவும் முடியாத நிலை. இதனை கேவலமான நிலை என்று பாடலில் கூறுகிறார். உய்த்த சங்காரம் – உடல், உயிர் அனைத்தும் அழிந்து இறைவனுடன் கலக்கும் நிலை.`,
  },
  {
    id: 427, tantraId: 2, verseNumber: 426,
    tamil: `நித்தசங் காரம் இரண்டுடல் நீவுதல்
வைத்தசங் காரமும் மாயாசங் காரமாஞ்
சுத்தசங் காரம் மனாதீதந் தோய்வுறல்
உய்த்தசங் காரஞ் சிவன் அருள் உண்மையே`,
    transliteration: `nittacaṅ kāram iraṇṭuṭal nīvutal
vaittacaṅ kāramum māyācaṅ kāramāñ
cuttacaṅ kāram maṉātītan tōyvuṟal
uyttacaṅ kārañ civaṉ aruḷ uṇmaiyē`,
    english: `426: What Transpires in the Four Deaths
In Daily Death, are bodies gross and subtle transcended;
In Fated Death, is the Mayaic body annihilated;
In Pure Death, Mind and cognates merge in Infinite
In Redemption Death, Siva's Grace descends true.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-426-Second-Tantra-11.-Destruction.mp3',
    elaborationTamil: `நித்த சங்காரத்தில் உயிர் ஸ்தூல சூட்சும சரீரங்களுடன் தொடர்பு கொண்டிருக்கும். வைத்த சங்காரத்தில் மாயையுடன் கனவு நிலையில் உயிர் ஸ்தூல உடலை விட்டு விலகி சூட்சும உடலுடன் தொடர்பு கொண்டிருக்கும். சுத்த சங்காரத்தில் மனம் எந்த எண்ணமும் இல்லாமல் செயல் ஒன்றும் இல்லாது இருக்கும். உய்த்த சங்காரத்தில் சிவன் அருளில் லயித்து இருக்கும். இதுவே உண்மையான சங்காரம் ஆகும்.`,
  },
  {
    id: 428, tantraId: 2, verseNumber: 427,
    tamil: `நித்தசங் காரம் கருவிடர் நீக்கினால்
ஒத்தசங் காரமும் உடலுயிர் நீவுதல்
வைத்தசங் காரம் கேவலம் ஆன்மாவுக்கு
உய்த்தசங் காரம் சிவமாகும் உண்மையே`,
    transliteration: `nittacaṅ kāram karuviṭar nīkkiṉāl
ottacaṅ kāramum uṭaluyir nīvutal
vaittacaṅ kāram kēvalam āṉmāvukku
uyttacaṅ kāram civamākum uṇmaiyē`,
    english: `427: Four Forms of Death
When but birth--impediment uprooted,
Daily Death is unto Fated Death
And Fated Death unto Pure Death
And Pure Death unto Redemption Death
In that alone is the Truth--Jiva becoming Siva.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-427-Second-Tantra-11.-Destruction.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உலகத்தில் பிறவி எடுக்க தாய் வயிற்றில் கருவாகப் பிறந்த அனைத்து உயிர்களுமே தங்களின் வினைப் பயனாகிய துன்பங்களையும் சேர்த்துக் கொண்டுதான் பிறக்கின்றன. இறைவனது கருணையினால் அந்த துன்பங்கள் சிறிது நேரமாவது நீங்கித் தம்மை மறந்து உயிர்கள் இருக்கும் தூக்க நிலை தினமும் நிகழும் நித்த சங்காரமாகும். உடலை விட்டு உயிர் பிரிந்து ஆன்மா மட்டுமே இருக்கின்ற நிலை சுத்த சங்காரமாகும் ஸ்தூல உடலும் சூட்சும உடலும் பிரிந்து இருக்கும் கனவு நிலையில் ஆன்மா மாயையிலேயே மூழ்கி கேவலப்பட்டு இருக்கின்ற நிலை வைத்த சங்காரமாகும். வினைகளையெல்லாம் தீர்த்துவிட்ட உயிர் ஸ்தூல உடலை விட்டுப் பிரிந்து சூட்சும உடலும் அழிந்து தனித்தன்மையோடு இருந்த ஆன்மா உண்மைப் பொருளான இறைவனுடனே இரண்டறக் கலந்துவிடும் போது நான் எனும் தனித்தன்மை முற்றிலும் அழிந்து சிவமாக மாறும் நிலை உய்த்த சங்காரமாகும்.`,
  },
  {
    id: 429, tantraId: 2, verseNumber: 428,
    tamil: `நித்தசங் காரமும் நீடிளைப் பாற்றலின்
வைத்தசங் காரமும் மன்னும் அனாதியிற்
சுத்தசங் காரமுந் தோயாப் பரன்அருள்
வைத்தசங் காரமும் நாலாம் மதிக்கிலே`,
    transliteration: `nittacaṅ kāramum nīṭiḷaip pāṟṟaliṉ
vaittacaṅ kāramum maṉṉum aṉātiyiṟ
cuttacaṅ kāramun tōyāp paraṉaruḷ
vaittacaṅ kāramum nālām matikkilē`,
    english: `428: Thus Four are the Deaths
Thus are Deaths Four;
The Daily Death in deep Sleep;
The Fated Death that gives the soul a longer rest;
The Pure Death that puts the Soul in primal quiescence;
The Redemption Death that steeps the Soul in Lord's Grace.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-428-Second-Tantra-11.-Destruction.mp3',
    elaborationTamil: `உயிர்கள் தங்களது துன்பங்களை மறந்து நீண்ட நேரத்திற்கு இளைப்பாற வேண்டும் என்கிற இறைவனது கருணையினால் நித்த சங்காரம் நிகழ்கிறது. ஆரம்பம் இல்லாத கனவு நிலையில் உலக மாயைகளெல்லாம் மறைந்து எண்ணங்களும் இல்லாமல் உயிர்கள் சிறிது நேரமாவது இளைப்பாற வேண்டும் என்கிற இறைவனது கருணையினால் வைத்த சங்காரம் நிகழ்கிறது. இறைவனது திருவருளை மட்டுமே எண்ணிக் கொண்டு மற்ற அனைத்தையும் விட்டு விலகி ஆன்மா திரும்ப வர வேண்டும் என்கிற இறைவனது கருணையினால் சுத்த சங்காரம் நிகழ்கிறது. அனைத்து வினைகளையும் கழித்த ஆன்மா இனி தனித்தன்மை இல்லாமல் உண்மைப் பொருளான இறைவனுடனே கலந்துவிட வேண்டும் என்கிற இறைவனது கருணையினால் உய்த்த சங்காரம் நிகழ்கிறது. இறைவனது கருணையை மதித்துப் பார்த்தால் இந்த நான்கு சங்காரங்களும் உயிர்களின் நன்மைக்காகவே இறைவன் வைத்திருக்கின்றான்.`,
  },
  {
    id: 430, tantraId: 2, verseNumber: 429,
    tamil: `பாழே முதலா எழும்பயிர் அப்பயிர்
பாழாய் அடங்கினும் பண்டைப்பாழ் பாழாகா
வாழாச்சங் காரத்தின் மாலயன் செய்தியாம்
பாழாம் பயிராய் அடங்கும்அப் பாழிலே`,
    transliteration: `pāḻē mutalā eḻumpayir appayir
pāḻāy aṭaṅkiṉum paṇṭaippāḻ pāḻākā
vāḻāccaṅ kārattiṉ mālayaṉ ceytiyām
pāḻām payirāy aṭaṅkumap pāḻilē`,
    english: `429: Void the Beginning and End
Out of Void, a plant (soul) it sprang,
To the Void it returns;
Yet shall it not be Void again;
In that Void, exhausted, it shall die;
That the fate of Hari and Brahma too,
Who the holocaust of Samhara survvive not.`,
    elaborationTamil: `சேற்றுச் சகதியில் விதைத்த விதை அந்தச் சகதியையே ஆதாரமாகக் கொண்டு அதனிடமிருந்து வெளிப்பட்டு பயிராக மேலெழும்பி வருவதைப் போல அனைத்திற்கும் பழைமையான இறைவனிடமிருந்து அவனையே முதலாகக் கொண்டு அவனிடமிருந்து வெளிப்பட்டு உலகத்தில் கருவாக வந்து பிறக்கின்றது ஆன்மா. விளைந்த பயிர் பயன்படுத்தப்பட்ட பிறகு அழிந்து திரும்பவும் மண்ணோடு மண்ணாகவே ஆகிவிட்டாலும் அது எப்படி முன்பு விதைத்த விதைக்குள் மீண்டும் போய் சேர முடியாதோ அதுபோலவே உலகத்தில் கருவாக வந்து பிறந்த ஆன்மா உலகத்தில் வாழ்ந்து இறந்த பிறகும் திரும்பவும் இறைவனிடமே சென்று சேர்ந்துவிட முடியாது. இதனாலேயே ஆன்மாவுக்குத் தனித்த வாழ்வு என்பது இல்லாத சங்காரச் சுழற்சியில் தள்ளப்பட்டு மீண்டும் பிரம்மனால் கருவாக பிறந்து திருமாலால் காக்கப்பட்டு வளர்ந்து மறுபடியும் சங்காரத்தில் இறந்து கொண்டே இருக்கும். எப்போது மண்ணில் பிறந்த பயிர் மண்ணிலே கலந்து அந்த மண்ணும் ஒரு நாள் மறைந்து போகின்றபோது அந்தப் பயிரின் தடயமே அழிந்து போய்விடுவது போல உலகத்தில் மீண்டும் மீண்டும் பிறவி எடுத்து இறக்கும் ஆன்மா எப்போது வினைகளை முடித்துத் தான் என்கிற தடயத்தை (ஆணவ மலம்) முற்றிலும் துறந்து மாயைகளை நீக்கி உண்மையை உணருகின்றதோ அப்போது அது தோன்றிய இறைவனிடமே சென்று அடங்கிவிடும். உட்கருத்து: ஆன்மாவைப் பயிராகவும் இறைவனை சகதியாகவும் உருவகிக்கும் திருமூலர் இந்த உவமையின் மூலம் சங்காரத்தின் தத்துவமும் அது ஏன் நிகழ்கிறது என்கிற விளக்கத்தையும் தந்து அருளுகிறார். இறைவனிடமிருந்து முதலில் தோன்றிய ஆன்மா உலகத்தில் பிறவி எடுத்து வினையினால் பிறவிச் சுழலில் சிக்கித் தன் வினைகளையெல்லாம் முடித்துவிட்டு பிறகு இறைவனிடமே வந்து அடங்கிவிடுவதே சங்காரத்தின் தத்துவமும் அதன் பயனுமாகும்.`,
  },
  {
    id: 431, tantraId: 2, verseNumber: 430,
    tamil: `தீயவைத் தார்மிங்கள் சேரும் வினைதனை
மாயவைத் தான்வைத்த வன்பதி ஒன்றுண்டு
காயம்வைத் தாங்கலந் தெங்கும் நினைப்பதோர்
ஆயம்வைத் தானுணர் வாரவைத் தானே`,
    transliteration: `tīyavait tārmiṅkaḷ cērum viṉaitaṉai
māyavait tāṉvaitta vaṉpati oṉṟuṇṭu
kāyamvait tāṅkalan teṅkum niṉaippatōr
āyamvait tāṉuṇar vāravait tāṉē`,
    english: `430: Scorch Your Karmas
Scorch the gathering Karmas
And exhaust them;
There is One who annihilates them
And the city where He does it
He fashioned the body, He pervades everywhere.
He placed the Mind and cognate tattva group besides,
He gave us Wisdom ample to discriminate.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-429-Second-Tantra-11.-Destruction.mp3',
    elaborationEnglish: `Mantras 429 & 430

The jiva sprang as a plant out of the void, and into the void, it shall finally retum. Even the gods are not exempt from this law. Death follows birth, as the night follows day: The only escape from death is not to be born again. By uprooting karma alone, can the birth-death be ended. God dissolves the karma; pray to Him.

Rudra is the god to whom the work of destruction is entrusted, but the real power behind Rudra is that of Siva.`,
    elaborationTamil: `இறைவனிடமிருந்து தோன்றிய ஆன்மா தனது ஆசைகளை அனுபவித்துத் தீர்த்துக் கொள்ள செய்யும் செயலினால் சேரும் வினைகளைத் தீர்க்க மாயையை வைத்து அந்த வினைகள் தீர உடலையும் ஆன்மாவிற்கு கொடுத்துப் பிறவி எடுக்க வைக்கின்றான். பிறவி எடுத்த ஆன்மா வினைச் சுழலில் சிக்கி மீண்டும் மீண்டும் பிறவி எடுத்துக் கொண்டே இருக்கக் கூடாது என்கிற கருணையினால் உலகத்திலுள்ள அனைத்திலும் கலந்து இருக்கும் இறைவன் தன்னை அடையும் வழிகள் அறிந்த கலந்து குருவாய் இருக்கும் அடியார்களோடு சேர வைத்து தன்னை எப்போதும் நினைக்கக் கூடிய எண்ணத்தை வைக்கின்றான். இறைவனின் சிந்தனையிலேயே இருப்பதால் மாயை அழிந்து நான் என்கின்ற அகங்காரம் அழிந்து ஆன்மா மீண்டும் தம்மை வந்து அடையும் மெய்யுணர்வு வரச் செய்கிறான் இறைவன்.`,
  },
  {
    id: 432, tantraId: 2, verseNumber: 431,
    tamil: `உள்ளத் தொருவனை உள்ளுறு சோதியை
உள்ளம்விட் டோ ரடி நீங்கா ஒருவனை
உள்ளமுந் தானும் உடனே இருக்கினும்
உள்ளம் அவனை உருவறி யாதே`,
    transliteration: `uḷḷat toruvaṉai uḷḷuṟu cōtiyai
uḷḷamviṭ ṭō raṭi nīṅkā oruvaṉai
uḷḷamun tāṉum uṭaṉē irukkiṉum
uḷḷam avaṉai uruvaṟi yātē`,
    english: `431: He is Within You Yet You Know Him Not
He is the One within; He is the Light within;
He moves not a wee bit from within
He and your heart are thus together,
Though, the heart His Form knows not.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-431-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationEnglish: `God is within us all. He is the Light within us. He does not move a bit away from us. Yet we do not know Him. Why this concealment by the Lord?`,
    elaborationTamil: `ஒவ்வொரு உயிரின் உள்ளத்திற்குள்ளும் கண்டு உணரக் கூடிய ஜோதி உருவமாக இறைவன் வீற்றிருக்கின்றான். அவன் உயிர்களின் உள்ளத்தை விட்டு ஒரு அடி கூட விலகி நிற்பதில்லை. எப்போதும் உயிர்களின் உள்ளத்துடனே சேர்ந்து இறைவன் இருந்தாலும் மாயையினால் மறைக்கப்பட்ட உயிர்களின் உள்ளம் அவனது உருவத்தை அறியாது.`,
  },
  {
    id: 433, tantraId: 2, verseNumber: 432,
    tamil: `இன்பப் பிறவி படைத்த இறைவனுந்
துன்பஞ்செய் பாசத் துயருள் அடைத்தனன்
என்பிற் கொளுவி இசைந்துறு தோற்றசை
முன்பிற் கொளுவி முடிகுவ தாமே`,
    transliteration: `iṉpap piṟavi paṭaitta iṟaivaṉun
tuṉpañcey pācat tuyaruḷ aṭaittaṉaṉ
eṉpiṟ koḷuvi icaintuṟu tōṟṟacai
muṉpiṟ koḷuvi muṭikuva tāmē`,
    english: `432: The Lord Gave This Life
The Lord who gave life so sweet
Imprisoned me in pasas miseries;
A skeletal frame He fashioned,
With flesh and skin He clothed it;
Lighting then the spark of life
To annihilation He hastened me.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-432-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationEnglish: `Siva gave us life so sweet; yet, He imprisoned us in the miseries of Pasam. He builds for us a body with meticulous care; yet He hastens it to death. Why is this so?`,
    elaborationTamil: `இறைவனோடு இருந்த ஆன்மாக்கள் ஆசைப்பட்டுவிடும் போது அந்த ஆசைகளைத் தீர்த்துக்கொள்ள வேண்டி உலகத்தில் பிறவி எடுக்கும்படி உயிர்களாகப் படைக்கின்றான் இறைவன். அந்த உயிர்கள் ஆசைகளைத் தீர்த்துக் கொள்ளும் போது சில வினைகளும் சேர்த்து விடுகிறது. இந்த வினைகளை அனுபவிக்க வேண்டி உலகப்பற்று குடும்பம் பாசம் என்னும் துயரத்துக்குள் உயிர்களை மாயையால் பூட்டி அடைத்துவிடுகின்றான். எலும்பை முழுவதும் தோல் தசைகளால் மூடி அந்த எலும்போடு ஒன்றாகச் சேர்ந்து செயல்படும் இந்த உலக உடம்பானது உயிர்களின் பிறவிக்கு காரணமாகிய வினைகள் முடியும் வரை ஒன்றாகச் சேர்ந்து இருக்கும். இந்தப் பிறவியின் வினைகள் முடிந்ததும் உயிரை முடிப்பதாக இருக்கின்றது. உட்கருத்து: ஆன்மாக்கள் ஆசையினால் இன்பம் பெறுவதற்காகப் பிறவி எடுப்பதால் அந்த இன்பத்தை அனுபவித்து தீர்க்கும்வரை பேரின்பத்தை மறைத்து அருளும் இறைவன் அந்த ஆன்மாக்கள் எடுத்த பிறவியில் இன்பத்தை அனுபவிப்பதினால் கிடைக்கும் வினைகளையும் அதன் விளைவுகளால் ஏற்படும் துன்பத்தையும் அந்தத் துன்பத்திற்குக் காரணமாக இருக்கும் உலகப் பற்றுக்களையும் சேர்த்து பிறவிக்குள் அடைத்துவிடுகின்றான். இதில் எலும்பும் தோலும் போர்த்திய உடலே சிறையாகவும் உலகப் பற்று எனும் மாயை பூட்டாகவும் வினைகள் சாவியாகவும் இருக்கின்றது. எப்போது உயிர்கள் தமது வினைகளை அனுபவித்துக் கழித்து முடிக்கின்றதோ அப்போது இந்தப் பூட்டு திறந்து உலகத்தில் அதுவரை ஆன்மா அனைத்தையும் அனுபவிக்க உதவிய உடலையும் உயிரையும் அழித்து ஆன்மா விடுதலை பெறுகின்றது.`,
  },
  {
    id: 434, tantraId: 2, verseNumber: 433,
    tamil: `இறையவன் மாதவன் இன்பம் படைத்த
மறையவன் மூவரும் வந்துடன் கூடி
இறையவன் செய்த இரும்பொறி யாக்கை
மறையவன் வைத்த பரிசறி யாதே`,
    transliteration: `iṟaiyavaṉ mātavaṉ iṉpam paṭaitta
maṟaiyavaṉ mūvarum vantuṭaṉ kūṭi
iṟaiyavaṉ ceyta irumpoṟi yākkai
maṟaiyavaṉ vaitta paricaṟi yātē`,
    english: `433: Even the Three Gods do not Know the Mystery of Life
With Hara, Hari and Brahma assembling
The Primal Lord fashioned this body,
The subtle organs of sense built-in;
Why the Holy One did it,
The three know not the mystery.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-433-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationTamil: `இறைவன் உயிர்களை படைக்கும் தொழிலுக்கு காரியம் புரியும் தெய்வங்களாகிய உருத்திரன் மாபெரும் தவம் புரிபவனாகிய திருமால் வேதங்கள் ஓதி உயிர்களையும் அவை உலகத்தில் அடையும் இன்பத்தையும் படைத்த பிரம்மன் ஆகிய மூவரும் ஒன்றாகச் சேர்ந்து இறைவனின் கட்டளைக்கு ஏற்ப செய்த வலிமை மிக்க இரும்பாலான இயந்திரம் போன்ற உடலுக்குள் மாயையால் மறைத்து இறைவன் வைத்த ஒரு மாபெரும் பரிசு இருக்கின்றது. அதை உயிர்கள் அறியவில்லை. உட்கருத்து: உலகத்தில் உயிர்களை படைத்த இறைவன் அதன் வினைகளை அனுபவித்துக் கழிக்கும் வரை அந்த உயிர்களைப் பாதுகாக்க இறைவனே மாபெரும் பரிசாக உயிர்களின் உள்ளத்திற்குள் இருக்கின்றதை மாயையால் மறைத்து அருளுகின்றான்.`,
  },
  {
    id: 435, tantraId: 2, verseNumber: 434,
    tamil: `காண்கின்ற கண்ணொளி காதல்செய் தீசனை
ஆண்பெண் அலியுரு வாய்நின்ற ஆதியை
ஊண்படு நாவுடை நெஞ்சம் உணர்ந்திட்டுச்
சேண்படு பொய்கைச் செயலணை யாரே`,
    transliteration: `kāṇkiṉṟa kaṇṇoḷi kātalcey tīcaṉai
āṇpeṇ aliyuru vāyniṉṟa ātiyai
ūṇpaṭu nāvuṭai neñcam uṇarntiṭṭuc
cēṇpaṭu poykaic ceyalaṇai yārē`,
    english: `434: Adore and Attain
The Lord is the light of our eyes
He loves us
He is the Primal One
--Male, Female and Neuter is He;
Tongues praising and hearts melting,
They seek not the path
That leads to the Celestial Lake.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-434-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationTamil: `உயிர்களின் மேலுள்ள மாபெரும் அன்பினால் உயிர்களுடனே இருந்து அவர்களின் கண்ணில் காணும் ஒளியாகவும் காட்சிகளைக் காட்டும் ஒளியாகவும் இருக்கின்றான் இறைவன். ஆதியாக இருக்கும் இறைவனே அனைத்து உயிர்களின் உருவத்தில் ஆணாகவும் பெண்ணாகவும் அலியாகவும் இருக்கின்றான். உண்ணும் உணவை நாக்கினால் சுவைத்து அதன் இன்பத்தை நெஞ்சத்தில் உணர்வதைப்போலவே தமது தலையின் உச்சியில் இறைவனாக இருக்கும் அமிர்தத்தை நெஞ்சத்தில் உணராத உயிர்கள் பேரின்பத்தைக் கொடுக்கும் அமிர்தத்தின் செயலை உணராமல் இருக்கின்றார்கள். உட்கருத்து: உண்ணும் உணவை நாக்கினால் சுவைத்து அதன் இன்பத்தை நெஞ்சத்தில் உணர்வதைப்போலவே கண்ணில் காணும் ஒளியாகவும் காட்சிகளைக் காட்டும் ஒளியாகவும் இருப்பவன் இறைவன் என்பதையும் நெஞ்சத்தில் உணர்ந்து விட்டால் ஆணாகவும் பெண்ணாகவும் அலியாகவும் இருப்பவன் இறைவன் என்பதையும் தலை உச்சியில் பேரின்பத்தைக் கொடுக்கும் இறைவனாக இருக்கும் அமிர்தத்தையும் உணர்ந்து கொள்ளலாம். ஆனால் உயிர்கள் உணவு உண்ணும் ருசிக்கு ஆசைப்பட்டு அதனால் கிடைக்கும் வினையின் காரணமாக மறைக்கப்பட்டு உணராமல் இருக்கின்றார்கள்.`,
  },
  {
    id: 436, tantraId: 2, verseNumber: 435,
    tamil: `தெருளும் உலகிற்குந் தேவர்க்கும் இன்பம்
அருளும் வகைசெய்யும் ஆதிப் பிரானுஞ்
சுருளுஞ் சுடருறு தூவெண் சுடரும்
இருளும் அறநின் றிருட்டறை யாமே`,
    transliteration: `teruḷum ulakiṟkun tēvarkkum iṉpam
aruḷum vakaiceyyum ātip pirāṉuñ
curuḷuñ cuṭaruṟu tūveṇ cuṭarum
iruḷum aṟaniṉ ṟiruṭṭaṟai yāmē`,
    english: `435: He Dispels the Darkness Within
The Primal Lord blesses all
Denizens of earth below and heaven above;
From the black chamber of the Soul
He dispels darkness;
And within radiates the pure rays of His dazzling light.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-435-Second-Tantra-12.-Illusion-of-the-Soul-1.mp3',
    elaborationTamil: `உண்மை ஞானத்தை அடைந்த உலக உயிர்களுக்கும் விண்ணுலகத் தேவர்களுக்கும் பேரின்பத்தைப் பெறும் வழியை அருளிச் செய்கின்றான் ஆதியிலிருந்தே இருக்கின்ற தலைவனாகிய இறைவன். உண்மை ஞானத்தை அடையாமல் உலக ஆசையில் இருக்கின்ற உயிர்களுக்கு தினமும் மாறி மாறி வரும் சூரியனின் ஒளியையும் அந்தச் சூரியனின் ஒளியை தன்னுள் வாங்கிக் கொடுக்கும் நிலாவின் ஒளியையும் வெப்பமான தீயினால் கிடைக்கும் ஒளியையும், இந்த மூன்றுவித ஒளியும் இல்லாதபோது இருக்கும் இருளை உணர்வினால் அறிந்திருக்கின்ற உயிர்களுக்கு உணர்வினால் அறியமுடியாத மாயை எனும் இருளைக் கொண்ட உள்ளம் எனும் இருட்டறையில் வீற்றிருக்கின்றான் இறைவன். உட்கருத்து: உண்மை ஞானம் பெற்ற உலகத்து உயிர்களுக்கும் விண்ணுலக உயிர்களுக்கும் பேரின்பத்தைக் கொடுக்கும் இறைவன் உண்மை ஞானம் பெறாத உயிர்களுக்கு மாயை எனும் இருட்டையே கொடுக்கின்றான்.`,
  },
  {
    id: 437, tantraId: 2, verseNumber: 436,
    tamil: `அரைகின் றருள்தரும் அங்கங்கள் ஓசை
உரைக்கின்ற ஆசையும் ஒன்றோடொன் றொவ்வாப்
பரக்கும் உருவமும் பாரகந் தானாய்க்
கரகின் றவைசெய்த காண்டகை யானே.`,
    transliteration: `araikiṉ ṟaruḷtarum aṅkaṅkaḷ ōcai
uraikkiṉṟa ācaiyum oṉṟōṭoṉ ṟovvāp
parakkum uruvamum pārakan tāṉāyk
karakiṉ ṟavaiceyta kāṇṭakai yāṉē.`,
    english: `436: Dispel Darkness and Give Thine Light
Lord! Your Form fills all the worlds
Yet You are invisible;
How my eyes long to see You!
My senses clamour aloud
In desire contending;
Save me, my Lord;
And bless me with Your grace inscrutable.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-436-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `இன்ப துன்பத்திற்கு ஓர் காரணமாய் இருக்கும் உடல் உறுப்புகள் கேட்கின்ற ஓசை பேசுகின்ற உரை இவற்றிலெல்லாம் உணருகின்ற ஆசை ஒன்றுக்கு ஒன்று பொருந்தாமல் வித்தியாசமாய் பலவித உருவங்களில் எங்கும் பரவி இருக்கும் உயிர்கள் பரந்து விரிந்த உலகம் ஆகிய இவை அனைத்தும் இறைவனாகவே இருக்கின்ற பெரிய உண்மையை மறைத்து உயிர்களுக்குள் உணர்ந்து காணக்கூடியவனாக இருக்கின்றான் இறைவன். உட்கருத்து: உயிர்கள் தமது ஐந்து புலன்களால் பார்த்து கேட்டு பேசி சுவைத்து உணர்ந்து ஆசையைத் தீர்த்துக் கொண்டு வினைகளைப் புரிந்து கொண்டு இருக்கின்றன. இந்த ஐம்புலன்களால் இறைவனை அறிய முடியாது. உள்ளத்துக்குள்ளே உணர்ந்தால் மட்டுமே காணக்கூடியவனாக இருக்கின்றான் இறைவன்.`,
  },
  {
    id: 438, tantraId: 2, verseNumber: 437,
    tamil: `ஒளித்துவைத் தேனுள் ளுறவுணர்ந் தீசனை
வெளிப்பட்டு நின்றருள் செய்திடு மீண்டே
களிப்பொடுங் காதன்மை என்னும் பெருமை
வெளிப்பட் டிறைஞ்சினும் வேட்சியு மாமே`,
    transliteration: `oḷittuvait tēṉuḷ ḷuṟavuṇarn tīcaṉai
veḷippaṭṭu niṉṟaruḷ ceytiṭu mīṇṭē
kaḷippoṭuṅ kātaṉmai eṉṉum perumai
veḷippaṭ ṭiṟaiñciṉum vēṭciyu māmē`,
    english: `437: The Hidden One Will Reveal Himself
I held my Lord in me concealed,
I adored Him in my heart's depths,
Lo! He revealed Himself unto me
And blessed me--here below,
Well may you adore Him
Revealing the rapture abounding and love endearing
That too pleases Him far.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-437-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationTamil: `இறைவன் எமக்குள் மறைத்திருந்ததை அவனது திருவருளால் எமது உள்ளத்துக்குள்ளேயே உணர்ந்து வேண்டிட அவன் யாம் இருந்த இடத்திலேயே வெளிப்பட்டு நின்று அருள் புரிந்தான். எப்போதுமே தெகிட்டி விடாத பேரின்பத்தை வழங்கும் பெருமைக்குரிய இறைவனை உயிரின் உள்ளத்துக்குள் ஒளிந்து கொண்டு இருந்தாலும் உண்மையான அன்போடு உள்ளம் உருக வேண்டினால் தமக்கு முன்னால் வந்து நின்று அருள் புரிவதை உணரலாம்.`,
  },
  {
    id: 439, tantraId: 2, verseNumber: 438,
    tamil: `நின்றது தானாய் நிறைந்த மகேசுரன்
சென்றங் கியங்கும் அரந்திரு மாலவன்
நன்றது செய்யும் மலர்மிசை மேலயன்
என்றிவ ராகி இசைந்திருந் தானே`,
    transliteration: `niṉṟatu tāṉāy niṟainta makēcuraṉ
ceṉṟaṅ kiyaṅkum arantiru mālavaṉ
naṉṟatu ceyyum malarmicai mēlayaṉ
eṉṟiva rāki icaintirun tāṉē`,
    english: `438: One Became Five
The Sadasiva that stood as one
Animated Maheswara;
And then Hara, Hari, and Brahma
Thus did the One become the familial five.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-438-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `ஒவ்வொரு உயிரின் உள்ளத்துக்குள்ளும் தாமாகவே நிறைந்து நின்று மாயையால் மறைக்கும் மகேசுவரன். அழிக்கவும் காக்கவும் சென்று உலகங்களிலெல்லாம் இயங்கிக் கொண்டிருக்கும் உருத்திரன் திருமால். நன்மைக்காக படைப்புகளைச் செய்து கொண்டு தாமரை மலரின் மீது வீற்றிருக்கும் பிரம்மன் ஆகிய இவர்கள் அனைவரும் தாமாகவே இருந்தும் அவர்கள் புரியும் தொழில்களில் ஒன்றாகவே இணைந்து இருக்கின்றான் இறைவன். குறிப்பு: இந்தப் பாடலும் #403 ஆவது பாடலும் ஒன்று போல இருந்தாலும் இப்பாடலில் சிறிது வார்த்தைகளை மாற்றி இறைவனது மாயா காரியங்களைச் சொல்லி அருளுகின்றார் திருமூலர். பாடல் #403 இல் அனைத்தையும் படைக்கவும் காக்கவும் அழிக்கவும் மூவர்களாக இருக்கும் இறைவனே இந்தப் பாடலில் எங்கும் நிறைந்து மறைக்கவும் அனைத்து உயிர்களுக்கும் அருளவும் செய்து ஐவராக இருக்கின்றான் என்பதையும் ஐவராக இருந்து அவன் புரியும் இந்தத் தொழில்களை உயிர்களின் மேல் கொண்ட கருணையினால் மறைத்து வைத்திருக்கின்றான் என்பதையும் திருமூலர் சொல்லியிருக்கின்றார்.`,
  },
  {
    id: 440, tantraId: 2, verseNumber: 439,
    tamil: `ஒருங்கிய பாசத்துள் உத்தமச் சித்தன்
இருங்கரை மேலிருந் தின்புற நாடி
வருங்கரை ஓரா வகையினிற் கங்கை
அருங்கரை பேணில் அழுக்கற லாமே`,
    transliteration: `oruṅkiya pācattuḷ uttamac cittaṉ
iruṅkarai mēlirun tiṉpuṟa nāṭi
varuṅkarai ōrā vakaiyiṉiṟ kaṅkai
aruṅkarai pēṇil aḻukkaṟa lāmē`,
    english: `439: He is the Pure One
He is the Pure One
The Siddha in whom Pasa lies prostrate;
Be firmly seated on land here below
And Seek Him in ways falicitous--
That you may vision the Land Beyond;
Not doing this,
You are like one
Who is seated on the banks of Ganga,
Yet remains unwashed and impure.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-439-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationTamil: `மாயையால் உலகப் பற்றுக்களில் சிக்கிக் கொண்ட உயிர்கள் அந்த உலகப் பற்றுக்களின் மேல் வைத்திருக்கும் பாசத்திலேயே மூழ்கிக் கொண்டு தமது உள்ளத்துக்குள் உத்தமனாக வீற்றிருக்கும் இறைவனை உணர்ந்து அவன் அருளிய அமிர்தத்தை அருந்தி பேரின்பத்தில் திளைக்காமல் இருப்பது எப்படி இருக்கின்றதென்றால் கங்கையின் புனித நீரில் மூழ்கித் தமது பாவ அழுக்குகளைப் போக்கிக் கொள்ள முயற்சி செய்யாமல் கரையிலேயே நின்று பார்த்துக் கொண்டிருப்பதைப் போல இருக்கின்றது. உட்கருத்து: கங்கையில் மூழ்கி பாவத்தைத் தீர்த்துக்கொள்ள முடிந்த போதும் அதைச் செய்யாமல் கரையிலேயே நின்று பார்ப்பது போல தமக்குள்ளேயே இறைவனை உணர்ந்து பேரின்பத்தைப் பெற முடிந்த போதும் அதைச் செய்யாமல் உலகச் சிற்றின்பங்களிலேயே திளைத்து இருப்பதைத்தான் உயிர்கள் விரும்புகின்றன.`,
  },
  {
    id: 441, tantraId: 2, verseNumber: 440,
    tamil: `மண்ணொன்று தான்பல நற்கல மாயிடும்
உண்ணின்ற யோனிகட் கெல்லாம் ஒருவனே
கண்ணொன்று தான்பல காணுந் தனைக்காணா
அண்ணலும் அவ்வண்ண மாகிநின் றானே.`,
    transliteration: `maṇṇoṉṟu tāṉpala naṟkala māyiṭum
uṇṇiṉṟa yōṉikaṭ kellām oruvaṉē
kaṇṇoṉṟu tāṉpala kāṇun taṉaikkāṇā
aṇṇalum avvaṇṇa mākiniṉ ṟāṉē.`,
    english: `440: The Eye Sees Not Itself
One clay, many the receptacles
One God, pervades species all;
The eye sees things several
Yet itself it sees not;
Thus it is, we see not the God in us.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-440-Second-Tantra-12.-Illusion-of-the-Soul.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உயிர்களுக்கு நல்ல முறையில் பயன்படும் பல்வேறு விதமான பாத்திரங்களை குயவன் செய்தாலும் அனைத்தையும் ஒரே விதமான களிமண்ணில் இருந்து தான் செய்கின்றான். அதுபோலவே உலகத்தில் பல்வேறு உருவங்களில் பல பிறவிகள் எடுத்தாலும் அனைத்து பிறவிகளிலும் ஆத்மாவாக இறைவன் ஒருவனே இருக்கின்றான். உயிர்களின் கண்கள் இரண்டாக இருந்தாலும் அவை ஒரேவிதமான காட்சிகளைக் கண்டாலும் தமது உருவத்தை அவற்றால் காண முடியாது. அதுபோலத்தான் இறைவனும் ஒவ்வொரு உயிரின் உள்ளத்துக்குள் இருந்து உயிர்களுக்கு அனைத்தையும் உணர வைத்தாலும் தம்மையே உணர முடியாதவனாக இருக்கின்றான். உட்கருத்து: அனைத்தையும் தமது கண்களால் பார்க்கும் உயிர்கள் தமது கண்களின் பிம்பத்தை கண்ணாடியில் காண முடியுமே தவிர தமது கண்களால் தமது கண்களையே காண முடியாது. அதுபோலவே மாயையால் மறைந்திருக்கும் இறைவன் உள்ளத்துக்குள்ளேயே இருந்து அனைத்தையும் உணர்த்தினாலும் அவனை மட்டும் உணர முடியாமல் இருக்கும்படி உயிர்களை மாயையால் மறைத்து வைத்திருக்கின்றான்.`,
  },
  {
    id: 442, tantraId: 2, verseNumber: 441,
    tamil: `எட்டுத் திசையும் எறிகின்ற காற்றொடு
வட்டத் திரையனல் மாநிலம் ஆகாயம்
ஒட்டி உயிர்நிலை என்னுமிக் காயப்பை
கட்டி அவிழ்ப்பான் கண்ணுதல் காணுமே`,
    transliteration: `eṭṭut ticaiyum eṟikiṉṟa kāṟṟoṭu
vaṭṭat tiraiyaṉal mānilam ākāyam
oṭṭi uyirnilai eṉṉumik kāyappai
kaṭṭi aviḻppāṉ kaṇṇutal kāṇumē`,
    english: `441: Life and Death are Acts of God
He is the Wind that Blows in Directions Eight
He is the wavy ocean that girdles the earth,
He is fire, earth and sky;
Know this:
He is the One that binds and unbinds
The body that holds life precious.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-441-Second-Tantra-13.-Kindness.mp3',
    elaborationEnglish: `Having experienced pleasure and pain in life, the jivas who seek the Lord are bestowed grace. This bestowal of Grace that leads to the jiva’s redemption or liberation from the of birth and death is the Supreme Act of God. That is the act that gives the ‘coup de grace to all the previous four acts of His.

The attainment of Grace can come through total surrender in loving prayer, through the yoga way or through the ‘realization that the All-Pervasive God is the object of all knowledge. And when it comes, the jiva is cleansed of its primordial triple impurities.

This function is performed by Sadasiva.`,
    elaborationTamil: `எட்டுத் திசைகளிலும் வீசுகின்ற காற்றும் வட்ட வடிவ உலகைச் சூழ்ந்து இருக்கும் அலை கடல் நீரும் உலகம் தனக்குள்ளிருந்தும் தன்னைச் சுற்றியிருக்கும் வளி மண்டலங்களிலிருந்தும் பெறும் நெருப்பும் உள்ளிருக்கும் நெருப்பை மூடி விரிந்து பரவி இருக்கும் இந்த மாபெரும் நிலமும் உலகத்தைச் சுற்றியிருக்கும் வளிமண்டலத்தைத் தாண்டி இருக்கும் ஆகாயமும் ஆகிய பஞ்ச பூதங்களையும் உள்ளடக்கி ஆன்மாவோடு உயிரைச் சேர்த்து அதை நிலைபெற வைக்கும் மூச்சுக்காற்றை அடைத்து வைத்த தோலால் ஆன பையைப் போன்ற உடலை அவரவர் வினைகளுக்கு ஏற்ப இறக்கும் காலம் வரும் வரை பாதுகாப்பாக கட்டி வைத்தும் காலம் வரும்போது அவிழ்த்துப் போட்டும் விளையாடுவது நெற்றிக் கண்ணை உடைய சிவபெருமானின் அருளே. உட்கருத்து: வினைகள் முடியும் வரை உயிர்களை உலகத்தில் பஞ்ச பூதங்களை அடக்கிய உடலில் பிறக்க வைத்து அவற்றை காலம் வரும் வரை காப்பாற்றி வந்து முடியும் காலம் வந்தபின் அழித்து அடுத்த நிலைக்குச் செல்லும்படி செய்வது அனைத்தும் இறைவனின் திருவருளே ஆகும்.`,
  },
  {
    id: 443, tantraId: 2, verseNumber: 442,
    tamil: `உச்சியில் ஓங்கி ஒளிதிகழ் நாதத்தை
நச்சியே இன்பங்கொள் வார்க்கு நமன்இல்லை
விச்சும் விரிசுடர் மூன்றும் உலகுக்குத்
தச்சு மவனே சமைக்கவல் லானே`,
    transliteration: `ucciyil ōṅki oḷitikaḻ nātattai
nacciyē iṉpaṅkoḷ vārkku namaṉillai
viccum viricuṭar mūṉṟum ulakukkut
taccu mavaṉē camaikkaval lāṉē`,
    english: `442: Lord is the Substance and Architect
Who seeks the luminous Nada atop
And of its sweetness savour
Know of death--no more;
The Lord is the seed of all
Of Sun, Moon and Fire
Of the Universe Vast
That Architect that builds all as well.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-442-Second-Tantra-13.-Kindness.mp3',
    elaborationTamil: `தலை உச்சியிலுள்ள சகஸ்ரரதளத்தில் ஒளிவீசித் திகழும் நாத வடிவான இறைவனை அன்பு செய்து அவனோடு சேர்ந்து பேரின்பத்தை உணர்ந்தவர்களுக்கு மரணம் என்பது இல்லாததால் எமன் கிடையாது. விரிந்து பரந்திருக்கின்ற இந்த உலகத்தில் கண்களால் காணக்கூடிய சூரியன் சந்திரன் நெருப்பில் இருந்து வரும் மூன்றுவித ஒளிகளைக் கொடுத்து அருளிய அவனேதான் கண்களால் காண முடியாத ஒளியாக சகஸ்ரரதளத்தில் கலந்து இருக்கின்றான். அந்த ஒளியில் தன்னை நாடி வருகின்றவர்களுக்கு பேரின்பத்தை வழங்கி மரணமில்லாத பெருவாழ்வை அருளக்கூடியவனாக இறைவன் இருக்கின்றான்.`,
  },
  {
    id: 444, tantraId: 2, verseNumber: 443,
    tamil: `குசவன் திரிகையில் ஏற்றிய மண்ணைக்
குசவன் மனத்துற்ற தெல்லாம் வனைவன்
குசவனைப் போல்எங்கள் கோன்நந்தி வேண்டில்
அசைவில் உலகம் அதுயிது வாமே`,
    transliteration: `kucavaṉ tirikaiyil ēṟṟiya maṇṇaik
kucavaṉ maṉattuṟṟa tellām vaṉaivaṉ
kucavaṉaip pōleṅkaḷ kōṉnanti vēṇṭil
acaivil ulakam atuyitu vāmē`,
    english: `443: Potter Fashions as His Fancy Takes
The potter mounts the clay on the wheel
The potter fashions as he conceives
Even as the Potter our Lord Nandi is;
He sways the world, this way and that
The way His Fancy takes.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-443-Second-Tantra-13.-Kindness.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `குயவன் களிமண்ணைப் பிடித்து தனது மனதுக்கு எதுவெல்லாம் நன்மை தரும் என்று தோன்றுகின்றதோ அந்த மாதிரியெல்லாம் பாத்திரங்கள் வரும்படி வளைத்து உருவாக்குவான். அந்தக் குயவனைப் போலவே குருநாதனாக இருக்கும் எம் இறைவனும் ஆன்மாக்களின் வேண்டுதலுக்கு இணங்கி எதுவாக இருந்தால் அவர்கள் வேண்டிக்கொண்டது நிறைவேறும் என்பதை அறிந்து அதுவாகவே அவர்களை, அசைவில்லாத இந்த அண்டசராசரத்தில் அசைவு பெற்றுச் சுழலும் உலகங்களில் பல்வேறு வித உயிர்களாகப் படைத்து அருளுகின்றான். உட்கருத்து: உயிர்கள் உலகத்தில் பிறப்பது அவற்றின் ஆசையினால்தான். ஆன்மாவாக இருக்கும் உயிர் ஆசைப்பட்டுவிடும் போது இறைவனை வேண்டி உயிர் எடுத்து உலகத்தில் பிறக்கிறது. அப்படிப் பிறக்கும் உயிர் எந்த உருவத்தில் இருந்தால் விரைவில் ஆசைகளைத் தீர்த்துக்கொண்டு தனது வினைகளையும் கழித்துக் கொள்ளும் என்பதை அறிந்த இறைவன் அந்த விதத்திலேயே அவர்களைப் படைத்து அருளுகின்றான்.`,
  },
  {
    id: 445, tantraId: 2, verseNumber: 444,
    tamil: `விடையுடை யான்விகிர் தன்மிகு பூதப்
படையுடை யான்பரி சேஉல காக்குங்
கொடையுடை யாங்குணம் எண்குண மாகுஞ்
சடையுடை யாஞ்சிந்தை சார்ந்துநின் றானே`,
    transliteration: `viṭaiyuṭai yāṉvikir taṉmiku pūtap
paṭaiyuṭai yāṉpari cēula kākkuṅ
koṭaiyuṭai yāṅkuṇam eṇkuṇa mākuñ
caṭaiyuṭai yāñcintai cārntuniṉ ṟāṉē`,
    english: `444: He Dwells in My Thoughts
He is Lord Supreme;
He has bull for His mount;
Mighty demons for army;
Boundless is His munificience
He gifts the world for us;
His goodness alone is goodness;
He is of matted locks;
He dwells in my thoughts.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-444-Second-Tantra-13.-Kindness.mp3',
    elaborationTamil: `காளையை வாகனமாகக் கொண்டவனும் வேறு பட்ட பலவித உருவங்களில் ஒன்றாக இருப்பவனும் பூத கணங்களைப் படையாகக் கொண்டவனும் ஆன்மாக்களுக்குக் கொடுத்த மிகப்பெரிய பரிசு உலகத்துப் பிறவியாகும். பிறவியைப் பரிசாகக் கொடுத்த மாபெரும் வள்ளலாகிய இறைவன் அந்தப் பிறவியில் உயிர்கள் அனுபவிக்க வேண்டிய ஆசைகளையும் வினைகளையும் அடைய வேண்டிப் பலவித குணங்களையும் வைத்து அருளுகின்றான். குணங்களையும் மீறித் தம்மை சிந்திக்கும் அடியவர்களுக்கு அவர்களின் சிந்தனையிலேயே திரிசடையைத் தலையில் தரித்த இறைவன் பேரின்பமாக சேர்ந்து இருந்து அருளுகின்றான். உட்கருத்து: ஆன்மாக்கள் ஆசைக்கும் வினைக்கும் பிறவி எடுக்கும்போது அதற்கேற்ற உடலையும் உள்ளத்தையும் குணங்களையும் கொடுத்து அருளும் இறைவன் தன் தலையில் திரித்துச் சூடிய சடைபோல வினைகளால் முற்றும் சூழப்பட்ட ஆன்மாக்கள் அதையும் தாண்டி இறைவனை நினைக்கும் போது அவர்களின் சிந்தனையில் பேரின்பமாக வந்து அருளுகின்றான்.`,
  },
  {
    id: 446, tantraId: 2, verseNumber: 445,
    tamil: `உகந்துநின் றேபடைத் தான்உல கேழும்
உகந்துநின் றேபடைத் தான்பல ஊழி
உகந்துநின் றேபடைத் தான்ஐந்து பூதம்
உகந்துநின் றேஉயிர் ஊன்படைத் தானே`,
    transliteration: `ukantuniṉ ṟēpaṭait tāṉula kēḻum
ukantuniṉ ṟēpaṭait tāṉpala ūḻi
ukantuniṉ ṟēpaṭait tāṉaintu pūtam
ukantuniṉ ṟēuyir ūṉpaṭait tāṉē`,
    english: `445: In Love, He Created
In fondness for us He created the seven worlds,
In fondness for us He created the several aeons
In fondness for us He created the five elements;
In fondness for us He created this body and breath.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-445-Second-Tantra-13.-Kindness.mp3',
    elaborationTamil: `ஆன்மாக்களின் மேல் வைத்த மாபெரும் அன்பினால் அவை ஆசைகளைத் தீர்த்துக் கொள்ளட்டும் என்று ஏழு உலகங்களையும் படைத்து அருளினான். அந்த உலகங்களின் காலம் முடியும் போது அவற்றை அழித்து மீண்டும் புதியதாக உருவாக்கி அருளினான். உலகங்களும் உயிர்களும் தனது தொழிலை செய்வதற்காக பஞ்ச பூதங்களையும் படைத்து அருளினான். ஆன்மாக்கள் பிறவி எடுக்க உயிரையும் உடலையும் கொடுத்து அருளினான்.`,
  },
  {
    id: 447, tantraId: 2, verseNumber: 446,
    tamil: `படைத்துடை யான்பண் டுலகங்கள் ஏழும்
படைத்துடை யான்பல தேவரை முன்னே
படைத்துடை யான்பல சீவரை முன்னே
படைத்துடை யான்பர மாகிநின் றானே`,
    transliteration: `paṭaittuṭai yāṉpaṇ ṭulakaṅkaḷ ēḻum
paṭaittuṭai yāṉpala tēvarai muṉṉē
paṭaittuṭai yāṉpala cīvarai muṉṉē
paṭaittuṭai yāṉpara mākiniṉ ṟāṉē`,
    english: `446: God Created All, Himself the Param Uncreated
Of yore He created worlds seven
Of yore He created celetials countless
Of yore He created species numberless
He who of yore created all
Himself stood as Primal Param uncreated.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-446-Second-Tantra-13.-Kindness.mp3',
    elaborationTamil: `ஏழு உலகங்களைப் படைத்து அவை தம் வினைகளைத் தீர்த்தபின் அவற்றை அழித்து தம்மோடு மீண்டும் சேர்த்துக் கொண்டு அருளுகின்றவன் இறைவன். ஏழு உலகங்களும் தன் தொழில்களை செய்ய பலவித தேவர்களையும் படைத்து அருளினான். பலவித உயிர்களைப் படைத்து தம் வினைகளைத் தீர்த்தபின் அவற்றை அழித்து தம்மோடு மீண்டும் சேர்த்துக் கொண்டு அருளுகின்றவன் இறைவன். அந்த உயிர்கள் தன்னை நாடி வரும்போது அனைத்திற்கும் மேலான பரம்பொருளாகவும் நின்று அருளுகின்றான்.`,
  },
  {
    id: 448, tantraId: 2, verseNumber: 447,
    tamil: `ஆதி படைத்தனன் ஐம்பெரும் பூதம்
ஆதி படைத்தனன் ஆசில்பல் ஊழி
ஆதி படைத்தனன் எண்ணிலி தேவரை
ஆதி படைத்தவை தாங்கிநின் றானே`,
    transliteration: `āti paṭaittaṉaṉ aimperum pūtam
āti paṭaittaṉaṉ ācilpal ūḻi
āti paṭaittaṉaṉ eṇṇili tēvarai
āti paṭaittavai tāṅkiniṉ ṟāṉē`,
    english: `447: He Who Created, Sustained As Well
The Primal One created the elements five;
The Primal One created the endless aeons past;
The Primal One created the countless heavenly beings,
The Primal One created and sustained as well.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-447-Second-Tantra-13.-Kindness.mp3',
    elaborationTamil: `அனைத்திற்கும் ஆதியான இறைவனே உயிர்கள் வாழ்வதற்க்காக ஆகாயம் நீர் நெருப்பு காற்று மண் என ஐந்து பெரும் பூதங்களைப் படைத்து அருளினான். அந்த உயிர்கள் வினைகள் முடியும் வரை வாழ்ந்து தன்னை வந்து அடைவதற்காக பல ஊழிக்காலங்களையும் அருளினான். அந்த உயிர்கள் தவமிருந்து தன்னை நாடி வரும் போது அவர்களை எண்ணிலடங்காத பல தேவர்களாகக்கி அருளுகின்றான். இப்படி அனைத்தையும் படைத்த இறைவனே தான் படைத்த அனைத்தையும் தாங்கிக் கொண்டு பாதுகாத்து அருளுகின்றான்.`,
  },
  {
    id: 449, tantraId: 2, verseNumber: 448,
    tamil: `அகன்றான் அகலிடம் ஏழுமொன் றாகி
இவன்றா னெனநின் றெளியனும் அல்லன்
சிவன்றான் பலபல சீவனும் ஆகி
நவின்றான் உலகுறு நம்பனு மாமே`,
    transliteration: `akaṉṟāṉ akaliṭam ēḻumoṉ ṟāki
ivaṉṟā ṉeṉaniṉ ṟeḷiyaṉum allaṉ
civaṉṟāṉ palapala cīvaṉum āki
naviṉṟāṉ ulakuṟu nampaṉu māmē`,
    english: `448: The Pervasive Siva is Here as Well
The infinite spaces of the Seven worlds
He filled in oneness, expanding limitless
Yet is He not easy of reach;
Siva Himself into myriad Jivas pervaded
In this worlds as well, He our Lord.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-448-Second-Tantra-13.-Kindness.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `பரந்து விரிந்த ஏழு உலகங்கள் முழுவதும் அகன்று பரவி இருந்தாலும் அனைத்தும் ஒருவனாய் இருப்பவன் இறைவன் ஒருவனே. இவன் தான் இறைவன் என்று சுட்டிக் காட்டி உணர்த்தக் கூடிய அளவிற்கு இறைவன் எளிமையானவன் இல்லை. அவனே பலவித ஆன்மாக்களின் உயிரோடு உயிராக உடனே இருந்து பாதுகாத்து அருளுகின்றவன். அவனே பல்வேறு குருநாதர்களாய் வந்து உயிர்களுக்கு நல்வழியை போதித்து அருளிய அவனே உலகத்து உயிர்களெல்லாம் நம்பியிருக்கும் தலைவனும் ஆவான்.`,
  },
  {
    id: 450, tantraId: 2, verseNumber: 449,
    tamil: `உண்ணிற்ற சோதி உறநின்ற ஓருடல்
விண்ணிற் றமரர் விரும்பும் விழுப்பொருள்
மண்ணிற்ற வானோர் புகழ்திரு மேனியன்
கண்ணிற்ற மாமணி மாபோத மாமே`,
    transliteration: `uṇṇiṉṟa cōti uṟaniṉṟa ōruṭal
viṇṇiṉ ṟamarar virumpum viḻupporuḷ
maṇṇiṉṟa vāṉōr pukaḻtiru mēṉiyaṉ
kaṇṇiṉṟa māmaṇi māpōta māmē`,
    english: `449: He is the Object of All Knowledge
He is the light within
He is the body without
The precious object, beloved of immortals above,
The Holy Form, adored of saintly beings below,
He is the pupil of your eyes;
He the Object of all Knowledge.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-449-Second-Tantra-13.-Kindness.mp3',
    elaborationTamil: `உயிர்களின் உள்ளத்திற்குள் ஒளியாக இருக்கும் இறைவனே உயிரோடு உயிராகவும் கலந்து ஒரே உடலாக இருக்கின்றான். அவனே விண்ணுலக அமரர்களெல்லாம் விரும்பித் தொழும் அனைத்திற்கும் மேலான பரம்பொருள். அவனே மண்ணுலக அடியவர்களெல்லாம் புகழ்ந்து போற்றும் பல்வேறு உருவங்களாகத் திருமேனி தரித்து இருப்பவன். அவனே கண்களுக்குள் இருந்து காட்சியைக் காட்டும் கருமணியாகவும் இருந்து கண்களால் காண முடியாத பேருண்மைகளைக் குருநாதனாய் இருந்து போதிப்பவனும் ஆவான்.`,
  },
  {
    id: 451, tantraId: 2, verseNumber: 450,
    tamil: `ஆரும் அறியாத அண்டத் திருவுருப்
பார்முத லாகப் பயிலுங் கடத்திலே
நீரினிற் பால்போல நிற்கின்ற நேர்மையைச்
சோராமற் காணுஞ் சுகம்அறிந் தேனே`,
    transliteration: `ārum aṟiyāta aṇṭat tiruvurup
pārmuta lākap payiluṅ kaṭattilē
nīriṉiṟ pālpōla niṟkiṉṟa nērmaiyaic
cōrāmaṟ kāṇuñ cukamaṟin tēṉē`,
    english: `450: The Lord Pervades All in Partiality to None
His is the Cosmic Form that none know
He is the infinite space that fills the universe;
He is the space in the tiny pot too;
Inseparable as water in milk
He pervades all in union close;
Impartial indeed His Goodness;
Unwearied His bliss--I knew.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-450-Second-Tantra-13.-Kindness.mp3',
    elaborationTamil: `யாராலும் அறிந்துவிட முடியாத அண்டசராசரங்கள் அடங்கிய திருமேனியைக் கொண்ட இறைவன் நீரில் பால் சேர்க்கும் போது எப்படி இரண்டும் ஒன்றாகிக் கலந்து விடுகின்றதோ அதுபோலவே உலகத்தில் பிறக்கும் உயிர்களுடன் உயிராகக் கலந்து உடலாகி ஒன்றாக இருப்பதை இடைவிடாமல் கண்டு பேரின்பம் அடையும் பாக்கியத்தை அவனது திருவருளால் யான் பெற்றிருக்கின்றேன்.`,
  },
  {
    id: 452, tantraId: 2, verseNumber: 451,
    tamil: `ஆக்குகின் றான்முன் பிரிந்த இருபத்தஞ்
சாக்குகின் றானவ னாதிஎம் ஆருயிர்
ஆக்குகின் றான்கர்ப்பக் கோளகை யுள்ளிருந்
தாக்குகின் றான்அவன் ஆவ தறிந்தே`,
    transliteration: `ākkukiṉ ṟāṉmuṉ pirinta irupattañ
cākkukiṉ ṟāṉava ṉātiem āruyir
ākkukiṉ ṟāṉkarppak kōḷakai yuḷḷirun
tākkukiṉ ṟāṉavaṉ āva taṟintē`,
    english: `451: God Creates From Within the Womb
He conjoins the tattvas five and twenty
That in life past departed from me;
To my dear life awaken;
Thus He creates, seated within the globular womb
He the Primal One creates
Knowing what I am to be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-451-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உயிர்கள் உலகத்தில் பிறவி எடுக்கும் முன்பு அவற்றின் முன் ஜென்மத்தில் அவற்றை விட்டும் பிரிந்து இருந்த இருபத்தைந்து தத்துவங்களை ஒன்றாகச் சேர்த்து ஆதியாக இருக்கும் எமது ஆருயிரான இறைவன் உயிரை உருவாக்குகின்றான். உடலுடன் கூடிய உயிர் இந்த உலகத்தில் எப்படி இருக்க வேண்டும் என்பதை அறிந்து அந்தக் கரு உருவாகும் போதே அதற்கு ஏற்றவாறு அந்தக் கர்ப்பப் பையின் உள்ளிருந்தே உடலுடன் கூடிய உயிரை உருவாக்கி அருளுகின்றான் இறைவன். இருபத்தைந்து தத்துவங்கள்: 5 பூதங்கள்: நிலம், நீர், காற்று, நெருப்பு, ஆகாயம். 5 புலன்கள்: கண்களால் பார்த்தல், காதுகளால் கேட்டல், வாயால் சுவைத்தல், மூக்கால் நுகருதல், தோலால் தொடுதல். 5 ஞானேந்திரியங்கள்: ஓசை – கேட்பது, ஊறு – உணர்தல், ஒளி – பார்ப்பது, சுவை – உண்பது, நாற்றம் – முகர்வது. 5 கன்மேந்திரியங்கள்: வாய் – பேச்சு, கைகள் – செயல், கால்கள் – போக்குவரவு, எருவாய் – கழிவு நீக்கம் பகுதி, கருவாய் – இன்பமும் பிறப்பும். 4 அந்தக்கரணங்கள்: மனம் – எண்ணங்கள், புத்தி – அறிவு, சித்தம் – சிந்தனை, அகங்காரம் – நான் எனும் நினைப்பு. 1 புருடன்: ஆன்மா.`,
  },
  {
    id: 453, tantraId: 2, verseNumber: 452,
    tamil: `அறிகின்ற மூலத்தின் மேல்அங்கி அப்புச்
செறிகின்ற ஞானத்துச் செந்தாள் கொளுவிப்
பொறைநின்ற இன்னுயிர் போந்துற நாடிப்
பறிகின்ற பத்தெனும் பாரஞ்செய் தானே`,
    transliteration: `aṟikiṉṟa mūlattiṉ mēlaṅki appuc
ceṟikiṉṟa ñāṉattuc centāḷ koḷuvip
poṟainiṉṟa iṉṉuyir pōntuṟa nāṭip
paṟikiṉṟa patteṉum pārañcey tāṉē`,
    english: `452: The Lord Grants Breath and the Child is Born
Above the Muladhara
The Kundalini fire abides;
There in the water-filled womb
The infant lay, its tiny feet entangled;
That the sweet life in patience waiting
Its onward course may seek,
He ordained, releasing the Pranas ten.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-452-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `தியானத்தின் மூலம் உயிர்கள் அறியக்கூடிய ஆறு ஆதார சக்கரங்களில் முதலாவதான மூலாதரத்திற்கு மேல் இருக்கின்ற சுவாதிட்டான சக்கரத்தின் அருகில் மூச்சுக்காற்றின் வெப்பமும் பித்த நீரும் கலந்து இருக்கின்ற கர்ப்பப் பைக்குள் செக்கச் சிவந்த சிறு கால்களோடு தலையையும் சேர்த்து உடலை வைத்திருக்கின்ற கருவை உடலில் இருக்கின்ற வெப்பமும் நீரும் சிதைத்துவிடாத படி பொறுமையோடு உயிருக்கு உயிராய் உடன் இருந்து பாதுகாக்கும் இறைவன் அந்தக் கரு வெளியே போக வழி தேடும் போது அது இன்னமும் வளர்ச்சி பெற்று முழுமையடைந்த பிறகே வெளியே போக வேண்டும் என்று அதற்கான தேவையாக பத்து மாதங்களை காலக் கெடுவாக வைத்து அந்தக் காலக் கெடு முடியும் வரை கருவையும் காத்து அதைத் தாங்கிக் கொண்டு இருக்கின்ற தாய்க்கும் அதன் பாரம் பாதிக்காத படி பாதுகாத்து அருளுகின்றான் இறைவன்.`,
  },
  
  {
    id: 454, tantraId: 2, verseNumber: 453,
    tamil: `இன்புறு காலத் திருவர்முன் பூறிய
துன்புறு பாசத் துயர்மனை வானுளன்
பண்புறு காலமும் பார்மிசை வாழ்க்கையும்
அன்புறு காலத் தமைத்தொழிந் தானே`,
    transliteration: `iṉpuṟu kālat tiruvarmuṉ pūṟiya
tuṉpuṟu pācat tuyarmaṉai vāṉuḷaṉ
paṇpuṟu kālamum pārmicai vāḻkkaiyum
aṉpuṟu kālat tamaittoḻin tāṉē`,
    english: `453: The Course of Life Was Ordained at Time of Union
When parents two in pleasure united,
Then was ordained, this body,
The sorrow-house of vexing pasa;
When that is to be,
At that hour of union, He ordained;
He, the Heavenly Lord.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-453-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆணும் பெண்ணும் சிற்றின்பத்தில் மகிழ்ந்து கூடுகின்ற போதே அவர்களின் முன் ஜென்ம வினைகளாலும் புதிதாக பிறக்கும் உயிரின் முன் ஜென்ம வினைகளாலும் இவர்களுக்கு இந்த உயிர் பிறக்க வேண்டும் என்பதை முடிவு செய்து அந்த உயிரினால் பெற்றவர்களும் பெற்றவர்களால் அந்த உயிரும் அடையும் துன்பத்திற்கு காரணமாக இருக்கும் பாசம் எனும் துயரமாகிய பந்தத்தால் கட்டி வைத்து அந்த உயிர் உலகத்தில் எத்தனைக் காலம் வாழ வேண்டும் என்பதையும் அந்த உயிரின் பண்புகளையும் அந்த உயிரின் வாழ்க்கை முறையையும் முன்பே முடிவு செய்து ஆணும் பெண்ணும் அன்பாக சேர்ந்த போதே அதற்கு ஏற்றவாறு கருவை அமைத்து முடிக்கின்றான் இறைவன்.`,
  },
{
    id: 455, tantraId: 2, verseNumber: 454,
    tamil: `கருவை ஒழிந்தவர் கண்டநால் மூவேழ்
புருடன் உடலில் பொருந்துமற் றோரார்
திருவின் கருக்குழி தேடிப் புகுந்த
உருவம் இரண்டாக ஓடி விழுந்ததே`,
    transliteration: `karuvai oḻintavar kaṇṭanāl mūvēḻ
puruṭaṉ uṭalil poruntumaṟ ṟōrār
tiruviṉ karukkuḻi tēṭip pukunta
uruvam iraṇṭāka ōṭi viḻuntatē`,
    english: `454: Through That Union Entered the 25 Tattvas to Make the
Infant Body
They who birth's finale saw,
Alone knew how purusha,
Of Tattvas five and twenty
The body Corporeal entered;
None else know,
That which sought woman's birth-pit,
In form twain, rushed within.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-454-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `இருபத்தைந்து தத்துவங்களும் (பாடல் #451 இல் காண்க) ஒன்றாகச் சேர்ந்து ஆணும் பெண்ணும் சேரும் பொழுது உருவாகும் கருமுட்டை கருவாக மாறி அதுவே ஆண் பெண் என்கிற இரண்டுவித உருவங்களாகவும் மாறுகின்ற உண்மையை பிறவி இல்லாத நிலையை அடைந்த ஞானிகள் கண்டு உணர்ந்திருக்கின்றார்களே தவிர மற்றவர்கள் அறியவில்லை.`,
  },
  {
    id: 456, tantraId: 2, verseNumber: 455,
    tamil: `விழுந்தது லிங்கம் விரிந்தது யோனி
ஒழிந்த முதல்ஐந்தும் ஈரைந்தொ டேறிப்
பொழிந்த புனல்பூதம் போற்றுங் கரணம்
ஒழிந்த நுதல்உச்சி உள்ளே ஒளித்ததே`,
    transliteration: `viḻuntatu liṅkam virintatu yōṉi
oḻinta mutalaintum īrainto ṭēṟip
poḻinta puṉalpūtam pōṟṟuṅ karaṇam
oḻinta nutalucci uḷḷē oḷittatē`,
    english: `455: The Tattvas Remained in the Forehead of the Foetus
The penis pierced; the vagina opened,
And together they rushed in
The Tattvas in groups of Five--
The Elements Five,
The tanmatras Five,
The sense organs Five gross,
And the Five Subtle,
And cognising organs four--Mind, Intellect, Will and Egoity
And in the Centre of Forehead they all lay, concealed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-455-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `ஆணும் பெண்ணும் சேர்ந்த போது இருபத்தைந்து தத்துவங்களில் (பாடல் #451 இல் காண்க) ஐந்து புலன்களைத் தவிர்த்து ஆணிடமிருந்து ஐந்து ஞானேந்திரியங்களும் ஐந்து கன்மேந்திரியங்களும் சேர்ந்து பெண்ணின் கருப்பைக்குள் பனிக்குட நீரில் உருவான கருமுட்டைக்குள் ஐந்து பூதங்களும் நான்கு அந்தக் கரணங்களும் சேர்த்து கருவாகி அதன்பின் உருவம் பெறும் போது ஐந்து புலன்களும் சேர்ந்து விட மீதி இருக்கும் புருடன் மட்டும் அந்தக் கருவுடம்பின் நெற்றி உச்சியின் உள்ளே சென்று ஒளிந்து கொண்டது. உட்கருத்து: கரு உற்பத்தியில் இருபத்தைந்து தத்துவங்களும் அடங்கியிருக்கும் முறையில் முதலில் ஆணிடமிருந்து ஞானேந்திரியங்களும் கன்மேந்திரியங்களும் சேர்ந்து பிறகு பெண்ணின் கருப்பைக்குள் செல்லும் போது ஐந்து பூதங்களும் அந்தக் கரணங்களும் சேர்ந்து கருவிலிருந்து குழந்தையாகும் போது ஐந்து புலன்களும் சேர்ந்து அந்தக் குழந்தை பிறக்கும் போது ஆன்மா புருவ மத்தியில் சென்று மாயையால் தன்னை மறைத்துக் கொள்கின்றது. மற்ற இருபத்து நான்கு தத்துவங்களையும் உயிர்கள் அறியவும் உணரவும் முடியும். கருவில் ஐந்து புலன்கள் கிடையாது உடல் முழுமையடைந்து பிறந்த பின்பே ஐந்து புலன்களும் தன் வேலைகளை செய்யும்.`,
  },
  {
    id: 457, tantraId: 2, verseNumber: 456,
    tamil: `பூவின் மணத்தைப் பொருந்திய வாயுவுந்
தாவி உலகில் தரிப்பித்த வாறுபோல்
மேவிய சீவனில் மெல்லநீள் வாயுவுங்
கூவி அவிழுங் குறிக்கொண்ட போதே`,
    transliteration: `pūviṉ maṇattaip poruntiya vāyuvun
tāvi ulakil tarippitta vāṟupōl
mēviya cīvaṉil mellanīḷ vāyuvuṅ
kūvi aviḻuṅ kuṟikkoṇṭa pōtē`,
    english: `456: Prana Enters Jiva at Birth
As unto when flower blossoms, the breeze spreads fragrance,
In spaces all around
So does Prana over Jiva extend,
Gently unfolding at the time destined.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-456-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `பூக்களின் மகரந்தத்தில் கலந்த காற்று உலகத்தில் பூவின் நறுமணத்தை பரப்பி காற்றிலேயே தங்க வைத்து அந்தக் காற்றை மற்ற உயிர்கள் சுவாசிக்கும் போது பூவின் நறுமணத்தை நுகரச் செய்வது போல தாயின் கருப்பைக்குள் இருக்கும் கருவிற்குள் புகுந்து இருக்கும் உயிரில் கலந்து இருக்கும் தனஞ்சயன் என்கிற காற்று அது குறிப்பிட்ட காலத்தில் குழந்தையாகப் பிறந்து முதன் முதலில் கூவி அழும் போது வெளிவந்து குழந்தையை முதன்முதலில் சுவாசிக்கச் செய்கிறது. அறிவியல் விளக்கம்: கருப்பைக்குள் இருக்கும் சிசு சுவாசிப்பது இல்லை. அதற்கு நுரையீரல்கள் உருவானாலும் அந்த நுரையீரல்களுக்குள் அமிலம் கலந்த நீரே நிரம்பியிருக்கும். கரு வளர்வதற்குத் தேவையான காற்றுக்களையும் சத்துக்களையும் தாயின் தொப்புள் கொடியின் மூலம்தான் எடுத்துக் கொள்கிறது. தொப்புள் கொடியில் இரண்டு நரம்புகள் இருக்கின்றது. அதில் முதலாவது நரம்பின் வழியே வரும் இரத்தத்தில் தாயின் மூச்சுக் காற்றும் தாய் சாப்பிட்ட உணவிலிருந்த சத்துக்களும் குழந்தைக்கு கிடைக்கின்றன. குழந்தை வெளிவிடும் நச்சுக் காற்றும் மற்ற கழிவுகளும் அமில நீரோடு சேர்ந்து இரண்டாவது நரம்பின் வழியே தாயிடம் வந்து தாயின் உடல் கழிவுகளோடும் மூச்சோடும் கலந்து வெளியேறுகின்றது. ஆகவே குழந்தையின் உடலில் காற்று இருந்தாலும் அது பிறந்த பிறகு வாய்விட்டு கூவி அழும்போதுதான் மூச்சுக்காற்றை முதன் முதலில் சுவாசிக்கின்றது. இதற்குக் காரணமாக இருப்பது தனஞ்சயன் எனும் காற்றாகும்.`,
  },
  
  {
    id: 458, tantraId: 2, verseNumber: 457,
    tamil: `போகின்ற எட்டும் புகுகின்ற பத்தெட்டும்
மூழ்கின்ற முத்தனும் ஒன்பது வாய்தலும்
நாகமும் எட்டுடன் நாலு புரவியும்
பாகன் விடானெனிற் பன்றியு மாமே`,
    transliteration: `pōkiṉṟa eṭṭum pukukiṉṟa patteṭṭum
mūḻkiṉṟa muttaṉum oṉpatu vāytalum
nākamum eṭṭuṭaṉ nālu puraviyum
pākaṉ viṭāṉeṉiṟ paṉṟiyu māmē`,
    english: `457: The Lord Drives in the Tattvas into the Infant Body
The eight constituents of body subtle
That ultimately leave,
The eight and ten Tattvas that sneak in,
With Purusha in them immersed
The orifices nine,
The Kundalini that serpent-like coils,
The life breath twelve-finger breadth long,
--If these, the Divine Charioteer drives not in,
Verily may the infant be less than human (say, pig).`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-457-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `கரு உருவாகும் போது அதனுடன் போகின்ற எட்டுவிதமான சூட்சும உருவங்களும் பத்துவிதமான வாயுக்களும் எட்டுவிதமான குணங்களும் இவற்றில் மூழ்கி இருக்கின்ற ஆன்மாவும் அது உயிராக உடலெடுக்கும் போது உருவாகும் ஒன்பது வாயில்களும் உடலின் மூலாதாரத்தில் இருக்கும் நாகமாகிய குண்டலினியும் பன்னிரண்டு அங்குலம் (கழுத்துக்குக் கீழே எட்டு அங்குலம் மனிதர்களுக்கும் கழுத்துக்கு மேலே நான்கு அங்குலம் யோகிகளுக்கும்) ஓடிக் கொண்டிருக்கும் மூச்சுக் காற்றும் இவை அனைத்தையும் அடக்கி ஆளும் இறைவன் தனது அருளால் பாதுகாத்து வழி நடத்தாமல் இருந்தால் கருவில் பிறக்கும் குழந்தை இழி பிறப்பாக போய் விடும். சூட்சும உருவங்கள் 8 – சுவை, ஒளி, ஊறு, ஓசை, நாற்றம், புத்தி, மனம், அகங்காரம். வாயுங்கள் 10 – பிராணன், அபானன், உதானன், வியானன், சமானன், நாகன், கூர்மன், கிருகரன், தேவதத்தன், தனஞ்சயன். குணங்கள் 8 – காமம், குரோதம், உலோபம், மோகம், மதம், மாச்சரியம், துன்பம், அகங்காரம். உடலின் வாயில்கள் 9 – 2 கண்கள், 2 காதுகள், 2 மூக்குத் துவாரங்கள், வாய், நீர்வாய், ஆசனவாய். உட்கருத்து: கருவைப் பாதுகாத்து அதற்கு வேண்டிய அனைத்தையும் செயல்படுத்துபவன் இறைவன். அப்படி அவன் செயல்படுத்தாமல் விட்டுவிட்டால் பிறக்கும் குழந்தை எதற்கும் உபயோகமில்லாத சதைப் பிண்டமாகப் பிறக்கும்.`,
  },
{
    id: 459, tantraId: 2, verseNumber: 458,
    tamil: `ஏற எதிர்க்கில் இறையவன் றானாகும்
மாற எதிர்க்கில் அரியவன் றானாகும்
நேரொக்க வைக்கின் நிகர்ப்போதத் தானாகும்
பேரொத்த மைந்தனும் பேரர சாளுமே`,
    transliteration: `ēṟa etirkkil iṟaiyavaṉ ṟāṉākum
māṟa etirkkil ariyavaṉ ṟāṉākum
nērokka vaikkiṉ nikarppōtat tāṉākum
pērotta maintaṉum pērara cāḷumē`,
    english: `458: The Child With the Three Gunas in Balance is Fit for
Rulership
When in sex union,
The male flow in force dominates
The infant is born with Tamasic qualities of Rudra;
When the flow in reverse is,
The Sattvic quality of Hari dominates;
When the two in balance flow,
The Rajasic quality of Brahma prevailes;
He is to kingship born
In whom gunas three proportionate sway.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-458-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆணின் சுக்கிலம் பெண்ணின் சுரோணிதத்தை எதிர்த்துச் சென்றால் பிறக்கும் குழந்தை உருத்திரனை ஒத்த தாமச குணம் உடையதாக இருக்கும். பெண்ணின் சுரோணிதத்தை ஆணின் சுக்கிலம் எதிர்த்து சென்றால் பிறக்கும் குழந்தை திருமாலை ஒத்த சத்துவ குணம் உடையதாக இருக்கும். ஆணின் சுக்கிலமும் பெண்ணின் சுரோணிதமும் சமமாக எதிர்த்து இணைந்தால் பிறக்கும் குழந்தை பிரம்மனை ஒத்த இராசத குணம் உடையதாக இருக்கும். ஆணும் பெண்ணும் சமமான இன்பத்தில் இணைந்திருந்தால் பிறக்கும் குழந்தை மாபெரும் அரசன் போல ஆளும் தன்மையைக் கொண்டு இருக்கும். குணங்களின் விளக்கம்: தாமச குணம் (தாமசம்) – காமம், வெகுளி, மயக்கம், கலக்கம், கோபம், பேராசை, பொய் பேசுதல், இம்சை, யாசித்தல், வெளிவேசம், சிரமம், கலகம், வருத்தம், மோகம், கவலை, தாழ்மை, உறக்கம், அச்சம், சோம்பல், காரணமில்லாமல் பிறரிடம் பொருட்களை எதிர்பார்த்தல் மற்றும் பிறர்க்கு கேடு விளைவிக்கும் செயல்கள் செய்வது, பகட்டுக்காக செயல்கள் செய்வது. சத்துவ குணம் (சாத்விகம்) – நற்காரியங்களில் மனதைச் செலுத்தும் குணம், மன அடக்கம், புலன் அடக்கம் (தமம்), துன்பங்களைப் பொறுத்துக் கொள்ளும் இயல்பு (சகிப்புத் தன்மை), விவேகம், வைராக்கியம், தவம், வாய்மை, கருணை, மகிழ்ச்சி, நம்பிக்கை, பாவம் செய்வதற்கு கூச்சப்படுதல், தன்னிலேயே மகிழ்ந்திருத்தல், தானம், பணிவு மற்றும் எளிமை. இராசத குணம் (இராட்சதம்) – ஊக்கம், ஞானம், வீரம், தருமம், தானம், கல்வி, ஆசை, முயற்சி, இறுமாப்பு, வேட்கை, திமிர், தெய்வங்களிடம் செல்வங்கள் வேண்டுவது, வேற்றுமை எண்ணம், புலனின்பப் பற்று, சண்டைகளில் உற்சாகம், தன் புகழில் ஆசை, மற்றவர்களை எள்ளி நகையாடுவது, பராக்கிரமம், பிடிவாதத்துடன் ஒரு முயற்சியை மேற்கொள்ளுதல்.`,
  },
  {
    id: 460, tantraId: 2, verseNumber: 459,
    tamil: `ஏயங் கலந்த இருவர்தஞ் சாயத்துப்
பாயுங் கருவும் உருவா மெனப்பல
காயங் கலந்தது காணப் பதிந்தபின்
மாயங் கலந்த மனோலய மானதே`,
    transliteration: `ēyaṅ kalanta iruvartañ cāyattup
pāyuṅ karuvum uruvā meṉappala
kāyaṅ kalantatu kāṇap patintapiṉ
māyaṅ kalanta maṉōlaya māṉatē`,
    english: `459: Into the Foetus Mayaic Mind was Placed
There two in accord united;
And from their vital flows
Emerged the infant form;
But when into it Jiva,
Who in myriad bodies has dwelt of yore,
Now entered,
Lo! it is dominated by Mind;
Maya subtle pervades it.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-459-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `எத்தனையோ பிறவிகளை எடுத்து முடிந்த பின் எடுத்த இந்த பிறவியில் வினைப் பயனால் ஆண் பெண் இருவரும் சந்தித்து இன்பத்தில் கலந்து அவர்களது உருவங்களிலிருந்தும் அவர்களின் முன்னோர்களது உருவங்களிலிருந்தும் பலவிதமான அம்சங்களை எடுத்துக் கொண்டு அந்த அம்சங்களின் சாயலிலேயே உருவம் கொண்டு கரு உருவாகின்றது. ஆணும் பெண்ணும் இன்பத்தில் கலந்து பின் பெண்ணிடம் உருவான அந்தக்கரு புதிதாக உருவானதாக அனைவராலும் அறிந்து கொள்ளப்பட்டாலும் அந்தக் கரு உருவாகுவதற்கு முன்பே இந்த ஆணுக்கும் இந்த பெண்ணுக்கும் தான் இந்தக் கரு உருவாக வேண்டும் என்பது வினைப் பயனால் முடிவு செய்யப்பட்ட ஒன்று என்பதை உணராத ஆணும் பெண்ணும் மாயையில் ஒருவரோடு ஒருவர் கலந்து கரு உருவாகக் காரணமாகி அந்தக் கருவுக்கும் தங்களது மாயையோடு சேர்த்து தங்களது பலவித குணங்களையும் கொடுத்து விடுகின்றார்கள்.`,
  },
  {
    id: 461, tantraId: 2, verseNumber: 460,
    tamil: `கர்ப்பத்துக் கேவல மாயாள் கிளைகூட்ட
நிற்குந் துரியமும் பேதித்து நினைவெழ
வற்புறு காமியம் எட்டாதல் மாயேயஞ்
சொற்புறு தூய்மறை வாக்கினாஞ் சொல்லே`,
    transliteration: `karppattuk kēvala māyāḷ kiḷaikūṭṭa
niṟkun turiyamum pētittu niṉaiveḻa
vaṟpuṟu kāmiyam eṭṭātal māyēyañ
coṟpuṟu tūymaṟai vākkiṉāñ collē`,
    english: `460: Jiva Gets Consciousness and Desires
There in the pregnant womb,
The soul lay in Primordial quiescence (Turiya State)
From that State Maya and Her tribe aroused it;
And conferred Consciousness;
And Maya's evolutes eight--Desires and the rest,
Thus say scriptures, holy and true.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-460-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `கரு உருவாகும் போது முதலில் கரு தனித்து கேவல நிலையில் இருக்கும். அதன் பிறகு மாயை அதன் தத்துவங்களை கருவோடு சேர்த்து விடும்போது அதுவரை துரிய நிலையில் உறக்கத்தில் இருந்த கரு அந்த நிலையிலிருந்து மாறி விழித்துக் கொண்டு நினைவு தோன்ற ஆரம்பிக்கும். நினைவு தோன்றிய பின் அந்தக் கருவின் முற்பிறவிகளிலிருந்து தொடர்ந்து வரும் வினைப் பயன்களால் வரும் கன்மத்துடன் (மும்மலங்களில் ஒன்று) மாயேயம் என்கிற அசுத்த மாயையின் ஏழுவித காரியங்களும் (காலம், நியதி, கலை, வித்தை, இராகம், புருடன், மாயை) சேர்ந்து மொத்தம் எட்டுவித மாயைகளை அந்தக் கரு பெற்றுவிடும். இதுவே கருவுடன் மாயைகள் சேரும் முறைமை என்று தூய்மையான வேதங்கள் சொல்லும்.`,
  },
  {
    id: 462, tantraId: 2, verseNumber: 461,
    tamil: `என்பால் மிடைந்து நரம்பு வரிக்கட்டிச்
செம்பால் இறைச்சி திருந்த மனைசெய்து
இன்பால் உயிர்நிலை செய்த இறையோங்கும்
நண்பால் ஒருவனை நாடுகின் றேனே`,
    transliteration: `eṉpāl miṭaintu narampu varikkaṭṭic
cempāl iṟaicci tirunta maṉaiceytu
iṉpāl uyirnilai ceyta iṟaiyōṅkum
naṇpāl oruvaṉai nāṭukiṉ ṟēṉē`,
    english: `461: How the Body is Fashioned
With skeletal bones He erected the frame;
With tendons circuitous He fastened it;
With blood and flesh He cemented it;
Thus did Lord fashion this body-mansion,
For dear life to dwell
Him I seek forth, endearment increasing.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-461-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `உயிர்கள் தாம் ஆசைப்பட்ட இன்பத்தை அடைய வேண்டும் என்று எலும்புகளை இணைத்து நரம்புகளால் வரிசையாகக் கட்டி வைத்து சிவந்த இரத்தத்தை வைத்து தோலால் அழகாக மூடி திருத்தமாக செய்யப்பட்ட இந்த வீடாகிய உடலுக்கு உயிர் கொடுத்த இறைவனின் கருணையை எண்ணி அவன் மீது பொங்கிய நட்பினால் அவன் ஒருவனை மட்டுமே அன்பினால் தேடி அடைகின்றேன். உட்கருத்து: ஆன்மா ஆசைப்பட்டுவிடும் போது அந்த ஆசையைத் தீர்க்க பிறவி கொடுத்து அருமையான உடலைக் கருவிலிருந்தே செதுக்கி அழகான வீடாக்கி அதனுள் உயிராக உலவ விட்ட இறைவனை உயிர்கள் எப்போதும் நினைத்து அவன் கருணையை எண்ணி அன்பு கொண்டு அவனைத் தமக்குள் தேடி அடைய வேண்டும்.`,
  },
  {
    id: 463, tantraId: 2, verseNumber: 462,
    tamil: `பதஞ்செய்யும் பால்வண்ணன் மேனிப் பகலோன்
இதஞ்செய்யு மொத்துடல் எங்கும் புகுந்து
குதஞ்செய்யும் அங்கியின் கோபந் தணிப்பான்
விதஞ்செய்யு மாறே விதித்தொழிந் தானே`,
    transliteration: `patañceyyum pālvaṇṇaṉ mēṉip pakalōṉ
itañceyyu mottuṭal eṅkum pukuntu
kutañceyyum aṅkiyiṉ kōpan taṇippāṉ
vitañceyyu māṟē vitittoḻin tāṉē`,
    english: `462: The Lord Contains the Fire in Muladhara
He is milky white in hue,
Effulgent is He unto the sun;
He is benignant;
He pervades the entire body
And diffuses His tenderness;
He contained the rage of fire in Muladhara
This He ordained, in ways diverse.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-462-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `நிலவைப் போன்ற வெள்ளை நிறத்தில் சூரியனைப் போன்ற பிரகாசிக்கும் ஒளி உடலாக இருக்கின்ற இறைவன் தாயின் சூரிய கலை (வலது நாசி) மூச்சுக்காற்றின் மூலம் இதமான சூட்டையும் சந்திர கலை (இடது நாசி) மூச்சுக்காற்றின் மூலம் இதமான குளிர்ச்சியையும் கொண்டு கருவின் உடலோடு கலந்து எங்கும் பரவி நின்று தாயின் அடிவயிற்றில் உணவைச் செரிப்பதற்காக சூடாக உருவாகும் நெருப்பினாலும் நீராலும் கரு ஒருவித பாதிப்பும் அடையாமல் இருக்கும்படி காத்து நின்று குழந்தை எந்த விதமாக வளர வேண்டுமோ அப்படியெல்லால் வளர வைத்து குழந்தை பிறக்கும் வரை காத்து அருளுகின்றான்.`,
  },
  {
    id: 464, tantraId: 2, verseNumber: 463,
    tamil: `ஒழிபல செய்யும் வினையுற்ற நாளே
வழிபல நீராடி வைத்தெழு வாங்கிப்
பழிபல செய்கின்ற பாசக் கருவைச்
சுழிபல வாங்கிச் சுடாமல்வைத் தானே`,
    transliteration: `oḻipala ceyyum viṉaiyuṟṟa nāḷē
vaḻipala nīrāṭi vaitteḻu vāṅkip
paḻipala ceykiṉṟa pācak karuvaic
cuḻipala vāṅkic cuṭāmalvait tāṉē`,
    english: `463: The Lord Preserves the Foetus
Even the day, ruinous Karma trailed after Jiva,
He designed ways of preservation numerous;
He surrounded the foetus with water
Kept it safe from burning Muladhara Fire,
He drew charmed circles eddying,
Around the budding life, from Pasa harassing
And so preserved it safe and cool.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-463-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `The Lord takes infinite care to protect the foetus inside the womb for 300 days. He surrounds it with a protective 'bag of waters', keeps it from being scorched by the mother's muladhara fire; and He draws charmed circles around the budding life to shield it from harm. The Absolute Being stands as the sentinel, guarding the child in the womb.`,
    elaborationTamil: `ஆன்மா தான் இருக்கும் உடலின் மூலம் அனுபவிக்க வேண்டிய வினைகளை எப்போது அனுபவித்து முடிக்கின்றதோ அப்போதே அதனது அடுத்த பிறவியை எடுக்க உதவும் பலவிதமான வழிகளை உருவாக்கி விடுகின்றான் இறைவன். ஆன்மா இருக்கும் உடல் இறந்த பின் சுற்றத்தாரால் நீராட்டப்பட்டு சுடுகாட்டிற்கு சுட்டெரிக்க எடுத்துச் செல்லும்போதே அதிலிருந்து வெளிப்பட்ட ஆன்மாவை இன்னும் அனுபவிக்க வேண்டிய பலவிதமான வினைகளான பந்த பாசத்தால் கட்டி புதிய கருவாக உருவாக்கி கர்ப்பப் பைக்குள் வைத்து அங்கே பெண்ணின் அடிவயிற்றில் இருக்கும் நெருப்பினாலும் நீராலும் பாதிக்கப் படாதபடி காப்பாற்றி அருளுகின்றான் இறைவன்.`,
  },
  {
    id: 465, tantraId: 2, verseNumber: 464,
    tamil: `சுக்கில நாடியில் தோன்றிய வெள்ளியும்
அக்கிர மத்தே தோன்றுமவ் வியோனியும்
புக்கிடும் எண்விரல் புறப்பட்டு நால்விரல்
அக்கரம் எட்டும்எண் சாணது வாகுமே`,
    transliteration: `cukkila nāṭiyil tōṉṟiya veḷḷiyum
akkira mattē tōṉṟumav viyōṉiyum
pukkiṭum eṇviral puṟappaṭṭu nālviral
akkaram eṭṭumeṇ cāṇatu vākumē`,
    english: `464: Breathing and Size of Infant
The Silvery semen welled up
And met the vaginal flow, alike surging,
And lo! then was born the infant
Inhaling eight and exhaling four
Finger-length of breath,
And measuring eight finger-span
Of its own tiny palm.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-464-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `The child born measures eight spans of its own finger length, because out of the 12 finger-lengths the prana breath constitutes, only 8 are inhaled; the other four are exhaled.`,
    elaborationTamil: `ஆணின் சுக்கிலமும் பெண்ணின் சுரோணிதமும் சிவப்பு நிற கருமுட்டையாக வளர்கிறது. இதற்காக ஆணின் சுக்கிலம் எட்டு விரற்கடை அளவும் பெண்ணின் சுரோணிதம் நான்கு விரற்கடை அளவும் பயணிக்கின்றது. இப்படி பயணிக்கின்ற அனைத்தும் கருமுட்டையாக வளர்வது இல்லை. இறைவன் அருளால் பிழைத்த ஒன்றோ அல்லது சமயத்தில் பலவும் ஒன்றாக ஒரே சமயத்தில் கருமுட்டையாக வளர்கிறது. அப்படி உருவான கருமுட்டை உடல்தான் எட்டு ஜாண் அளவிற்கு வளர்கிறது. அறிவியல் விளக்கம்: கருவில் உருவாகும் குழந்தையிலிருந்து பிறந்து வளர்ந்து இறக்கும் மனிதன் வரை அனைவருக்குமே அவர்களது விரல்களால் அளவிட்டால் எட்டு ஜான் அளவிற்கே உடல் இருக்கும் இதைத்தான் திருமூலரும் எண் சாண் அது ஆகுமே என்று அருளுகின்றார்.`,
  },
  {
    id: 466, tantraId: 2, verseNumber: 465,
    tamil: `போகத்துள் ஆங்கே புகுந்த புனிதனுங்
கோசத்துள் ஆகங்கொணர்ந்த கொடைத்தொழில்
ஏகத்துள் ஆங்கே இரண்டெட்டு மூன்றைந்து
மோகத்துள் ஆங்கொரு முட்டைசெய் தானே`,
    transliteration: `pōkattuḷ āṅkē pukunta puṉitaṉuṅ
kōcattuḷ ākaṅkoṇarnta koṭaittoḻil
ēkattuḷ āṅkē iraṇṭeṭṭu mūṉṟaintu
mōkattuḷ āṅkoru muṭṭaicey tāṉē`,
    english: `465: Body of 25 Tattvas
In to the union, the Holy One entered;
Gathering Tattvas five and twenty
Fashioned the (five)-sheathed body;
Munificient indeed was his gift!
A veritable Bundle of Desire He made.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-465-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆண் பெண் இருவரின் இன்பத்தில் உருவான கருவின் மூலமாக ஆன்மாவை உயிராக உருவாக்கும் கொடைத் தொழிலைப் புரிந்து அருளுகின்றான் புனிதனான இறைவன். கருவிற்குள் இருபத்தைந்து தத்துவங்களையும் (பாடல் #451 இல் காண்க) சேர்த்து ஆண் பெண்ணின் இன்பத்தின் விளைவாக அங்கே ஒரு சினைமுட்டையைச் செய்து அருளுகின்றான். உட்கருத்து: ஆணும் பெண்ணும் எத்தனை முறை இன்பம் கொண்டாலும் கரு எளிதில் உருவாகி விடுவதில்லை. அப்படி நடந்தால் பெண் ஆயிரக்கணக்கான குழந்தைகள் பெற வேண்டும். பெண்ணிடம் உருவாகும் அனைத்து கருமுட்டைகளும் சினைமுட்டையாக மாறுவதில்லை. அப்படி நடந்தால் பெண் கோடிக்கணக்கான குழந்தைகள் பெற வேண்டும். கருமுட்டை சினைமுட்டையாகிவிட்டால் மட்டும் குழந்தை உருவாகி விடுவதில்லை. அப்படி நடந்தால் கருத்தரித்த அனைத்து பெண்களும் உயிரோடு இருக்கும் குழந்தையைப் பெற்று இருக்க வேண்டும். அறிவியலின்படி பல பெண்கள் கரு கலைந்தோ அல்லது இறந்த குழந்தைகளை பெற்றெடுக்கின்றார்கள். ஆணும் பெண்ணும் இன்பமாக இருக்கும் போதே இவர்களுக்கு இப்படிப்பட்ட குழந்தைதான் பிறக்க வேண்டும் என்பதை முடிவு செய்து அதன்படி சினைமுட்டைகளை கருவாக்கி அதைக் குழந்தையின் உடலாக்கி இருபத்து ஐந்து தத்துவங்களையும் சேர்த்த உயிராக்கி பிறக்கும் வரை பாதுகாத்தும் அருளுகின்றான் இறைவன்.`,
  },
  {
    id: 467, tantraId: 2, verseNumber: 466,
    tamil: `பிண்டத்தில் உள்ளுறு பேதைப் புலன்ஐந்தும்
பிண்டத்தி னூடே பிறந்து மரித்தது
அண்டத்தின் உள்ளுறு சீவனும் அவ்வகை
அண்டத்து நாதத் தமர்ந்திருந் தானே`,
    transliteration: `piṇṭattil uḷḷuṟu pētaip pulaṉaintum
piṇṭatti ṉūṭē piṟantu marittatu
aṇṭattiṉ uḷḷuṟu cīvaṉum avvakai
aṇṭattu nātat tamarntirun tāṉē`,
    english: `466: After Death, Senses End With Body; Jiva Ends in Nada
The five senses with their foolish ways
Are in this body born;
And there they subside;
So does Jiva
That permeates macrocosm
Surely subside in Nada.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-466-Second-Tantra-14.-Act-of-Conception-1.mp3',
    elaborationTamil: `பெண்ணின் கருப்பைக்குள் உருவாகும் குழந்தையின் உடலினுள் மாயையால் ஒன்றும் அறியாத ஐந்துவகைப் புலன்களும் சேர்ந்து உடலோடு வளர்ந்து உடலோடு இறக்கின்றன. அதுபோலவே அண்டசராசரங்கள் அனைத்திலும் நிறைந்திருக்கும் இறைவனின் நாதத் தத்துவத்திலிருந்து உருவாகிய ஆன்மா கருவுக்குள் உயிரோடு பிறந்து உடலோடு இறந்தபின் மீண்டும் இறைவனின் நாத தத்துவத்திலேயே சென்று அமர்ந்து இருக்கின்றது. உட்கருத்து: அசையா சக்தியாகிய இறைவனிடமிருந்து உருவாகிய ஒளி ஓசை ஆகிய இருவகைத் தத்துவங்களாலேயே ஆன்மா உருவாகின்றது. அத்தகைய ஆன்மா வினைப் பயனால் கருவுக்குள் புகுந்து உடலோடு உயிராகி வளர்ந்து உடல் இறந்தபின் பிரிந்து மீண்டும் அந்தத் தத்துவங்களுடனே சேர்ந்து அடுத்த பிறவி வரை காத்திருத்து பிறவி எடுக்கும். எப்போது அனைத்து பிறவிக்கான வினைகளும் தீர்ந்துவிடுகின்றதோ அப்போது இறைவனுடனே சென்று இரண்டறக் கலந்துவிடும்.`,
  },
  {
    id: 468, tantraId: 2, verseNumber: 467,
    tamil: `இலைபொறி யேற்றி யெனதுடல் ஈசன்
துலைப்பொறி யிற்கரு ஐந்துட னாட்டி
நிலைபொறி முப்பது நீர்மை கொளுவி
உலைப்பொறி ஒன்பதில் ஒன்றுசெய் தானே`,
    transliteration: `ilaipoṟi yēṟṟi yeṉatuṭal īcaṉ
tulaippoṟi yiṟkaru aintuṭa ṉāṭṭi
nilaipoṟi muppatu nīrmai koḷuvi
ulaippoṟi oṉpatil oṉṟucey tāṉē`,
    english: `467: The 35 Tattvas Introduced
As on to a leaf-like device
He mounted my life;
And there;
With balance like precision planted,
Subtle senses five;
And other Tattvas thirty;
And thus fashioned a body;
A steaming cauldron with openings nine.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-467-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `பெண்ணின் உடல் என்ற இயந்திரத்தினுள் ஆணின் உடல் என்ற இயந்திரத்தை இயக்கி பெண்ணின் கர்ப்பப்பை என்னும் இயந்திரத்தினுள் கருவை உருவாக வைத்த இறைவன் அந்த கருவை ஐந்து பூதங்களால் ஆட்டி வைத்து ஆன்மாவையும் முப்பது தத்துவங்களையும் சேர்த்து உடல் என்ற இயந்திரத்தைக் கொடுத்து குழந்தையாக்கி அதைப் பித்த நீரினுள் பத்து மாதங்கள் மூழ்கி இருக்கச் செய்து மூச்சுக்காற்றினால் உணவைச் சுட்டு எரிக்கும் வயிறாகிய இயந்திரத்துடன் ஒன்பது துவாரங்களைக் கொண்ட உடம்பில் ஆன்மாவையும் உயிரையும் ஒன்றாகச் சேர்த்து வைத்து அருளுகின்றான் இறைவன். ஒன்பது துவாரங்கள்: கண்கள் 2, காதுகள் 2, மூக்குத்துவாரம் 2, வாய், பிறவிக்குறி, ஆசனவாய். முப்பத்தாறு தத்துவங்கள்: 5 சிவ தத்துவங்கள்: நாதம் – தூய அறிவாலான பரம்பொருளின் முழுமையான நிலை, விந்து – இயங்கிக் கொண்டிருக்கும் கிரியா சக்தி, சாதாக்கியம் – சதாசிவன், ஈசுரம் – மறைத்தல் சக்தியான மகேசுரன், சுத்த வித்தை – படைத்தல், காத்தல், அழித்தல் எனும் முத்தொழிலுக்கு அடிப்படையான இறைதத்துவம். 7 வித்தியா தத்துவங்கள்: காலம், நியதி, கலை, வித்தை, இராகம், மாயம், புருடன் (ஆன்மா) 24 ஆன்ம தத்துவங்கள்: 5 பூதங்கள் – நிலம் (உடல்), நீர் (இரத்தம் மற்று பித்த நீர்கள்), நெருப்பு (உணவைச் செரிக்கும் நெருப்பு மற்றும் உடல் சூடு), காற்று (மூச்சுக் காற்று மற்றும் பத்துவிதமான வாயுக்கள்), ஆகாயம் (உயிர் மற்றும் ஆன்மா). 5 புலன்கள் – கண்களால் பார்த்தல், காதுகளால் கேட்டல், வாயால் சுவைத்தல், மூக்கால் நுகருதல், தோலால் தொடுதல். 5 ஞானேந்திரியங்கள் – ஓசை (கேட்பது), ஊறு (தொடுவது), ஒளி (பார்ப்பது), சுவை (உண்பது), நாற்றம் (முகர்வது). 5 கன்மேந்திரியங்கள்: வாய் (பேச்சு), கைகள் (செயல்), கால்கள் (போக்குவரவு), எருவாய் (கழிவு நீக்கம்), கருவாய் (இன்பமும் பிறப்பும்). 4 அந்தக்கரணங்கள் – மனம் (எண்ணங்கள்), புத்தி (அறிவு), சித்தம் (சிந்தனை), அகங்காரம் (நான் என்ற எண்ணம்).`,
  },
  {
    id: 469, tantraId: 2, verseNumber: 468,
    tamil: `இன்புற் றிருவர் இசைவித்து வைத்தமண்
துன்பக் கலசம் அணைவான் ஒருவனே
ஒன்பது நீர்ச்சால் கலசம் பதினெட்டு
வெந்தது சூளை விளைந்தது தானே`,
    transliteration: `iṉpuṟ ṟiruvar icaivittu vaittamaṇ
tuṉpak kalacam aṇaivāṉ oruvaṉē
oṉpatu nīrccāl kalacam patiṉeṭṭu
ventatu cūḷai viḷaintatu tāṉē`,
    english: `468: Lord Creates
In union's rapture they kneaded the clay
For Him to fashion sorrow's tenement;
The kiln burnt, the pitcher emerged,
With channels nine and Tattvas eighteen.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-468-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `இன்பத்தில் கலந்த ஆண் பெண் இருவரும் மனமொத்து வைத்த கருவாகிய மண் (பிண்டம்) பந்த பாசத்தால் சிக்குண்டு துன்பத்தைப் பெறும் களிமண்ணாலான கலசம் போன்றது. அதைக் குயவன் போல குழைத்து உருவாக்குபவன் இறைவன் ஒருவனே. இந்தக் களிமண்ணாலான கலசத்தில் ஒன்பது துவாரங்களும் (கண்கள் 2 காதுகள் 2 மூக்குத்துவாரம் 2 வாய் பிறவிக்குறி ஆசனவாய்) பதினெட்டு அச்சாரங்களும் (எலும்புகள்) உள்ளன. எப்படி குயவன் தான் குழைத்து உருவாக்கிய கலசம் உறுதியாக இருக்க வேண்டும் என்று சூளையில் இட்டு சுடுகின்றானோ அதுபோல இறைவனும் கருவை தாயின் சூடான அடிவயிற்றுக் கருப்பை எனும் சூளையில் வைத்துப் பத்து மாதங்கள் சுட்டுப் பாதுகாத்து குழந்தையாக உருவாக்கி அருளுகின்றான்.`,
  },
  {
    id: 470, tantraId: 2, verseNumber: 469,
    tamil: `அறியீ ருடம்பினி லாகிய வாறும்
பிறியீ ரதனிற் பெருகுங் குணங்கள்
செறியீ ரவற்றினுட் சித்திகள் இட்ட
தறியவீ ரைந்தினு ளானது பிண்டமே`,
    transliteration: `aṟiyī ruṭampiṉi lākiya vāṟum
piṟiyī rataṉiṟ perukuṅ kuṇaṅkaḷ
ceṟiyī ravaṟṟiṉuṭ cittikaḷ iṭṭa
taṟiyavī raintiṉu ḷāṉatu piṇṭamē`,
    english: `469: Lord Placed the Six Adharas
You know not the six centers within;
You realise not the great good that wells therein;
You seek not the Siddhis within them;
Know this,
The fleshy body is but of ten senses made.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-469-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `உடம்பு அடையும் ஆறு வகையான நிலைகளை அறியாமல் இருக்கின்றீர்கள். அந்த நிலைகளில் வினைப் பயனால் உருவாகிப் பெரியதாக வளரும் பலவித குணங்களில் நல்லது எது கெட்டது எது என்று பிரித்துப் பார்த்து கெட்டதை விட்டுப் பிரியாமல் இருக்கின்றீர்கள். பஞ்ச பூதங்களால் ஆன இந்த பிண்டமாகிய உடம்பினுள் எட்டுவிதமான மாபெரும் சித்திகளையும் இறைவன் வைத்திருப்பதை அறிந்து அதை அடைந்து பேரின்பப் பெருவாழ்வைப் பெறுவதற்கும் முயற்சி செய்யாமல் இருக்கின்றீர்கள். உடலின் ஆறு நிலைகள்: பேறு – இன்பம். இழவு – பற்றாக்குறை. துன்பம் – துயரம். பிணி – நோய்கள் மூப்பு – முதுமை சாக்காடு – இழிவு நிலை. வினைப் பயனால் பெறும் குணங்கள்: பாடல் #458 இல் காண்க. உடலின் பஞ்ச பூதங்கள்: நிலம் – எலும்பு தோலால் ஆன உடல். நீர் – இரத்தம் மற்றும் பித்த நீர்கள். நெருப்பு – உணவைச் செரிக்கும் நெருப்பு மற்றும் உடல் சூடு. காற்று – மூச்சுக் காற்று மற்றும் உடலில் உள்ள பத்துவிதமான வாயுக்கள். ஆகாயம் – உயிர் மற்றும் ஆன்மா. எட்டு மாபெரும் சித்திகள்: அணிமா – அணுவைப் போல மிகவும் நுண்ணிய உருவம் எடுத்தல். மகிமா – மலையை விடவும் மிகப் பெரிய உருவம் எடுத்தல். இலகிமா – இலவம் பஞ்சை விடவும் மிகவும் லேசான எடையை எந்த உருவத்திலும் எடுத்தல். கரிமா – மலையை விடவும் மிகவும் கனமான எடையை எந்த உருவத்திலும் எடுத்தல். பிராந்தி – நினைத்த இடத்திற்கு கண் இமைக்கும் நேரத்திற்குள் உடனே சென்றுவிடுதல். பிரகாமியம் – மனதில் நினைத்ததை உடனே கைகொள்ளுதல். ஈசத்துவம் – வேண்டிய எதையும் கட்டுப் படுத்தி ஆட்டி வைத்தல். வசித்துவம் – எதையும் அல்லது எவரையும் தன் வசமாக்கி ஆட்கொள்ளுதல்.`,
  },
  {
    id: 471, tantraId: 2, verseNumber: 470,
    tamil: `உடல்வைத்த வாறும் உயிர்வைத்த வாறும்
மடைவைத்த ஒன்பது வாய்தலும் வைத்துத்
திடம்வைத்த தாமரைச் சென்னியுள் அங்கிக்
கடைவைத்த ஈசனைக் கைகலந் தேனே`,
    transliteration: `uṭalvaitta vāṟum uyirvaitta vāṟum
maṭaivaitta oṉpatu vāytalum vaittut
tiṭamvaitta tāmaraic ceṉṉiyuḷ aṅkik
kaṭaivaitta īcaṉaik kaikalan tēṉē`,
    english: `470: Lord Placed Divine Jnana in Cranium
He fashioned this body,
Into that body He breathed life;
And set gates nine;
And then into the lotus-like cranium
He lit the Fire (of Divine Jnana),
The Lord made these,
And Him I salute in endearment intense.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-470-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `In this act of fashioning the corporeal body, the Divine Architect provides for the subtle body that consists of eight tattvas, the purusha body into which enters 18 avastas or states; the nine orifices, the six adharas, the kundalini fire coiled in the muladhara chakra, and the prana breath that measures 12 matras in length. To crown all, in the lotus-like sahasrara chakra in the cranium, He places the fire of divine jnana.`,
    elaborationTamil: `ஆன்மா தனது வினையின் பயனால் பிறவி எடுக்க உடலை படைத்து உடலுக்குள் ஆன்மாவை வைத்து தேவையான காலத்திற்கு வாழும்படி உயிரையும் வைத்து தேவைக்கேற்ப திறந்து மூடிக்கொள்ளுகின்ற ஒன்பது துவாரங்களைக் கொண்ட உறுதியான உடலையும் வைத்து அந்த உயிர் பிறவியில்லா நிலையை அடைய அந்த உடலின் தலையின் உச்சியின் இறுதியில் சகஸ்ரரதளத்தில் ஆயிரம் இதழ் தாமரையின் மேல் நெருப்பு வடிவமாகத் தங்கியும் இருப்பதைக் கண்டு அவனோடு பேரின்பத்தில் கலந்து திளைத்து நின்றேன். உட்கருத்து: ஆன்மா தான் கொண்ட ஆசையினாலும் வினையினாலும் பிறவி எடுக்கின்றது. அந்தப் பிறவிச் சுழலிலிருந்து தப்பிக்க உடலில் ஆறு ஆதார சக்தி மயங்களிலும் உச்சியில் ஏழாவது இடமாக சகஸ்ரர தளத்தில் ஆயிரம் இதழ் கொண்ட தாமரை மலரின் மேலே நெருப்பு வடிவமாக இருக்கும் இறைவனை உயிர்கள் உணர்ந்தால் பிறவி இல்லாத பேரின்பத்தில் திளைத்திருக்கலாம்.`,
  },
  {
    id: 472, tantraId: 2, verseNumber: 471,
    tamil: `கேட்டுநின் றேன்எங்குங் கேடில் பெருஞ்சுடர்
மூட்டுகின் றான்முதல் யோனி மயனவன்
கூட்டுகின் றான்குழம் பின்கரு வையுரு
நீட்டுநின் றாகத்து நேர்ப்பட்ட வாறே`,
    transliteration: `kēṭṭuniṉ ṟēṉeṅkuṅ kēṭil peruñcuṭar
mūṭṭukiṉ ṟāṉmutal yōṉi mayaṉavaṉ
kūṭṭukiṉ ṟāṉkuḻam piṉkaru vaiyuru
nīṭṭuniṉ ṟākattu nērppaṭṭa vāṟē`,
    english: `471: Lord Creates Life From Primal Seed of Causation
The Lord is Limitless Light;
He kindles all life from Primal Womb;
He stirrs the liquid-seed of Causation;
He endows it with form expansive;
Him I seek in heaven and earth.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-471-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `What is the origin of this life? The Lord is Limitless Light, and-He kindles all life from the primordial womb of His Sakti. There the liquid seed of causation is stirred by nadam; and in bindu it attains manifest form.`,
    elaborationTamil: `பாடல் #470 பாடலின் படி ஈசனுடன் பேரின்பத்தில் கலந்து திளைத்து இருந்த போது ஈசன் அருளியவற்றை கேட்டு வியந்து நின்றேன். அது என்னவென்றால் எங்கும் கலந்திருக்கும் ஒரு மாசும் இல்லாத மாபெரும் சுடராக இருக்கும் இறைவனே வினைகளின் பொருட்டு உயிர்களைப் பிறக்க வைக்க முழுமுதல் காரணமாக இருக்கின்றான் என்பதையும் உயிர்கள் அவர்களின் வினைகளை அனுபவிக்க வேண்டிய மாயையாகவும் அவனே இருக்கின்றான் என்பதையும் சுக்கிலத்தை சுரோனிதத்தையும் சேர்த்து கர்ப்பப் பைக்குள் கொண்டு சென்று கருவாக்கி அதை குழந்தையின் உருவமாக அதை நீட்டிக் காப்பாற்றி அது பிறந்தபின் அதனுடன் உள் ஒளியாகக் கலந்து மாயையால் மறைந்து நின்று அந்த குழந்தை வாழும் காலம் வரை அதை உள்ளிருந்தே வழி நடத்துகின்றான் என்பதையும் கேட்டு உணர்ந்தேன்.`,
  },
  {
    id: 473, tantraId: 2, verseNumber: 472,
    tamil: `பூவுடன் மொட்டுப் பொருந்த அலர்ந்தபின்
காவுடைத் தீபங் கலந்து பிறந்திடும்
நீரிடை நின்ற குமிழி நிழலதாய்ப்
பாருடல் எங்கும் பரந்தெட்டும் பற்றுமே`,
    transliteration: `pūvuṭaṉ moṭṭup porunta alarntapiṉ
kāvuṭait tīpaṅ kalantu piṟantiṭum
nīriṭai niṉṟa kumiḻi niḻalatāyp
pāruṭal eṅkum paranteṭṭum paṟṟumē`,
    english: `472: Body's Impermanence
In the union of sexes opposite
The light of life is born shielded true;
A bubble it is in Life's watery expanse;
A shadow that spreads on earth below;
Sheathed in the subtle Body-Eight.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-472-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `The individual life is but a bubble in the Primal Life’s infinite expanse. It is but a shadow of the Divine Light encased in the subtle body that is made of the five protean senses (tanmatras), and the three internal instruments: mind, will and intelligence.`,
    elaborationTamil: `பூவிதழ் போன்ற யோனியில் நுழைந்த மொட்டு போன்ற இலிங்கத்தின் நுனியிலிருந்து வெளிவந்த சுக்கிலம் சென்று கர்ப்பப் பையின் வாசலில் இருக்கும் கருமுட்டையுடன் கலந்தபின் கருமுட்டை கர்ப்பப் பைக்குள் சென்று விரியும். அப்போது விரிந்த முட்டையிலிருந்து வெளிவந்த நீர்க் குழம்பில் ஒளி வடிவான இறைவனின் அம்சமும் ஜென்ம சுமைகளைச் சுமந்த ஆன்மாவும் சேர்ந்து கலந்து பிறவி எடுக்கும். ஆண் பெண்ணின் உயிர் அணுக்கள் சேர்ந்து ஆண் பெண்ணின் சாயலிலேயே உலகத்தில் பிறக்கும் உடம்பாக மாறிவிடும். அந்த உடம்பு முழுவதும் இறைவனின் அம்சம் பரவி எட்டுவிதமான காரணிகள் பற்றிக்கொள்ளும். உடலின் எட்டுவித காரணிகள்: உடல். 2. வாய். 3. கண். 4. மூக்கு. 5. காது. 6. மனம். 7. புத்தி. 8. அகங்காரம்.`,
  },
  {
    id: 474, tantraId: 2, verseNumber: 473,
    tamil: `எட்டினுள் ஐந்தாகும் இந்திரி யங்களும்
கட்டிய மூன்று கரணமு மாய்விடும்
ஒட்டிய பாச உணர்வென்னுங் காயப்பை
கட்டி அவிழ்த்திடுங் கண்ணுதல் காணுமே`,
    transliteration: `eṭṭiṉuḷ aintākum intiri yaṅkaḷum
kaṭṭiya mūṉṟu karaṇamu māyviṭum
oṭṭiya pāca uṇarveṉṉuṅ kāyappai
kaṭṭi aviḻttiṭuṅ kaṇṇutal kāṇumē`,
    english: `473: Lord Gives and Lord Takes Life
Of the eight organs of Body Subtle,
Are senses protean five
And cognitive instruments three--
Mind, will and cognition;
Know the dear Lord
Who fastened this body-bag,
With Desire's sticky glue
Will in time unfasten it too.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-473-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `பாடல் #472 ல் உள்ளபடி குழந்தையின் உடலெங்கும் பரவி ஒட்டிக்கொள்ளும் அந்த எட்டுவித சூட்சும காரணிகளாக இருப்பவை ஐந்து ஞானேந்திரியங்களும் மூன்று அந்தக் கரணங்களும் ஆகும். இவற்றோடு குழந்தையை ஒட்டியே பிறப்பது வினைப் பயனால் பெற்ற பந்தம் பாசம் எனும் உணர்வுகள். இப்படி எல்லாம் கலந்து உருவாகிய பை போன்ற உடலை வினையின் படி கட்டி வைத்து உருவாக்குவதும் பிறவி முடிவில் அவிழ்த்து அழிப்பதும் நெற்றிக் கண்ணையுடைய சிவபெருமானே.`,
  },
  {
    id: 475, tantraId: 2, verseNumber: 474,
    tamil: `கண்ணுதல் நாமங் கலந்துடம் பாயிடைப்
பண்ணுதல் செய்து பசுபாசம் நீங்கிட
எண்ணிய வேதம் இசைந்த பரப்பினை
மண்முத லாக வகுத்துவைத் தானே`,
    transliteration: `kaṇṇutal nāmaṅ kalantuṭam pāyiṭaip
paṇṇutal ceytu pacupācam nīṅkiṭa
eṇṇiya vētam icainta parappiṉai
maṇmuta lāka vakuttuvait tāṉē`,
    english: `474: Lord Gave Means of Redemption
The Lord made the body,
A name and form it assumed;
Then, for Jiva his redemption to seek
He created earth and Tattvas many,
--Thus speak the Vedas.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-474-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `ஆன்மா பிறவி எடுப்பதற்காக நெற்றிக் கண்ணையுடைய சிவனின் திருநாமமாகிய ஐந்தெழுத்தும் (நமசிவாய) பிரணவமும் (ஓம்) கலந்து வினைப்படி பந்த பாச மாயையை வைத்து ஆன்மாவை சேர்த்து உடம்பாக செய்த இறைவனே அந்த ஆன்மா தனது பந்த பாச மாயையை நீக்கி இறைவனிடம் வந்து சேருவதற்கான வழிமுறைகளை வேதங்களாக கொடுத்து அருளினான். அந்த வேதங்களின் பொருளை புரிந்து உணர்ந்து கொள்ள கருவினுள் முப்பத்தாறு தத்துவங்களையும் (பாடல் #467 இல் காண்க) வகை பிரித்து வைத்து அருளினான். உட்கருத்து: ஆன்மாவிற்கு ஆசையை தீர்த்துக்கொள்ள பிறவி கொடுத்து அதற்கேற்ற வினையையும் மாயையையும் கொடுத்த இறைவனே அதிலிருந்து விடுபட்டு பிறவிச் சுழலில் இருந்து தப்பிக்க வழிமுறையான வேதங்களையும் கொடுத்து அதன் பொருளைப் புரிந்து கொள்ள முப்பத்தாறு தத்துவங்களையும் குழந்தைக்கு கொடுத்து அருளுகின்றான்.`,
  },
  {
    id: 476, tantraId: 2, verseNumber: 475,
    tamil: `அருளல்ல தில்லை அரனவன் அன்றி
அருளில்லை யாதலி னவ்வோர் உயிரைத்
தருகின்ற போதிரு கைத்தாயர் தம்பால்
வருகின்ற நண்பு வகுத்திடுந் தானே`,
    transliteration: `aruḷalla tillai araṉavaṉ aṉṟi
aruḷillai yātali ṉavvōr uyirait
tarukiṉṟa pōtiru kaittāyar tampāl
varukiṉṟa naṇpu vakuttiṭun tāṉē`,
    english: `475: He Placed Jiva in Care of Two Foster-Mothers
None the Grace but Hara's,
None Hara's but the Grace,
And so as He bestows life,
He bestows, too,
The Loving care of foster mother twine,
(Maya and Mamaya.)`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-475-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `அருளைத் தருகின்ற சக்தியில்லாமல் சிவம் இல்லை. அசையா சக்தியாகிய சிவம் இல்லாமல் அருளுகின்ற சக்தியும் இல்லை. உயிர்களுக்கு உடலைத் தருகின்ற போதே சிவத்தையும் சக்தியையும் இரண்டு வளர்ப்புத் தாய்களாக கூடவே வந்து விடுகின்றான் இறைவன். சிவமும் அன்பும் வேறு வேறு இல்லை வளர்ப்புத் தாய்களாக வந்த சிவமும் சக்தியும் அன்போடு கருவை வளர்த்து பாதுகாத்து அதைப் பிறக்க வைக்கின்றார்கள்.`,
  },
  {
    id: 477, tantraId: 2, verseNumber: 476,
    tamil: `வகுத்த பிறவியை மாதுநல் லாளுந்
தொகுத்திருள் நீக்கிய சோதி யவனும்
பகுத்துணர் வாக்கிய பல்லுயிர் எல்லாம்
வகுத்துள்ளும் நின்றதோர் மாண்பது வாமே`,
    transliteration: `vakutta piṟaviyai mātunal lāḷun
tokuttiruḷ nīkkiya cōti yavaṉum
pakuttuṇar vākkiya palluyir ellām
vakuttuḷḷum niṉṟatōr māṇpatu vāmē`,
    english: `476: Then Siva and Sakti Pervaded Jivas
Sakti, the Conjoint Cause of creation,
The Luminous One that dispelled darkness total,
Together created the myriad lives,
Their genus and species,
And having done that, they pervaded them too;
Oh! magnificience non-pareil!`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-476-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `வினைப் பயனால் எடுக்கும் பிறவி எத்தகையது என்பதை முடிவு செய்து அதன்படி உயிர்களை படைக்கின்றது ஒலி வடிவமான சக்தி. வினைகளைக் கழிக்கும் உயிர்களுக்கு மாயையாகிய இருளை அகற்றி அருளுகின்றது ஒளி வடிவான சிவம். இவர்கள் இருவரும் இணைந்தே உயிர்களை ஓர் அறிவு ஜீவியிலிருந்து ஆறு அறிவு மனிதன் வரை வகை வகையாகப் பிரித்து அவர்களின் வினைகளுக்கு ஏற்ற வகையில் படைத்து அருளுகின்றார்கள். படைப்பதோடு மட்டும் நின்றுவிடாமல் அந்த உயிர்களுக்குள்ளேயும் உயிரோடு உணர்வாகக் கலந்து நிற்பதே சிவ சக்தியின் கருணையாகும்.`,
  },
  {
    id: 478, tantraId: 2, verseNumber: 477,
    tamil: `மாண்பது வாக வளர்கின்ற வன்னியுங்
காண்பது ஆண்பெண் அலியெனுங் கற்பனை
பூண்பது மாதா பிதாவழி போலவே
ஆம்பதி செய்தானச் சோதிதன் ஆண்மையே`,
    transliteration: `māṇpatu vāka vaḷarkiṉṟa vaṉṉiyuṅ
kāṇpatu āṇpeṇ aliyeṉuṅ kaṟpaṉai
pūṇpatu mātā pitāvaḻi pōlavē
āmpati ceytāṉac cōtitaṉ āṇmaiyē`,
    english: `477: He Printed the Sex of the Infant
The seed of life,
As a steady flame in womb burns
It takes shape one of three
Male, female and hermaphrodite;
How the father and mother at union were,
Even so He printed the sex,
Righteous indeed was that Lumninous One.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-477-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `இறைவனது கருணையினால் தாயின் வயிற்றில் வளர்கின்ற ஜோதி வடிவமான ஆன்மாவை ஆணாகவும் பெண்ணாகவும் அலியாகவும் பார்ப்பது மாயையாகும். அப்படியெல்லாம் உருவைக் கொடுப்பது அந்தக் குழந்தையின் தாய் தந்தையரின் வழிமுறைகளால் தானே தவிர ஆன்மாவிற்கு என்று ஒரு உருவமும் கிடையாது. தந்தை தாயின் வழியாகவே அவர்களின் சாயலில் கருவைப் பதித்து அதை ஆண் பெண் அலி என்ற உருவமாகச் செய்வது இறைவனின் வல்லமையே ஆகும்.`,
  },
  {
    id: 479, tantraId: 2, verseNumber: 478,
    tamil: `ஆண்மிகில் ஆணாகும் பெண்மிகிற் பெண்ணாகும்
பூணிரண் டொத்துப் பொருந்தில் அலியாகும்
தாண்மிகு மாகில் தரணி முழுதாளும்
பாணவ மிக்கிடில் பாய்ந்ததும் இல்லையே`,
    transliteration: `āṇmikil āṇākum peṇmikiṟ peṇṇākum
pūṇiraṇ ṭottup poruntil aliyākum
tāṇmiku mākil taraṇi muḻutāḷum
pāṇava mikkiṭil pāyntatum illaiyē`,
    english: `478: Sex Determined at Sexual Union
The masculine flow dominates, the infant is male born,
The feminine dominates, the infant is female born;
When the two are in force equal, a hermaphrodite is born;
When masculine flow gushes in plenty,
The infant born will sway the world entire;
When masculine flow is scanty,
Naught indeed conception is.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-478-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆண் பெண் இன்பத்தின் முடிவில் கலக்கும் நீரில் ஆணின் சுக்கிலம் பெண்ணின் சுரோணிதத்தை விட அதிகமாக இருந்தால் பிறப்பது ஆண் குழந்தையாக இருக்கும். அப்படி இல்லாமல் ஆணின் சுக்கிலத்தை விட பெண்ணின் சுரோணிதம் அதிகமாக இருந்தால் பிறப்பது பெண் குழந்தையாக இருக்கும். அப்படியும் இல்லாமல் ஆணின் சுக்கிலமும் பெண்ணின் சுரோணிதமும் சமமாக இருந்தால் பிறப்பது அலியாக இருக்கும். இதில் ஆணின் சுக்கிலத்தில் உயிரணுவின் சக்தி மிகவும் அதிகமாக இருந்தால் பிறக்கின்ற குழந்தை உலகத்தையே ஆளுகின்ற அரசன் போல சீரும் சிறப்பும் மிகுந்ததாக இருக்கும். பெண்ணின் சுரோணிதத்தின் உயிரணு அழிப்பு சக்தி மிகவும் அதிகமாக இருந்தால் சுக்கிலம் பாய்ந்தும் ஒரு பயனும் இல்லாமல் கரு உருவாகாமல் போய்விடும்.`,
  },
  {
    id: 480, tantraId: 2, verseNumber: 479,
    tamil: `பாய்ந்தபின் னஞ்சோடில் ஆயுளும் நூறாகும்
பாய்ந்தபின் நாலோடில் பாரினில் எண்பதாம்
பாய்ந்திடும் வாயுப் பகுத்தறிந் திவ்வகை
பாய்ந்திடும் யோகிக்குப் பாய்ச்சலு மாமே`,
    transliteration: `pāyntapiṉ ṉañcōṭil āyuḷum nūṟākum
pāyntapiṉ nālōṭil pāriṉil eṇpatām
pāyntiṭum vāyup pakuttaṟin tivvakai
pāyntiṭum yōkikkup pāyccalu māmē`,
    english: `479: Age is Determined
If after emission,
The male's breath five finger-length extends,
The infant born lives a hundred years;
When breath to four finger measure stretches,
To age eighty the infant lives;
The Yogi who knows the science of breath control
If in sex act He indulges,
He, the vital flow, accordingly regulates.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-479-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `If afier ejaculation, man inhales spontaneously five times, the infant to be born will live upto 100 years; eighty, if he inhales four times and so on. Only yogis who have mastered the science of breath can control and regulate the discharge at will.`,
    elaborationTamil: `ஆண் பெண் இன்பத்தின் முடிவில் ஆணிடமிருந்து சுக்கிலம் வெளிவந்து பெண்ணின் யோனியில் பாய்ந்த பிறகு ஆண் விடும் மூச்சுக்காற்றின் அளவு ஐந்து வினாடிகள் அளவிற்கு வெளிவந்தால் பிறக்கும் குழந்தை நூறு ஆண்டுகள் ஆயுளோடு பிறக்கும். ஆண் விடும் மூச்சுக்காற்றின் அளவு நான்கு வினாடிகள் அளவிற்கு வெளிவந்தால் பிறக்கும் குழந்தை எண்பது ஆண்டுகள் ஆயுளோடு பிறக்கும். எந்த அளவு மூச்சுக்காற்று வெளிவருகின்றது என்பதை பிரித்துப் பார்த்து அறிந்து கொண்டு தமக்கு வேண்டிய அளவிற்கு வெளிவரும் படி செய்வது யோக சாதனைகளைப் புரிந்து சாதனைகள் கைவரப்பெற்ற யோகியர்களுக்கே முடியும் என்பதால் அவர்களுக்கு ஆயுள் அளவு கிடையாது. குறிப்பு :மூச்சுக்காற்றைத் தம் வசம் பழக்கி அளவு அறிந்து இழுத்து அளவு அறிந்து வெளிவிடும் ஆற்றலைப் பெற்றவர்கள் யோகியர்கள். அவர்களால் தாம் வெளிவிடும் மூச்சுக்காற்றின் நேர அளவைக் கூட்டி தங்களது ஆயுளை எவ்வளவு வேண்டுமானாலும் நீட்டிக்க முடியும்.`,
  },
  {
    id: 481, tantraId: 2, verseNumber: 480,
    tamil: `பாய்கின்ற வாயுக் குறையிற் குறளாகும்
பாய்கின்ற வாயு விளைக்கின் முடமாகும்
பாய்கின்ற வாயு நடுப்படிற் கூனாகும்
பாய்கின்ற வாயுமா தர்க்கில்லை பார்க்கிலே`,
    transliteration: `pāykiṉṟa vāyuk kuṟaiyiṟ kuṟaḷākum
pāykiṉṟa vāyu viḷaikkiṉ muṭamākum
pāykiṉṟa vāyu naṭuppaṭiṟ kūṉākum
pāykiṉṟa vāyumā tarkkillai pārkkilē`,
    english: `480: Birth Imperfections Explained
When after intercourse, the man is short of breath,
The infant born a dwarf will be;
When breath spires feeble,
The issue may, of defective limbs be born;
When breath halts in mid-act
A hunch-back will be born;
All these apply not,
To woman's breathing rhythm.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-480-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `If the flow of the male discharge is slow, the offspring is short in stature; if sluggish, lame; if fitful and interrupted, hunchback.`,
    elaborationTamil: `ஆண் பெண் இன்பத்தின் முடிவில் ஆணிடமிருந்து சுக்கிலம் வெளிவந்து பெண்ணின் யோனியில் பாய்ந்த பிறகு ஆண் விடும் மூச்சுக்காற்றின் அளவு நான்கு வினாடிக்கும் குறைவான அளவு வெளிவந்தால் பிறக்கும் குழந்தை குட்டையாகப் பிறக்கும். ஆணின் மூச்சுக்காற்று மெலிந்து வெளிவந்தால் பிறக்கும் குழந்தை முடமாகப் பிறக்கும். ஆணின் மூச்சுக்காற்று சீராக வராமல் தடை பட்டு தடை பட்டு வந்தால் பிறக்கும் குழந்தை கூனுடன் பிறக்கும். இப்படி வெளிவருகின்ற மூச்சுக்காற்றின் அளவைக் கணக்கிடும் முறை ஆண்களுக்குத் தானே தவிர பெண்கள் விடும் மூச்சுக் காற்றின் அளவு கணக்கில் எடுத்துக் கொள்ளப் படுவதில்லை. குறிப்பு ஆணின் மூச்சுக்காற்று சுக்கிலத்திலிருந்து உயிரணுக்களைத் தருகின்றது. பெண்ணின் மூச்சுக்காற்று சுரோணிதத்திலிருந்து அழிக்கும் சக்தியைத் தருகின்றது (பாடல் #478 இல் இதற்கான விளக்கம் காண்க). உயிரின் ஆயுள் காலம் ஆணின் மூச்சுக்காற்றின் அளவிலிருந்து மட்டுமே நிர்ணயிக்கப்படுகின்றது.`,
  },
  {
    id: 482, tantraId: 2, verseNumber: 481,
    tamil: `மாதா உதரம் மலமிகில் மந்தனாம்
மாதா உதரம் சலமிகில் மூங்கையாம்
மாதா உதரம் இரண்டொக்கில் கண்ணில்லை
மாதா உதரத்தில் வந்த குழவிக்கே.`,
    transliteration: `mātā utaram malamikil mantaṉām
mātā utaram calamikil mūṅkaiyām
mātā utaram iraṇṭokkil kaṇṇillai
mātā utarattil vanta kuḻavikkē.`,
    english: `481: How Deaf, Dumb, and Blind are Born
When at the time of union,
The mother's bowels are heavy exceeding,
A dullard will be born;
If urine exceeds,
A dumb will be born;
If both exceed,
A blind will be born;
Thus is it for the infant born
The mother's condition according.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-481-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆண் பெண் இன்பத்தின் முடிவில் சுக்கிலம் கருமுட்டையுடன் சேரும் போது தாயாகப் போகின்ற பெண்ணின் வயிற்றில் மலக்கழிவு அதிகமாக இருந்தால் பிறக்கும் குழந்தை மந்த புத்தியுடன் பிறக்கும். அவள் வயிற்றில் சிறுநீர் அதிகமாக இருந்தால் பிறக்கும் குழந்தை ஊமையாகப் பிறக்கும். மலக்கழிவும் சிறுநீரும் சமமான அளவு இருந்தால் பிறக்கும் குழந்தை குருடாகப் பிறக்கும். உடலுறவின் போது பெண்கள் தங்களின் வயிற்றில் மலக்கழிவோ சிறுநீரோ அதிகமாக இல்லாமல் பார்த்துக் கொள்வது ஆரோக்கியமான குழந்தைக்கு வழிவகுக்கும்.`,
  },
  {
    id: 483, tantraId: 2, verseNumber: 482,
    tamil: `குழவியும் ஆணாம் வலத்தது வாகில்
குழவியும் பெண்ணாம் இடத்தது வாகில்
குழவியும் இரண்டாம் அபான னெதிர்க்கில்
குழவி அலியாகுங் கொண்டகால் ஒக்கிலே`,
    transliteration: `kuḻaviyum āṇām valattatu vākil
kuḻaviyum peṇṇām iṭattatu vākil
kuḻaviyum iraṇṭām apāṉa ṉetirkkil
kuḻavi aliyākuṅ koṇṭakāl okkilē`,
    english: `482: Breathing at Union Decides Sex of Baby
If breath spires leading on nostril right,
The infant born will a male be;
If on the nostril left,
A female will be born;
If the descending current Apana,
Opposes the ascending current Prana,
Twins there shall be;
If in measure equal the breath rhythm runs,
Through nostrils right and left,
Hermaphrodite shall be the baby born.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-482-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `If the male breath runs dominant in the right nostril (Pingala) at the time of discharge, the offspring will be male; if it Tuns dominant in the left nostril {ida), the offspring will be female. If the apana breath comes up from the lower regions of the body twins will be born. If the breathing is through both the nostrils, the child born will be impotent.`,
    elaborationTamil: `ஆண் பெண் இன்பத்தின் போது ஆணின் மூச்சுக்காற்று வலது புற நாசியான சூரியகலையின் வழியே சென்றால் பிறக்கும் குழந்தை ஆணாகப் பிறக்கும். ஆணின் மூச்சுக்காற்று இடது புற நாசியான சந்திரகலையின் வழியே சென்றால் பிறக்கும் குழந்தை பெண்ணாகப் பிறக்கும். ஆணின் மூச்சுக்காற்று இரண்டு நாசிகளின் வழியாகவும் ஒன்றாக சென்றால் பிறக்கும் குழந்தை அலியாகப் பிறக்கும். உடலுறவின் போது பெண்ணின் மூச்சுக்காற்றை எதிர்த்துக் கொண்டு மலக்காற்று வந்தால் பிறக்கும் குழந்தை இரட்டைக் குழந்தைகளாகப் பிறக்கும். குறிப்பு: அபானன் என்பது மனித உடலின் வயிற்றிலிருந்து கீழ் நோக்கிப் பாயும் ஒரு வாயு. இது மலக்காற்று என்று அறியப்படுகின்றது.`,
  },
  {
    id: 484, tantraId: 2, verseNumber: 483,
    tamil: `கொண்டநல் வாயு இருவர்க்கும் ஒத்தெழில்
கொண்ட குழவியுங் கோமள மாயிடுங்
கொண்டநல் வாயு இருவர்க்குங் குழறிடில்
கொண்டதும் இல்லையாங் கோள்வளை யாட்கே`,
    transliteration: `koṇṭanal vāyu iruvarkkum otteḻil
koṇṭa kuḻaviyuṅ kōmaḷa māyiṭuṅ
koṇṭanal vāyu iruvarkkuṅ kuḻaṟiṭil
koṇṭatum illaiyāṅ kōḷvaḷai yāṭkē`,
    english: `483: How a Handsome Baby is Born
If in Male and Female breath runs
In measure equable,
The infant born will exceeding handsome be;
When in both breath rhythm falters,
No Conception will there be.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-483-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆண் பெண் இன்பத்தின் போது உடலுக்கு நன்மை தரும் மூச்சுக் காற்றை இருவரும் சீராக இழுத்து விட்டால் பிறக்கும் குழந்தை மிகவும் அழகாகப் பிறக்கும். இருவருக்கும் மூச்சுக் காற்று தடுமாறி சீரில்லாமல் ஓடினால் பெண்ணின் வயிற்றில் கருத்தரித்தாலும் அது குழந்தையாக மாறாமல் சிதைந்து போய்விடும்.`,
  },
  {
    id: 485, tantraId: 2, verseNumber: 484,
    tamil: `கோள்வளை உந்தியிற் கொண்ட குழவியுந்
தால்வளை யுள்ளே தயங்கிய சோதியாம்
பால்வளர்ந் துள்ளே பகலவன் பொன்னுருப்
போல்வளர்ந் துள்ளே பொருந்துரு வாமே`,
    transliteration: `kōḷvaḷai untiyiṟ koṇṭa kuḻaviyun
tālvaḷai yuḷḷē tayaṅkiya cōtiyām
pālvaḷarn tuḷḷē pakalavaṉ poṉṉurup
pōlvaḷarn tuḷḷē porunturu vāmē`,
    english: `484: How Infant in the Womb Grows
The infant-seed,
The damsel in her womb bore
Nourished by bright milk
That is fed by Sakti in Eye-brow Centre
Grew,
Beaming like the golden rays of rising sun
Inside, it took form appropriate.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-484-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆண் பெண் இன்பத்தின் முடிவில் பெண்ணின் வயிற்றில் தங்கிய கருவானது மனித உடலின் உள் நாக்கிற்கு மேலே இருக்கும் சுழு முனை நாடித் துளை வழியே தரிசிக்கும் ஜோதி வடிவான இறைவனின் அம்சமாகும். அந்தக் கரு குழந்தையாக மாறும் போது சூரியனைப் போன்ற தகதகக்கும் தங்க நிறத்தில் இருக்கும். பிறகு அதுவே உடலின் பல்வேறு உறுப்புகளாக வளரும் போது தந்தை தாயின் உருவத்திற்கு ஏற்ற மாதிரி குழந்தையின் உருவமும் பொருத்தமாக வளரும். உட்கருத்து: உடலின் ஆறு ஆதாரச் சக்கரங்களும் நடுவில் இருக்கும் சுழுமுனை நாடியின் வழியில்தான் இருக்கின்றன. அதன் வழியே குண்டலினி சக்தியை மேலே ஏற்றினால் அது ஏழாவது இடமான தலை உச்சியில் இருக்கும் சகஸ்ரர தளத்தைச் சென்று சேர்ந்து அங்கே ஒளி வடிவமாக வீற்றிருக்கும் இறைவனோடு கலந்து பிறகு அங்கிருந்து கீழே வந்து உள் நாக்கிற்கு மேலே இருக்கும் துளை வழியே அமிர்தமாகப் பொழிந்தால் பிறவி இல்லாத பெரும் வாழ்வு கிடைக்கும். இந்தத் துளை வழியே இறைவனை ஜோதி வடிவாக தரிசிக்க முடியும். அங்கே ஜோதியாக வீற்றிருக்கும் இறைவனின் அம்சம்தான் தந்தையின் உடலிலிருந்து குழந்தையின் உயிராகத் தாயின் வயிற்றில் சென்று சேருகின்றது. பெண்ணின் வயிற்றில் தங்கிய கரு குழந்தையாக மாறும் போது சூரியனைப் போன்ற நிறத்திலும் பிறகு எல்லா உறுப்புகளும் உருவாகும் போது தந்தை தாயின் சாயலிலேயே உருவாகும்.`,
  },
  {
    id: 486, tantraId: 2, verseNumber: 485,
    tamil: `உருவம் வளர்ந்திடும் ஒண்டிங்கள் பத்திற்
பருவம தாகவே பாரினில் வந்திடும்
மருவி வளர்ந்திடு மாயையி னாலே
அருவம தாவதிங் காரறி வாரே`,
    transliteration: `uruvam vaḷarntiṭum oṇṭiṅkaḷ pattiṟ
paruvama tākavē pāriṉil vantiṭum
maruvi vaḷarntiṭu māyaiyi ṉālē
aruvama tāvatiṅ kāraṟi vārē`,
    english: `485: Maya Fosters the Baby
In months ten, it forms full
And then on earth in time appointed, it lands;
And grows, Maya fostering;
But who knows that Formless Maya!`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-485-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `குழந்தையின் உருவம் பத்து மாதங்களாகத் தாயின் கர்ப்பப் பைக்குள் கருவாக வளர்ந்து பூமியில் குழந்தையாக பிறந்து இளைஞன் முதியவன் ஆகிய பலவித பருவங்களாக வளர்ந்தாலும் தனக்குள் இருக்கும் இறைவனையும் தான் யார் என்பதையும் மாயையினால் அறியாமலேயே வளரும். எப்பொழுது அந்த உயிர் இறக்கின்றதோ அப்போது அதனின் உடலை விட்டு சூட்சுமமான ஆன்மாவாகத் திரும்பி போய்விடுவதை உலகத்தவர்கள் எவரும் அறிய மாட்டார்கள். மாயையினால் கட்டுண்டு இருக்கும் உலகத்தவர்கள் உயிர் ஆன்மாவாக இருப்பதையோ ஆன்மா இறைவனின் அம்சமாக இருப்பதையோ என்றும் அறியாமலேயே பிறந்து வாழ்ந்து இறந்து போகின்றனர்.`,
  },
  {
    id: 487, tantraId: 2, verseNumber: 486,
    tamil: `இட்டான் அறிந்திலன் ஏற்றவள் கண்டிலள்
தட்டான் அறிந்தும் ஒருவர்க் குரைத்திலன்
பட்டாங்கு சொல்லும் பரமனும் அங்குளன்
கெட்டேன் இம்மாயையின் கீழ்மையெவ் வாறே`,
    transliteration: `iṭṭāṉ aṟintilaṉ ēṟṟavaḷ kaṇṭilaḷ
taṭṭāṉ aṟintum oruvark kuraittilaṉ
paṭṭāṅku collum paramaṉum aṅkuḷaṉ
keṭṭēṉ immāyaiyiṉ kīḻmaiyev vāṟē`,
    english: `486: Maya's Hidden Act
He who planted seed, knew it not;
She who received saw it not;
The Creator knew, but he told none;
The Lord who Truth reveals is also there;
Yet I saw not Maya,
How cunning was her stealthy Conduct!`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-486-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `சுக்கிலத்தை இட்ட ஆண்களும் அது கருவாகியதா என்பதை அறிந்திருக்க மாட்டார்கள். அந்த சுக்கிலத்தை ஏற்றுக் கொண்ட பெண்களும் அது கருவாகியதா என்பதை அறிந்திருக்க மாட்டார்கள். தங்கத்தை நகையாகச் செய்யும் தச்சன் போல ஆன்மாவை வினைப்படி உயிராகச் செய்யும் பிரம்மன் இதை அறிந்திருந்தாலும் அதை யாருக்கும் அவன் சொன்னதில்லை. அனைத்தும் அறிந்த இறைவனும் உயிர்களிடம் கலந்து இருந்தாலும் அவனும் யாருக்கும் ஒன்றும் சொல்வதில்லை. இதையெல்லாம் உயிர்கள் அறியாதது அவர்களின் மாயையினால் தான். இறைவனின் அருளால் யான் இறைவனை எனக்குள்ளேயே கண்டு உணர்ந்துவிட்டதால் அந்த மாயையை அழித்து இதை அறிந்து கொண்டேன். உட்கருத்து: மாயையினால் உயிர்கள் எதையும் அறியாமல் இருக்கின்றார்கள். உண்மையை அறிந்த பிரம்மனும் இறைவனும் உயிர்களுக்கு தாமாகவே எதையும் சொல்லுவதில்லை. இறைவனை அறிந்து தமக்குள்ளேயே உயிர்கள் உணர்ந்து விட்டால் மாயை அழித்து உண்மையை உள்ளபடியே அறிந்து கொள்ளலாம். (இதை எவ்வாறு செய்வது என்பதை அடுத்த பாடல் #487 இல் விளக்குகின்றார்)`,
  },
  {
    id: 488, tantraId: 2, verseNumber: 487,
    tamil: `இன்புற நாடி இருவருஞ் சந்தித்துத்
துன்புறு பாசத்தில் தோன்றி வளர்ந்தபின்
முன்புற நாடி நிலத்தின்முன் தோன்றிய
தொன்புற நாடிநின் றோதலு மாமே`,
    transliteration: `iṉpuṟa nāṭi iruvaruñ cantittut
tuṉpuṟu pācattil tōṉṟi vaḷarntapiṉ
muṉpuṟa nāṭi nilattiṉmuṉ tōṉṟiya
toṉpuṟa nāṭiniṉ ṟōtalu māmē`,
    english: `487: In Manhood Jiva Seeks God
Seeking pleasure, the two met;
In pasa's misery was it born and bred;
And having grown to stature
Grew to manhood here below;
Well may it seek the Ancient One
That before all worlds was.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-487-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஆண் பெண் இருவரும் சந்தித்து இன்பத்தில் உறவாடுகின்றார்கள். அவர்களின் உறவினால் துன்பத்தையே கொடுக்கும் பந்த பாசம் எனும் மாயையால் கட்டப்பட்ட கரு உருவாகி குழந்தையாக பிறந்து உயிராக வளர்கிறது. வளரும் அந்த உயிர் மாயையிலிருந்து விடுபட வேண்டும் என்று எண்ணினால் தன்னை உயிராகப் பிறக்க வைத்த இறைவன் ஒருவன் ஆதி காலத்திலிருந்தே எப்போதும் இருக்கின்றான் என்பதை உணர்ந்து அவனைத் தேடி அடைய ஆசைப்பட்டு அவனின் திருநாமத்தை (ஓம் நமசிவாய) மந்திரமாக ஓதி தியானத்தில் இருந்து அவனைத் தமக்குள்ளே அறிந்து மாயையிலிருந்து விடுபடலாம். குறிப்பு: உயிர்கள் தங்களுக்கு பிடித்த தனது இஷ்ட தெய்வத்தின் நாமத்தையும் மந்திரமாக ஓதி தியானத்தில் இருந்து அவனைத் தமக்குள்ளே அறிந்து மாயையிலிருந்து விடுபடலாம்.`,
  },
  {
    id: 489, tantraId: 2, verseNumber: 488,
    tamil: `குயிற்குஞ்சு முட்டையைக் காக்கைக் கூட்டிட்டால்
அயிர்ப்பின்றிக் காக்கை வளர்க்கின் றதுபோல்
இயக்கில்லை போக்கில்லை ஏனென்ப தில்லை
மயக்கத்தால் காக்கை வளர்க்கின்ற வாறே`,
    transliteration: `kuyiṟkuñcu muṭṭaiyaik kākkaik kūṭṭiṭṭāl
ayirppiṉṟik kākkai vaḷarkkiṉ ṟatupōl
iyakkillai pōkkillai ēṉeṉpa tillai
mayakkattāl kākkai vaḷarkkiṉṟa vāṟē`,
    english: `488: How Maya Fosters Babe
The koil bird leaves its egg in the crow's nest;
The crow hatches it, nurses it, suspecting nothing;
It does not move it, does not reject it,
Does not ask why,
So does Maya the young one foster.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-488-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `And maya taking charge, fosters the egg that lay in the womb. Even as the cuckoo leaves its egg in the crow’s nest, for the crow to hatch and foster, so does maya perform this act in the womb.`,
    elaborationTamil: `குயில் தனது முட்டையை காக்கையின் கூட்டில் கொண்டு போய் போட்டுவிட்டு வந்துவிடும். காக்கைக்கு குயிலின் முட்டைக்கும் தன்னுடைய முட்டைக்கும் வித்தியாசம் தெரியாததால் அதைத் தனது குஞ்சு என்றே நினைத்துக் கொண்டு எந்தவித சந்தேகமும் இல்லாமல் அடை காத்துப் பொரித்து பிறந்து அது கூவும் வரை குயிலின் குஞ்சு என்பதை அறியாமல் வளர்க்கும். அதுபோலவே இறைவன் தாயின் கருவில் இட்ட உயிரை தாய் தனது குழந்தை என்றே எண்ணிக் கொண்டு எந்தவித சந்தேகமும் இல்லாமல் உடல் அதிர்ந்து வேலை செய்யாமல் கருவை அழிந்துவிடாமல் பாதுகாத்து அது ஏன் வந்தது எதற்கு வந்தது என்கிற எண்ணம் இல்லாமல் இறைவனின் உயிரை தனது சொந்த உயிர் என்று எண்ணி பந்தம் பாசம் என்கிற மாயையினால் நினைத்துக் கொண்டு தாய் வளர்க்கிறாள். உட்கருத்து: உலகத்தில் பிறக்கும் அனைத்து உயிர்களும் இறைவனின் அம்சமான ஆன்மாவாக இறைவனின் பிள்ளைகளாகவே பிறக்கின்றன. இதை மாயையால் அறியாத உயிர்கள் தான் பெற்ற குழந்தை என்று நினைத்துக் கொண்டு பந்த பாசத்தில் கிடந்து தவிக்கின்றார்கள்.`,
  },
  {
    id: 490, tantraId: 2, verseNumber: 489,
    tamil: `முதற்கிழங் காய்முளை யாயம் முளைப்பின்
அதற்புத லாய்ப்பல மாய்நின் றளிக்கும்
அதற்கது வாயின்ப மாவதுபோல
அதற்கது வாய்நிற்கும் ஆதிப் பிரானே`,
    transliteration: `mutaṟkiḻaṅ kāymuḷai yāyam muḷaippiṉ
ataṟputa lāyppala māyniṉ ṟaḷikkum
ataṟkatu vāyiṉpa māvatupōla
ataṟkatu vāyniṟkum ātip pirāṉē`,
    english: `489: God Protects Jiva at All Stages
The Lord is the Primal One;
The root, the shoot, the plant and fruit;
Thus He blesses all life;
To each, He grants his life's pleasure,
With each, He stands according.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-489-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `ஒரு விதை முதலில் முளைத்து செடியாய் வளர்ந்து பின்பு வேர் மண் மற்றும் நீருடன் வினைபுரிந்து தன்னைப்போலவே பலத்துடன் தன்னுடைய தன்மையுடன் பல செடிகளை புதர் போல் உருவாக்குகின்றது. ஒரு வகை செடி தனது வகை செடியை மட்டுமே உருவாக்கும் வேறு வகை செடியை உருவாக்காது. உலகத்தில் எத்தனை வகை தாவரங்கள் அதன் வகைகளை உருவாக்குகின்றதோ அத்தனை வகை தாவரங்களாகவும் ஆதியாய் இருக்கும் இறைவனே இருக்கின்றான். குறிப்பு: கர்ப்பக்கிரியை தலைப்பில் இதுவரை மனித உயிர்கள் எப்படி உருவாகின்றது என்று மட்டுமே சொல்லப்பட்டு இருந்தது. இந்த பாடலில் உலகில் உள்ள தாவரங்கள் உருவாக்கம் பற்றி அருளியிருக்கின்றார்.`,
  },
  {
    id: 491, tantraId: 2, verseNumber: 490,
    tamil: `ஏனோர் பெருமைய னாகிலும் எம்மிறை
ஊனே சிறுமையுள் உட்கலந் தங்குளன்
வானோர் அறியும் அளவல்லன் மாதேவன்
தானே அறியுந் தவத்தினி னுள்ளே`,
    transliteration: `ēṉōr perumaiya ṉākilum emmiṟai
ūṉē ciṟumaiyuḷ uṭkalan taṅkuḷaṉ
vāṉōr aṟiyum aḷavallaṉ mātēvaṉ
tāṉē aṟiyun tavattiṉi ṉuḷḷē`,
    english: `490: Lord Appears in Prayer and Penance
My Lord is of infinite greatness,
Yet is He within the littleness of this fleshly body;
Beyond the ken of Celestials is He;
Yet in prayer and penance
He himself shall appear before you.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-490-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationTamil: `அனைத்து தெய்வங்களையும் விட மாபெரும் பெருமையை உடைய எமது இறைவன் வினைகள் கர்மாக்கள் மலங்கள் கொண்ட குறைகள் நிறைந்த உயிர்களின் உடல்களிலும் கலந்து இருக்கின்றான். வானுலகத்திலுள்ள தேவர்களாலும் அறிய முடியாத அளவு இருக்கும் மகாதேவனாகிய அந்த இறைவனை உயிர்கள் தனக்குள் தவம் செய்து தமக்குள்ளேயே அறியலாம்.`,
  },
  {
    id: 492, tantraId: 2, verseNumber: 491,
    tamil: `பரத்திற் கரைந்து பதிந்தநற் காயம்
உருத்தரித் திவ்வுடல் ஓங்கிட வேண்டித்
திரைக்கடல் உப்புத் திரண்டது போலத்
திரித்துப் பிறக்குந் திருவரு ளாலே`,
    transliteration: `parattiṟ karaintu patintanaṟ kāyam
uruttarit tivvuṭal ōṅkiṭa vēṇṭit
tiraikkaṭal upput tiraṇṭatu pōlat
tirittup piṟakkun tiruvaru ḷālē`,
    english: `491: Birth is by Lord's Grace
Even unto the salt that from wavy sea emerges,
Out of Tattvas that arose in Para,
Was this body formed;
To be born thus is His Grace indeed!`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-491-Second-Tantra-14.-Act-of-Conception.mp3',
    elaborationEnglish: `The individual body is made of tattvas that arose in Parasakti, like salt that emerges from the vast sea.

Thus microcosmic creation, as much as macrocosmic creation, is the potent function of Siva/Sakti, is who pervades all creation.

And all this elaborate and minute work of. Siva/Sakti is. for what purpose? That the jiva may seek liberation from the primordial impurities and itself become pristine Siva, the Pure Spirit.

Mular considers birth, and hence, life itself, as a valuable gift.`,
    elaborationTamil: `இறைவனின் பரமான்மாவோடு கலந்திருந்த நல்ல ஆன்மா உலகில் உயிராகப் பிறந்து தனது ஆசைகளைத் தீர்த்துக் கொள்ள வேண்டும் என்று ஆசைப்பட்டு விட்டால் கடல் தண்ணீர் சூரியனின் வெப்பத்தினால் திரண்டு உப்புக் கட்டிகளாக மாறுவதுபோல இறைவனது திருவருளால் பேரான்மாவோடு கலந்திருக்கும் ஆன்மா உடல் பெற்று ஒரு உயிராகப் பிறவி எடுக்கின்றது.`,
  },
  {
    id: 493, tantraId: 2, verseNumber: 492,
    tamil: `சத்தி சிவன்விளை யாட்டால் உயிராக்கி
ஒத்த இருமாயா கூட்டத் திடைப்பூட்டிச்
சுத்தம தாகுந் துரியம் புரிவித்துச்
சித்தம் புகுந்து சிவமய மாக்குமே`,
    transliteration: `catti civaṉviḷai yāṭṭāl uyirākki
otta irumāyā kūṭṭat tiṭaippūṭṭic
cuttama tākun turiyam purivittuc
cittam pukuntu civamaya mākkumē`,
    english: `492: Play of Sakti-Siva Infuses Divine Spirit
Out of Sakti-Siva Play
Life blossomed;
And Jiva who was in pure Kevala state
Of Turiya quiescence
Was freed and consigned to the folds of Maya,
And the Lord then entered Jiva's thought
And suffused his being with Divine Spirit.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-492-Second-Tantra-15.-Three-Types-of-Souls.mp3',
    elaborationEnglish: `The condition of the Jiva before birth is considered to be the same as what it is in the Mukti state, which is the Turiya state. 7 %

Jivas, who are eternal, are given life and body by Siva/Sakti that they may rid themselves of their primordial impurities and become truly free and pure.

These jivas are classified into three basic categories according to the degree of impurities they possess. In a scheme of evolution, the one class rises to the next by divesting itself of the impurities, one after another.

These three catagories are called vijnanakalars, pralayakalars and sakalars, according to the state of. their evolution. Each of these three broad classifications has again sub-classifications, and in all the hierarchy of jivas is divided imto ten divisions.

The-vijnanas (abbreviated form of vijnanakalars) are the most highly evolved souls. No longer affected by karma or maya, they are amenable to anava alone. They are categorized into four subdivisions, beginning with those of lesser evolution.

First come those who are not rid of anava (egoity), but are in a quiescent state of inaction. Then come those who have realised the Self, but are still conscious of the self. Then are those who have reached the ranks of the Vidyesvaras. And above them are the seven crores of Mantra Nayakas.

But all these possess the impurity of  egoity (self-consciousness) to some extent or other. Only the truly enlightended are totally rid of anava or self-consciousness.

Below the Vijnanas are the pralayakalars. They possess two malams: anava and karma, out of the three.

Among them, the first category consists of those souls who will attain mukti in their next life. More advanced than they are the jivan-muktas, who have attained enlightenment during their immediate incarnation. Above them in evolution are the 108 Mudras.

All these three categories of pralayakalars possess the sense of self consciousness. and experience karma in gradations of intensity.

The third major category of jivas is called the sakalars.

The sakalars are encumbered by all three malams; anava, karma and maya. Among the = sakalars are three sub-classifications: those who have attained the miraculous powers of siddhis, but are aspiring towards eventual God realization; those who having attained the siddhis, are content with cultivating these powers; and those who are not performing yoga sadhana, remaining powerless to conquer any of the malamsy. and are simply in the world of sense experience.

There are further subdivisions among these three main categories. These are elaborated later in ‘‘Tantra the Eighth,” Mantras 2229-2223 under the heading Kevala Sakala Sudham.

In whatever stage of spiritual evolution they are, all jivas have ultimately to divest themselves of their triple malam, and unite with bindu and nada before they become one with Siva.`,
    elaborationTamil: `அசையா சக்தியாகிய சிவமும் அசையும் சக்தியாகிய சக்தியும் தங்கள் திருவிளையாட்டால் ஆன்மா ஆசைப்படும் போது அதைத் தீர்த்துக் கொள்ள வினைகளைச் சேர்த்து உயிராக்கி உலகத்தில் பிறக்க வைத்து அந்த உயிருக்கு சுத்த மாயை அசுத்த மாயை என்ற இரண்டு விதமான மாயைகளையும் வினைகள் தீரும் வரை உடலுக்குள் வைத்து பூட்டுகின்றார்கள். பின்பு உயிர்களின் எண்ணத்தில் புகுந்து சுத்த மாயை அசுத்த மாயை ஆகிய இரண்டு விதமான மாயைகளையும் நீங்கி உயிர் உருவாகுவதற்கு முன்பு இருந்த துரியம் எனும் ஆழ்நிலை உறக்க நிலையில் ஆன்மாவை சிவமாக்குகின்றார்கள். உட்கருத்து: இறைவன் தனது திருவிளையாட்டினால் தன்னிடம் துரிய நிலையில் கலந்திருக்கும் ஆன்மாவை மாயையை சேர்த்து பிறக்க வைத்து பின்பு மாயை நீக்கி தன்னிடமே சேர்த்துக்கொள்கிறார். துரிய நிலையையும் மாயை சேரும் நிலையையும் பாடல் #460 இல் காண்க.`,
  },
  {
    id: 494, tantraId: 2, verseNumber: 493,
    tamil: `விஞ்ஞானர் நால்வரு மெய்ப்பிரள யாகலத்
தஞ்ஞானர் மூவருந் தாங்கு சகலத்தின்
அஞ்ஞானர் மூவரு மாகும் பதின்மராம்
விஞ்ஞான ராதியர் வேற்றுமை தானே`,
    transliteration: `viññāṉar nālvaru meyppiraḷa yākalat
taññāṉar mūvarun tāṅku cakalattiṉ
aññāṉar mūvaru mākum patiṉmarām
viññāṉa rātiyar vēṟṟumai tāṉē`,
    english: `493: The Three Categories From Ten Classes
Vignanars true are of groups four
Pralayakalas are of three;
Sakalars below are another three
Thus are Jivas grouped, ten in all.`,
    elaborationEnglish: `Vijnana is a term more commonly used in Buddhism, ordinary or individual consciousness as opposed to Prajna world or Universe consciousness.`,
    elaborationTamil: `உடலோடு இருக்கும் போதே இறைவனை உணர்ந்து உண்மை ஞானத்தை அடைந்தவர்கள் அதமர், மத்திமர், உத்தமர், சித்தர் என நான்கு வகைப்படுவார்கள். இவர்கள் ஆணவ மலத்தை மட்டுமே கொண்ட விஞ்ஞானர் ஆவார்கள். மாயை நீங்கப் பெற்றாலும் ஆணவமும் கன்மமும் நீங்கப் பெறாததால் பிரளய ஊழிக்காலம் வரை இறைவனோடு கலப்பதற்கு காத்திருப்பவர்கள் அபக்குவர், பரமுத்தர், அபரமுத்தர் என மூன்று வகைப்படுவார்கள். இவர்கள் மெய்பிரளய அகலர் ஆவார்கள். ஆணவம், கன்மம், மாயை ஆகிய மும்மலங்களும் கொண்டவர்கள் முத்தர், சாதகர், சகலர் என்று மூன்று வகைப்படுவார்கள். இவர்கள் அஞ்ஞானர் ஆவார்கள். விஞ்ஞானர், மெய்பிரளய அகலர், அஞ்ஞானர் என உலகத்தில் உள்ள உயிர்கள் அனைத்தும் 3 பகுதியாக பத்து வகையினராக வேறுபட்டு இருக்கின்றார்கள். குறிப்பு: முதல் வகையினர் கன்மம், மாயை அனைத்தும் நீங்கப்பெற்று நான் என்ற எண்ணம் நீங்கி ஞானம் அடைந்தாலும் இறைவனுடன் கலக்காமல் தனிப்பட்ட தனது பெயரினால் அழைக்கப்படுவதினால் ஆணவமலம் இருக்கின்றது. இவர்கள் மரணமில்லாத உடலுடன் இருக்கும் சித்தர்கள், யோகிகள், ரிஷிகள், தேவர்கள் ஆகின்றார்கள். 2 வது வகையினர் மாயை நீங்கி ஆணவம் கன்மம் ஆகிய இரண்டு மலங்களை மட்டுமே உடையவர்கள். இவர்கள் இறைவனை உணர்ந்து ஞானம் அடைந்தாலும் இறைவனோடு கலக்காமல் உலக நன்மைக்காக அவ்வப்போது மீண்டும் மீண்டும் உடலேடுத்து பிறந்து இறப்பார்கள் இவர்கள் பிரளய ஊழிக்காலம் வரை இறைவனோடு கலப்பதற்கு காத்திருக்கும் ஞானிகள் ஆவார்கள். 3 வது வகையினர் ஆணவம், கன்மம், மாயை ஆகிய மூன்று மலங்களையும் கொண்டு உலக வாழ்க்கையிலேயே மூழ்கி இருக்கின்றவர்கள். ஆன்மாவின் மூன்று வகைகளும் பத்து உப வகைகளும்: விஞ்ஞானர் = 1. அதமர், 2. மத்திமர், 3. உத்தமர், 4. சித்தர். மெய்பிரளய அகலர் = 5. அபக்குவர், 6. பரமுத்தர், 7. அபரமுத்தர். அஞ்ஞானர் = 8. முத்தர், 9. சாதகர், 10. சகலர்.`,
  },
  {
    id: 495, tantraId: 2, verseNumber: 494,
    tamil: `விஞ்ஞானர் கேவலத் தாரது விட்டவர்
தஞ்ஞானர் அட்டவித் தேசராஞ் சார்ந்துளோர்
எஞ்ஞானர் ஏழ்கோடி மந்திர நாயகர்
மெய்ஞானர் ஆணவம் விட்டுநின் றாரே`,
    transliteration: `viññāṉar kēvalat tāratu viṭṭavar
taññāṉar aṭṭavit tēcarāñ cārntuḷōr
eññāṉar ēḻkōṭi mantira nāyakar
meyñāṉar āṇavam viṭṭuniṉ ṟārē`,
    english: `494: The Four Classes of Vijnars
Vijnanakalars are of classes four;
Those who are in Kevala (Anava) state,
Next are those who are Self-realised;
Those who reached the state of Eight Vidyeswaras,
And finally are those who rank as the Seven Crores of Manthra Nayakas;
Those who are of Egoity Impure rid
Are the truly realised beings (no more are they Jivas).`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-494-Second-Tantra-15.-Three-Types-of-Souls.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உயிர்களின் வகைகளில் முதலாவதாக இருக்கும் விஞ்ஞானர் மாயையும் கன்மமும் நீங்கப் பெற்ற ஜீவன் முக்தர்களாக நான்கு வகைப்பட்டு இருப்பவர்கள். முதலாவது வகையினர் ஞானம் பெற்றும் ஆணவம் நீங்காத தஞ்ஞானர் (அதமர்). இரண்டாவது வகையினர் அட்டவித்தீசுர நிலையை அடைந்த எஞ்ஞானர் (மத்திமர்). மூன்றாவது வகையினர் ஏழு கோடி மந்திரங்களின் நிலையை அடைந்த மந்திர நாயகர் (உத்தமர்). நான்காவது வகையினர் உண்மை ஞானமாகிய பேரறிவை பெற்று ஆணவ மலத்தையும் விட்டு நின்ற மெய்ஞ்ஞானர் (சித்தர்). 1, அதமர் விளக்கம்: (ரிஷிகள்) ஞானம் அடைந்தாலும் தனிப்பட்ட தனது பெயரினால் அழைக்கப்பட்டு இறைவனுடன் கலக்காலம் இறைவனுக்காக யாகங்கள் பூஜைகள் செய்து கொண்டிருப்பவர்கள் அதமர் என்று அழைக்கப்படுகின்றார்கள். 2, அட்டவித்தீசுர நிலை பெற்ற மத்திமர் விளக்கம்: (யோகிகள்) யோகத்தின் வழியாக எட்டு விதமான ஞானம் தத்துவ நிலைகளைப் பெற்று ஈஸ்வர நிலையை அடைந்து எட்டுவிதமான ஞானத்தைப் பெற்றவர்கள் மத்திமர் என்று அழைக்கப்படுகின்றார்கள். 3, ஏழு கோடி மந்திர நிலை பெற்ற உத்தமர் விளக்கம்: (தேவர்கள்) மந்திரங்களில் முக்கியமான 1. நம 2. சுவாஹா 3. சுவதா 4. வெளஷட் 5. வஷ்ட் 6. பட் 7. ஹம் ஆகிய ஏழு விதமான வார்த்தைகளில் முடிகின்ற மந்திரங்கள் ஒவ்வொன்றும் ஒரு கோடி வீதம் மொத்தம் ஏழு கோடி ஆகும். இந்த ஏழு கோடி மந்திரங்களாலும் உச்சரித்துப் போற்றி வணங்கப்படும் நிலையை அடைந்தவர்கள் மந்திர நாயகர் என்றும் உத்தமர் என்று அழைக்கப்படுகின்றார்கள். 4, சித்தர்கள் விளக்கம்: இறத்தால் தானே பிறப்பதற்கு என்று என்றும் இறப்பில்லாமல் இருப்பதற்கு பல தியான, யோகமுறைகளை கையாண்டு அட்டமா சித்திகள் அடைந்து ஆணவம், கன்மம், மாயை நீங்கி இறைவனை உணர்ந்து ஞானத்தை அடைந்து உடலோடு தானே இறைவன் என்ற நிலையில் இருப்பவர்கள்.`,
  },
  {
    id: 496, tantraId: 2, verseNumber: 495,
    tamil: `இரண்டா வதில்முத்தி எய்துவர் அத்தனை
இரண்டாவ துள்ளே இருமல பெத்தர்
இரண்டாகு நூற்றெட்டு ருத்திரர் என்பர்
முரண்சேர் சகலத்தர் மும்மலத் தாரே`,
    transliteration: `iraṇṭā vatilmutti eytuvar attaṉai
iraṇṭāva tuḷḷē irumala pettar
iraṇṭāku nūṟṟeṭṭu ruttirar eṉpar
muraṇcēr cakalattar mummalat tārē`,
    english: `495: The Three Classes of Pralaya Kalas
Of the Pralayakalars three,
Are those who Mukti attained;
Another, by malas twine (Egoity and Karma) bound;
Yet another, the Rudras Hundred and Eight;
The Sakalas have all malas three.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-495-Second-Tantra-15.-Three-Types-of-Souls.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உயிர்களின் வகைகளில் இரண்டாவதாக இருக்கும் மெய்பிரளய அகலர் அனைவரும் பிரளயகாலப் பேரழிவில் முக்தியைப் பெறுபவர்கள். ஆணவம், கன்மம் ஆகிய இரண்டு மலங்களை மட்டும் கொண்டிருக்கும் இவர்கள் அபக்குவர் பரமுத்தர் அபரமுத்தர் என்ற பெயருடன் இருக்கின்றனர். அபக்குவர் பரமுத்தர் என்கிற இரண்டு வகையாக 54- 54 என்ற எண்ணிக்கையில் நூற்று எட்டு உருத்திரர்களாக இருக்கின்றனர். அபரமுக்தர் ஒரு வகையாகவும் மொத்தம் மூன்று வகைகளாக இருக்கின்றனர். பாடல் #494ல் உள்ள விஞ்ஞானர். இந்த பாடலில் கூறிய மெய்பிரளய அகலர் ஆகிய இரு வகையில் இல்லாத மற்ற அனைவரும் ஆணவம் கன்மம் மாயை என்ற மூன்று மலங்களையும் கொண்ட அஞ்ஞானர் ஆவார்கள். அபரமுக்தர் விளக்கம்: இவர்கள் ஞானம் அடைந்து உலகத்தில் படைத்தல் மறைத்தல் காத்தல் அருளல் அழித்தல் ஆகிய இறைவனின் தொழில்களை செய்து பிறவி இல்லாத நிலையில் ஆணவம், கன்மம் என இரண்டு மலங்களை மட்டுமே கொண்டு பிரளய ஊழிக்காலம் வரை இறைவனோடு கலப்பதற்கு காத்திருக்கும் ஞானிகள் ஆவார்கள். பரமுக்தர் விளக்கம்: உலக நன்மைக்காக உயிர்களை உய்விக்க உலகத்தில் பிறப்பதற்கு வானுலகத்தில் இறைவனின் கட்டளைக்காக காத்திருப்பவர்கள் பரமுக்தர் என்கின்ற ஞானிகள் ஆவார்கள். இவர்கள் 54 வகையான ருந்திரர் என்கின்ற பதவியில் இருக்கின்றார்கள் அபக்குவர் விளக்கம்: உலக நன்மைக்காக உயிர்களை உய்விக்க உலகத்தில் பிறந்து அனைத்து உயிர்களோடு வாழ்ந்து வருபவர்கள் அபக்குவர் என்கின்ற ஞானிகள் ஆவார்கள். இவர்கள் 54 ருந்திரர் வகையான என்கின்ற பதவியில் இருக்கின்றார்கள் குறிப்பு: பரமுக்தர் அபக்குவர் இருவகையினரும் உலக நன்மைக்காக உயிர்களை உய்விக்க உலகத்தில் பிறந்து உயிர்களோடு உயிராக வாழ்ந்து பல நல்கருத்துக்களை கூறி ஆணவம், கன்மம், மாயை என்ற மூன்று மலங்களையும் கொண்ட அஞ்ஞானர்களை பிறவியில்லா நிலையை அடையச்செய்வதற்கும் இறைவனை உணர்வதற்க்கான காரியத்தையும் செய்து கொண்டிருக்கின்றார்கள்.`,
  },
  {
    id: 497, tantraId: 2, verseNumber: 496,
    tamil: `பெத்தெத்த சித்தொடு பேண்முத்தச் சித்தது
ஒத்திட் டிரண்டிடை யூடுற்றார் சித்துமாய்
மத்தது மும்மலம் வாட்டுகை மாட்டாதார்
சத்தத் தமிழ்ந்து சகலத்து ளாரே`,
    transliteration: `pettetta cittoṭu pēṇmuttac cittatu
ottiṭ ṭiraṇṭiṭai yūṭuṟṟār cittumāy
mattatu mummalam vāṭṭukai māṭṭātār
cattat tamiḻntu cakalattu ḷārē`,
    english: `496: The Three Classes of Sakalas
Sakalas three are:
Those who have attained Siddhis miraculous,
Those who have attained Mukti (Jivan)
Those who have attained neither
--All powerless to conquer Malas three
And in sound and other senses immersed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-496-Second-Tantra-15.-Three-Types-of-Souls.mp3',
    elaborationTamil: `உயிர்களின் வகைகளில் மூன்றாவதாக இருப்பவர்கள் ஆணவம், கன்மம், மாயை ஆகிய மூன்று மலங்களையும் கொண்ட அஞ்ஞானர். இவர்கள் முத்தர் சாதகர் சகலர் ஆகிய மூன்று விதமாக இருக்கிறார்கள். முக்தர்: முன் ஜென்ம நல்வினைப் பயனால் இறைவனே குருவாக மனித உருவில் வந்து கொடுத்த ஞானத்தைப் பெற்று மும்மலம் கொண்ட தங்களின் ஆன்மாவை சிவத்தோடு இரண்டறக் கலந்து முக்தி பெற்ற முத்தர் ஆவார்கள். சாதகர்: முன் ஜென்ம வினைப் பயனால் இறையருளைப் பெற்று தியானம் தவம் யோகப்பயிற்சிகள் பூஜைகள் செய்து கொண்ணிருப்பார்கள். இவர்கள் சாதகர் ஆவார்கள். இவர்கள் தாம் மேற்கொண்ட சாதகங்களின் பயனால் மும்மலங்களால் உருவாகும் துன்பங்களிலிருந்து பாதிக்காமல் இருப்பார்கள். சகலர்: இவர்கள் மாயையால் உலக வாழ்க்கையிலேயே அமுங்கிக் கிடந்து மும்மலங்களின் வலிமை அதிகமாகப் பெற்ற சகலர் ஆவார்கள்.`,
  },
  {
    id: 498, tantraId: 2, verseNumber: 497,
    tamil: `சிவமாகி ஐவகைத் திண்மலஞ் செற்றோர்
அவமாகார் சித்தர்முத் தாந்தத்து வாழ்வார்
பவமான தீர்வோர் பசுபாசம் அற்றோர்
நவமான தத்துவம் நாடிக்கண் டோ ரே`,
    transliteration: `civamāki aivakait tiṇmalañ ceṟṟōr
avamākār cittarmut tāntattu vāḻvār
pavamāṉa tīrvōr pacupācam aṟṟōr
navamāṉa tattuvam nāṭikkaṇ ṭō rē`,
    english: `497: Stages of Attainment in Mala Riddance
They who are of five malas hard rid,
Themselves Siva become;
They blemishless become,
They become Siddhas,
Attain state of Mukti Finale,
They uproot Jiva's bondage,
End cycle of births;
They alone are,
Who truth of peerless Tattvas realised.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-497-Second-Tantra-15.-Three-Types-of-Souls.mp3',
    elaborationTamil: `ஆணவம், கன்மம், மாயை, மாயேயம், திரோதாயி என்னும் ஐந்து வலிமை மிகுந்த மலங்களை வென்று தாமே சிவமாகி சித்தர்கள் சாயுச்சியம் என்னும் பேரின்பப் பெருவாழ்வு பெற்று அதிலேயே என்றும் திளைத்து இருப்பார்கள். இவர்கள் இறவாத நிலை பெற்றதால் எப்போதும் பிறவி இல்லாத நிலையைப் பெற்று பசு பாசம் ஆகிய இரண்டும் நீங்கி பதியாக இருக்கும் ஒன்பது வகை தத்துவங்களை தமது தவத்தினால் உணர்ந்து அடைந்தார்கள். பதி பசு பாசம் விளக்கம்: பதி என்பது இறைவனின் பேரான்மா. பசு என்பது இறைவனின் பேரான்மாவிலிருந்து பிரிந்து வந்து உலகங்களில் பிறந்த ஜீவ ஆன்மா. பாசம் என்பது பேரான்மாவுடம் ஜீவ ஆன்மா சேராதவாறு பிரித்து ஐந்து வகை மலங்களால் கட்டி இருப்பது. எப்போது பசுவாகிய ஜீவ ஆன்மா தனது பாசமாகிய மலங்களை அறுத்துக் கொண்டு பதியாகிய பரமாத்மாவை சென்று அடைகிறதோ அப்போது அது முக்தியைப் பெற்று இனி பிறவி இல்லாத நிலையை அடைகிறது. ஒன்பது தத்துவ விளக்கம்: உலகம் உருவாகுவதற்கும் உலக தொழில்கள் நடைபெறுவதற்கு காரணமாய் இருப்பவை ஒன்பது தத்துவங்களாகும். இந்த ஒன்பது தத்துவங்களையும் சித்தர்கள் தமது தவத்தினால் தமக்குள் கண்டு உணர்பவர்கள். சிவம் – அசையா சக்தி சக்தி – அசையும் சக்தி ஒலி – சத்தம் ஒளி – வெளிச்சம் சதாசிவம் – அருளல் மகேசுவரன் – மறைத்தல் உருத்திரன் – அழித்தல் திருமால் – காத்தல் பிரம்மன் – படைத்தல்`,
  },
  {
    id: 499, tantraId: 2, verseNumber: 498,
    tamil: `விஞ்ஞான ஆணவ கேவலம் மேவுவோர்
விஞ்ஞானம் மாயையில் தங்கும் இருமலர்
அஞ்ஞானர் அச்சக லத்தர் சகலராம்
விஞ்ஞானர் ஆதிகள் ஒன்பான்வே றுஉயிர்களே`,
    transliteration: `viññāṉa āṇava kēvalam mēvuvōr
viññāṉam māyaiyil taṅkum irumalr
añjñāṉar accaka lattara cakaḷarām
viññāṉar ātikaḷ oṉpāṉvē ṟuuyirkaḷē`,
    english: `498: Nine Gradations of Jivas
Vijnanakalas are of gradations three;
Those who in quiescent Anava alone abides; (the Pralayakala among Vijnanas)
So are Pralayakalas of gradations three;
And Sakalas too;
Thus are there nine classes of Jivas,
Evolving in gradations separate.`,
    elaborationTamil: `விஞ்ஞானர் என்பவர் ஆணவம் மலம் மட்டுமே கொண்டு கன்மம், மாயை ஆகிய இரண்டு கேவல நிலைகளுக்கும் மேலே இருப்பவர்கள். இவர்கள் கன்மம், மாயை ஆகியவற்றில் சிக்க மாட்டார்கள். மெய்பிரளய அகலர் என்பவர் ஆணவம், கன்மம் ஆகிய இரண்டு மலம் கொண்டு இருப்பவர்கள். இவர்கள் மாயையில் சிக்க மாட்டார்கள். அஞ்ஞானர் என்பவர் இந்த மூன்று மலங்களும் கொண்ட மற்ற அனைவரும் ஆவார்கள். சித்தர்களைத் தவிர்த்து விஞ்ஞானர், மெய்பிரளய அகலர், அஞ்ஞானர் மொத்தம் ஒன்பது வகையினராக இருக்கின்றனர். குறிப்பு இந்த பாடலில் ஏற்கனவே சொல்லப்பட்ட கருத்துக்கள் இந்த பாடலிலும் இருந்தாலும் மூவகைச் சீவவர்க்கம் தலைப்பில் உள்ள மூன்று விதமான உயிர்களில் 10 வகையினரில் சித்தர்களை மேன்மையானவர்களாக இந்த பாடல் கூறிப்பிடுகின்றது.`,
  },
  {
    id: 500, tantraId: 2, verseNumber: 499,
    tamil: `விஞ்ஞான கன்மத்தால் மெய்யகங் கூடிய
அனையான கன்மத்தினால் சுவர் யோனிபுக்
கெஞ்ஞான மெய்தீண்டி யேயிடை யிட்டுப்போய்
மெய்ஞ்ஞான ராகிச் சிவமேவல் உண்மையே`,
    transliteration: `viññāṉa kaṉmattāl meyyakaṅ kūṭiya
aṉaiyāṉa kaṉmattināl cuvar yōṉipuk
keññāṉa meytīṇṭi yēyiṭai yiṭṭuppōy
meyññāṉa rākic civamēval uṇmaiyē`,
    english: `499: How Sakalas Among Vijnanakalas Attain Siva-State
Vijnanakalas may by karma assume form corporeal;
But by performing holy deeds,
Acquire Celestial frame
And higher Jnana Form;
And Constant striving thus,
Gain wisdom perennial
And in the end Siva Himself become.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-499-Second-Tantra-15.-Three-Types-of-Souls.mp3',
    elaborationTamil: `விஞ்ஞானர் தன்னுடைய ஞான கன்மத்தினால் எடுத்த பிறவியிலேயே தன் உள்ளமும் மெய்யான இறைவனும் கூடி ஒன்றாக கலந்து தாமே சிவமாகி இருப்பார்கள். மெய்பிரளய அகலர் அஞ்ஞான கன்மத்தினால் ஞானிகளாகப் பிறந்து பாடல் #493 ல் உள்ள குறிப்பின் படி பிரளய ஊழிக்காலம் வரை இறைவனோடு கலப்பதற்கு காத்திருந்து பிரளய ஊழிக்காலத்தில் சிவத்தோடு கலப்பார்கள். அஞ்ஞானர்கள் தன்னுடைய சாதகத்தினாலோ அல்லது மெய்பிரளய அகலர்களாக உள்ள ஞானிகளாலோ உயர்வதற்கு ஏதுவாகிய ஞானம் பெற்று ஒரு நாள் மெய்பிரளய அகலர்களாகவோ விஞ்ஞானர்களாகவோ மாறி சிவத்தோடு கலப்பார்கள். அசையா சக்தியாக இருக்கும் இறைவனுடன் கலந்து பேரின்பத்தில் இருக்கும் சிவசாயுச்சியம் என்பது அனைவருக்கும் உறுதியாகக் கிடைக்கும் இது உண்மை.`,
  },
  {
    id: 501, tantraId: 2, verseNumber: 500,
    tamil: `ஆணவந் துற்ற வவித்தா நனவற்றோர்
காணிய விந்துவா நாத சகலாதி
ஆணவ மாதி யடைந்தோ ரவரன்றே
சேணுயர் சத்தி சிவதத் துவமாமே`,
    transliteration: `āṇavan tuṟṟa vavittā naṉavaṟṟōr
kāṇiya vintuvā nāta cakalāti
āṇava māti yaṭaintō ravaraṉṟē
cēṇuyar catti civatat tuvamāmē`,
    english: `500: How Jivas Reach Siva
Rid themselves of Anava entire
And consciousness lost of all Jiva memory,
They Bindu and Nada become,
The highest heavenly goal
Of one-ness with Siva Tattva;
Albeit all three, Sakala and the rest of yore possessed,
The primal impurities triple,
Anava, Maya and Karma.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-500-Second-Tantra-15.-Three-Types-of-Souls.mp3',
    elaborationTamil: `ஆணவம் முதலான 5 மலங்களும் இருப்பதினால் கண்ணால் பார்த்தும் அறியாமையால் அதில் உள்ள உண்மை தெரிந்து கொள்ளாதவர்கள் ஒளி ஒலி முதலான அனைத்து இறை தத்துவங்களையும் உணர முடியாது. ஆணவம் முதலான 5 மலங்களும் கடந்தவர்கள் உயர்வான இடத்தில் இருக்கும் சிவசக்தி தத்துவத்தை உணரலாம் உட்கருத்து: ஆணவம் என்கிற மலத்தை விட்டு நீங்காத வரை இறைவனை முழுவதுமாக உணர முடியாது. ஐந்து மலங்களையும் இறையருளால் வென்றவர்கள் மட்டுமே ஆதிப்பரம்பொருளாக இருக்கும் சிவம் (அசையா சக்தி) சக்தி (அசையும் சக்தி) எனும் இரண்டு தத்துவங்களையும் உணர முடியும்.`,
  },
  {
    id: 502, tantraId: 2, verseNumber: 501,
    tamil: `திலமத் தனைபொன் சிவஞானிக்கு ஈந்தால்
பலமுத்தி சித்தி பரபோக மும் தரும்
நிலமத் தனைபொன்னை நின்மூடர்க்கு ஈந்தால்
பலமும்அற் றேபர போகமும் குன்றுமே.`,
    transliteration: `tilamat taṉaipoṉ civañāṉikku īntāl
palamutti citti parapōka mum tarum
nilamat taṉaipoṉṉai niṉmūṭarkku īntāl
palamumaṟ ṟēpara pōkamum kuṉṟumē.`,
    english: `501: Give Freely to Sivajnanis
Give a wee bit to Sivajnani,
You shall attain Siddhi, Mukti and heavenly bliss;
Give a world of gold to the witless,
You shall become poor losing all joys.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-501-Second-Tantra-16.-Eligibility.mp3',
    elaborationTamil: `உண்மையான அறிவைப் பெற்ற சிவ ஞானியர்களுக்கு ஒரு எள்ளின் அளவு தங்கத்தைக் கொடுத்தாலும் அதனை இறைவனே ஏற்றுக் கொண்டு அதன் பயனாக முக்தியையும், எண்ணியதை அடைகின்ற சக்தியையும், பேரின்பப் பெருவாழ்விற்கான வழியையும் தந்து அருளுவான். உலக அறிவை மட்டும் கொண்டு தமக்கு ஞானம் இருப்பதாக எண்ணி ஞானியர் போல வேஷம் போட்டுக் கொண்டு இருக்கும் முடர்களிடம் இந்த உலகத்திலுள்ள அனைத்து தங்கத்தையும் தானமாக கொடுத்தாலும் அதனால் ஒரு பயனும் கிடைக்காதது மட்டுமில்லாமல் கொடுத்த வீண் தானத்தின் பயனால் அடுத்த பிறவியிலும் பேரின்பப் பெருவாழ்வு கிடைக்காமல் போய்விடும். உள்விளக்கம்: தகுதியானவர்களுக்கே தானம் செய்ய வேண்டும்.`,
  },
  {
    id: 503, tantraId: 2, verseNumber: 502,
    tamil: `கண்டிருந் தாருயிர் உண்டிடுங் காலனைக்
கொண்டிருந் தாருயிர் கொள்ளும் குணத்தனை
நன்றுணர்ந் தார்க்கருள் செய்திடு நாதனைச்
சென்றுணர்ந் தார்சிலர் தேவரு மாமே.`,
    transliteration: `kaṇṭirun tāruyir uṇṭiṭuṅ kālaṉaik
koṇṭirun tāruyir koḷḷum kuṇattaṉai
naṉṟuṇarn tārkkaruḷ ceytiṭu nātaṉaic
ceṉṟuṇarn tārcilar tēvaru māmē.`,
    english: `502: Lord's Devotees are Elevated Souls
Death waits for the moment due
And seizes lives;
But the Lord seizes Death's life;
Such indeed, His Prowess is;
He blesses all who know Him true;
They who sought Him, immortals became.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-502-Second-Tantra-16.-Eligibility.mp3',
    elaborationTamil: `எமனால் உயிர்கள் ஒரு நாள் இறந்து போவதைப் பார்த்தாலும் தாமும் அப்படி ஒரு நாள் இறந்து போவோம் என்பதை உணராமல் உயிர்கள் இருக்கின்றனர். அதுபோலவே ஒவ்வொரு உயிருக்குள்ளும் அந்த உயிரையே தனது அம்சமாகக் கொண்டு இருக்கும் இறைவன் தமக்குள்ளும் இருக்கின்றான் என்பதையும் உணராமல் இருக்கின்றனர். உலக வாழ்க்கையை விட நன்மை தருவது பேரின்பப் பெருவாழ்வு என்பதை உணர்ந்து அன்பாலும் தவத்தாலும் தேடிச் சென்று தமக்குள் இருக்கும் இறைவனை உணர்ந்து கொள்ளும் சிலர் மட்டுமே இறைவனின் அருள் பெற்று தேவர்களாக பதவி பெறுகிறார்கள். உட்கருத்து: விரைவில் முடியும் உலக வாழ்க்கை மேல் ஆசை வைக்காமல் என்றும் நிரந்தரமான பேரின்பப் பெருவாழ்வுதான் வேண்டும் என்று உணர்ந்த உயிர்கள் மட்டுமே இறைவனின் அருளைப் பெறுவதற்கு தகுதியான பாத்திரமாக இருக்கிறார்கள்.`,
  },
  {
    id: 504, tantraId: 2, verseNumber: 503,
    tamil: `கைவிட்டி லேன்கரு வாகிய காலத்து
மெய்விட்டி லேன்விகிர் தன்அடி தேடுவன்
பொய்விட்டு நானே புரிசடை யானடி
நெய்விட் டிலாத விடிஞ்சிலு மாமே.`,
    transliteration: `kaiviṭṭi lēṉkaru vākiya kālattu
meyviṭṭi lēṉvikir taṉaṭi tēṭuvaṉ
poyviṭṭu nāṉē puricaṭai yāṉaṭi
neyviṭ ṭilāta viṭiñcilu māmē.`,
    english: `503: Lord's Feet are unto a Self-Effulgent Lamp
I gave Him not up even while in womb;
I forgot not the truth of His holy Feet;
I gave up falsehood and sought them;
The Feet of Lord of matted locks
Are a Lamp no oil feeds.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-503-Second-Tantra-16.-Eligibility.mp3',
    elaborationTamil: `வினைப் பயனால் பிறவி எடுத்த போது கருவாக உருவான போதிலிருந்தே யாம் இறை நினைப்பை கைவிடாது பற்றிக் கொண்டேன். உயிர்கள் அனைத்துமாக இருக்கும் உண்மை இறைவனின் திருவடிகளையே எனக்குள் தேடி கயிறு போல பின்னிய சடையை தலையில் அணிந்த இறைவனின் திருஉருவத்தை எனக்குள் கண்டு அவனது திருவடிகளையே சரணடைந்தேன். அதனால் நெய் விட்டு எரிக்கப்படுகின்ற உலக விளக்குகளைப் போல இல்லாமல் நெய்யே விடாமல் தானாக ஒளிரும் விளக்காக எனக்குள் இறைவன் வந்து இருக்கின்றான் என்பதை உணர்ந்து கொண்டேன். உட்கருத்து: பொய்யான உலகப் பற்றுக்களை விட்டுவிட்டு உண்மையான இறைவனையே முழுவதுமாகப் பற்றிக்கொண்ட உயிர்கள் தான் இறைவனைத் தமக்குள் ஒளி வடிவமாகத் தரிசிக்கத் தகுதியான பாத்திரமாக இருக்கிறார்கள்.`,
  },
  {
    id: 505, tantraId: 2, verseNumber: 504,
    tamil: `ஆவன ஆவ அழிவ அழிவன
போவன போவ புகுவ புகுவன
காவலன் பேர்நந்தி காட்டித்துக் கண்டவன்
ஏவன செய்யும் இளங்கிளை யோனே.`,
    transliteration: `āvaṉa āva aḻiva aḻivaṉa
pōvaṉa pōva pukuva pukuvaṉa
kāvalaṉ pērnanti kāṭṭittuk kaṇṭavaṉ
ēvaṉa ceyyum iḷaṅkiḷai yōṉē.`,
    english: `504: Lord does Things Appropriate to Those of Tender Love
Those that are destined to be
Let them be;
Those that are destined not to be
Let them not be;
Those that are destined to go
Let them go;
Those that are destined to come
Let them Come;
The Mighty Nandi shows all
And witnesses all:
All things appropriate,
He does
To those of tender love for Him.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-504-Second-Tantra-16.-Eligibility.mp3',
    elaborationTamil: `உலகங்களும் உயிர்களும் உருவாகும் காலத்தில் உருவாகி அழியும் காலத்தில் அழிகின்றன. உயிர்களின் வினைகள் தீர்க்க தீர்க்க வினைகள் சென்று விடும். உயிர்கள் செய்யும் கர்மங்களால் வினைகள் வந்தும் சேரும். இவை எல்லாவற்றையும் கட்டிக் காக்கும் குருவாக இருக்கும் இறைவன் காட்டியருள அதைக் கண்டவர்கள் இறைவனின் கட்டளையைப் பெற்று அதைச் செயல்படுத்தும் தகுதி பெற்ற புதிய அடியவர்கள் ஆவார்கள். உட்கருத்து: அனைத்தும் இறைவனே என்ற உண்மையை இறைவன் காட்டத் தமக்குள் கண்டு உணர்ந்தவர்கள் இறைவனின் கட்டளையை செயல் படுத்தும் தகுதியான பாத்திரமாக இருக்கிறார்கள்.`,
  },
  {
    id: 506, tantraId: 2, verseNumber: 505,
    tamil: `கோல வறட்டைக் குனிந்து குளகிட்டுப்
பாலைக் கறந்து பருகுவதே ஒக்கும்
சீலமும் நோன்பும் இலாதவர்க்கு ஈந்தது
காலங் கழிந்த பயிரது ஆகுமே.`,
    transliteration: `kōla vaṟaṭṭaik kuṉintu kuḷakiṭṭup
pālaik kaṟantu parukuvatē okkum
cīlamum nōṉpum ilātavarkku īntatu
kālaṅ kaḻinta payiratu ākumē.`,
    english: `505: Giving to Unworthy is Undesirable
Well may you tender her;
And with fresh grass feed her,
The barren cow can no milk give;
Even so is giving
Unto those who neither good nor holy are;
Unto a crop they are,
Raised in season improper.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-505-Second-Tantra-17.-Ineligibility.mp3',
    elaborationEnglish: `The unworthy jivas are those who are neither good nor holy. They are like a crop that is raised in improper Season. They do not flourish, do not yield. They are like the barren cows that give no milk. They are steeped in worldly pleasures. They will never get God-vision. They are perpetuaters of the five deadly sins. They are destined only to the hot hell.

Do not feed them; do- not look after them; do not give them anything. To give’to them is a heinous crime. Both the giver and the receiver will be condemned to perdition.`,
    elaborationTamil: `மடி வற்றிப்போன பசுமாடு அழகாக இருக்கிறதே என்று குனிந்து அதற்கு புற்களை உணவாகக் கொடுத்து அதன் மடியிலிருந்து பாலைக் கறந்து குடித்து விடலாம் என்று நினைப்பது ஒழுக்கமும் தவமும் இல்லாதவர்களுக்கு தானம் கொடுத்து பேரின்ப வாழ்வைப் பெற்று விடலாம் என்று நினைப்பது போலாகும். ஒழுக்கமும் தவமும் இல்லாதவர்களுக்கு கொடுக்கும் தானம் பருவம் முடிந்த பிறகு விதைத்த பயிர் எப்படி வளர்ந்து செழிக்காதோ அதுபோல எந்தப் பயனையும் கொடுக்காமல் வீணாகிவிடும். உள்விளக்கம்: ஒழுக்கமும் தவமும் இல்லாதவர்கள் தானம் பெற தகுதி இல்லாதவர்கள் ஆவார்கள்.`,
  },
  {
    id: 507, tantraId: 2, verseNumber: 506,
    tamil: `ஈவது யோக இயம நியமங்கள்
சார்வ தறிந்தன்பு தங்கு மவர்க்கன்றி
ஆவ தறிந்தன்பு தங்கா தவர்களுக்கு
ஈவ பெரும்பிழை என்றுகொள் ளீரே`,
    transliteration: `īvatu yōka iyama niyamaṅkaḷ
cārva taṟintaṉpu taṅku mavarkkaṉṟi
āva taṟintaṉpu taṅkā tavarkkaḷukku
īva perumpiḻai eṉṟukoḷ ḷīrē..`,
    english: `506: Do not Give to Those Who Have no Love for God
Give only unto those
Who follow the way of Yoga, Iyama, and Niyama,
And who adore Lord, in constancy abiding;
To give those who have no love for God,
A heinous crime, indeed it is.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/08/Song-506-Second-Tantra-17.-Ineligibility.mp3',
    elaborationTamil: `தவம் யோகம் செய்து தீய குணங்களை போக்கி நன்மைகளைச் செய்து அனைத்து உயிர்களிடமும் அன்பாக இருக்கும் அடியவர்களுக்கு மட்டுமே தானம் கொடுக்க வேண்டும். வேஷம் போட்டுக் கொண்டு நடித்தால் தானம் கிடைக்கும் என்கிற ஆசையில் மனதில் உண்மையான அன்பில்லாமல் இருப்பவர்களுக்கு தானம் கொடுப்பது மிகப்பெரிய தவறு என்பதைப் புரிந்து கொள்ளுங்கள்.`,
  },
  {
    id: 508, tantraId: 2, verseNumber: 507,
    tamil: `ஆமாறு அறியான் அதிபஞ்ச பாதகன்
தோமாறும் ஈசற்குந் தூய குரவற்கும்
காமாதி விட்டோ ர்க்குந் தரல்தந்து கற்பிப்போன்
போமா நரகில் புகான்போதங் கற்கவே.`,
    transliteration: `āmāṟu aṟiyāṉ atipañca pātakaṉ
tōmāṟum īcaṟkun tūya kuravaṟkum
kāmāti viṭṭō rkkun taraltantu kaṟpippōṉ
pōmā narakil pukāṉpōtaṅ kaṟkavē.`,
    english: `507: He Who Gives to Sivajnanis will Become a Jnani
He who gives to Gods, Guru,
And the Goodly ones
Who are of passions rid,
Will a Jnani become,
Imparting Jnana appropriate to disciples several;
For him is not the burning hell,
That is destined for perpetrators
Of deadly sins five,
Who know not consequences dire.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-507-Second-Tantra-17.-Ineligibility.mp3',
    elaborationTamil: `ஒழுக்கத்தில் செல்லும் வழியை அறியாமல் பஞ்சமகா பாவங்களை செய்கின்ற மகா பாவியாக இருந்தாலும் குற்றமில்லாத சிவனடியார்களுக்கும் தூய்மையான சிவஞானத்தைப் போதிக்கும் குருக்களுக்கும் காமம் மற்றும் பஞ்சமாக தீயகுணங்களை கைவிட்ட சிவயோகியர்களுக்கும் தரக்கூடிய தானத்தை தந்து அதன் பயனால் ஞானம் பெற்றுவிட்டால் மகா பாவங்கள் செய்திருந்தாலும் நரகத்திற்குப் போக மாட்டார்கள். உட்கருத்து: மகாபாவத்தை செய்தவர்களாக இருந்தாலும் முறையான தானத்தை சரியானவர்களுக்குச் செய்துவிட்டால் அதன் பயனால் பாவ வினைகள் தீர்ந்து நல் வினைகளைச் சேர்த்து நரகத்திலிருந்து தப்பித்துக் கொள்வார்கள். ஐந்து மகா பாவங்கள் (பாடல் #200 இல் காண்க): கொலை – தெரிந்தே ஒரு உயிரைக் கொல்வது களவு – அடுத்தவர் பொருளுக்கு ஆசைப்பட்டு திருடுவது கள் – போதையில் மயங்கிக் கிடப்பது காமம் – மோகத்தில் மயங்கிக் கிடப்பது பொய் – உண்மையை மறைத்துப் பொய் பேசுவது ஐந்து மகா தீய குணங்கள்: காமம் – மோகம் குரோதம் – கோபம் லோபம் – சுயநலம் மதம் – கர்வம், ஆணவம் மாச்சரியம் – பொறாமை`,
  },
  {
    id: 509, tantraId: 2, verseNumber: 508,
    tamil: `மண்மலை யத்தனை மாதனம் ஈயினும்
அண்ணல் இவனென்றே அஞ்சலி அத்தனாய்
எண்ணி இறைஞ்சாதார்ககு ஈந்த இருவரும்
நண்ணுவர் ஏழா நரகக் குழியிலே.`,
    transliteration: `maṇmalai yattaṉai mātaṉam īyiṉum
aṇṇal ivaṉeṉṟē añcali attaṉāy
eṇṇi iṟaiñcātārkaku īnta iruvarum
naṇṇuvar ēḻā narakak kuḻiyilē.`,
    english: `508: Do not Give to Unworthy; the Giver and the Receiver Both
Reach Hell
You may give away wealth
As massive as a mountain;
Yet if you give it
To those that adore not our Lord,
You shall with them reach
The Seventh Hell of ineffable pain.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-508-Second-Tantra-17.-Ineligibility.mp3',
    elaborationTamil: `தம்மை ஆளுகின்ற தந்தையான இறைவனே மனித வடிவில் வந்து தானம் கொடுக்கின்றான் என்று கைகூப்பித் தொழுது இறைவனை நினைத்துத் தானம் கேட்காதவர்களுக்கு மலையளவு மாபெரும் பொருளை தானமாகத் தந்தாலும் அதனால் ஒரு பயனும் கிடையாது. இறைவனை நினைக்காமல் தானம் கொடுத்தவனும் இறைவனை நினைக்காமல் தானம் பெற்ற இருவருமே ஏழு வித நரகங்களின் குழியை சென்று அடைவார்கள்.`,
  },
  {
    id: 510, tantraId: 2, verseNumber: 509,
    tamil: `உள்ளத்தின் உள்ளே உளபல தீர்த்தங்கள்
மெள்ளக் குடைந்துநின் றாடார் வினைகெடப்
பள்ளமும் மேடும் பரந்து திரிவரே
கள்ள மனமுடைக் கல்வியி லோரே.`,
    transliteration: `uḷḷattiṉ uḷḷē uḷapala tīrttaṅkaḷ
meḷḷak kuṭaintuniṉ ṟāṭār viṉaikeṭap
paḷḷamum mēṭum parantu tirivarē
kaḷḷa maṉamuṭaik kalviyi lōrē.`,
    english: `509: The Holy Waters are Within Us
Within this body are many Holy Waters;
They take not gentle dips in them
And drive Karma away;
Vainly do they roam hill and dale,
Witless men of confused mind they are!`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-509-Second-Tantra-18.-Truth-of-Holy-Water.mp3',
    elaborationEnglish: `Within the body itself there are many water fronts. They are holy. Yet men do not dip in them and get They vainly roam hill and dale in search of purificatory baths The Vedas, including the Rg Veda, emphasize the sacredness of the Waters; Power, ‘Sakti’, resides in them and they are, therefore, highly purifying, and powerful.`,
    elaborationTamil: `உயிர்களின் உள்ளத்துக்குள் பலவித புனித தீர்த்தங்கள் இருக்கின்றன. அவற்றை தியானத்தின் மூலம் மெள்ள ஆராய்ந்து உணர்ந்து அதனுள் மூழ்கிக் குளித்து தங்களின் வினைகளை நீங்க முயற்சி செய்யாமல் தங்களின் வினைகளைக் கழிக்க உலகத்தில் இருக்கும் புனித தீர்த்தங்களைத் தேடி பள்ளத்தாக்குகளுக்கும் மலை மேடுகளுக்கும் அலைந்து திரிகின்றவர்கள் பொய்யான மனதைக் கொண்ட உண்மை ஞானமில்லாதவர்கள். உட்கருத்து: உயிர்களின் உள்ளத்துக்குள் இறைவன் பலவித குணங்களாக இருக்கின்றான். இவற்றை ஆராய்ந்து நல்ல குணங்களை வளர்த்துக் கொண்டு தீய குணங்களை நீக்கிக் கொண்டால் வினைகள் நீங்கி விடும். இதை அறியாமல் உலகத்தில் இருக்கும் நதிகளிலும் குளங்களிலும் குளித்துவிட்டால் எல்லா பாவங்களும் போய்விடும் என்று தம்மைத் தாமே பொய்யாக ஏமாற்றி கொள்ளுபவர்கள் உண்மை ஞானமில்லாதவர்கள்.`,
  },
  {
    id: 511, tantraId: 2, verseNumber: 510,
    tamil: `தளியறி வாளர்க்குத் தண்ணிதாய்த் தோன்றும்
குளியறி வாளர்க்குக் கூடவும் ஒண்ணான்
வளியறி வாளர்க்கு வாய்க்கினும் வாய்க்கும்
தெளியறி வாளர்தம் சிந்தையு ளானே.`,
    transliteration: `taḷiyaṟi vāḷarkkut taṇṇitāyt tōṉṟum
kuḷiyaṟi vāḷarkkuk kūṭavum oṇṇāṉ
vaḷiyaṟi vāḷarkku vāykkiṉum vāykkum
teḷiyaṟi vāḷartam cintaiyu ḷāṉē.`,
    english: `510: Lord Abides in Jnana Thought
To them who love Him dear,
The Lord will appear delicious cool;
To them steeped in worldly pleasures,
He will appear never;
To Yogis who breath control;
But sure does He
In thoughts abide,
Of Jnanis, who doubt-free see.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-510-Second-Tantra-18.-Truth-of-Holy-Water.mp3',
    elaborationTamil: `கோயில்களுக்குச் சென்று இறைவனை வழிபடும் முறையை அறிந்தவர்க்கு இறைவனின் அருள் குளிச்சியாய் தோன்றும். அவனே அந்த கோவிலில் உள்ள தீர்த்தக்குளத்தில் குளித்தால் பாவங்கள் தீர்ந்து விடும் என்றும் இறைவனை அடைந்து விடலாம் என்றும் எண்ணினால் இறைவன் பக்கத்தில் கூட நிற்க மாட்டான். அவனே மூச்சை அடக்கி அளவாக விட்டு முறைப்படி தியானம் செய்யத் தெரிந்து அதை செயல்படுத்தினால் இறைவனின் அருள் கிடைத்தாலும் கிடைக்கும். அவனே தமது உள்ளத்தில் இருக்கும் தீர்த்தத்தை உணர்ந்து தெளிந்து விட்டால் அவன் சிந்தனையில்தான் இறைவன் எப்போதுமே குடிகொண்டிருக்கின்றான்.`,
  },
  {
    id: 512, tantraId: 2, verseNumber: 511,
    tamil: `உள்ளத்தின் உள்ளே உணரும் ஒருவனைக்
கள்ளத்தி னாரும் கலந்தறி வார்இல்லை
வெள்ளத்தை நாடி விடும்அவர் தீவினைப்
பள்ளத்தல் இட்டதோர் பத்துள் ளாமே.`,
    transliteration: `uḷḷattiṉ uḷḷē uṇarum oruvaṉaik
kaḷḷatti ṉārum kalantaṟi vārillai
veḷḷattai nāṭi viṭumavar tīviṉaip
paḷḷattal iṭṭatōr pattuḷ ḷāmē.`,
    english: `511: Men of False Faith do not See Lord Within
The Lord is within them,
Yet they know Him not,
They of faith false;
Limitless the flow of their evil deeds;
Down down the deep drain it goes,
Never its destination to know.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-511-Second-Tantra-18.-Truth-of-Holy-Water.mp3',
    elaborationTamil: `உயிர்கள் தமது உள்ளத்தில் இருக்கும் தீர்த்தத்தில் மூழ்கி குளித்தால் தமக்குள் இருக்கும் இறைவன் ஒருவனை உணரலாம். அந்த இறைவனுக்கு அடியவர் போல நடித்துக் கொண்டாவது அவனோடு கலந்து அவனை அறிந்து கொள்ளுபவர்கள் எவரும் இல்லை. நதிகளுக்கும் குளங்களுக்கும் சென்று மூழ்கி எழுபவர்களது பாவ வினைகள் கிணற்றில் விட்ட ஓட்டைக் குடம் போன்றதே ஆகும். உள்விளக்கம்: ஓட்டையான குடத்தில் எவ்வளவு முறை அள்ளினாலும் தண்ணீர் நிற்காதது போல உலகத்திலுள்ள எத்தனை குளங்களுக்கும் நதிகளுக்கும் சென்று குளித்தாலும் பாவ வினைகள் தீராது.`,
  },
  {
    id: 513, tantraId: 2, verseNumber: 512,
    tamil: `அறிவார் அமரர்கள் ஆதிப் பிரானைச்
செறிவான் உறைபதம் சென்று வலங்கொள்
மறியார் வளைக்கை வருபுனல் கங்கைப்
பொறியார் புனல்மூழ்கப் புண்ணிய ராமே.`,
    transliteration: `aṟivār amararkaḷ ātip pirāṉaic
ceṟivāṉ uṟaipatam ceṉṟu valaṅkoḷ
maṟiyār vaḷaikkai varupuṉal kaṅkaip
poṟiyār puṉalmūḻkap puṇṇiya rāmē.`,
    english: `512: Bathe in Ganga and Be Purified
They who adore Him,
Reach His heavenly abode;
Thus it is,
Immortals know Primal Lord;
Bathe in pellucid waters of Sacred Ganga
That from Lord's crest here descend;
You shall holy become,
Saved of impurities sinful.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-512-Second-Tantra-18.-Truth-of-Holy-Water.mp3',
    elaborationEnglish: `The Ganga, the holiest of waters is within us, even as God is within us. It descends from the Lord’s Crest in sahasrara within the cranium. If we pilgrimage to its banks in the yogic way, we shall bathe in it and be purified of the triple malam.`,
    elaborationTamil: `உயிர்கள் அனைத்துக்குள்ளும் வீற்றிருக்கும் ஆதிமூல நாயகனாகிய இறைவனை தேவர்கள் தங்களுக்குள் இருக்கும் தீர்த்தத்தைத் தேடி அடைந்து அதன் மூலம் தங்களைப் பக்குவப் படுத்திக்கொண்டே அடைந்திருக்கிறார்கள். அது போலவே உயிர்கள் தங்களிடம் இருக்கும் 5 வித தீய குணங்களை நீக்கித் தங்களைப் பக்குவப் படுத்திக்கொண்டு தங்களுக்குள் மூலப்பொறியாக இருக்கும் குண்டலினி சக்தியை மேலெழுப்பிச் சென்று தங்களின் தலைக்குள் இருக்கும் கங்கைத் தீர்த்தத்தில் மூழ்கி எழுந்து விட்டால் புண்ணியர்களாக ஆகலாம். 5 வித தீய குணங்கள் காமம் – மோகம் குரோதம் – கோபம் லோபம் – சுயநலம் மதம் – கர்வம், ஆணவம் மாச்சரியம் – பொறாமை`,
  },
  {
    id: 514, tantraId: 2, verseNumber: 513,
    tamil: `கடலில் கெடுத்துக் குளத்தினில் காண்டல்.
உடலுற்றுத் தேடுவார் தம்மைஒப் பாரிலர்
திடமுற்ற நந்தி திருவரு ளால்சென்று
உடலிற் புகுந்தமை ஒன்றறி யாரே.`,
    transliteration: `kaṭalil keṭuttuk kuḷattiṉil kāṇṭal.
uṭaluṟṟut tēṭuvār tammaiop pārilar
tiṭamuṟṟa nanti tiruvaru ḷālceṉṟu
uṭaliṟ pukuntamai oṉṟaṟi yārē.`,
    english: `513: Seek not Lord Elsewhere; He is Within Thee
They dropped gold in sea,
And looked hard for it in pond;
Nothing indeed to match their folly;
Within you is Nandi,
Firm as rock of ages,
Yet they know Him not, and seek Him not
Lacking in Grace, they sure are.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-513-Second-Tantra-18.-Truth-of-Holy-Water-1.mp3',
    elaborationTamil: `கடலினில் ஒரு பொருளைத் தொலைத்து விட்டு அதை கடலினில் தேடாமல் குளத்தில் தேடி அலைவதைப் போல உடலில் இறைவனே பல தீர்த்தங்களாக இருப்பதை அறியாமல் வெளியே தேடி அலைகின்றனர். உயிர்களின் உயிரை உறுதியாக பற்றிக்கொண்டிருக்கும் குருநாதனாகிய இறைவன் தனது திருவருளால் உடலுக்குள்ளேயே புகுந்து இருப்பதை ஒருவரும் அறியாமல் இருக்கின்றனர்.`,
  },
  {
    id: 515, tantraId: 2, verseNumber: 514,
    tamil: `கலந்தது நீரது உடம்பில் கறுக்கும்
கலந்தது நீரது உடம்பில் சிவக்கும்
கலந்தது நீரது உடம்பில் வெளுக்கும்
கலந்தது நீர்அனல் காற்றது வாமே.`,
    transliteration: `kalantatu nīratu uṭampil kaṟukkum
kalantatu nīratu uṭampil civakkum
kalantatu nīratu uṭampil veḷukkum
kalantatu nīraṉal kāṟṟatu vāmē.`,
    english: `514: Water Within Forms Vital Body Constituent
Water that mixes in body, black urine becomes,
Water that mixes in body, red blood becomes
Water that mixes in body, white semen becomes,
Water that primal arose,
Land, wind and rest of elements became.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-514-Second-Tantra-18.-Truth-of-Holy-Water.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உயிர்கள் பிறக்கும் போது உள்ளத்தில் பலவகை குணங்கள் உள்ளது. அவை தாமசம், இராசதம், சாத்வீகம் என்ற 3 வகை குணங்களுக்கு உட்பட்டவை. தாமச குணங்கள் இருக்கும் போது குண்டலினி சக்தியாக இருக்கும் தீர்த்தமானது கறுப்பாக இருக்கும். இந்த தாமச குணம் இராசத குணங்களாக மேலோங்கும் போது அந்த தீர்த்தமானது சிவப்பாக மாறும். இந்த இராசத குணம் சாத்வீக குணங்களாக மேலோங்கும் போது அந்த தீர்த்தமானது வெளுப்பாகி மேலே சென்று சகஸ்ரதளத்தை அடையும். அவ்வாறு சகஸ்ரதளத்தை அடைந்ததும் தமது உடலாகவும் உடலுக்குள் உயிராகவும் இறைவனே இருப்பதை உயிர்கள் உணரலாம். குணங்களின் விளக்கம்: தாமச குணம் (தாமசம்) – காமம், வெகுளி, மயக்கம், கலக்கம், கோபம், பேராசை, பொய் பேசுதல், இம்சை, யாசித்தல், வெளிவேசம், சிரமம், கலகம், வருத்தம், மோகம், கவலை, தாழ்மை, உறக்கம், அச்சம், சோம்பல், காரணமில்லாமல் பிறரிடம் பொருட்களுக்கு ஆசைப்படுதல் மற்றும் பிறர்க்கு கேடு விளைவிக்கும் செயல்கள் செய்வது, பகட்டுக்காக செயல்கள் செய்வது. இராசத குணம் (இராட்சதம்) – ஊக்கம், ஞானம், வீரம், தருமம், தானம், கல்வி, ஆசை, முயற்சி, இறுமாப்பு, வேட்கை, திமிர், தெய்வங்களிடம் செல்வங்கள் வேண்டுவது, வேற்றுமை எண்ணம், புலனின்பப் பற்று, சண்டைகளில் உற்சாகம், தன் புகழில் ஆசை, மற்றவர்களை எள்ளி நகையாடுவது, பராக்கிரமம், பிடிவாதத்துடன் ஒரு முயற்சியை மேற்கொள்ளுதல். சத்துவ குணம் (சாத்விகம்) – நற்காரியங்களில் மனதைச் செலுத்தும் குணம், மன அடக்கம், புலன் அடக்கம் (தமம்), துன்பங்களைப் பொறுத்துக் கொள்ளும் இயல்பு (சகிப்புத் தன்மை), விவேகம், வைராக்கியம், தவம், வாய்மை, கருணை, மகிழ்ச்சி, நம்பிக்கை, பாவம் செய்வதற்கு கூச்சப்படுதல், தன்னிலேயே மகிழ்ந்திருத்தல், தானம், பணிவு மற்றும் எளிமை. குறிப்பு: இப்படாலில் 4வது வரியில் குறிப்பிட்டுள்ள நீர் அமிர்தத்தையும் நிலம் மண்ணாகிய உடம்பையும் காற்று மூச்சுக்காற்றாகிய உயிரையும் குறிக்கும்.`,
  },
  {
    id: 516, tantraId: 2, verseNumber: 515,
    tamil: `தாவர லிங்கம் பறித்தொன்றில் தாபித்தால்
ஆவதன் முன்னே அரசு நிலைகெடும்
சாவதன் முன்னே பெருநோய் அடுத்திடும்
காவலன் பேர்நந்தி கட்டுரைத் தானே.`,
    transliteration: `tāvara liṅkam paṟittoṉṟil tāpittāl
āvataṉ muṉṉē aracu nilaikeṭum
cāvataṉ muṉṉē perunōy aṭuttiṭum
kāvalaṉ pērnanti kaṭṭurait tāṉē.`,
    english: `515: Dangers of Transplanting Linga
Let them beware who transplant
A Linga at a Shrine 'stablisthed;
Even before the transplant is completed,
The Kingdom will to disaster fall;
And disease fell chased culprit to sure death;
Thus did He declare,
Nandi, the Divine Protector.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-515-Second-Tantra-19.-Demeaning-the-Temple.mp3',
    elaborationEnglish: `Temples are monuments that require to be preserved intact. Let not a linga that has been established be removed from its original site. Dire harm will fall on the culprit.`,
    elaborationTamil: `ஒரு திருக்கோயிலில் உள்ள சுயம்பு சிவலிங்கத்தைப் பெயர்த்தெடுத்துக் கொண்டு போய் வேறொரு திருக்கோயிலில் நிறுவினால் அச்செயல் அந்த வேறொரு திருக்கோயில் கட்டி முடிப்பதற்கு முன்பே அரசனது ஆட்சி நிலைகுலையும். அந்தச் செயலை செய்தவன் இறப்பதற்கு முன்பு தொழுநோய் வந்து துன்புற்று இறப்பான். இவ்வாறு எம் உயிர்க் காவலனாகிய நந்திபெருமான் உறுதிபட கூறினார்.`,
  },
  {
    id: 517, tantraId: 2, verseNumber: 516,
    tamil: `கட்டுவித் தார்மதில் கல்லொன்று வாங்கிடில்
வெட்டுவிக் கும்அபி டேகத்து அரசரை
முட்டுவிக் கும்முனி வேதிய ராயினும்
வெட்டுவித் தேவிடும் விண்ணவன் ஆணையே.`,
    transliteration: `kaṭṭuvit tārmatil kalloṉṟu vāṅkiṭil
veṭṭuvik kumapi ṭēkattu aracarai
muṭṭuvik kummuṉi vētiya rāyiṉum
veṭṭuvit tēviṭum viṇṇavaṉ āṇaiyē.`,
    english: `516: Dangers of Destruction to Temple
As they move away,
A single stone from temple wall
That shall spell the Crowned King's ruin;
Be he a sage, be he one learned in Vedas,
Sure the crisis; certain the ruin;
--So Ordained Lord.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-516-Second-Tantra-19.-Demeaning-the-Temple.mp3',
    elaborationTamil: `திருக்கோயில் சுற்றுச்சுவரைக் கட்டியவரே பின்பு பொருள் மீது ஆசை கொண்டு அந்தச் சுவற்றிலிருந்து ஒரு கல்லை எடுத்தாலும் தவம் புரியும் முனிவரோ வேதங்களைச் சொல்லும் அந்தணரோ என கல்லை எடுத்தவர் யாராக இருந்தாலும் அவர்களையும் அந்தக் குற்றம் நிகழாதவாறு பாதுகாப்பாக வைக்காததால் அப்பொழுது முடிசூடி ஆள்கின்ற அந்நாட்டு அரசனையும் ஆகமங்களை அருளிச்செய்த சிவபெருமானின் ஆணை அழித்துவிடும்.`,
  },
  {
    id: 518, tantraId: 2, verseNumber: 517,
    tamil: `ஆற்றரு நோய்மிக்கு அவனி மழையின்றிப்
போற்றரு மன்னரும் போர்வலி குன்றுவர்
கூற்றுதைத் தான்திருக் கோயில்கள் எல்லாம்
சாற்றிய பூசைகள் தப்பிடில் தானே.`,
    transliteration: `āṟṟaru nōymikku avaṉi maḻaiyiṉṟip
pōṟṟaru maṉṉarum pōrvali kuṉṟuvar
kūṟṟutait tāṉtiruk kōyilkaḷ ellām
cāṟṟiya pūcaikaḷ tappiṭil tāṉē.`,
    english: `517: Dangers of Skipping Performance of Puja
Rains fail; epidemics spread;
All this sure happens,
If worship in Lord's temples falters,
—The Lord who spurned the very God of Death.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-517-Second-Tantra-19.-Demeaning-the-Temple.mp3',
    elaborationTamil: `சிவபெருமானது திருக்கோயில்களில் அன்றாட வழிபாடுகள் சிறப்பு நாள் வழிபாடுகள் (பிரதோஷம் சிவராத்திரி) ஆகியவற்றை முறையாகச் செய்யாமல் விட்டாலோ அல்லது ஆகமங்களில் சொல்லப்பட்ட முறை தவறி அக்கோவில்களில் ஏதேனும் தவறாக செய்தால் அந்த நாட்டில் தீர்க்க முடியாத நோய்கள் பரவும். மழை பெய்யாது. அந்த நாட்டை ஆளும் அரசன் பேரரசனாக இருந்தாலும் தனது எதிரிகளைப் போரில் வெல்லும் வலிமை குறைந்து போய்த் தன் நாட்டையே இழப்பான்.`,
  },
  {
    id: 519, tantraId: 2, verseNumber: 518,
    tamil: `முன்னவ னார்கோயில் பூசைகள் முட்டிடின்
மன்னர்க்குத் தீங்குள வாரி வளம்குன்றும்
கன்னம் களவு மிகுத்திடும் காசினி
என்னரு நந்தி எடுத்துரைத் தானே.`,
    transliteration: `muṉṉava ṉārkōyil pūcaikaḷ muṭṭiṭiṉ
maṉṉarkkut tīṅkuḷa vāri vaḷamkuṉṟum
kaṉṉam kaḷavu mikuttiṭum kāciṉi
eṉṉaru nanti eṭutturait tāṉē.`,
    english: `518: Dangers of Puja Ceasing
When in Siva's temple worship ceases,
Harm befalls the ruler;
Scanty the rains;
Theft and robbery abound in land,
Thus did my Holy Nandi declare.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-518-Second-Tantra-19.-Demeaning-the-Temple.mp3',
    elaborationTamil: `அனைத்திற்கும் முதலாய் இருக்கும் இறைவன் கோவில்களில் தினந்தோறும் நடக்கும் பூஜைகள் தடைப்பட்டால் அந்த நாட்டை ஆளும் மன்னனுக்குத் தீமைகள் உண்டாகும். மழை இல்லாமல் நீர் குறைந்து நாட்டின் வளம் குன்றும். பொறி வைத்து திருடும் திருடர்கள் அதிகரித்து களவு பெருகும். இவ்வாறு உலகத்தில் நடக்கும் என்று எமது குருவாய் இருக்கும் இறைவன் எடுத்துரைத்தான்.`,
  },
  {
    id: 520, tantraId: 2, verseNumber: 519,
    tamil: `பேர்கொண்ட பார்ப்பான் பிரான்தன்னை அர்ச்சித்தால்
போர்கொண்ட வேந்தர்க்குப் பொல்லா வியாதியாம்
பார்கொண்ட நாட்டுக்குப் பஞ்சமு மாம்என்றே
சீர்க்கொண்ட நந்தி தெரிந்துரைத் தானே`,
    transliteration: `pērkoṇṭa pārppāṉ pirāṉtaṉṉai arccittāl
pōrkoṇṭa vēntarkkup pollā viyātiyām
pārkoṇṭa nāṭṭukkup pañcamu māmeṉṟē
cīrkkoṇṭa nanti terinturait tāṉē`,
    english: `519: Puja to be Performed Only by Qualified Priests
If he is but a priest in name
Who, Lord's worship performs,
Deathly wars rage in fury
Fell diseases spread;
Famine stalks land--
Thus did goodly Nandi in truth declare.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-519-Second-Tantra-19.-Demeaning-the-Temple.mp3',
    elaborationTamil: `தான் ஒரு அந்தணன் என்று பெயரை மட்டும் கூறிக்கொண்டு சிவபெருமானிடம் அன்பும் சிவனைப் பற்றிய அறிவும் ஒழுக்கமும் இல்லாத அந்தணன் திருக்கோயிலில் சிவபெருமானுக்குப் பூஜைகள் செய்தால் அக்கோயில் உள்ள நாட்டில் உள்நாட்டுக் கலகங்களும் வெளிநாட்டுப் போர்களும் நடப்பதோடு அந்நாட்டில் கொடிய நோய்களும் விவசாய நிலங்களில் ஒன்றும் விளையாமல் பஞ்சமும் உண்டாகும் என்று எமது குருவாய் இருக்கும் இறைவன் எடுத்துரைத்தான்.`,
  },
  {
    id: 521, tantraId: 2, verseNumber: 520,
    tamil: `எம்பெரு மான்இறை வாமுறை யோஎன்று
வம்பவிழ் வானோர் அசுரன் வலிசொல்ல
அம்பவள மேனி அறுமுகன் போயவர்
தம்பகை கொல்லென்ற தற்பரன் தானே.`,
    transliteration: `emperu māṉiṟai vāmuṟai yōeṉṟu
vampaviḻ vāṉōr acuraṉ valicolla
ampavaḷa mēṉi aṟumukaṉ pōyavar
tampakai kolleṉṟa taṟparaṉ tāṉē.`,
    english: `520: Manifestation of Downward-looking Face
"Hail our Lord! Our God!
Deathly is might of Padmasura
Save us, help, oh!"
Thus did Celestials to Primal Lord pray!;
And the Primal Lord to the Six-faced God
Of coral hue beckoned;
And said, "Proceed and smite the enemy."`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-520-Second-Tantra-20.-Sight-of-Downward-Face.mp3',
    elaborationTamil: `தேவர்களை விட அசுரர்கள் வலிமை பெற்றுத் தேவர்களை துன்புறுத்திட தேவர்கள் சிவபெருமானை நோக்கி எம்பெருமானே இறைவா நாங்கள் அசுரர்களால் துன்பப்படுகின்றோமே இது சரியா எங்களைக் காப்பாற்றுங்கள் என்று கூறி வேண்டிட சிவபெருமான் தற்பரன் நிலையில் நின்று (நெற்றிக் கண் நெருப்பால் அனைத்தையும் அழித்துத் தானே அனைத்திற்கும் மேலானவன் நிரந்தரமானவன் ஆனந்தமானவன் எதனாலும் அழிக்க முடியாதவன் என்கின்ற நிலை) தன் இதயத்திலிருக்கும் ஒளியாகிய அழகிய பவளம் போன்ற திருமேனியுடைய ஆறுமுகனை யாம் அளிக்கும் படையுடன் சென்று தேவர்களின் பகைவர்களான அசுரர்களை அழித்து வருவாயாக என்று கூறினார்.`,
  },
  {
    id: 522, tantraId: 2, verseNumber: 521,
    tamil: `அண்டமொடு எண்டிசை தாங்கும் அதோமுகம்
கண்டங் கறுத்த கருத்தறி வாரில்லை
உண்டது நஞ்சென்று உரைப்பர் உணர்விலோர்
வெண்டலை மாலை விரிசடை யோற்கே.`,
    transliteration: `aṇṭamoṭu eṇṭicai tāṅkum atōmukam
kaṇṭaṅ kaṟutta karuttaṟi vārillai
uṇṭatu nañceṉṟu uraippar uṇarvilōr
veṇṭalai mālai viricaṭai yōṟkē.`,
    english: `521: Blue Throat of Downward-looking Face
He sports the garland of white skulls,
His spreading locks are matted;
He supports Universe vast,
He fills Space in directions eight,
On the throat of His Downward-directed Face
Darkness suffuses;
They say, "He swallowed poison;"
They are ignorant, they know not truth.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-521-Second-Tantra-20.-Sight-of-Downward-Face.mp3',
    elaborationTamil: `சிவபெருமானின் ஐந்து முகங்களில் ஒன்றான அதோமுகம் பூமி அனைத்துக் கோள்கள் பல நட்சத்திரங்கள் உள்ளடக்கிய விண்வெளிப் பிரதேசங்கள் கொண்ட அண்டங்கள் அனைத்தையும் வடக்கு, வடகிழக்கு, கிழக்கு, தென்கிழக்கு, தெற்கு, தென்மேற்கு, மேற்கு, வடமேற்கு என எட்டுத் திசைகளையும் தாங்கிக் கொண்டிருப்பதை யாரும் அறியவில்லை. அதனால்தான் அவருடைய அதோமுகத்திற்கு அடியில் இருக்கும் கழுத்து அண்டவெளியைப் போல கண்டங் கருமையாய் உள்ளது என்கிற உண்மையை யாரும் அறிந்துகொள்ளாமல் சிவபெருமான் நஞ்சை உண்டதால்தான் (அமுதம் எடுக்கப் பாற்கடலை வாசுகி பாம்பினால் கடைந்தபோது வெளிப்பட்ட ஆலகால விஷம்) அவருடைய கழுத்து கருமையாய் இருக்கிறது என்று கூறுவார்கள் அவரை உணராதவர்கள். இதுபோலவே இறந்தவர்களின் ஆன்மாக்களைத் தாங்கிக் கொண்டிருப்பதை உணர்த்தும் வகையில் அவர்களின் வெள்ளை நிறத்திலான மண்டையோடுகளை மாலையாக அணிந்து விரிந்த சடையைக் கொண்டிருக்கும் சிவபெருமானின் தன்மையை யாரும் அறியவில்லை. அதோமுகம்: சிவபெருமானின் அதோமுகம் என்பது சூட்சும உடலில் எங்கும் செல்லும் ஆற்றலை உடையது. தீயவர்களை அழிக்க முற்படும்போது தோன்றுவது அதோமுகம். அதோமுகத்தைக் கொண்ட சிவபெருமான் அழித்தலின் தலைவன் ஆவார். அவர் சூரபதுமன் என்ற அசுரனை அழிக்கத் தன் அதோமுகத்தை வெளிப்படுத்திய போது சக்தி தேவியே அதைக் கண்டு பயந்து மறைந்து கொண்டாள். இந்த அதோமுகத்தை உலக அழிவின் போதும் முருகப்பெருமானைப் படைத்த போதும் உக்கிரமாக வெளிப்படுத்திய சிவன்பெருமான் தன்னை வணங்கும் யோகிகளுக்கும் முனிவர்களுக்கும் அருள் கொடுக்கும் போது மட்டும் சாந்தமாக வெளிப்படுத்துவதே அதோமுக தரிசனம்.`,
  },
  {
    id: 523, tantraId: 2, verseNumber: 522,
    tamil: `செய்தான் அறியுஞ் செழுங்கடல் வட்டத்துப்
பொய்யே யுரைத்துப் புகழும் மனிதர்கள்
மெய்யே உரைக்கில் விண்ணோர் தொழச்செய்வன்
மைதாழ்ந்து இலங்கும் மிடறுடை யோனே.`,
    transliteration: `ceytāṉ aṟiyuñ ceḻuṅkaṭal vaṭṭattup
poyyē yuraittup pukaḻum maṉitarkaḷ
meyyē uraikkil viṇṇōr toḻacceyvaṉ
maitāḻntu ilaṅkum miṭaṟuṭai yōṉē.`,
    english: `522: The Truth of Lord's Blue-Throat
Ye men!,
Who in this sea-girt globe live
In falsehood and flattery!
Why His throat gleams dark,
He knows who made it so;
When you realize the truth
He will make,
Celestial beings bow to you.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-522-Second-Tantra-20.-Sight-of-Downward-Face-1.mp3',
    elaborationEnglish: `Mantras 521 & 522 ; The throat of the Fifth Face is suffused with darkness. Siva is blue-throated. The story goes that He swallowed the deadly © poison that arose at the time of the chumming the 'milky ocean' by the devas and asuras, and that it stayed-in His throat. But the inner meaning is something deeper. Siva alone knows. The knowledge of Truth is verily the goal of realisation.`,
    elaborationTamil: `செழுமையான கடல்களால் சூழப்பட்டிருக்கும் இந்த உலகத்தைப் படைத்த இறைவனுக்கு மனிதர்களில் யாரெல்லாம் தம்மீது உண்மையான பக்தி இல்லாமல் பொய்யாகப் புகழ்ந்து போற்றுகின்றனர் என்பது நன்றாகத் தெரியும். யாரெல்லாம் தம்மீது உண்மையான பக்தி கொண்டு போற்றி வணங்குகின்றார்களோ அவர்களை வாணுலகத்து தேவர்களும் வந்து வணங்கச்செய்வான் அதோமுகம் கொண்ட கருத்த தொண்டையை உடைய இறைவன்.`,
  },
  {
    id: 524, tantraId: 2, verseNumber: 523,
    tamil: `நந்தி எழுந்து நடுவுற ஓங்கிய
செந்தீக் கலந்துள் சிவனென நிற்கும்
முந்திக் கலந்தங்கு உலகம் வலம்வரும்
அந்தி இறைவன் அதோமுகம் ஆமே.`,
    transliteration: `nanti eḻuntu naṭuvuṟa ōṅkiya
centīk kalantuḷ civaṉeṉa niṟkum
muntik kalantaṅku ulakam valamvarum
anti iṟaivaṉ atōmukam āmē.`,
    english: `523: The Downward-Looking Face is of Sadasiva
Inside Primal Fire that is Siva
Nandi rises in the centre, gleaming
He pervads worlds all,
His hue is of the twilight sun
Who the world in glory ambulates,
He is the Lord of the Downward-looking Face--
Athomukha.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-523-Second-Tantra-20.-Sight-of-Downward-Face-1.mp3',
    elaborationTamil: `குண்டலினிசக்தி முதலாவது சக்கரமான மூலாதாரத்திலிருந்து சுழுமுனை (முதுகெலும்பு) வழியாக மேலே ஏறிச்சென்று சிரசிலுள்ள (தலை உச்சி) சகஸ்ரர தளத்தில் உள்ள செஞ்சிவப்பு நிற ஒளியுடன் கலந்து சிவமாகி நிற்கும். அவ்வாறு மேலெழுந்து நின்றவுடன் முன் வினைகள் அனைத்தையும் அழித்து உலகப்பற்றை அறுத்து உலகமும் உடலும் ஒன்றே என்ற நிலையை அடைவித்து ஆட்கொள்வது சிவபெருமானின் அதோமுகம் ஆகும்.`,
  },
  {
    id: 525, tantraId: 2, verseNumber: 524,
    tamil: `அதோமுகம் கீழண்ட மான புராணன்
அதோமுகம் தன்னொடும் எங்கும் முயலும்
சதோமுகத் து ஒண்மலர்க் கண்ணிப் பிரானும்
அதோமுகன் ஊழித் தலைவனு மாமே.`,
    transliteration: `atōmukam kīḻaṇṭa māṉa purāṇaṉ
atōmukam taṉṉoṭum eṅkum muyalum
catōmukat tu oṇmalark kaṇṇip pirāṉum
atōmukaṉ ūḻit talaivaṉu māmē.`,
    english: `524: The Face Creates All
The Ancient One of Athomukha
Created Universe vast here below;
In Athomukha He animates all life;
He is Lord of Athomukha Sakti of lotus eye;
He is Lord of Aeons' End.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-524-Second-Tantra-20.-Sight-of-Downward-Face.mp3',
    elaborationEnglish: `In this aspect-of Five-faced manifestation, Siva is Sadasiva.

It is in this aspect that He creates all the universe, animates all life, conjoint with the Adhomukha Sakti of lotus eyes.`,
    elaborationTamil: `ஆதியான அதோமுகம் கொண்ட சிவபெருமான் தனது அதோமுகத் தத்துவத்தில் தனக்குக் கீழே உள்ள அண்டம் முழுவதும் எங்கும் வியாபித்திருக்கின்றார். அவரே ஓம் எனும் பிரணவ ஒலியை மாலையாக அணிந்துகொண்டு அழித்தலின் தலைவனாகவும் நின்று அருள் புரிகின்றார்.`,
  },
  {
    id: 526, tantraId: 2, verseNumber: 525,
    tamil: `அதோமுகம் மாமல ராயது கேளும்
அதோமுகத் தால் ஒரு நூறாய் விரிந்து
அதோமுகம் ஆகிய அந்தமில் சத்தி
அதோமுகம் ஆகி அமர்ந்திருந் தானே.`,
    transliteration: `atōmukam māmala rāyatu kēḷum
atōmukat tāl oru nūṟāy virintu
atōmukam ākiya antamil catti
atōmukam āki amarntirun tāṉē.`,
    english: `525: It Blossomed Into a Hundred Worlds and Impregnated Them With Energy
Hearken to this,
How Athomukha blossomed into a Gigantic Flower
Then, it transformed itself into a hundred worlds;
And into Limitless Energy
Animating them;
And then as Athomukha,
The Lord remained as their Support as well.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-525-Second-Tantra-20.-Sight-of-Downward-Face.mp3',
    elaborationTamil: `அதோமுகம் பெரிய தாமரை மலராக மாறிய அதிசயத்தைக் கேளுங்கள். பாடல் 523 ல் உள்ளபடி குண்டலினி சக்தி உயிர்களின் தலையின் உச்சியிலுள்ள சகஸ்ரர தளத்தை அடைந்து நூற்றுக்கணக்கான இதழ்களைக் கொண்ட தாமரை மலராக விரிந்தவுடன் அழிவில்லாத சக்தியாகி அந்த சிவபெருமானே அதோமுகமாகி அமர்ந்திருக்கின்றார்.`,
  },
  {
    id: 527, tantraId: 2, verseNumber: 526,
    tamil: `தெளிவுறு ஞானத்துச் சிந்தையின் உள்ளே
அளிவுறு வார்அம ராபதி நாடி
எளியனென்று ஈசனை நீசர் இகழில்
கிளியொன்று பூஞையால் கீழது வாகுமே.`,
    transliteration: `teḷivuṟu ñāṉattuc cintaiyiṉ uḷḷē
aḷivuṟu vārama rāpati nāṭi
eḷiyaṉeṉṟu īcaṉai nīcar ikaḻil
kiḷiyoṉṟu pūñaiyāl kīḻatu vākumē.`,
    english: `526: Abuse of Siva Brings Misery
Those who have Jnana attained,
Rid of all doubts in their thoughts
Seek Him in love intense
Shall reach the World of Celestials;
If the low-born think any the less of Him,
Dismal indeed is their fate--
Unto the parrot in cat's claw.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-526-Second-Tantra-21.-Demeaning-Shiva.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `தெளிந்த ஞானம் உள்ளவர்கள் சிந்தனை செய்து தமக்குள்ளே இருக்கும் தேவர்களுக்கெல்லாம் தலைவனாகிய சிவபெருமானை உணர்ந்து அவருடைய அருளைப் பெறுவார்கள். தெளிந்த ஞானமில்லாத கீழான மக்கள் அச்சிவபெருமானை சிறுதெய்வமாக எண்ணி இகழ்ந்து புறக்கணித்தால் அவர்களின் நிலை பூனையால் கிழிக்கப்பட்ட கிளிபோல ஆகும்.`,
  },
  {
    id: 528, tantraId: 2, verseNumber: 527,
    tamil: `முளிந்தவர் வானவர் தானவர் எல்லாம்
விளிந்தவர் மெய்ந்நின்ற ஞானம் உணரார்
அளிந்தமுது ஊறிய ஆதிப் பிரானைத்
தளிந்தவர்ககு அல்லது தாங்கஒண் ணாதே.`,
    transliteration: `muḷintavar vāṉavar tāṉavar ellām
viḷintavar meynniṉṟa ñāṉam uṇarār
aḷintamutu ūṟiya ātip pirāṉait
taḷintavarkaku allatu tāṅkaoṇ ṇātē.`,
    english: `527: Adore Lord and Attain Jnana
The Devas and Asuras wasted their lives
And finally died;
They attained not Jnana true;
They alone can attain Truth
Who adore Primal Lord in devotion intense.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/527a.mp3',
    elaborationTamil: `ஆசையால் அனுபவித்து வாடிப்போன தேகத்தை உடையவர்கள், தேவர்கள் அசுரர்கள் ஆகியவர்கள் உண்மை ஞானத்தை உணரவில்லையென்றால் இறந்தவர்களைப் போலானவர்களே. அன்பினால் கசிந்து அமுதம்போல் சுரக்கும் ஆதியாகிய சிவபெருமானைத் தன் உள்ளக் கோவிலில் வைத்து வழிபடுபவர்களால் மட்டுமே உண்மையான ஞானத்தைப் பெற இயலும்.`,
  },
  {
    id: 529, tantraId: 2, verseNumber: 528,
    tamil: `அப்பகை யாலே அசுரரும் தேவரும்
நற்பகை செய்து நடுவே முடிந்தனர்
எப்பகை யாகிலும் எய்தார் இறைவனைப்
பொய்ப்பகை செய்யினும் ஒன்றுபத் தாமே.`,
    transliteration: `appakai yālē acurarum tēvarum
naṟpakai ceytu naṭuvē muṭintaṉar
eppakai yākilum eytār iṟaivaṉaip
poyppakai ceyyiṉum oṉṟupat tāmē.`,
    english: `528: Abuse not Siva Even in Fun
They defied the Lord,
Devas and Asuras,
And they defied themselves one another
And destruction met;
However little, defy not Lord,
Not even for fun,
They snow-ball, one into ten.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/528b.mp3',
    elaborationTamil: `அறியாமையால் வரும் அகங்காரத்தினால் தேவர்களும் அசுரர்களும் சிவபெருமானுடன் பகைமை கொண்டு விரைவில் அழிந்து போனார்கள். சிவபெருமானுடன் எந்த வகையான பகைமை கொண்டாலும் அவரை அடைய முடியாது. அது பொய்யான பகையாக இருந்தாலும் அதனால் வரும் தீமை ஒன்றுக்குப் பத்து மடங்காகப் பெருகி அழிக்கும்.`,
  },
  {
    id: 530, tantraId: 2, verseNumber: 529,
    tamil: `போகமும் மாதர் புலவி அதுநினைந்து
ஆகமும் உள்கலந்து அங்குஉள ராதலில்
வேதிய ராயும் விகிர்தன்நாம் என்கின்ற
நீதியுள் ஈசன் நினைப்பொழி வாரே.`,
    transliteration: `pōkamum mātar pulavi atuniṉaintu
ākamum uḷkalantu aṅkuuḷa rātalil
vētiya rāyum vikirtaṉnām eṉkiṉṟa
nītiyuḷ īcaṉ niṉaippoḻi vārē.`,
    english: `529: Dare not Forget Lord However Holy
Learned are they in Vedic lore;
Knowing God is within them,
They bethought themselves to be God
And Plunged into pleasures distracting
Forgetting all thought of God.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/529.mp3',
    elaborationEnglish: `Remember the fate that overtook the rishis that were learned in the Vedic lore. Postulating that God is within them, they presumed they themselves were God, and so plunged into distracting pleasures, forgetting all thought -of the Lord. (The reference here is to the rishis of Daruka forest, who ignored Siva and performed unholy sacrifice.)`,
    elaborationTamil: `மாதருடன் கூடியும் ஊடியும் அச்சிறிய இன்பத்தையே நினைத்து அந்த வேட்கையை உள்ளத்தில் வைத்திருப்பவர்கள் வேதம் கற்று அறிந்த வேதியர்களாக இருந்தாலும் தாமே இன்னொரு உயிரை உருவாக்குகின்றோம் என்கின்ற தவறான எண்ணத்தில் சிவபெருமானைப் பற்றிய எண்ணங்களை மறந்து விடுவார்கள். உள்விளக்கம்: மாதர் இன்பத்தை நினைத்து இறைவனை மறப்பதும் சிவநிந்தையே ஆகும்.`,
  },
  {
    id: 531, tantraId: 2, verseNumber: 530,
    tamil: `பெற்றிருந் தாரையும் பேணார் கயவர்கள்
உற்றிருந் தாரை உளைவன சொல்லுவர்
கற்றிருந் தார்வழி உற்றிருந் தாரவர்
பெற்றிருந் தார்அன்றி யார்பெறும் பேறே.`,
    transliteration: `peṟṟirun tāraiyum pēṇār kayavarkaḷ
uṟṟirun tārai uḷaivaṉa colluvar
kaṟṟirun tārvaḻi uṟṟirun tāravar
peṟṟirun tāraṉṟi yārpeṟum pēṟē.`,
    english: `530: The True Disciples are Blessed
The lowly ones
Care not for their parents,
They abuse their kith and kin and words foul
Nor do they follow the Guru's behest
Only those who revere the parents, kith and kin and the Guru
Are in truth blessed, none else indeed.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-530-Second-Tantra-22.-Demeaning-Guru.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `ஞானத்தை அறிந்த பெரியோர்களை மதிக்காத கீழான எண்ணமுடையவர்கள் அப்பெரியோர்களின் உடனிருப்பவர்களையும் வருந்தும்படி கீழ்மையாக பேசுபவர்கள் ஆகிய இவர்கள் ஞானமில்லாமல் கல்வியை மட்டுமே அறிந்தவர்களின் வழியில் சென்று ஞானம் கிடைக்கும் என்ற எண்ணத்தில் ஞானத்தை அடைய முயற்சிப்பார்கள். ஞானத்தை அறிந்த பெரியோர்களால் கிடைக்காத ஞானம் வேறு யாரிடம் கிடைக்கும்?`,
  },
  {
    id: 532, tantraId: 2, verseNumber: 531,
    tamil: `ஓரெழுத்து ஒருபொருள் உணரக் கூறிய
சீரெழுத் தாளரைச் சிதையச் செப்பினோர்
ஊரிடைச் சுணங்கனாய்ப் பிறந்தங் கு ஓர்உகம்
வாரிடைக் கிருமியாய் பழகுவர் மண்ணிலே.`,
    transliteration: `ōreḻuttu oruporuḷ uṇarak kūṟiya
cīreḻut tāḷaraic citaiyac ceppiṉōr
ūriṭaic cuṇaṅkaṉāyp piṟantaṅ ku ōrukam
vāriṭaik kirumiyāy paḻakuvar maṇṇilē.`,
    english: `531: Consequences of Abusing Guru
The Guru taught the wisdom
Of One-Letter mantra (Aum);
He who speaks derisive of Him
Will be born a lowly Cur;
And having led a dog's life for a Yuga entire,
He will be a worm born;
And then to dust shall be consigned.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-531-Second-Tantra-22.-Demeaning-Guru.mp3',
    elaborationTamil: `ஓம் என்ற பிரணவ மந்திரத்தின் பொருளை சீடனுக்கு உணர்த்திய குருவின் பெருமை குலையும்படி தவறாகப் பேசுகின்ற சீடர்கள் ஊர் சுற்றித் திரியும் நோயுள்ள நாயாகப் பிறந்து பின்னர் ஒரு யுகத்திற்குப் பூமியில் புழுவாக கிடப்பார்கள்.`,
  },
  {
    id: 533, tantraId: 2, verseNumber: 532,
    tamil: `பத்தினி பத்தர்கள் தத்துவ ஞானிகள்
சித்தங் கலங்கச் சிதைவுகள் செய்தவர்
அத்தமும் ஆவியும் ஆண்டொன்றில் மாண்டிடும்
சத்தியம் ஈது சதாநந்தி ஆணையே.`,
    transliteration: `pattiṉi pattarkaḷ tattuva ñāṉikaḷ
cittaṅ kalaṅkac citaivukaḷ ceytavar
attamum āviyum āṇṭoṉṟil māṇṭiṭum
cattiyam ītu catānanti āṇaiyē.`,
    english: `532: Consequences of Abusing the Good
The virtuous wife, devotee true, and Jnani Great
Those who have done exceeding harm to shock them
Their life and wealth will in a year disappear,
True this is,
Upon Holy Nandi, I swear.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-532-Second-Tantra-22.-Demeaning-Guru.mp3',
    elaborationTamil: `இல்லறத்தில் இருக்கும் ஞானிகள் மற்றும் இறை தத்துவத்தை உணர்ந்த ஞானிகளை அவர்களுடைய மனம் வருந்தும்படி தீங்கு செய்தவர்களின் சொத்துக்களும் உயிரும் ஒரே ஆண்டில் அழிந்துவிடும் இது உண்மை இதுவே சதாசிவத்தின் ஆணை.`,
  },
  {
    id: 534, tantraId: 2, verseNumber: 533,
    tamil: `மந்திரம் ஓரெழுத்து உரைத்த மாதவர்
சிந்தையில் நொந்திடத் தீமைகள் செய்தவர்
நுந்திய சுணங்கனாய்ப் பிறந்து நூறுரு
வந்திடும் புலையராய் மாய்வர் மண்ணிலே.`,
    transliteration: `mantiram ōreḻuttu uraitta mātavar
cintaiyil nontiṭat tīmaikaḷ ceytavar
nuntiya cuṇaṅkaṉāyp piṟantu nūṟuru
vantiṭum pulaiyarāy māyvar maṇṇilē.`,
    english: `533: Do not Abuse Guru
Those who wounded feelings,
Of Holy Guru who taught,
The One-lettered mantra, "AUM"
Will be a dog born,
And after a hundred dog incarnations
Will die a human out-caste.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-533-Second-Tantra-22.-Demeaning-Guru.mp3',
    elaborationTamil: `ஓம் என்ற பிரணவ மந்திரத்தில் பெரிய தவங்களைச் செய்தவர்களின் மனம் வருந்தும்படி தீமைகள் செய்தவர்கள் பசியால் வருந்தி அலைகின்ற நாயாகப் பிறந்து பின்னர் மனிதப் பிறவி எடுத்தாலும் எண்ணில் அடங்காத தாழ்ந்த பிறப்பு எடுத்து இறப்பார்கள்.`,
  },
  {
    id: 535, tantraId: 2, verseNumber: 534,
    tamil: `ஈசன் அடியார் இதயம் கலங்கிடத்
தேசமும் நாடும் சிறப்பும் அழிந்திடும்
வாசவன் பீடமும் மாமன்னர் பீடமும்
நாசமது ஆகுமே நம்நந்தி ஆணையே.`,
    transliteration: `īcaṉ aṭiyār itayam kalaṅkiṭat
tēcamum nāṭum ciṟappum aḻintiṭum
vācavaṉ pīṭamum māmaṉṉar pīṭamum
nācamatu ākumē namnanti āṇaiyē.`,
    english: `534: Harm to World by Maltreatment of Gurus
If Gurus who are devout of God
Are caused pain in heart
The country, people and their greatness
Will all as one destroyed be;
The thrones of heavenly king Indra,
And of kings mighty here below,
Will alike Crumble down;
Sure This is,
I swear by our Nandi true.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-534-Second-Tantra-22.-Demeaning-Guru.mp3',
    elaborationTamil: `சிவனடியார்கள் மனம் வருந்தினால் அவர்களிருக்கும் நாடும் அது தேடும் பெருமைகளும் அழிந்துபோகும். அதுமட்டுமில்லாமல் இந்திரனது ஆட்சியும் பேரரசர்களுடைய ஆட்சியும் அதற்குப் பொறுப்பாகி அழிந்துவிடும் என்பது சிவபெருமானின் ஆணையாகும்.`,
  },
  {
    id: 536, tantraId: 2, verseNumber: 535,
    tamil: `சன்மார்க்க சற்குருச் சந்நிதி பொய்வாரின்
நன்மார்க்க மும்குன்றி ஞானமும் தங்காது
தொன்மார்க்க மாய துறையும் மறந்திட்டுப்
பன்மார்க்க மும்கெட்டுப் பஞ்சமும் ஆமே.`,
    transliteration: `caṉmārkka caṟkuruc canniti poyvāriṉ
naṉmārkka mumkuṉṟi ñāṉamum taṅkātu
toṉmārkka māya tuṟaiyum maṟantiṭṭup
paṉmārkka mumkeṭṭup pañcamum āmē.`,
    english: `535: Do not Utter False-hood in Gurus Presence
Utter not falsehood in holy Guru's presence;
Then will goodness and wisdom depart;
Forgotten will be,
The time-honoured path of righteousness,
And all else that to prosperity leads;
The land a prey to famine falls.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-535-Second-Tantra-22.-Demeaning-Guru.mp3',
    elaborationTamil: `உண்மையான ஞான வழியைக் கூறிய குருவின் முன்பாகப் பொய் பேசினால் இருக்கும் நல்லொழுக்கம் குறைந்து போவது மட்டுமன்றி அவர் கொடுத்த ஞானமும் அழிந்துவிடும். தொன்றுதொட்டு (பழங்காலத்திலிருந்து) வருகின்ற ஞானத்தை அடையும் வழிகளும் மறந்துபோய் ஆத்ம வளர்ச்சிக்கான பிற வழிகளும் அழிந்து போய் வறுமையும் உண்டாகும்.`,
  },
  {
    id: 537, tantraId: 2, verseNumber: 536,
    tamil: `கைப்பட்ட மாமணி தானிடை கைவிட்டு
மெய்ப்பட்ட கல்லைச் சுமப்போன் விதிபோன்றும்
கைப்பட்ட நெய்பால் தயிர்நிற்கத் தானறக்
கைப்பிட்டுண் பான்போன்றுங் கன்மிஞானிக் கொப்பே.`,
    transliteration: `kaippaṭṭa māmaṇi tāṉiṭai kaiviṭṭu
meyppaṭṭa kallaic cumappōṉ vitipōṉṟum
kaippaṭṭa neypāl tayirniṟkat tāṉaṟak
kaippiṭṭuṇ pāṉpōṉṟuṅ kaṉmiñāṉik koppē.`,
    english: `536: Jnana Guru is the Real Guru
Who will throw away the precious Gem in hand
And carry a heavy stone instead?
Who will part with milk, curd and ghee on hand
And prefer the bitter poison, fatal?
Such indeed are the Gurus of Karma path;
Will they ever with Jnani compare?`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-536-Second-Tantra-22.-Demeaning-Guru.mp3',
    elaborationTamil: `ஞானத்தைப் பெற்ற குரு இருக்கும் போது அவரை விட்டுவிட்டு கர்மத்தின் வழியில் நடப்பவரை குருவாக ஏற்பது கையில் இருக்கும் மாணிக்கத்தைத் தவற விட்டுவிட்டு காலில் பட்ட கல்லை எடுத்துச் சுமப்பவரின் விதியைப் போன்றதாகும். அதுமட்டுமின்றி கையில் இருக்கும் நெய், பால், தயிரை விட்டுவிட்டு தனக்கு நன்மை தராத உணவை சாப்பிடுவது போன்றதாகும்.`,
  },
  {
    id: 538, tantraId: 2, verseNumber: 537,
    tamil: `ஆண்டான் அடியவர் ஆர்க்கும் விரோதிகள்
ஆண்டான் அடியவர் ஐயமேற் றுண்பவர்
ஆண்டான் அடியரை வேண்டாது பேசினோர்
தாம்தாம் விழுவது தாழ்நர காமே.`,
    transliteration: `āṇṭāṉ aṭiyavar ārkkum virōtikaḷ
āṇṭāṉ aṭiyavar aiyamēṟ ṟuṇpavar
āṇṭāṉ aṭiyarai vēṇṭātu pēciṉōr
tāmtām viḻuvatu tāḻnara kāmē.`,
    english: `537: Consequences of Abusing Mahesvara
The Lord's devotee lives by alms,
Those who show animus to him,
However humble his condition be,
And those who abuse him as they will,
Shall into lowly hell fall.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-537-Second-Tantra-23.-Demeaning-Lord-Shiva.mp3',
    elaborationTamil: `உலகத்தவர்களிடம் எந்தப் பற்றும் இல்லாத சிவனடியார்கள் யாருக்கு விரோதிகள்? தங்கள் வயிற்றுப் பசிக்குப் பிச்சை எடுத்து உண்ணும் அந்த அடியவர்களை தான் கொண்ட வெறுப்பினால் இகழ்ந்து பேசுபவர்கள் தமக்குத் தாமே செய்துகொண்ட தீவினையால் நரகத்திலேயே மிகவும் கொடியதான கடைசி நிலை நரகத்தில் சென்று விழுவார்கள்.`,
  },
  {
    id: 539, tantraId: 2, verseNumber: 538,
    tamil: `ஞானியை நிந்திப் பவனும் நலன் என்றே
ஞானியை வந்திப் பவனுமே நல்வினை
யான கொடுவினை தீர்வார் அவன்வயம்
போன பொழுதே புகுஞ்சிவ போகமே.`,
    transliteration: `ñāṉiyai nintip pavaṉum nalaṉ eṉṟē
ñāṉiyai vantip pavaṉumē nalviṉai
yāṉa koṭuviṉai tīrvār avaṉvayam
pōṉa poḻutē pukuñciva pōkamē.`,
    english: `538: Blessings of Jnani's Presence
Those who deride Jnani
Are rid of benefits of goodly deeds done;
Those who revere him as holy,
Are rid of harm of evil deeds done;
Those who reach Jnani's presence.
Will verily taste of Siva Bhoga.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-538-Second-Tantra-23.-Demeaning-Lord-Shiva.mp3',
    elaborationTamil: `சிவஞானியை நிந்தித்தலே (திட்டுதலே) நல்லது என்றுத் தவறாக நினைத்து நிந்திப்பவர்களுக்கு இருக்கும் நல்ல வினைகளும் தீய வினைகளாக மாறி துன்புறுவார்கள். சிவஞானியை வந்தித்தலே (வணங்குதலே) நல்லது என்று நினைத்து வணங்கியவர்களுக்கு இருக்கும் தீய வினைகளும் நல்ல வினைகளாக மாறி சிவஞானிகளின் அடியவர்களாக ஆகியவுடன் அவர்களின் அருளால் பேரின்பமான சிவபோகத்தை அடைவார்கள்.`,
  },
  {
    id: 540, tantraId: 2, verseNumber: 539,
    tamil: `பற்றிநின் றார்நெஞ்சில் பல்லிதான் ஒன்றுண்டு
முற்றிக் கிடந்தது மூக்கையும் நாவையும்
தெற்றிக் கிடந்து சிதைக்கின்ற சிந்தையுள்
வற்றா தொழிவது மாகமை யாமே.`,
    transliteration: `paṟṟiniṉ ṟārneñcil pallitāṉ oṉṟuṇṭu
muṟṟik kiṭantatu mūkkaiyum nāvaiyum
teṟṟik kiṭantu citaikkiṉṟa cintaiyuḷ
vaṟṟā toḻivatu mākamai yāmē.`,
    english: `539: Patience is the Sheet-anchor of Yogis
In the hearts of those who are firm of mind
Lie the (Varmamus) lizard of Yoga Vairagya
It lay besieging nose and tongue--(in Kesari Mudra)
In the troubled thought that knows but torture,
The only thing that stands still
Is devotional Patience Exceeding.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-539-Second-Tantra-24.-Virtue-of-Patience.mp3',
    elaborationTamil: `உண்மை வழியைப் பற்றி அதிலிருந்து விலகாமல் நிற்கும் யோகியர்களின் நெஞ்சில் இறைவனோடு இரண்டறக் கலக்கவேண்டும் என்கின்ற எண்ணம் இருக்கின்றது. பல்லி எப்படி தான் பற்றியதை விடாதோ அதுபோல எண்ணமும் தான் எண்ணியதை விடாது. இந்திரியங்களை (மூக்கின் வழியாக பிராணாயாமமும், நாக்கின் வழியாக மந்திரமும்) அடக்கி சிந்தனையை பல எண்ணங்களில் வீணாக சிதறவிடாமல் பொறுமையாக இருப்பவர்களுக்கு வற்றாத அமுதம் சுரக்கும்.`,
  },
  {
    id: 541, tantraId: 2, verseNumber: 540,
    tamil: `ஓலக்கம் சூழ்ந்த உலப்பிலி தேவர்கள்
பாலொத்த மேனியன் பாதம் பணிந்துய்ய
மாலுக்கும் ஆதி பிரமற்கும் மன்னவன்.
ஞாலத் திவன்மிக நல்லன்என் றாரே`,
    transliteration: `ōlakkam cūḻnta ulappili tēvarkaḷ
pālotta mēṉiyaṉ pātam paṇintuyya
mālukkum āti piramaṟkum maṉṉavaṉ.
ñālat tivaṉmika nallaṉeṉ ṟārē`,
    english: `540: Celestial Beings Worship Lord
The Lord was seated on His throne;
He was of milk-white hue;
Surrounding Him stood
Celestial Beings in number countless;
Hari and Brahma too,
Whose King He is;
And low they bowed at His Feet,
And prayed for His Grace,
And the Lord blessed,
"They shall on earth prosper high."`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-540-Second-Tantra-24.-Virtue-of-Patience.mp3',
    elaborationTamil: `சிவபெருமானின் திருச்சபையைச் சுற்றி இருக்கும் அழிவில்லாத தேவர்கள் அவரின் பால் போன்ற வெண்ணிற உடலின் பாதத்தைப் பணிந்து தாங்கள் முக்தி பெற வேண்டி பொறுமையுடன் காத்திருப்பார்கள். அவ்வாறு பொறுமையுடன் இருக்கும் தேவர்களை திருமாலுக்கும் ஆதிபிரம்மனுக்கும் மன்னராக இருக்கின்ற சதாசிவமூர்த்தி உலகத்தில் மிகவும் நல்லவர்கள் என்று அருளினார்.`,
  },
  {
    id: 542, tantraId: 2, verseNumber: 541,
    tamil: `ஞானம் விளைந்தவர் நம்மிடம் மன்னவர்
சேனை வளைந்து திசைதொரும் கைதொழ
ஊனை விளைத்திடும் உம்பர்தம் ஆதியை
ஏனை விளைந்தருள் எட்டலு மாமே.`,
    transliteration: `ñāṉam viḷaintavar nammiṭam maṉṉavar
cēṉai vaḷaintu ticaitorum kaitoḻa
ūṉai viḷaittiṭum umpartam ātiyai
ēṉai viḷaintaruḷ eṭṭalu māmē.`,
    english: `541: Lord Grants Grace to Those Who Adore Him
The Lord is of wisdom ripe;
He is our King,
As unto an army they swell,
In directions all to pray;
He creates the fleshly body,
He is the Primal One of Celestials.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-541-Second-Tantra-24.-Virtue-of-Patience.mp3',
    elaborationEnglish: ``,
    elaborationTamil: `உண்மை ஞானம் அடைந்தவர்கள் உலகத்தில் இருக்கும் உயிர்களுக்கு மன்னர்கள் ஆவார்கள். படைகள் எவ்வாறு மன்னரைச் சுற்றி நின்று கைகூப்பி வணங்குவார்களோ அதுபோல உண்மை ஞானம் அடைந்தவர்களை ஞானம் பெறவேண்டி பொறுமையுடன் வணங்கி நிற்பவர்கள் தேவர்களுக்குத் தலைவனும் உயிர்களின் உடலை வளர்ப்பவனுமாகிய ஆதி சிவபெருமானின் அருளை அடைவார்கள்.`,
  },
  {
    id: 543, tantraId: 2, verseNumber: 542,
    tamil: `வல்வகை யானும் மனையிலும் மன்றிலும்
பல்வகை யானும் பயிற்றி பதஞ்செய்யும்
கொல்லையி னின்று குதிகொள்ளும் கூத்தனுக்கு
எல்லையி லாத இலயம்உண் டாமே.`,
    transliteration: `valvakai yāṉum maṉaiyilum maṉṟilum
palvakai yāṉum payiṟṟi patañceyyum
kollaiyi ṉiṉṟu kutikoḷḷum kūttaṉukku
ellaiyi lāta ilayamuṇ ṭāmē.`,
    english: `542: Lord's Patience
Inside home and outside
By force and means gentle
The Lord prepared you--(in patience surpassing)
He dances on the burning ground;
Many and varied are His play.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-542-Second-Tantra-24.-Virtue-of-Patience.mp3',
    elaborationTamil: `ஆன்மாக்களின் பக்குவத்திற்கேற்ப உடலிலும் உள்ளத்திலும் பலவகையில் இன்பங்களையும் துன்பங்களையும் கொடுத்து பக்குவம் செய்யும் சிவபெருமான் பொறுமையுடன் தவமிருப்பவர்களின் மூலாதாரத்தில் இருந்து திருக்கூத்து ஆடுவதின் பயனால் அவர்களின் மனம் இறைவனுடன் ஒன்றுபட்டு நிற்கும்.`,
  },
  {
    id: 544, tantraId: 2, verseNumber: 543,
    tamil: `ஓடவல் லார்தம ரோடு நடாவுவன்
பாடவல் லாரொலி பார்மிசை வாழ்குவன்
தேடவல் லார்க்கருள் தேவர் பிரானொடும்
கூடவல் லாரடி கூடுவன் யானே.`,
    transliteration: `ōṭaval lārtama rōṭu naṭāvuvaṉ
pāṭaval lāroli pārmicai vāḻkuvaṉ
tēṭaval lārkkaruḷ tēvar pirāṉoṭum
kūṭaval lāraṭi kūṭuvaṉ yāṉē.`,
    english: `543: Walk With the Holy
I walk with those who go after God,
I live with those who sing His praise,
The Lord blesses those who seek Him,
With them I consort,
Their feet I seek.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-543-Second-Tantra-25.-Seeking-the-Sages.mp3',
    elaborationTamil: `திருத்தலங்களில் யாத்திரை செய்பவர்களுடன் யானும் நடப்போம். இறைவனை பக்தியுடன் பாடக்கூடியவர்களின் பாடலைக் கேட்டு யானும் இன்புற்று இருப்போம். இறைவனைத் தனக்குள்ளே தேடி அடையக்கூடியவர்களுக்கு அருளுகின்ற மகாதேவனுடன் இணையக் கூடிய ஆற்றலுள்ள பெரியோர்களின் திருவடியோடு யானும் இணைந்து இருப்போம். உட்கருத்து: இறைவனை அடையக்கூடிய வழிகளில் செல்பவர்களுக்கு இறைவனே பெரியவராக உடன் இருந்து இறைவனை அடைய வழிகாட்டுவார்.`,
  },
  {
    id: 545, tantraId: 2, verseNumber: 544,
    tamil: `தாமிடர்ப் பட்டுத் தளிர்போல் தயங்கினும்
மாமனதது அங்குஅன்பு வைத்தது இலையாகும்
நீஇடர்ப் பட்டிருநது என்செய்வாய் நெஞ்சமே
போமிடத் து என்னொடும் போதுகண் டாயே.`,
    transliteration: `tāmiṭarp paṭṭut taḷirpōl tayaṅkiṉum
māmaṉatatu aṅkuaṉpu vaittatu ilaiyākum
nīiṭarp paṭṭirunatu eṉceyvāy neñcamē
pōmiṭat tu eṉṉoṭum pōtukaṇ ṭāyē.`,
    english: `544: Holy Company Saves You From Distress
You may in distress
Unto a tender leaf quiver,
What avails you if you are distressed,
My Heart!
Yet you love not Lord;
Do you go with me,
To where the Lord succours.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-544-Second-Tantra-25.-Seeking-the-Sages.mp3',
    elaborationTamil: `மனமே நீ வருத்தப்படும் காலங்களில் படர்வதற்குப் பிடிமானம் இல்லாத செடிபோல வாடினாலும் இறைவன் மீது நம்பிக்கை வைத்தது இல்லை. இப்படித் தனியாக வருத்தப்பட்டு என்ன செய்யப் போகின்றாய்? இறைவனை நோக்கி யாம் செல்லும்போது எம்மோடு வந்து உன் துன்பங்கள் போவதைக் காண்பாயாக.`,
  },
  {
    id: 546, tantraId: 2, verseNumber: 545,
    tamil: `அறிவார் அமரர் தலைவனை நாடிச்
செறிவார் பெறுவர் சிலர்தத் துவத்தை
நெறிதான் மிகமிக நின்றருள் செய்யும்
பெரியார் உடன்கூடல் பேரின்ப மாமே.`,
    transliteration: `aṟivār amarar talaivaṉai nāṭic
ceṟivār peṟuvar cilartat tuvattai
neṟitāṉ mikamika niṉṟaruḷ ceyyum
periyār uṭaṉkūṭal pēriṉpa māmē.`,
    english: `545: Holy Company Leads You to Bliss
The Jnanis seek the Lord of Celestials;
They who seek the Company of Jnanis
Will attain Siva Truth;
They indeed Walk in the Path of Virtue
And are truly blessed;
To consort with such
Is indeed Bliss Supreme.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-545-Second-Tantra-25.-Seeking-the-Sages.mp3',
    elaborationTamil: `தேவர்களின் தலைவனான சிவபெருமானை உணர்ந்த பெரியோர்களைத் தேடிச் சென்று அவர்களோடு இணைந்து இருப்பவர்கள் சிவதத்துவத்தைப் பெறுவார்கள். இறைவனை அடையத் தாம் எடுத்துக் கொண்ட நெறியிலிருந்து மாறாமல் நின்று அருள் செய்யும் பெரியாரோடு சேர்ந்திருப்பதே பேரின்பமாகும்.`,
  },
  {
    id: 547, tantraId: 2, verseNumber: 546,
    tamil: `தார்சடை யான்தன் தமராய் உலகினில்
போர புகழா எந்தை பொன்னடி சேருவர்
வாயடை யாவுள்ளம் தேர்வார்ககு அருள்செய்யும்
கோவந்தடைந் து அந்நெறி கூடலு மாமே.`,
    transliteration: `tārcaṭai yāṉtaṉ tamarāy ulakiṉil
pōra pukaḻā entai poṉṉaṭi cēruvar
vāyaṭai yāvuḷḷam tērvārkaku aruḷceyyum
kōvantaṭain tu anneṟi kūṭalu māmē.`,
    english: `546: The Holy are Kin of Lord
The Holy are kin of Lord
They reach Golden Feet of Father;
He, of flowing matted locks;
Whose fame envelopes worlds all,
He blesses those,
Who seek Him in silentness of their hearts;
Reach the King Almighty,
You shall attain the Regal Goal.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-546-Second-Tantra-25.-Seeking-the-Sages.mp3',
    elaborationTamil: `இறைவனின் அடியவர்கள் உலகத்தில் இருக்கும் மன்னர்களை பொய்யாக புகழாமல் கயிறு போல திரித்து விரிந்த சடையைக் கொண்டு வீற்றிருக்கும் எம் தந்தையான இறைவனை உண்மையான பக்தியோடு புகழ்ந்து அவரின் பொன்னான திருவடிகளை சேருவார்கள். இறைவனை வெறும் வார்த்தைகளால் போற்றி வணங்காமல் உண்மையான பக்தியோடு உள்ளம் உருக வேண்டினால் அந்த இறைவனின் அடியவர்களின் துணையைப்பெற்று அவர்களின் வழிசென்று இறைவனை அடையலாம்.`,
  },
  {
    id: 548, tantraId: 2, verseNumber: 547,
    tamil: `உடையான் அடியார் அடியா ருடன்போய்ப்
படையார் அழல்மேனிப் பதிசென்று புக்கேன்
கடையார நின்றவர் கண்டறி விப்ப
உடையான் வருகென ஓலம் என் றாரே.`,
    transliteration: `uṭaiyāṉ aṭiyār aṭiyā ruṭaṉpōyp
paṭaiyār aḻalmēṉip paticeṉṟu pukkēṉ
kaṭaiyāra niṉṟavar kaṇṭaṟi vippa
uṭaiyāṉ varukeṉa ōlam eṉ ṟārē.`,
    english: `547: Siva Welcomes Devotees of His Devotees
I walked with them--
Devotees of Lord's devotees
And reached the City of Fire-hued Lord
Sporting weapons divine
They who stood at gate saw me,
And announced me to the Lord;
And the Lord said "Come in"
And they all cried "Hail! You are the Refuge."`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-547-Second-Tantra-25.-Seeking-the-Sages.mp3',
    elaborationEnglish: `Walk with the noly men. Be a devotee of the Lord’s devotees. |

The devotees reach the city of the Lord; they stand at heaven’s gate and pray “‘Thou art the refuge.’” The Lord sees them and welcomes them saying, ‘‘Come in;"’ and takes them into His bosom.`,
    elaborationTamil: `அனைத்தையும் தனக்குள் உடைய இறைவனின் அடியவர்களான பெரியோர்களுக்கு அடியவர்களாகி தேவலோகப் படைகளை உடைய ஒளி உடம்போடு இருக்கும் சிவபெருமானின் திருக்கயிலாயத்திற்குச் செல்லுபவர்களை அங்கே வாயிற் காவலர்களாக இருக்கும் சிவகணங்கள் கண்டு இறைவனிடம் கூற அனைத்தும் அறிந்த இறைவன் உமக்கு அபயம் உள்ளே வருக என்று அருள் புரிந்தார்.`,
  },
  {
    id: 549, tantraId: 2, verseNumber: 548,
    tamil: `அருமைவல் லோன்கலை ஞானத்துள் தோன்றும்
பெருமைவல் லோன்பிற விச்சுழி நீந்தும்
உரிமைவல் லோன்உணர்ந்து ஊழி இருக்கும்
திருமைவல் லாரொடு சேர்ந்தனன் யானே..`,
    transliteration: `arumaival lōṉkalai ñāṉattuḷ tōṉṟum
perumaival lōṉpiṟa viccuḻi nīntum
urimaival lōṉuṇarntu ūḻi irukkum
tirumaival lāroṭu cērntaṉaṉ yāṉē..`,
    english: `548: I Joined the Company of the Rich in Grace
The Devout Supreme will in, be;
The Devout Eminent will master eddies of birth,
Devout Dear realizing self will immortal, remain;
With them who are Rich in Grace
I joined to consort.`,
    audioUrl: 'https://www.kvnthirumoolar.com/wp-content/uploads/2020/09/Song-548-Second-Tantra-25.-Seeking-the-Sages.mp3',
    elaborationEnglish: `Only the true devotees will master the karmic eddies; only they will realise the Self and achieve the deathless state. Only they will enter and be in God. gancy. are rich in grace. Consort with them.`,
    elaborationTamil: `கலை ஞானத்தில் சிறந்து இறைவனை அடையக்கூடிய அருமையை உணர்ந்தவர்கள் ஒரு நொடிப் பொழுதும் இறைவனை மறக்காமல் இருப்பதின் பயனால் பிறவியாகிய பெருங்கடலை நீந்திக் கரைசேரும் பெருமையை உடையவர்கள், இறைவனைத் தனக்குள்ளே உணர்ந்து அதிலேயே ஆழ்ந்து அவனது திருவருளைப் பெற்றவர்கள் ஆகியவர்களோடு யாமும் சேர்ந்து இருக்கின்றோம். உள்கருத்து: 64 கலைகள் உள்ளது. அதில் ஏதேனும் ஒன்றோ பலவோ கற்று அதில் ஞானம் அடைந்தவர்கள். பக்தி மார்கத்தின் மூலமாக இறைவனை ஒரு நொடிப்பொழுதும் மறக்காமல் இருப்பவர்கள். யோக மார்கத்தின் மூலமாக இறைவனை தனக்குள் உணர்ந்தவர்களுடன் யாம் துணையாக இருக்கன்றோம் என்று அருளுகின்றார்.`,
  },
];
